class UpstreamProtocolError(RuntimeError):
    """The provider returned HTTP success without a usable completion."""


class UpstreamBackgroundDeferred(ConnectionError):
    """A non-essential model request yielded to a foreground chat request."""


def sanitize_provider_error_message(value: Any) -> str:
    """Keep provider diagnostics useful without persisting credentials."""

    text = re.sub(r"\s+", " ", str(value or "")).strip()
    text = re.sub(
        r"(?i)\b(?:bearer\s+)?(?:sk|ds)-[A-Za-z0-9._-]{8,}\b",
        "[REDACTED_API_KEY]",
        text,
    )
    text = re.sub(
        r"(?i)(api[_ -]?key\s*[:=]\s*)\S+",
        r"\1[REDACTED]",
        text,
    )
    return text[:500]


def upstream_http_error_diagnostics(
    error: urllib.error.HTTPError,
) -> dict[str, Any]:
    """Read an HTTP error body once and retain content-safe provider metadata."""

    cached = getattr(error, "_amadeus_upstream_diagnostics", None)
    if isinstance(cached, dict):
        return dict(cached)
    raw = b""
    try:
        raw = error.read(16_384)
    except Exception:
        pass
    provider_code = ""
    provider_type = ""
    provider_message = ""
    if raw:
        try:
            payload = json.loads(raw.decode("utf-8", errors="replace"))
        except json.JSONDecodeError:
            payload = None
        if isinstance(payload, dict):
            detail = payload.get("error")
            if isinstance(detail, dict):
                provider_code = str(detail.get("code") or "")
                provider_type = str(detail.get("type") or "")
                provider_message = str(detail.get("message") or "")
            elif detail is not None:
                provider_message = str(detail)
            if not provider_message:
                provider_message = str(payload.get("message") or "")
            if not provider_code:
                provider_code = str(payload.get("code") or "")
            if not provider_type:
                provider_type = str(payload.get("type") or "")
    diagnostics = {
        "status": int(error.code),
        "providerErrorCode": sanitize_provider_error_message(provider_code),
        "providerErrorType": sanitize_provider_error_message(provider_type),
        "providerMessage": sanitize_provider_error_message(provider_message),
        "responseBodyLength": len(raw),
    }
    setattr(error, "_amadeus_upstream_diagnostics", dict(diagnostics))
    return diagnostics


def upstream_http_error_user_message(error: urllib.error.HTTPError) -> str:
    diagnostics = upstream_http_error_diagnostics(error)
    status = int(diagnostics.get("status") or error.code)
    provider_code = str(
        diagnostics.get("providerErrorCode")
        or diagnostics.get("providerErrorType")
        or ""
    ).strip()
    suffix = f"，错误类型 {provider_code}" if provider_code else ""
    if status == 400:
        return f"DeepSeek 拒绝了主对话请求（HTTP 400{suffix}），请求格式或模型上下文不兼容。"
    return f"DeepSeek 返回 HTTP {status}{suffix}。"


class GroundingGateError(RuntimeError):
    """A complete model draft needs internal evidence recovery before delivery."""

    def __init__(self, decision: Any) -> None:
        self.decision = decision
        self.code = "GROUNDING_GATE"
        super().__init__(
            "grounded claim gate requires internal recovery: "
            + str(getattr(decision, "status", "BLOCK"))
        )


class RequestValidationError(ValueError):
    """The local client sent a request that cannot be processed."""

    def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code
        self.message = message


class LocalTtsSynthesisError(RuntimeError):
    """The loopback speech service rejected or failed a synthesis request."""

    def __init__(
        self,
        message: str,
        *,
        upstream_status: int = 500,
        deterministic: bool = False,
        diagnostics: dict[str, Any] | None = None,
    ) -> None:
        super().__init__(message)
        self.message = str(message or "本地语音服务合成失败")[:1000]
        self.upstream_status = int(upstream_status)
        self.deterministic = bool(deterministic)
        self.diagnostics = dict(diagnostics or {})
        self.code = (
            "tts_incomplete_audio"
            if self.deterministic
            else "tts_service_error"
        )


class RuntimeProcessLock:
    """Prevent two backend processes from mutating the same data profile."""

    def __init__(self) -> None:
        digest = runtime_fingerprint(str(DATA_DIR).casefold())
        self.name = f"AmadeusRuntime-{digest}"
        self.handle: Any = None
        self.file_handle: Any = None

    def acquire(self) -> None:
        if os.environ.get("AMADEUS_ALLOW_PARALLEL_RUNTIME") == "1":
            return
        if os.name == "nt":
            import ctypes

            kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
            kernel32.CreateMutexW.argtypes = [ctypes.c_void_p, ctypes.c_bool, ctypes.c_wchar_p]
            kernel32.CreateMutexW.restype = ctypes.c_void_p
            kernel32.CloseHandle.argtypes = [ctypes.c_void_p]
            kernel32.CloseHandle.restype = ctypes.c_bool
            handle = kernel32.CreateMutexW(None, True, f"Local\\{self.name}")
            if not handle:
                raise OSError(ctypes.get_last_error(), "CreateMutexW failed")
            if ctypes.get_last_error() == 183:  # ERROR_ALREADY_EXISTS
                kernel32.CloseHandle(handle)
                raise RuntimeError(
                    "已有一个 AMADEUS 后端正在使用同一份 data 目录。"
                    "桌面窗口会自动复用 5174，请不要同时运行 server.py。"
                )
            self.handle = handle
            return

        import fcntl

        lock_path = DATA_DIR / ".runtime.lock"
        lock_path.parent.mkdir(parents=True, exist_ok=True)
        file_handle = lock_path.open("a+b")
        try:
            fcntl.flock(file_handle.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
        except OSError as error:
            file_handle.close()
            raise RuntimeError("已有一个 AMADEUS 后端正在使用同一份 data 目录。") from error
        self.file_handle = file_handle

    def release(self) -> None:
        if self.handle is not None and os.name == "nt":
            import ctypes

            kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
            kernel32.ReleaseMutex.argtypes = [ctypes.c_void_p]
            kernel32.ReleaseMutex.restype = ctypes.c_bool
            kernel32.CloseHandle.argtypes = [ctypes.c_void_p]
            kernel32.CloseHandle.restype = ctypes.c_bool
            kernel32.ReleaseMutex(self.handle)
            kernel32.CloseHandle(self.handle)
            self.handle = None
        if self.file_handle is not None:
            try:
                import fcntl

                fcntl.flock(self.file_handle.fileno(), fcntl.LOCK_UN)
            finally:
                self.file_handle.close()
                self.file_handle = None

    def __enter__(self) -> "RuntimeProcessLock":
        self.acquire()
        return self

    def __exit__(self, *_args: Any) -> None:
        self.release()


def write_server_log(event: str, **details: Any) -> None:
    """Persist compact diagnostics without prompts, API keys, or response bodies."""

    record = {
        "at": datetime.now().astimezone().isoformat(timespec="seconds"),
        "event": str(event),
        **details,
    }
    try:
        SERVER_ERROR_LOG_PATH.parent.mkdir(parents=True, exist_ok=True)
        line = json.dumps(record, ensure_ascii=False, default=str) + "\n"
        with _server_log_lock:
            with SERVER_ERROR_LOG_PATH.open("a", encoding="utf-8", newline="\n") as handle:
                handle.write(line)
    except OSError:
        pass


def write_network_incident(**details: Any) -> None:
    """Persist one redacted upstream transport failure for field diagnosis."""

    record = {
        "at": datetime.now().astimezone().isoformat(timespec="seconds"),
        **details,
    }
    try:
        NETWORK_INCIDENT_LOG_PATH.parent.mkdir(parents=True, exist_ok=True)
        line = json.dumps(record, ensure_ascii=False, default=str) + "\n"
        with _server_log_lock:
            with NETWORK_INCIDENT_LOG_PATH.open("a", encoding="utf-8", newline="\n") as handle:
                handle.write(line)
    except OSError:
        pass


def normalize_runtime_client_id(value: Any) -> str:
    return re.sub(r"[^A-Za-z0-9._:-]", "", str(value or ""))[:120]


def prune_runtime_clients(now: float | None = None) -> None:
    current = time.monotonic() if now is None else now
    expired = [
        client_id
        for client_id, entry in _runtime_clients.items()
        if current - float(entry.get("lastSeen") or 0) > RUNTIME_CLIENT_LEASE_SECONDS
    ]
    for client_id in expired:
        _runtime_clients.pop(client_id, None)


def touch_runtime_client(client_id: Any, mode: Any = "desktop") -> dict[str, Any]:
    normalized = normalize_runtime_client_id(client_id)
    if not normalized:
        raise ValueError("clientId is required")
    now = time.monotonic()
    with _runtime_client_lock:
        prune_runtime_clients(now)
        current = _runtime_clients.get(normalized, {})
        _runtime_clients[normalized] = {
            "clientId": normalized,
            "mode": re.sub(r"[^A-Za-z0-9._:-]", "", str(mode or "desktop"))[:40] or "desktop",
            "connectedAt": float(current.get("connectedAt") or now),
            "lastSeen": now,
        }
        count = len(_runtime_clients)
    return {"clientId": normalized, "activeClients": count, "leaseSeconds": RUNTIME_CLIENT_LEASE_SECONDS}


def remove_runtime_client(client_id: Any) -> int:
    normalized = normalize_runtime_client_id(client_id)
    with _runtime_client_lock:
        if normalized:
            _runtime_clients.pop(normalized, None)
        prune_runtime_clients()
        return len(_runtime_clients)


def runtime_client_snapshot() -> list[dict[str, Any]]:
    now = time.monotonic()
    with _runtime_client_lock:
        prune_runtime_clients(now)
        return [
            {
                "clientId": str(entry.get("clientId") or ""),
                "mode": str(entry.get("mode") or "desktop"),
                "ageSeconds": round(max(0.0, now - float(entry.get("lastSeen") or now)), 1),
            }
            for entry in _runtime_clients.values()
        ]


def refresh_runtime_client_leases() -> int:
    """Extend existing leases after the machine resumes from sleep."""
    now = time.monotonic()
    with _runtime_client_lock:
        for entry in _runtime_clients.values():
            entry["lastSeen"] = now
        return len(_runtime_clients)


def active_runtime_client_count() -> int:
    return len(runtime_client_snapshot())


def normalize_chat_request_id(value: Any) -> str:
    return re.sub(r"[^A-Za-z0-9._:-]", "", str(value or ""))[:120]


def prune_chat_request_cache(now: float | None = None) -> None:
    current = time.monotonic() if now is None else now
    expired = [
        request_id
        for request_id, entry in _chat_requests.items()
        if entry.get("state") != "running"
        and current - float(entry.get("updatedAt") or entry.get("createdAt") or current)
        > CHAT_REQUEST_CACHE_TTL_SECONDS
    ]
    for request_id in expired:
        _chat_requests.pop(request_id, None)
    if len(_chat_requests) <= CHAT_REQUEST_CACHE_LIMIT:
        return
    removable = sorted(
        (
            (request_id, float(entry.get("updatedAt") or entry.get("createdAt") or 0))
            for request_id, entry in _chat_requests.items()
            if entry.get("state") != "running"
        ),
        key=lambda item: item[1],
    )
    for request_id, _ in removable[:max(0, len(_chat_requests) - CHAT_REQUEST_CACHE_LIMIT)]:
        _chat_requests.pop(request_id, None)


def prepare_external_chat_body(body: dict[str, Any]) -> str:
    """Remove client-forged internal state and establish a server request ID."""

    for key in [item for item in body if str(item).startswith("_")]:
        body.pop(key, None)
    request_id = normalize_chat_request_id(body.get("requestId"))
    if not request_id:
        request_id = f"turn-{int(time.time() * 1000)}-{uuid.uuid4().hex[:12]}"
    body["requestId"] = request_id
    return request_id


def claim_chat_request(request_id: str, supersedes_request_id: str = "") -> tuple[str, Any]:
    """Claim a request, reuse its result, or wait for an identical in-flight POST."""

    if not request_id:
        return "owner", None
    with _chat_request_lock:
        prune_chat_request_cache()
        if supersedes_request_id and supersedes_request_id != request_id:
            superseded = _chat_requests.get(supersedes_request_id)
            if superseded and superseded.get("state") == "running":
                superseded["cancelled"] = True
                superseded["updatedAt"] = time.monotonic()
                superseded_turn_state = superseded.get("turnState")
                if isinstance(superseded_turn_state, TurnState) and not superseded_turn_state.terminal:
                    try:
                        superseded_turn_state.finish(
                            TurnPhase.CANCELLED,
                            TerminalReason.USER_CANCELLED,
                            reason="superseded_by_new_request",
                        )
                    except ValueError:
                        pass
        existing = _chat_requests.get(request_id)
        if existing:
            if existing.get("state") == "completed" and isinstance(existing.get("result"), dict):
                return "cached", dict(existing["result"])
            if existing.get("state") == "running":
                return "wait", existing["event"]
            _chat_requests.pop(request_id, None)
        event = threading.Event()
        turn_id = f"{request_id or uuid.uuid4().hex}:turn"
        _chat_requests[request_id] = {
            "state": "running",
            "event": event,
            "createdAt": time.monotonic(),
            "updatedAt": time.monotonic(),
            "cancelled": False,
            "turnState": TurnState(request_id=request_id, turn_id=turn_id),
            "progress": {
                "stage": "received",
                "detail": "请求已进入处理队列",
                "sequence": 1,
                "startedAt": time.monotonic(),
                "updatedAt": time.monotonic(),
            },
        }
    return "owner", None


def update_chat_request_progress(request_id: str, stage: str, detail: str = "") -> None:
    """Publish bounded, content-free progress for the developer UI."""

    normalized = normalize_chat_request_id(request_id)
    if not normalized:
        return
    now = time.monotonic()
    with _chat_request_lock:
        entry = _chat_requests.get(normalized)
        if not entry or entry.get("state") != "running":
            return
        turn_state = entry.get("turnState")
        target_phase = phase_for_progress_stage(stage)
        if (
            isinstance(turn_state, TurnState)
            and target_phase is not None
            and target_phase != TurnPhase.RECEIVED
            and not turn_state.terminal
        ):
            previous_phase = turn_state.phase
            try:
                turn_state.advance_to(target_phase, reason=f"progress:{stage}")
                if target_phase == TurnPhase.WAITING_MODEL and previous_phase != target_phase:
                    turn_state.note_model_round()
                if target_phase == TurnPhase.WAITING_TOOL and previous_phase != target_phase:
                    turn_state.note_tool_round()
            except ValueError as error:
                write_server_log(
                    "turn_state_transition_rejected",
                    requestId=normalized,
                    currentPhase=turn_state.phase.value,
                    targetPhase=target_phase.value,
                    progressStage=str(stage)[:48],
                    error=str(error)[:240],
                )
        previous = entry.get("progress") if isinstance(entry.get("progress"), dict) else {}
        entry["progress"] = {
            "stage": re.sub(r"[^a-z0-9_-]", "", str(stage or "working").lower())[:48] or "working",
            "detail": str(detail or "")[:160],
            "sequence": int(previous.get("sequence") or 0) + 1,
            "startedAt": float(previous.get("startedAt") or now),
            "updatedAt": now,
        }
        entry["updatedAt"] = now


def chat_request_progress(request_id: Any) -> dict[str, Any]:
    normalized = normalize_chat_request_id(request_id)
    now = time.monotonic()
    with _chat_request_lock:
        prune_chat_request_cache(now)
        entry = _chat_requests.get(normalized)
        if not entry:
            return {"ok": False, "requestId": normalized, "state": "missing"}
        progress = entry.get("progress") if isinstance(entry.get("progress"), dict) else {}
        started_at = float(progress.get("startedAt") or entry.get("createdAt") or now)
        return {
            "ok": True,
            "requestId": normalized,
            "state": str(entry.get("state") or "running"),
            "cancelled": bool(entry.get("cancelled")),
            "stage": str(progress.get("stage") or entry.get("state") or "working"),
            "detail": str(progress.get("detail") or ""),
            "sequence": int(progress.get("sequence") or 0),
            "elapsedMs": round(max(0.0, now - started_at) * 1000),
            **(
                {"turnState": entry["turnState"].to_dict()}
                if isinstance(entry.get("turnState"), TurnState)
                else {}
            ),
        }


def chat_request_cancelled(request_id: str) -> bool:
    if not request_id:
        return False
    with _chat_request_lock:
        entry = _chat_requests.get(request_id)
        return bool(entry and entry.get("cancelled"))


def raise_if_chat_request_cancelled(request_id: str) -> None:
    if chat_request_cancelled(request_id):
        raise RequestValidationError(
            "request_cancelled",
            "这轮回答已被用户终止。",
        )


@contextmanager
def tracked_upstream_response(request_id: str, response: Any):
    """Let an explicit user cancellation close the active provider socket."""

    normalized = normalize_chat_request_id(request_id)
    if not normalized:
        yield response
        return
    with _active_upstream_response_lock:
        _active_upstream_responses.setdefault(normalized, []).append(response)
    try:
        yield response
    finally:
        with _active_upstream_response_lock:
            items = _active_upstream_responses.get(normalized, [])
            remaining = [item for item in items if item is not response]
            if remaining:
                _active_upstream_responses[normalized] = remaining
            else:
                _active_upstream_responses.pop(normalized, None)


def cancel_chat_request(request_id: Any, *, reason: str = "user_stop_button") -> dict[str, Any]:
    """Cancel one answer across model, repair, tool-gate, and TTS stages."""

    normalized = normalize_chat_request_id(request_id)
    if not normalized:
        return {"ok": False, "cancelled": False, "error": "request_id_required"}
    found = False
    already_terminal = False
    with _chat_request_lock:
        entry = _chat_requests.get(normalized)
        if entry:
            found = True
            already_terminal = entry.get("state") != "running"
            entry["cancelled"] = True
            entry["updatedAt"] = time.monotonic()
            previous = entry.get("progress") if isinstance(entry.get("progress"), dict) else {}
            entry["progress"] = {
                "stage": "cancelled",
                "detail": "用户已终止当前回答",
                "sequence": int(previous.get("sequence") or 0) + 1,
                "startedAt": float(previous.get("startedAt") or entry.get("createdAt") or time.monotonic()),
                "updatedAt": time.monotonic(),
            }
            turn_state = entry.get("turnState")
            if isinstance(turn_state, TurnState) and not turn_state.terminal:
                try:
                    turn_state.finish(
                        TurnPhase.CANCELLED,
                        TerminalReason.USER_CANCELLED,
                        reason=str(reason or "user_stop_button")[:120],
                    )
                except ValueError:
                    pass
    release_chat_stream_tool_gate(normalized)
    with _active_upstream_response_lock:
        responses = list(_active_upstream_responses.get(normalized, []))
    closed_responses = 0
    for response in responses:
        try:
            response.close()
            closed_responses += 1
        except Exception:
            pass
    tts_cancelled = cancel_local_tts_request(normalized)
    write_server_log(
        "chat_request_cancelled_by_user",
        requestId=normalized,
        found=found,
        alreadyTerminal=already_terminal,
        closedUpstreamResponses=closed_responses,
        ttsCancelForwarded=tts_cancelled,
    )
    return {
        "ok": True,
        "requestId": normalized,
        "cancelled": True,
        "found": found,
        "alreadyTerminal": already_terminal,
        "closedUpstreamResponses": closed_responses,
        "ttsCancelForwarded": tts_cancelled,
    }


def create_chat_stream_tool_gate(request_id: str) -> threading.Event:
    gate = threading.Event()
    if not request_id:
        gate.set()
        return gate
    with _chat_stream_tool_gate_lock:
        _chat_stream_tool_gates[request_id] = gate
    return gate


def release_chat_stream_tool_gate(request_id: str) -> bool:
    if not request_id:
        return False
    with _chat_stream_tool_gate_lock:
        gate = _chat_stream_tool_gates.get(request_id)
    if not isinstance(gate, threading.Event):
        return False
    gate.set()
    return True


def wait_chat_stream_tool_gate(
    request_id: str,
    gate: threading.Event,
    *,
    timeout_seconds: float = 45.0,
) -> str:
    deadline = time.monotonic() + max(0.1, float(timeout_seconds))
    while time.monotonic() < deadline:
        if gate.wait(min(0.12, max(0.0, deadline - time.monotonic()))):
            return "released"
        if chat_request_cancelled(request_id):
            return "cancelled"
    return "timeout"


def remove_chat_stream_tool_gate(request_id: str, gate: threading.Event) -> None:
    if not request_id:
        return
    with _chat_stream_tool_gate_lock:
        if _chat_stream_tool_gates.get(request_id) is gate:
            _chat_stream_tool_gates.pop(request_id, None)


def finish_chat_request(request_id: str, result: dict[str, Any] | None = None, error: str = "") -> None:
    if not request_id:
        return
    with _chat_request_lock:
        entry = _chat_requests.get(request_id)
        if not entry:
            return
        entry["updatedAt"] = time.monotonic()
        if entry.get("cancelled"):
            result = {
                "cancelled": True,
                "requestId": request_id,
            }
            error = ""
        turn_state = entry.get("turnState")
        if isinstance(result, dict):
            entry["state"] = "completed"
            entry["result"] = dict(result)
            entry.pop("error", None)
            completion_stage = "cancelled" if result.get("cancelled") else "complete"
            completion_detail = "请求已被后续输入替代" if result.get("cancelled") else "回答已交付前端"
            if isinstance(turn_state, TurnState) and not turn_state.terminal:
                try:
                    turn_state.finish(
                        TurnPhase.CANCELLED if result.get("cancelled") else TurnPhase.COMPLETED,
                        TerminalReason.USER_CANCELLED if result.get("cancelled") else TerminalReason.END_TURN,
                        reason=completion_detail,
                    )
                except ValueError as transition_error:
                    write_server_log(
                        "turn_state_finish_rejected",
                        requestId=request_id,
                        error=str(transition_error)[:240],
                    )
            if isinstance(turn_state, TurnState):
                result["turnState"] = turn_state.to_dict()
                entry["result"] = dict(result)
        else:
            entry["state"] = "failed"
            entry["error"] = str(error or "request_failed")[:500]
            completion_stage = "failed"
            completion_detail = "处理链路发生错误"
            if isinstance(turn_state, TurnState) and not turn_state.terminal:
                try:
                    turn_state.finish(
                        TurnPhase.FAILED,
                        TerminalReason.UPSTREAM_FAILURE,
                        reason=str(error or "request_failed")[:240],
                    )
                except ValueError as transition_error:
                    write_server_log(
                        "turn_state_finish_rejected",
                        requestId=request_id,
                        error=str(transition_error)[:240],
                    )
        previous = entry.get("progress") if isinstance(entry.get("progress"), dict) else {}
        entry["progress"] = {
            "stage": completion_stage,
            "detail": completion_detail,
            "sequence": int(previous.get("sequence") or 0) + 1,
            "startedAt": float(previous.get("startedAt") or entry.get("createdAt") or time.monotonic()),
            "updatedAt": time.monotonic(),
        }
        event = entry.get("event")
        if isinstance(event, threading.Event):
            event.set()


def completed_chat_request(request_id: str) -> dict[str, Any] | None:
    if not request_id:
        return None
    with _chat_request_lock:
        entry = _chat_requests.get(request_id)
        if entry and entry.get("state") == "completed" and isinstance(entry.get("result"), dict):
            return dict(entry["result"])
    return None

def registered_live2d_model_ids() -> set[str]:
    try:
        registry = json.loads(LIVE2D_MODELS_PATH.read_text(encoding="utf-8"))
        models = registry.get("models") if isinstance(registry, dict) else []
        model_ids = {
            str(item.get("id") or "").strip()
            for item in models if isinstance(item, dict)
            if str(item.get("id") or "").strip()
        }
        if model_ids:
            return model_ids
    except (OSError, json.JSONDecodeError):
        pass
    return {"aipoet-kurisu"}


