def read_system_prompt() -> str:
    parts: list[str] = []
    try:
        parts.append(CORE_PERSONA_PATH.read_text(encoding="utf-8"))
    except OSError:
        try:
            parts.append(SYSTEM_PROMPT_PATH.read_text(encoding="utf-8"))
        except OSError:
            pass
    persona_override = ""
    if not RELEASE_MODE:
        try:
            persona_override = PERSONA_OVERRIDE_PATH.read_text(encoding="utf-8").strip()
        except OSError:
            persona_override = ""
    if persona_override:
        parts.append("[Developer Persona Override]\n" + persona_override)
    return "\n\n".join(parts)


