def normalize_storage_scope(value: Any) -> str:
    if RELEASE_MODE:
        return "normal"
    return "developer" if str(value or "").strip().lower() == "developer" else "normal"


def set_request_storage_scope(value: Any) -> str:
    scope = normalize_storage_scope(value)
    REQUEST_STORAGE_SCOPE.set(scope)
    return scope


def current_storage_scope() -> str:
    return normalize_storage_scope(REQUEST_STORAGE_SCOPE.get())


def developer_storage_active() -> bool:
    return current_storage_scope() == "developer"


def scoped_data_path(normal_path: Path) -> Path:
    if developer_storage_active():
        return DEVELOPER_STORAGE_DIR / normal_path.name
    return normal_path


def state_database_path() -> Path:
    # Keep the database in the same injected storage domain as the
    # conversation context. Tests and developer mode often replace that domain
    # as a unit; deriving the parent prevents a stale global database path from
    # leaking turns across otherwise isolated stores.
    context_parent = scoped_data_path(CONVERSATION_CONTEXT_PATH).parent
    return context_parent / STATE_DATABASE_PATH.name


PREPARED_TURN_TTL_SECONDS = 2 * 60 * 60
RESEARCH_STATE_TTL_SECONDS = 24 * 60 * 60


def _state_record_cutoff(seconds: int) -> str:
    return (datetime.now(timezone.utc) - timedelta(seconds=max(1, seconds))).isoformat(
        timespec="seconds"
    )


def prune_transient_state_records(connection: sqlite3.Connection) -> None:
    """Bound request-scoped planning state without touching durable audit rows."""

    connection.execute(
        "DELETE FROM prepared_turns WHERE datetime(updated_at) < datetime(?)",
        (_state_record_cutoff(PREPARED_TURN_TTL_SECONDS),),
    )
    connection.execute(
        "DELETE FROM research_states WHERE datetime(updated_at) < datetime(?)",
        (_state_record_cutoff(RESEARCH_STATE_TTL_SECONDS),),
    )


def clear_transient_turn_records() -> None:
    with state_database() as connection:
        connection.execute("DELETE FROM prepared_turns")
        connection.execute("DELETE FROM research_states")
        connection.execute("DELETE FROM pending_actions")


def open_state_database() -> sqlite3.Connection:
    """Open the domain-separated state store; never rewrite conversation JSON."""

    path = state_database_path()
    path.parent.mkdir(parents=True, exist_ok=True)
    connection = sqlite3.connect(path, timeout=15)
    connection.row_factory = sqlite3.Row
    database_version = int(connection.execute("PRAGMA user_version").fetchone()[0])
    if database_version > 2:
        connection.close()
        raise ContextCompatibilityError(
            f"Unsupported AMADEUS state database version: {database_version}；请使用更新版本打开，原数据库未修改。",
            code="context_version_too_new",
        )
    connection.execute("PRAGMA journal_mode=WAL")
    connection.execute("PRAGMA synchronous=FULL")
    connection.executescript(
        """
        CREATE TABLE IF NOT EXISTS prepared_turns (
            request_id TEXT PRIMARY KEY,
            route TEXT NOT NULL,
            payload_json TEXT NOT NULL,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS research_states (
            request_id TEXT PRIMARY KEY,
            payload_json TEXT NOT NULL,
            status TEXT NOT NULL,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS pending_actions (
            action_id TEXT PRIMARY KEY,
            payload_json TEXT NOT NULL,
            status TEXT NOT NULL,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS action_receipts (
            action_id TEXT PRIMARY KEY,
            canonical_target TEXT NOT NULL DEFAULT '',
            payload_json TEXT NOT NULL,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS conversation_turns (
            turn_id TEXT PRIMARY KEY,
            session_id TEXT NOT NULL,
            created_at TEXT NOT NULL,
            user_text TEXT NOT NULL,
            assistant_text TEXT NOT NULL,
            metadata_json TEXT NOT NULL
        );
        CREATE INDEX IF NOT EXISTS idx_conversation_turns_session_time
        ON conversation_turns(session_id, created_at);
        """
    )
    ensure_todo_schema(connection)
    ensure_schedule_schema(connection)
    ensure_bookmark_schema(connection)
    ensure_web_destination_schema(connection)
    ensure_cognitive_schema(connection)
    if database_version < 2:
        connection.execute("PRAGMA user_version=2")
        connection.commit()
    return connection


@contextmanager
def state_database():
    connection = open_state_database()
    try:
        with connection:
            yield connection
    finally:
        connection.close()


def write_prepared_turn_record(payload: dict[str, Any]) -> None:
    request_id = str(payload.get("requestId") or "")
    if not request_id:
        return
    timestamp = now_iso()
    with state_database() as connection:
        prune_transient_state_records(connection)
        connection.execute(
            """
            INSERT INTO prepared_turns(request_id, route, payload_json, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?)
            ON CONFLICT(request_id) DO UPDATE SET
                route=excluded.route,
                payload_json=excluded.payload_json,
                updated_at=excluded.updated_at
            """,
            (
                request_id,
                str(payload.get("route") or "fast_chat"),
                json.dumps(payload, ensure_ascii=False, separators=(",", ":")),
                timestamp,
                timestamp,
            ),
        )


def read_prepared_turn_record(request_id: str) -> dict[str, Any]:
    normalized = str(request_id or "").strip()[:120]
    if not normalized:
        return {}
    with state_database() as connection:
        prune_transient_state_records(connection)
        row = connection.execute(
            "SELECT payload_json FROM prepared_turns WHERE request_id = ?",
            (normalized,),
        ).fetchone()
    if row is None:
        return {}
    try:
        value = json.loads(str(row["payload_json"]))
    except (TypeError, ValueError, json.JSONDecodeError):
        return {}
    return value if isinstance(value, dict) else {}


def write_research_state_record(state: ResearchLoopState) -> dict[str, Any]:
    payload = {"stateVersion": 1, **state.to_dict()}
    request_id = str(state.request_id or "").strip()[:120]
    if not request_id:
        return payload
    timestamp = now_iso()
    with state_database() as connection:
        prune_transient_state_records(connection)
        connection.execute(
            """
            INSERT INTO research_states(request_id, payload_json, status, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?)
            ON CONFLICT(request_id) DO UPDATE SET
                payload_json=excluded.payload_json,
                status=excluded.status,
                updated_at=excluded.updated_at
            """,
            (
                request_id,
                json.dumps(payload, ensure_ascii=False, separators=(",", ":")),
                str(state.status or "planned"),
                timestamp,
                timestamp,
            ),
        )
    return payload


def read_research_state_record(request_id: str) -> ResearchLoopState | None:
    normalized = str(request_id or "").strip()[:120]
    if not normalized:
        return None
    with state_database() as connection:
        prune_transient_state_records(connection)
        row = connection.execute(
            "SELECT payload_json FROM research_states WHERE request_id = ?",
            (normalized,),
        ).fetchone()
    if row is None:
        return None
    try:
        value = json.loads(str(row["payload_json"]))
    except (TypeError, ValueError, json.JSONDecodeError):
        return None
    return ResearchLoopState.from_dict(value) if isinstance(value, dict) else None


def read_pending_action_record() -> dict[str, Any]:
    with state_database() as connection:
        row = connection.execute(
            "SELECT payload_json FROM pending_actions ORDER BY updated_at DESC LIMIT 1"
        ).fetchone()
    if row is None:
        return {}
    try:
        value = json.loads(str(row["payload_json"]))
    except (TypeError, ValueError, json.JSONDecodeError):
        return {}
    return value if isinstance(value, dict) else {}


def write_pending_action_record(payload: dict[str, Any]) -> dict[str, Any]:
    action_id = str(payload.get("actionId") or "")
    if not action_id:
        return {}
    timestamp = now_iso()
    with state_database() as connection:
        connection.execute("DELETE FROM pending_actions WHERE action_id <> ?", (action_id,))
        connection.execute(
            """
            INSERT INTO pending_actions(action_id, payload_json, status, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?)
            ON CONFLICT(action_id) DO UPDATE SET
                payload_json=excluded.payload_json,
                status=excluded.status,
                updated_at=excluded.updated_at
            """,
            (
                action_id,
                json.dumps(payload, ensure_ascii=False, separators=(",", ":")),
                str(payload.get("status") or ""),
                str(payload.get("createdAt") or timestamp),
                timestamp,
            ),
        )
    return payload


def delete_pending_action_record(action_id: str = "") -> None:
    with state_database() as connection:
        if action_id:
            connection.execute("DELETE FROM pending_actions WHERE action_id = ?", (action_id,))
        else:
            connection.execute("DELETE FROM pending_actions")


def write_action_receipt_record(
    receipt: dict[str, Any],
    *,
    connection: sqlite3.Connection | None = None,
) -> dict[str, Any]:
    action_id = str(receipt.get("actionId") or "")
    if not action_id:
        return {}
    timestamp = now_iso()
    canonical = str(receipt.get("resolvedTarget") or receipt.get("canonicalUrl") or "")
    def write(active_connection: sqlite3.Connection) -> None:
        active_connection.execute(
            """
            INSERT INTO action_receipts(action_id, canonical_target, payload_json, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?)
            ON CONFLICT(action_id) DO UPDATE SET
                canonical_target=excluded.canonical_target,
                payload_json=excluded.payload_json,
                updated_at=excluded.updated_at
            """,
            (
                action_id,
                canonical,
                json.dumps(receipt, ensure_ascii=False, separators=(",", ":")),
                timestamp,
                timestamp,
            ),
        )
    if connection is not None:
        write(connection)
    else:
        with state_database() as active_connection:
            write(active_connection)
    return receipt


def read_action_receipt_records(limit: int = ACTION_RECEIPT_HISTORY_LIMIT) -> list[dict[str, Any]]:
    with state_database() as connection:
        rows = connection.execute(
            "SELECT payload_json FROM action_receipts ORDER BY updated_at DESC LIMIT ?",
            (max(1, int(limit)),),
        ).fetchall()
    result: list[dict[str, Any]] = []
    for row in reversed(rows):
        try:
            value = json.loads(str(row["payload_json"]))
        except (TypeError, ValueError, json.JSONDecodeError):
            continue
        if isinstance(value, dict):
            result.append(value)
    legacy_context = read_conversation_context()
    legacy = (
        legacy_context.get("actionReceipts")
        if isinstance(legacy_context.get("actionReceipts"), list)
        else []
    )
    merged: dict[str, dict[str, Any]] = {}
    for item in [*legacy, *result]:
        if not isinstance(item, dict):
            continue
        key = str(item.get("actionId") or item.get("resolvedTarget") or "")
        if key:
            merged[key] = dict(item)
    return list(merged.values())[-max(1, int(limit)):]


def find_action_receipt_by_idempotency_key(
    idempotency_key: str,
) -> dict[str, Any] | None:
    """Find a completed external action independently of its transient action id.

    A single chat request can enter the backend recovery path after a tool has
    already succeeded. Recovery creates fresh model tool/action ids, so those
    ids cannot be the exactly-once boundary for an external side effect.
    """

    key = str(idempotency_key or "").strip()
    if not key:
        return None
    with state_database() as connection:
        rows = connection.execute(
            "SELECT payload_json FROM action_receipts ORDER BY updated_at DESC"
        ).fetchall()
    for row in rows:
        try:
            value = json.loads(str(row["payload_json"]))
        except (TypeError, ValueError, json.JSONDecodeError):
            continue
        if (
            isinstance(value, dict)
            and str(value.get("idempotencyKey") or "") == key
            and str(value.get("status") or "") == "accepted"
        ):
            return value
    return None


def write_conversation_turn_record(
    turn: dict[str, Any],
    *,
    connection: sqlite3.Connection | None = None,
) -> None:
    timestamp = str(turn.get("at") or now_iso())
    stable_material = "\0".join([
        timestamp,
        str(turn.get("user") or ""),
        str(turn.get("assistant") or ""),
        str(turn.get("proactiveEventId") or ""),
    ])
    turn_id = str(
        turn.get("turnId")
        or "turn_" + legacy_persistent_fingerprint(stable_material, length=24)
    )
    metadata = {
        key: value
        for key, value in turn.items()
        if key not in {"user", "assistant"} and not str(key).startswith("_")
    }

    def write(active_connection: sqlite3.Connection) -> None:
        active_connection.execute(
            """
            INSERT OR IGNORE INTO conversation_turns(
                turn_id, session_id, created_at, user_text, assistant_text, metadata_json
            ) VALUES (?, ?, ?, ?, ?, ?)
            """,
            (
                turn_id,
                str(turn.get("sessionId") or "default"),
                timestamp,
                str(turn.get("user") or ""),
                str(turn.get("assistant") or ""),
                json.dumps(metadata, ensure_ascii=False, separators=(",", ":")),
            ),
        )

    if connection is not None:
        write(connection)
    else:
        with state_database() as active_connection:
            write(active_connection)


def read_conversation_turn_records(
    limit: int = CONVERSATION_RECENT_LIMIT,
    *,
    epoch: int | None = None,
) -> list[dict[str, Any]]:
    path = state_database_path()
    if not path.exists():
        return []
    with state_database() as connection:
        rows = connection.execute(
            """
            SELECT turn_id, created_at, user_text, assistant_text, metadata_json
            FROM conversation_turns
            WHERE session_id = 'default'
            ORDER BY created_at DESC
            LIMIT ?
            """,
            (max(1, int(limit)),),
        ).fetchall()
    turns: list[dict[str, Any]] = []
    for row in reversed(rows):
        try:
            metadata = json.loads(str(row["metadata_json"]))
        except (TypeError, ValueError, json.JSONDecodeError):
            metadata = {}
        turns.append({
            **(metadata if isinstance(metadata, dict) else {}),
            "turnId": str(row["turn_id"]),
            "at": str(row["created_at"]),
            "user": str(row["user_text"]),
            "assistant": str(row["assistant_text"]),
        })
    if epoch is not None:
        turns = [item for item in turns if turn_conversation_epoch(item) == max(0, int(epoch))]
    return turns[-max(1, int(limit)):]


def clear_conversation_turn_records() -> None:
    with state_database() as connection:
        connection.execute("DELETE FROM conversation_turns WHERE session_id = 'default'")


def conversation_turn_record_count() -> int:
    path = state_database_path()
    if not path.exists():
        return 0
    with state_database() as connection:
        row = connection.execute(
            "SELECT COUNT(*) AS count FROM conversation_turns WHERE session_id = 'default'"
        ).fetchone()
    return int(row["count"] if row is not None else 0)


def normalize_relationship_state(state: Any) -> dict[str, Any]:
    if not isinstance(state, dict):
        state = default_relationship_state()
    else:
        state = dict(state)
    defaults = default_relationship_state()
    for key, value in defaults.items():
        state.setdefault(key, value)
    state["version"] = 4
    return {
        **state,
        "familiarity": clamp_float(state.get("familiarity"), 0, 1, defaults["familiarity"]),
        "trust": clamp_float(state.get("trust"), 0, 1, defaults["trust"]),
        "teasingLevel": clamp_float(state.get("teasingLevel"), 0, 1, defaults["teasingLevel"]),
        "careLevel": clamp_float(state.get("careLevel"), 0, 1, defaults["careLevel"]),
        "stability": clamp_float(state.get("stability"), 0, 1, defaults["stability"]),
        "interactionCount": clamp_int(state.get("interactionCount"), 0, 1000000, 0),
        "positiveEvents": clamp_int(state.get("positiveEvents"), 0, 1000000, 0),
        "sharedRoutineEvents": clamp_int(state.get("sharedRoutineEvents"), 0, 1000000, 0),
        "repairEvents": clamp_int(state.get("repairEvents"), 0, 1000000, 0),
        "dignityViolationCount": clamp_int(state.get("dignityViolationCount"), 0, 5, 0),
        "dignityLocked": bool(state.get("dignityLocked")),
        "coldShoulder": bool(state.get("coldShoulder")),
        "coldShoulderReason": str(state.get("coldShoulderReason") or "")[:160],
        "lastBoundaryAssessment": str(state.get("lastBoundaryAssessment") or "none")[:48],
        "commitmentStatus": (
            "confirmed"
            if str(state.get("commitmentStatus") or "").strip().lower() == "confirmed"
            else "unconfirmed"
        ),
        "commitmentLabel": str(state.get("commitmentLabel") or "")[:80],
        "commitmentConfirmedAt": str(state.get("commitmentConfirmedAt") or "")[:80],
        "commitmentSourceTurnIds": unique_strings(
            state.get("commitmentSourceTurnIds")
            if isinstance(state.get("commitmentSourceTurnIds"), list)
            else []
        )[-24:],
        "milestones": unique_strings(state.get("milestones") if isinstance(state.get("milestones"), list) else [])[-24:],
    }


def read_relationship_state() -> dict[str, Any]:
    with RELATIONSHIP_LOCK:
        state = read_json_file(
            scoped_data_path(RELATIONSHIP_STATE_PATH),
            default_relationship_state(),
        )
    return normalize_relationship_state(state)


def read_relationship_state_for_scope(scope: str) -> dict[str, Any]:
    """Read one relationship domain without changing the request's active domain.

    The developer dashboard uses this as a read-only inspection boundary.  A
    normal-mode snapshot must never become the active developer relationship
    state merely because it was rendered in the diagnostics UI.
    """

    requested_scope = normalize_storage_scope(scope)
    token = REQUEST_STORAGE_SCOPE.set(requested_scope)
    try:
        return read_relationship_state()
    finally:
        REQUEST_STORAGE_SCOPE.reset(token)


def read_release_relationship_state() -> dict[str, Any]:
    """Read the installed release profile without activating or modifying it."""

    path = _default_data_dir / "relationship_state.json"
    return normalize_relationship_state(read_json_file(path, default_relationship_state()))


def write_relationship_state(state: dict[str, Any]) -> dict[str, Any]:
    with RELATIONSHIP_LOCK:
        path = scoped_data_path(RELATIONSHIP_STATE_PATH)
        path.parent.mkdir(parents=True, exist_ok=True)
        state["generation"] = _safe_nonnegative_int(state.get("generation")) + 1
        state["updatedAt"] = now_iso()
        payload = json.dumps(state, ensure_ascii=False, indent=2)
        temporary = path.with_name(
            f".{path.name}.{threading.get_ident()}.{uuid.uuid4().hex}.tmp"
        )
        temporary.write_text(payload, encoding="utf-8")
        os.replace(temporary, path)
    return state


BOUNDARY_ASSESSMENT_KINDS = {
    "none",
    "ordinary_conflict",
    "severe_personal_insult",
    "sincere_apology",
}


def normalize_boundary_assessment(value: Any) -> dict[str, Any]:
    raw = value if isinstance(value, dict) else {}
    kind = str(raw.get("kind") or raw.get("type") or "none").strip().lower()
    aliases = {
        "normal": "none",
        "criticism": "ordinary_conflict",
        "ordinary_argument": "ordinary_conflict",
        "personal_abuse": "severe_personal_insult",
        "personality_insult": "severe_personal_insult",
        "apology": "sincere_apology",
    }
    kind = aliases.get(kind, kind)
    if kind not in BOUNDARY_ASSESSMENT_KINDS:
        kind = "none"
    return {
        "kind": kind,
        "severity": clamp_int(raw.get("severity"), 0, 3, 0),
        "confidence": clamp_float(raw.get("confidence"), 0, 1, 0.5),
        "reason": str(raw.get("reason") or "")[:240],
    }


def dignity_boundary_context_prompt(
    state: dict[str, Any],
    preflight_assessment: dict[str, Any] | None = None,
    *,
    require_output_field: bool = True,
) -> str:
    count = clamp_int(state.get("dignityViolationCount"), 0, 5, 0)
    assessment = normalize_boundary_assessment(preflight_assessment)
    return "\n".join([
        DIGNITY_BOUNDARY_RULE,
        f"当前严重人格侮辱专用累计次数：{count}/5。这个数值与普通 annoyed/furious 情绪完全分开。",
        (
            "当前处于 furious 冷处理；除非独立判断确认真诚道歉，否则普通消息只能回复“哼”。"
            if state.get("coldShoulder") else
            "当前未处于 furious 冷处理。"
        ),
        "本轮独立预判：" + json.dumps(assessment, ensure_ascii=False),
        (
            (
                "最终 JSON 必须包含 boundaryAssessment={kind,severity,confidence,reason}。"
                if require_output_field else
                "本轮边界判断由后端采用上述独立预判，普通核心对话不要重复输出 boundaryAssessment。"
            )
            + "kind 只能是 none、ordinary_conflict、severe_personal_insult、sincere_apology。"
            + "普通争论和批评必须标 ordinary_conflict 或 none，不能为了表现生气而误计数。"
        ),
    ])


def classify_dignity_message_with_model(
    settings: dict[str, Any],
    user_message: str,
    recent_messages: list[dict[str, Any]],
    *,
    request_id: str = "",
) -> dict[str, Any]:
    """Classify boundary semantics; never infer a violation from a keyword."""

    payload: dict[str, Any] = {
        "model": settings["apiModel"],
        "temperature": 0.0,
        "max_tokens": 180,
        "messages": [
            {"role": "system", "content": (
                "你是对话边界分类器，只判断当前用户消息，不生成台词。"
                "severe_personal_insult 仅指直接贬低 AMADEUS 的人格、尊严、存在价值或以羞辱主体为目的的人身攻击；"
                "普通争论、粗鲁抱怨、对回答能力的具体批评、熟人吐槽和带脏字但不贬低人格的冲突都算 ordinary_conflict。"
                "sincere_apology 必须明确承担责任、表达停止伤害的意愿，且不能是讽刺、敷衍、条件式道歉或同时继续辱骂。"
                "理解否定、引用、假设和上下文，任何单个词都不能决定结果。只输出 JSON："
                "{\"kind\":\"none|ordinary_conflict|severe_personal_insult|sincere_apology\","
                "\"severity\":0,\"confidence\":0.0,\"reason\":\"简短依据\"}。"
            )},
            *[
                {
                    "role": "assistant" if item.get("role") == "assistant" else "user",
                    "content": str(item.get("content") or "")[:800],
                }
                for item in recent_messages[-4:]
                if isinstance(item, dict) and str(item.get("content") or "").strip()
            ],
            {"role": "user", "content": str(user_message or "")[:2400]},
        ],
    }
    if settings.get("useResponseFormat"):
        payload["response_format"] = {"type": "json_object"}
    if "deepseek.com" in settings["apiEndpoint"]:
        payload["thinking"] = {"type": "disabled"}
    content = send_upstream_chat_payload(
        settings,
        payload,
        timeout=25,
        request_id=request_id,
        purpose="dignity_boundary_classifier",
    )
    return normalize_boundary_assessment(parse_json_object(content))


