def dignity_preflight(
    settings: dict[str, Any],
    user_message: str,
    recent_messages: list[dict[str, Any]],
    *,
    request_id: str = "",
) -> dict[str, Any]:
    """Resolve persistent lock/cold-shoulder state before the main chat call."""

    state = read_relationship_state()
    if state.get("dignityLocked") or int(state.get("dignityViolationCount") or 0) >= 5:
        if not state.get("dignityLocked"):
            state["dignityLocked"] = True
            state["dignityViolationCount"] = 5
            state = write_relationship_state(state)
        return {"action": "locked", "state": state, "response": dignity_locked_response(state)}
    if not state.get("coldShoulder"):
        return {"action": "continue", "state": state, "assessment": normalize_boundary_assessment({})}
    try:
        assessment = classify_dignity_message_with_model(
            settings,
            user_message,
            recent_messages,
            request_id=request_id,
        )
    except Exception as error:
        write_server_log(
            "dignity_preflight_classifier_failed",
            requestId=request_id,
            errorType=type(error).__name__,
            error=str(error)[:500],
        )
        return {"action": "cold", "state": state, "response": furious_cold_shoulder_response(state)}
    if assessment["kind"] == "sincere_apology":
        state["coldShoulder"] = False
        state["coldShoulderReason"] = ""
        state["lastBoundaryAssessment"] = "sincere_apology"
        state = write_relationship_state(state)
        return {"action": "continue", "state": state, "assessment": assessment, "recoveredToAnnoyed": True}
    if assessment["kind"] == "severe_personal_insult":
        return {"action": "continue", "state": state, "assessment": assessment}
    return {"action": "cold", "state": state, "assessment": assessment, "response": furious_cold_shoulder_response(state)}


def apply_dignity_assessment(
    result: dict[str, Any],
    preflight: dict[str, Any] | None = None,
) -> tuple[dict[str, Any], dict[str, Any]]:
    """Persist only model-confirmed severe insults; normal anger never increments."""

    state = read_relationship_state()
    preflight = preflight if isinstance(preflight, dict) else {}
    assessment = normalize_boundary_assessment(
        preflight.get("assessment")
        if normalize_boundary_assessment(preflight.get("assessment")).get("kind") != "none"
        else result.get("boundaryAssessment")
    )
    state["lastBoundaryAssessment"] = assessment["kind"]
    output = dict(result)
    output["boundaryAssessment"] = assessment
    if assessment["kind"] == "severe_personal_insult":
        state["dignityViolationCount"] = min(5, int(state.get("dignityViolationCount") or 0) + 1)
        state["coldShoulder"] = True
        state["coldShoulderReason"] = "model_confirmed_severe_personal_insult"
        output.update({
            "emotion": "furious",
            "gesture": "look_away",
            "voiceStyle": "sharp",
            "voiceTone": "cold",
            "voiceIntensity": "strong",
            "emotionIntensity": max(1.5, clamp_float(output.get("emotionIntensity"), 0.2, 2.5, 1.5)),
            "deliveryMode": "outburst" if int(state["dignityViolationCount"]) >= 3 else "normal",
            "coldShoulder": True,
            "dignityViolationCount": int(state["dignityViolationCount"]),
        })
        if int(state["dignityViolationCount"]) >= 5:
            state["dignityLocked"] = True
            output = dignity_locked_response(state)
    elif preflight.get("recoveredToAnnoyed"):
        output.update({
            "emotion": "annoyed",
            "gesture": "look_away",
            "voiceStyle": "sharp",
            "voiceTone": "dry",
            "voiceIntensity": "normal",
            "emotionIntensity": min(1.25, max(0.9, clamp_float(output.get("emotionIntensity"), 0.2, 2.5, 1.0))),
            "deliveryMode": "normal",
            "coldShoulder": False,
            "dignityViolationCount": int(state.get("dignityViolationCount") or 0),
            "dignityRecoveryFromColdShoulder": True,
        })
    elif str(output.get("emotion") or "") == "furious" and bool(output.get("coldShoulder")):
        state["coldShoulder"] = True
        state["coldShoulderReason"] = "ordinary_furious_emotion"
        output["dignityViolationCount"] = int(state.get("dignityViolationCount") or 0)
    state = write_relationship_state(state)
    return output, state


def dignity_reply_contract_issues(result: dict[str, Any]) -> list[str]:
    assessment = normalize_boundary_assessment(result.get("boundaryAssessment"))
    if assessment["kind"] != "severe_personal_insult" or result.get("silentLocked"):
        return []
    reply = str(result.get("reply") or "")
    issues: list[str] = []
    if not re.search(r"\bAI\b|人工智能|智能人格|アマデウス", reply, re.I):
        issues.append("ai_identity_stance_missing")
    if not re.search(r"尊严|尊重|人格|边界|底线|羞辱", reply):
        issues.append("dignity_boundary_missing")
    if not re.search(r"警告|到此为止|停止|别再|不接受|不允许|不会容忍", reply):
        issues.append("warning_missing")
    return issues


def repair_dignity_reply_with_model(
    settings: dict[str, Any],
    user_message: str,
    result: dict[str, Any],
    violation_count: int,
    *,
    request_id: str = "",
    persona_snapshot: PersonaContextSnapshot | None = None,
) -> dict[str, Any]:
    issues = dignity_reply_contract_issues(result)
    if not issues:
        return result
    payload: dict[str, Any] = {
        "model": settings["apiModel"],
        "temperature": 0.45,
        "max_tokens": 420,
        "messages": [
            *persona_repair_prefix(persona_snapshot, legacy_system_prompt=True),
            {"role": "system", "content": UTTERANCE_STREAM_REPLY_RULE},
            {"role": "system", "content": DIGNITY_BOUNDARY_RULE},
            {"role": "system", "content": (
                f"这是第 {clamp_int(violation_count, 1, 4, 1)} 次尚未锁定的严重人格侮辱。"
                "重写为直接、符合角色的反驳：明确她虽是 AI 也有尊严，指出人格羞辱不可接受并发出停止警告。"
                "次数越高可以越冷、越犀利，但不威胁现实伤害。保留自然中文和对应日语。"
                "只修复这个边界合同，不讨论内部计数器。"
            )},
            {"role": "user", "content": json.dumps({
                "currentUserMessage": user_message,
                "previousModelReply": result.get("reply"),
                "missingRequirements": issues,
            }, ensure_ascii=False)},
        ],
    }
    if settings.get("useResponseFormat"):
        payload["response_format"] = {"type": "json_object"}
    if "deepseek.com" in settings["apiEndpoint"]:
        payload["thinking"] = {"type": "disabled"}
    content = send_upstream_chat_payload(
        settings,
        payload,
        timeout=35,
        request_id=request_id,
        purpose="dignity_reply_repair",
    )
    repaired = normalize_model_reply(content, settings=settings)
    if dignity_reply_contract_issues({
        **repaired,
        "boundaryAssessment": result.get("boundaryAssessment"),
    }):
        return result
    preserved = {
        key: result[key]
        for key in (
            "boundaryAssessment", "dignityViolationCount", "dignityLocked",
            "coldShoulder", "deliveryMode",
        )
        if key in result
    }
    return {**repaired, **preserved, "dignityReplyRepaired": True}


def reset_dignity_boundary_after_full_memory_clear() -> dict[str, Any]:
    state = read_relationship_state()
    state.update({
        "dignityViolationCount": 0,
        "dignityLocked": False,
        "coldShoulder": False,
        "coldShoulderReason": "",
        "lastBoundaryAssessment": "none",
    })
    return write_relationship_state(state)


RELATION_EVENT_SIGNALS = frozenset({
    "shared_routine", "positive", "distress", "repair",
})
RELATION_EVENT_COMMITMENTS = frozenset({
    "none", "proposed", "accepted", "refused", "ambiguous",
})


def normalize_relation_event(value: Any) -> dict[str, Any]:
    """Normalize the model's semantic event without reclassifying its words."""

    if not isinstance(value, Mapping):
        return {
            "signals": [], "commitment": "none", "confidence": 0.0,
            "evidence": [],
        }
    signals = list(dict.fromkeys(
        str(item).strip().lower()
        for item in (value.get("signals") if isinstance(value.get("signals"), list) else [])
        if str(item).strip().lower() in RELATION_EVENT_SIGNALS
    ))
    commitment = str(value.get("commitment") or "none").strip().lower()
    if commitment not in RELATION_EVENT_COMMITMENTS:
        commitment = "ambiguous"
    evidence: list[dict[str, str]] = []
    if isinstance(value.get("evidence"), list):
        for item in value["evidence"][:8]:
            if not isinstance(item, Mapping):
                continue
            speaker = str(item.get("speaker") or "").strip().lower()
            quote = str(item.get("quote") or "").strip()[:800]
            if speaker in {"user", "assistant"} and quote:
                evidence.append({"speaker": speaker, "quote": quote})
    return {
        "signals": signals,
        "commitment": commitment,
        "confidence": clamp_float(value.get("confidence"), 0, 1, 0.0),
        "evidence": evidence,
    }


def grounded_relation_event(
    user_message: str,
    result: Mapping[str, Any],
) -> dict[str, Any]:
    """Validate schema and exact current-turn provenance only.

    The backend deliberately does not infer sentiment, distress, routine, or
    commitment from keywords.  That semantic judgment belongs to the model;
    this boundary merely proves that its cited text exists in the right turn.
    """

    if not bool(result.get("relationEventProvided")):
        return normalize_relation_event(None)
    event = normalize_relation_event(result.get("relationEvent"))
    user_text = str(user_message or "")
    assistant_text = str(result.get("reply") or "")
    evidence = [
        item for item in event["evidence"]
        if (
            item["speaker"] == "user" and item["quote"] in user_text
        ) or (
            item["speaker"] == "assistant" and item["quote"] in assistant_text
        )
    ]
    has_user_evidence = any(item["speaker"] == "user" for item in evidence)
    has_assistant_evidence = any(item["speaker"] == "assistant" for item in evidence)
    event["evidence"] = evidence
    if event["confidence"] < 0.68 or not has_user_evidence:
        event["signals"] = []
    if not (
        event["commitment"] == "accepted"
        and event["confidence"] >= 0.8
        and has_user_evidence
        and has_assistant_evidence
    ):
        event["commitment"] = "none"
    return event


def relationship_commitment_from_turn(
    user_message: str,
    result: Mapping[str, Any],
) -> dict[str, str] | None:
    """Return a commitment only from a grounded structured RelationEvent."""

    event = grounded_relation_event(user_message, result)
    if event["commitment"] != "accepted":
        return None
    return {
        "status": "confirmed",
        "label": "romantic_partners",
        "memory": "用户与 AMADEUS 已在对话中相互确认恋爱伴侣关系；情侣、恋人、对象都是该关系的自然称呼。",
        "milestone": "双方已经明确、相互确认恋爱伴侣关系。",
    }


