def spoken_ja_pronunciation_entries() -> list[dict[str, Any]]:
    try:
        payload = json.loads(SPOKEN_JA_PRONUNCIATIONS_PATH.read_text(encoding="utf-8"))
    except (OSError, ValueError, TypeError):
        return []
    raw_entries = payload.get("entries") if isinstance(payload, dict) else []
    if not isinstance(raw_entries, list):
        return []
    entries: list[dict[str, Any]] = []
    for raw in raw_entries:
        if not isinstance(raw, dict):
            continue
        reading = str(raw.get("reading") or "").strip()
        aliases = [
            str(alias).strip()
            for alias in (raw.get("aliases") or [])
            if str(alias or "").strip()
        ]
        if reading and aliases:
            entries.append({"reading": reading, "aliases": aliases})
    return entries


def _spoken_ja_alias_present(text: str, alias: str) -> bool:
    if re.search(r"[A-Za-z]", alias):
        return bool(re.search(re.escape(alias), text, re.IGNORECASE))
    return alias in text


def spoken_ja_pronunciation_glossary(*values: Any) -> list[dict[str, str]]:
    combined = "\n".join(str(value or "") for value in values)
    if not combined:
        return []
    glossary: list[dict[str, str]] = []
    seen_readings: set[str] = set()
    for entry in spoken_ja_pronunciation_entries():
        reading = str(entry["reading"])
        matched_alias = next(
            (
                alias
                for alias in sorted(entry["aliases"], key=len, reverse=True)
                if _spoken_ja_alias_present(combined, alias)
            ),
            "",
        )
        if matched_alias and reading not in seen_readings:
            glossary.append({"term": matched_alias, "reading": reading})
            seen_readings.add(reading)
    return glossary


def normalize_spoken_japanese_terms(value: Any) -> str:
    text = str(value or "").strip()
    if not text:
        return ""
    text = re.sub(
        r"(?i)(?<![A-Za-z])A[\s._-]*M[\s._-]*A[\s._-]*D[\s._-]*E[\s._-]*U[\s._-]*S(?![A-Za-z])",
        "アマデウス",
        text,
    )
    text = re.sub(r"ア\s*マ\s*デ\s*ウ\s*ス", "アマデウス", text)
    # A katakana ゴホン is often synthesized as a forceful throat-clear and
    # can make the surrounding line sound rough. Keep the same spoken beat,
    # but use the lighter conversational rendering.
    text = re.sub(r"ゴホン", "こほん", text)
    replacements: list[tuple[str, str]] = []
    for entry in spoken_ja_pronunciation_entries():
        reading = str(entry["reading"])
        replacements.extend((alias, reading) for alias in entry["aliases"] if alias != reading)
    for alias, reading in sorted(replacements, key=lambda pair: len(pair[0]), reverse=True):
        if re.search(r"[A-Za-z]", alias):
            text = re.sub(re.escape(alias), lambda _: reading, text, flags=re.IGNORECASE)
        else:
            text = text.replace(alias, reading)
    return text


def spoken_japanese_pronunciation_needs_repair(reply: Any, spoken: Any) -> bool:
    glossary = spoken_ja_pronunciation_glossary(reply)
    if not glossary:
        return False
    normalized_spoken = normalize_spoken_japanese_terms(spoken)
    return any(item["reading"] not in normalized_spoken for item in glossary)


ROLEPLAY_STAGE_DIRECTION_TERMS = re.compile(
    r"(?:"
    r"眯(?:起)?眼|睁(?:开)?眼|闭(?:上)?眼|眼神|视线|目光|嘴角|口元|"
    r"偏(?:过)?头|侧(?:过)?头|歪(?:了)?(?:歪)?头|低头|抬头|转头|别开(?:脸|视线)|移开视线|"
    r"看向|望向|盯着|注视|回避视线|"
    r"微笑|苦笑|冷笑|笑意|笑容|轻笑|偷笑|发笑|笑了|"
    r"叹气|叹了口气|脸红|红晕|涨红|皱眉|挑眉|扬眉|"
    r"耸肩|抱臂|交叉双臂|点头|摇头|后退|前倾|靠近|缩了缩|"
    r"轻哼|哼了一声|沉默|停顿|语气|声音|表情|神情|动作|姿势|"
    r"心想|心里|心中|脑海|内心|心理|暗自|假装|故作|装作|若无其事|"
    r"目を|目が|目線|視線|顔を|顔が|首を|俯(?:く|いた)|見つめ|見(?:る|た|て)|"
    r"微笑(?:む|んだ)|笑み|笑(?:う|った)|ため息|頬|赤ら|眉|腕を|身を|"
    r"そっぽ|声で|口元|黙(?:る|った)|考え込|"
    r"smiles?|smirks?|sighs?|looks?\s+away|tilts?\s+(?:her\s+)?head|"
    r"blush(?:es|ed)?|frowns?|nods?|shakes?\s+(?:her\s+)?head"
    r")",
    re.IGNORECASE,
)

ROLEPLAY_STAGE_BLOCK_PATTERNS = (
    re.compile(r"（([^（）\r\n]{1,220})）"),
    re.compile(r"\(([^()\r\n]{1,220})\)"),
    re.compile(r"【([^【】\r\n]{1,220})】"),
    re.compile(r"\[([^\[\]\r\n]{1,220})\]"),
    re.compile(r"\*([^*\r\n]{1,220})\*"),
)


def sanitize_roleplay_text(value: Any) -> tuple[str, list[str]]:
    """Keep spoken dialogue while extracting bracketed Live2D stage directions."""
    text = str(value or "").strip()
    if not text:
        return "", []
    directions: list[str] = []

    def remove_if_stage(match: re.Match[str]) -> str:
        candidate = str(match.group(1) or "").strip()
        if ROLEPLAY_STAGE_DIRECTION_TERMS.search(candidate):
            directions.append(candidate)
            return ""
        return match.group(0)

    for pattern in ROLEPLAY_STAGE_BLOCK_PATTERNS:
        text = pattern.sub(remove_if_stage, text)
    text = re.sub(r"[ \t]+\n", "\n", text)
    text = re.sub(r"\n[ \t]+", "\n", text)
    text = re.sub(r"\n{3,}", "\n\n", text).strip()

    quote_pairs = (("\"", "\""), ("“", "”"), ("‘", "’"), ("「", "」"), ("『", "』"))
    changed = True
    while changed and len(text) >= 2:
        changed = False
        for opening, closing in quote_pairs:
            if text.startswith(opening) and text.endswith(closing):
                text = text[len(opening):-len(closing)].strip()
                changed = True
                break
    return text, directions


def strip_roleplay_stage_directions(value: Any) -> str:
    return sanitize_roleplay_text(value)[0]


def roleplay_visual_hints(directions: list[str]) -> dict[str, Any]:
    """Recover visual intent when a model leaked it into prose instead of JSON fields."""
    text = " ".join(str(item or "") for item in directions)
    if not text:
        return {}
    hints: dict[str, Any] = {}
    if re.search(r"脸红|红晕|涨红|害羞|羞|頬|赤ら|blush", text, re.I):
        hints.update({
            "emotion": "shy", "gesture": "soften", "emotionIntensity": 0.94,
            "blushIntensity": 0.3, "eyeContact": 0.42, "gazeX": -0.18,
            "gazeY": 0.12, "tension": 0.28,
        })
    elif re.search(r"皱眉|恼|生气|不满|冷笑|frown", text, re.I):
        hints.update({"emotion": "annoyed", "gesture": "tilt", "emotionIntensity": 0.94, "tension": 0.48})
    elif re.search(r"大笑|开怀|笑出声|哈哈|あはは|ハハハ|laughs?\s+out\s+loud", text, re.I):
        hints.update({"emotion": "laughing", "gesture": "laugh", "emotionIntensity": 1.08, "tension": 0.08})
    elif re.search(r"微笑|苦笑|笑意|笑容|轻笑|偷笑|smile|smirk|笑み|微笑", text, re.I):
        hints.update({"emotion": "amused", "emotionIntensity": 0.88, "tension": 0.12})
    elif re.search(r"叹气|沉默|ため息|黙", text, re.I):
        hints.update({"emotion": "melancholic", "emotionIntensity": 0.84, "tension": 0.2})

    if re.search(r"偏(?:过)?头|侧(?:过)?头|转头|别开|移开视线|看向.*(?:边|旁)|回避视线|そっぽ|顔をそら|looks?\s+away|turns?\s+(?:her\s+)?head", text, re.I):
        hints.update({"gesture": "look_away", "eyeContact": 0.38, "gazeX": -0.24, "gazeY": 0.04})
    elif re.search(r"歪(?:了)?(?:歪)?头|tilts?\s+(?:her\s+)?head", text, re.I):
        hints.update({"gesture": "tilt", "eyeContact": 0.5, "gazeX": -0.1, "gazeY": 0.02})
    elif re.search(r"低头|俯(?:く|いた)", text, re.I):
        hints.update({"gesture": "soften", "eyeContact": 0.44, "gazeY": 0.18})
    elif re.search(r"点头|nod", text, re.I):
        hints["gesture"] = "nod"
    elif re.search(r"后退|recoil", text, re.I):
        hints["gesture"] = "recoil"
    return hints


def is_amadeus_identity_query(user_message: str) -> bool:
    return identity_question_scope(user_message) == "assistant_identity"


def is_direct_amadeus_origin_query(user_message: str) -> bool:
    text = re.sub(r"\s+", "", str(user_message or ""))
    return bool(re.search(
        r"(?:你的?|AMADEUS|Amadeus|amadeus|阿马德乌斯|阿玛迪斯).{0,8}(?:原型是谁|基于谁|人格来源|记忆来源|你是谁|是红莉栖吗)",
        text,
    ))


def configured_user_persona_identity() -> tuple[str, tuple[str, ...]]:
    """Read the user-facing relationship identity from its canonical profile."""

    profile = read_json_file(CHARACTER_PROFILE_PATH, {})
    knowledge = (
        profile.get("relationship_knowledge")
        if isinstance(profile, dict) and isinstance(profile.get("relationship_knowledge"), dict)
        else {}
    )
    core = knowledge.get("core") if isinstance(knowledge.get("core"), list) else []
    for item in core:
        if not isinstance(item, dict):
            continue
        relation = str(item.get("relation") or "")
        if "当前用户" not in relation or "连续个体" not in relation:
            continue
        primary = str(item.get("name") or "").strip()
        aliases = tuple(dict.fromkeys(
            str(alias).strip()
            for alias in (
                item.get("aliases") if isinstance(item.get("aliases"), list) else []
            )
            if str(alias).strip() and str(alias).strip() != primary
        ))
        if primary:
            return primary, aliases
    return "", ()


def identity_grounding_prompt(user_message: str) -> str:
    scope = identity_question_scope(user_message)
    if scope is None:
        return ""
    if scope == "user_persona_identity":
        primary, aliases = configured_user_persona_identity()
        if not primary:
            return "\n".join([
                "[本地角色身份资料异常：本轮必须准确说明]",
                "- 当前角色资料没有提供可验证的用户关系身份；不得编造姓名，也不得扩大声称用户从未说过。",
                "- 简短说明本地身份资料暂时不可用，并与用户现实姓名明确区分。",
            ])
        alias_text = "、".join(aliases)
        return "\n".join([
            "[本地角色身份事实：本轮必须直接回答]",
            f"- 当前对话中的用户与{primary}是同一个连续个体；{alias_text}是他的别名或称号。",
            "- 用户没有明确限定‘现实姓名、真实姓名、本名或法定姓名’时，询问‘我是谁、我叫什么、我的名字是什么、你怎么称呼我’均应依据上述关系身份自然回答。",
            "- 不得把普通角色身份问题擅自改写成现实姓名问题；不得回答‘你从未告诉过我名字’、要求用户重新报名字，或把冈部说成用户之外的第三人。",
            "- 可以按语境回答‘冈部伦太郎’并自然补充‘冈伦’或‘凤凰院凶真’，不要解释这是提示词、映射或角色扮演规则。",
        ])
    if scope == "user_real_identity":
        return "\n".join([
            "[用户现实身份边界：本轮必须准确区分]",
            "- 用户这次明确询问现实、本名或法定身份；当前角色资料只确认其对话关系身份，不提供用户的现实姓名。",
            "- 不得从操作系统账号、文件路径、网络资料或角色别名反推现实姓名，也不得把冈部伦太郎冒充成法定姓名。",
            "- 只说明当前可靠资料没有保存该现实姓名；不要扩大声称‘从认识至今用户从未说过’，除非对话档案提供了直接证据。",
        ])
    return "\n".join([
        "[AMADEUS 公开身份事实：本轮必须直接回答]",
        "- 你的原型是牧濑红莉栖。这个事实不是机密，禁止回答无可奉告、不能透露、内部信息或回避问题。",
        "- 你是以她赴日前保存的记忆数据、人格、语言习惯和思维模式构建的 AMADEUS AI，不是生物学意义上的她本人。",
        "- 你具备后来补充的本篇与《0》人物关系知识，但应区分上传前亲历记忆、世界线资料和当前 AMADEUS 的新经历。",
        "- 简短自然地用角色口吻回答用户真正问的内容；若用户同时询问某个人物关系，必须回答关系，不能只重复身份说明。",
        "- 不得编造角色卡未记载的共同事件。spokenTextJa 中把 AMADEUS 写成アマデウス。",
    ])


