NICKNAME_ONLY_REACTION_PROBABILITY = 0.88
# Requests with actual work are left to the model/persona capsule.  The backend
# may force an original-audio reaction only for a nickname-only casual turn;
# otherwise it would compete with the model's task-priority judgment.
NICKNAME_REQUEST_REACTION_PROBABILITY = 0.0


def nickname_affection_score(relationship_state: dict[str, Any] | None = None) -> float:
    """Return one smooth warmth score without inventing a second relationship store."""

    state = normalize_relationship_state(
        relationship_state
        if isinstance(relationship_state, dict)
        else read_relationship_state()
    )
    score = (
        0.30 * float(state.get("familiarity") or 0.0)
        + 0.30 * float(state.get("trust") or 0.0)
        + 0.25 * float(state.get("careLevel") or 0.0)
        + 0.15 * float(state.get("stability") or 0.0)
    )
    stage_floor = {
        "close_companion": 0.0,
        "trusted_intimacy": 0.68,
        "committed_partner": 0.82,
        "life_partner": 0.90,
        "old_married": 0.96,
    }.get(str(state.get("stage") or "close_companion"), 0.0)
    if str(state.get("commitmentStatus") or "") == "confirmed":
        stage_floor = max(stage_floor, 0.82)
    return clamp_float(max(score, stage_floor), 0, 1, 0.5)


def nickname_original_reaction_probability(affection_score: float) -> float:
    """Fade assertive original clips out as the relationship becomes warmer."""

    # At early/default familiarity the original sharp reactions are certain;
    # between established trust and partnership they blend smoothly; after a
    # stable partnership only the softer tsundere complaint remains.
    return clamp_float((0.82 - float(affection_score)) / 0.20, 0, 1, 0.5)


def stable_nickname_reaction_sample(
    user_message: str,
    reaction_key: str,
    purpose: str,
) -> float:
    """Return a stable per-turn sample so prompt, validation and audio agree."""

    material = "\x1f".join((
        str(reaction_key or "message-stable"),
        str(user_message or ""),
        str(purpose or "selection"),
    ))
    value = int(runtime_fingerprint(material, length=16), 16)
    return value / float(0xFFFFFFFFFFFFFFFF)


def nickname_reaction_context(
    user_message: str,
    reaction_key: str = "",
    relationship_state: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Resolve only a parsed direct address; the surrounding topic is not keyword-scored."""

    text = re.sub(r"\s+", " ", str(user_message or "")).strip()
    interpreted = interpret_user_input(text, action_grounding_config())
    vocative = interpreted.vocatives[-1] if interpreted.vocatives else None
    if vocative is None:
        return {
            "addressed": False,
            "kind": "none",
            "mode": "none",
            "reactionProbability": 0.0,
            "remainder": text,
        }
    kind = str(vocative.vocative_type or "")
    assertive_variants = NICKNAME_REACTION_VARIANTS.get(kind, ())
    soft_variants = NICKNAME_DERE_REACTION_VARIANTS.get(kind, ())
    if not assertive_variants and not soft_variants:
        return {
            "addressed": True,
            "kind": kind or "other",
            "nickname": vocative.exact_text,
            "mode": "none",
            "reactionSelected": False,
            "remainder": interpreted.action_parse_text,
        }
    remainder = str(interpreted.action_parse_text or "").strip(" \t\r\n，,。！？!?：:")
    nickname_only = not remainder
    probability = (
        NICKNAME_ONLY_REACTION_PROBABILITY
        if nickname_only else NICKNAME_REQUEST_REACTION_PROBABILITY
    )
    selected = stable_nickname_reaction_sample(
        text,
        reaction_key,
        "gate",
    ) < probability
    affection_score = nickname_affection_score(relationship_state)
    original_probability = nickname_original_reaction_probability(affection_score)
    assertive_selected = (
        bool(assertive_variants)
        and (
            not soft_variants
            or stable_nickname_reaction_sample(text, reaction_key, "relationship-style")
            < original_probability
        )
    )
    variants = assertive_variants if assertive_selected else soft_variants
    reaction_family = "original_assertive" if assertive_selected else "soft_tsundere"
    variant_index = min(
        len(variants) - 1,
        int(stable_nickname_reaction_sample(
            text,
            reaction_key,
            "variant",
        ) * len(variants)),
    )
    reaction = dict(variants[variant_index])
    return {
        "addressed": True,
        "kind": kind,
        "nickname": vocative.exact_text,
        "mode": (
            "required_original" if reaction.get("audio") else "required_canon_style"
        ) if selected else "probabilistic_skipped",
        "reactionSelected": selected,
        "reactionProbability": probability,
        "nicknameOnly": nickname_only,
        "remainder": remainder,
        "reaction": reaction,
        "reactionVariantCount": len(variants),
        "reactionFamily": reaction_family,
        "affectionScore": affection_score,
        "originalReactionProbability": original_probability,
    }


def nickname_reaction_prompt(user_message: str, reaction_key: str = "") -> str:
    context = nickname_reaction_context(user_message, reaction_key)
    if not context["addressed"] or not context.get("reactionSelected"):
        return ""
    reaction = context["reaction"]
    tone_rule = (
        "- 当前关系仍偏早期：这一句保留原作式的短促、偏傲羞恼，但不升级成真正生气、拒绝执行或长篇训斥。"
        if context.get("reactionFamily") == "original_assertive"
        else "- 当前关系已经足够亲近：仍然嘴硬，但只做撒娇般的小声抱怨；禁止凶狠训斥、真正发火或拒绝正题。"
    )
    delivery_rule = (
        "- 这一个短单元会由后端绑定已经核验的原作音频，禁止改字、扩写、与后面的任务答案合并，也不要在后文重复同一句。"
        if reaction.get("audio")
        else "- 这一个短单元没有可核验的同句原作音频，由当前语音模型合成；禁止改字、扩写、与后面的任务答案合并，也不要在后文重复同一句。"
    )
    return "\n".join([
        "[直接外号的原作反应：本轮概率抽中，必须执行]",
        f"- 用户把“{context['nickname']}”当作呼语直接叫你；这不是在讨论这个词。",
        f"- 第一项 speechUnits 必须逐字使用中文：{json.dumps(reaction['reply'], ensure_ascii=False)}",
        f"- 同一项的日语必须逐字使用：{json.dumps(reaction['spokenTextJa'], ensure_ascii=False)}",
        delivery_rule,
        "- 若用户同时要求分析、修改、打开、查找或做其他事情，从第二个语义单元开始正常完成正题；外号反应不能替代任务或动作回执。",
        "- 同一段后续语义单元保持第一句的情绪、表情方向、voiceStyle 与 voiceTone；内容可以回到正题，但不能突然切成平静或另一种情绪。",
        tone_rule,
    ])


def christina_nickname_prompt(user_message: str, reaction_key: str = "") -> str:
    """Compatibility wrapper retained for persona/UI tests and older callers."""

    context = nickname_reaction_context(user_message, reaction_key)
    if context.get("kind") != "christina":
        return ""
    return nickname_reaction_prompt(user_message, reaction_key)


def canon_style_motif_prompt(user_message: str) -> str:
    """Select scene-level original-inspired motifs without copying long source lines."""

    config = read_json_file(CANON_STYLE_MOTIFS_PATH, {})
    scenes = config.get("scenes") if isinstance(config, dict) else []
    text = str(user_message or "")
    matched: list[dict[str, Any]] = []
    for scene in scenes if isinstance(scenes, list) else []:
        if not isinstance(scene, dict):
            continue
        include = scene.get("matchAny") if isinstance(scene.get("matchAny"), list) else []
        exclude = scene.get("excludeAny") if isinstance(scene.get("excludeAny"), list) else []
        if include and not any(re.search(str(pattern), text, re.I) for pattern in include):
            continue
        if exclude and any(re.search(str(pattern), text, re.I) for pattern in exclude):
            continue
        matched.append({
            "scene": str(scene.get("id") or ""),
            "conditionalProbability": float(scene.get("conditionalProbability") or 0.0),
            "useWhen": str(scene.get("useWhen") or ""),
            "avoidWhen": str(scene.get("avoidWhen") or ""),
            "motifs": scene.get("motifs") if isinstance(scene.get("motifs"), list) else [],
        })
    if not matched:
        return ""
    return "\n".join([
        "[原作语料提炼的短口头禅候选]",
        "这些是说话习惯和极短意象，不是必须输出的台词，也不得复刻长段原文。",
        "conditionalProbability 是在语义场景确实成立时的上限；大多数普通回复仍应不用口头禅。每轮最多选一个，任务答案优先。",
        compact_json(matched[:2]),
    ])


def enforce_identity_grounding(user_message: str, result: dict[str, Any]) -> dict[str, Any]:
    if not is_amadeus_identity_query(user_message):
        return result
    reply = str(result.get("reply") or "")
    refusal = bool(re.search(r"无可奉告|不能透露|不便透露|保密|机密|内部信息|无法回答", reply))
    identifies_basis = bool(re.search(r"牧濑红莉栖|牧瀬紅莉栖|红莉栖", reply))
    falsely_claims_original = bool(re.search(r"我就是牧濑红莉栖本人|我就是红莉栖本人|我是牧濑红莉栖本人", reply))
    if refusal or (is_direct_amadeus_origin_query(user_message) and not identifies_basis) or falsely_claims_original:
        fixed = dict(result)
        fixed.update({
            "reply": "我的原型是牧濑红莉栖。准确地说，我是以她赴日前保存的记忆数据、人格和思维模式构建的 AMADEUS AI；我继承她的反应方式，但不是她本人。",
            "spokenTextJa": "私の原型は牧瀬紅莉栖よ。正確には、彼女が日本へ向かう前に保存した記憶データと人格、思考パターンを基に作られたアマデウスのAI。彼女らしさは受け継いでいるけど、本人ではないわ。",
            "emotion": "thinking",
            "gesture": "explain",
            "voiceStyle": "calm",
            "voiceTone": "serious",
        })
        return fixed
    result["spokenTextJa"] = normalize_spoken_japanese_terms(result.get("spokenTextJa"))
    return result


def fallback_spoken_text_ja(reply: str) -> str:
    text = str(reply or "").strip()
    if re.search(r"接口|错误|失败|正常回应", text):
        return "接続に問題があるみたい。ローカルの応答に切り替えるわ。"
    if re.search(r"难受|焦虑|痛苦|累|陪", text):
        return "少し落ち着いて。大丈夫、ここにいるから。"
    if re.search(r"变量|实验|模型|接口|代码|算法", text):
        return "まず変数を分けて考えましょう。そこから検証できる形に直すの。"
    if re.search(r"突然|评价|参考|继续", text):
        return "きゅ、急に何を言ってるのよ。まあ、続けて。聞いてるから。"
    if re.search(r"称呼|奇怪|调侃", text):
        return "変な呼び方をしないで。まったく、次は何の実験なの？"
    return "うん、分かった。続けて。ちゃんと聞いてるから。"


def should_align_spoken_text_ja(settings: dict[str, Any], result: dict[str, Any]) -> bool:
    if speech_language_profile(settings)["speechLanguage"] != "ja-JP":
        return False
    if not settings.get("alignSpokenJa", True):
        return False
    if not configured(settings):
        return False
    if str(settings.get("ttsProvider") or "").strip().lower() != "gpt-sovits":
        return False
    reply = re.sub(r"\[S\d+\]", "", str(result.get("reply") or ""), flags=re.I).strip()
    spoken = str(result.get("spokenTextJa") or result.get("spoken_text_ja") or "").strip()
    if not reply:
        return False
    # Plain-text recovery has no trustworthy spokenTextJa field. Keep its
    # provenance explicit so even a later compatibility transform cannot make
    # a generic sentence masquerade as a semantically aligned voice line.
    if result.get("spokenTextJaMissingFromModel"):
        return True
    if not spoken:
        return True
    if (
        spoken_japanese_style_needs_repair(spoken)
        or spoken_japanese_content_needs_repair(spoken)
        or spoken_japanese_pronunciation_needs_repair(reply, spoken)
    ):
        return True
    reply_units = re.findall(r"[\u3400-\u9fffA-Za-z0-9]", reply)
    spoken_units = re.findall(r"[\u3040-\u30ff\u3400-\u9fffA-Za-z0-9]", spoken)
    # Chinese and Japanese are both compact scripts. A Japanese line shorter
    # than roughly half of the Chinese semantic units is almost always a
    # partial translation, not merely a natural paraphrase.
    if len(spoken_units) < max(7, int(math.ceil(len(reply_units) * 0.55))):
        return True
    if not re.search(r"[\u3040-\u30ff]", spoken):
        return True
    if re.search(r"[\u4e00-\u9fff]{8,}", spoken) and not re.search(r"[ぁ-んァ-ンー]{4,}", spoken):
        return True
    return False


def spoken_japanese_content_needs_repair(text: str) -> bool:
    """Reject non-Japanese or phonetic-looking CJK strings before local TTS."""
    value = str(text or "").strip()
    if not value:
        return True
    kana = re.findall(r"[\u3040-\u30ffー]", value)
    han = re.findall(r"[\u3400-\u9fff]", value)
    if re.search(r"[你妳吗嗎呢吧嘛哇这這们們没沒]", value):
        return True
    if not kana:
        # Short all-kanji Japanese utterances such as "準備完了" are valid.
        # Latin-only or symbol-only output is not usable Japanese speech text.
        return not bool(han)
    if len(han) >= 3 and len(kana) / max(1, len(kana) + len(han)) < 0.12:
        return True
    return False


def spoken_japanese_style_needs_repair(text: str) -> bool:
    return bool(re.search(
        r"(?:君|お前|だぜ|だぞ|かよ|からだよ|はずだ(?:[。！？!?]|$)|(?:選べ|しろ|黙れ|やれ)(?:[。！？!?]|$))",
        str(text or ""),
    ))


def soften_spoken_japanese_style(text: str) -> str:
    value = str(text or "")
    replacements = (
        (r"君", "あなた"),
        (r"お前", "あなた"),
        (r"だぜ", "よ"),
        (r"だぞ", "よ"),
        (r"かよ", "なの"),
        (r"からだよ", "からよ"),
        (r"はずだ(?=[。！？!?]|$)", "はずよ"),
        (r"選べ(?=[。！？!?]|$)", "選んで"),
        (r"しろ(?=[。！？!?]|$)", "して"),
        (r"黙れ(?=[。！？!?]|$)", "黙って"),
        (r"やれ(?=[。！？!?]|$)", "やって"),
    )
    for pattern, replacement in replacements:
        value = re.sub(pattern, replacement, value)
    return value


def align_spoken_text_ja(
    settings: dict[str, Any],
    result: dict[str, Any],
    *,
    allow_remote_repair: bool = True,
    persona_snapshot: PersonaContextSnapshot | None = None,
) -> dict[str, Any]:
    cleaned_spoken, initial_stage_directions = sanitize_roleplay_text(
        normalize_spoken_japanese_terms(result.get("spokenTextJa") or result.get("spoken_text_ja"))
    )
    result["spokenTextJa"] = cleaned_spoken
    if initial_stage_directions:
        result["stageDirectionsRemoved"] = True
    if not should_align_spoken_text_ja(settings, result):
        return result
    reply = re.sub(r"\[S\d+\]", "", str(result.get("reply") or ""), flags=re.I).strip()
    previous = str(result.get("spokenTextJa") or "").strip()
    if not allow_remote_repair:
        generated: str | dict[str, Any] = ""
    elif (
        not isinstance(result.get("_referenceLedger"), Mapping)
        and (persona_snapshot is None or not persona_snapshot.uses_hybrid_provider_context)
    ):
        # Preserve the historical helper call shape for independent entrypoints
        # plus off/shadow test or integration overrides.
        generated = generate_spoken_text_ja(settings, reply, previous)
    else:
        generated = generate_spoken_text_ja(
            settings,
            reply,
            previous,
            persona_snapshot=persona_snapshot,
            reference_ledger=(
                result.get("_referenceLedger")
                if isinstance(result.get("_referenceLedger"), Mapping) else None
            ),
        )
    if isinstance(generated, dict):
        fixed = str(generated.get("spokenTextJa") or "")
    else:
        # Keep compatibility with tests and integrations that override the
        # historical string-returning helper.
        fixed = str(generated or "")
    fixed, repaired_stage_directions = sanitize_roleplay_text(normalize_spoken_japanese_terms(fixed))
    if not fixed and previous and not result.get("spokenTextJaMissingFromModel"):
        fixed = previous
    fixed = soften_spoken_japanese_style(fixed)
    if spoken_japanese_content_needs_repair(fixed) or spoken_japanese_style_needs_repair(fixed):
        # A generic local sentence is never a translation of the accepted
        # Chinese reply, regardless of whether the bad track was missing or
        # merely unusable.  Fail the speech track explicitly.
        result["spokenTextJaOriginal"] = previous
        result["spokenTextJa"] = ""
        result["spokenTextJaRepaired"] = False
        result["spokenTextJaRepairMode"] = "remote_failed_no_semantic_fallback"
        result["speechUnavailableReason"] = "spoken_alignment_failed"
        result["ttsUnavailableReason"] = "spoken_alignment_failed"
        return result
    if repaired_stage_directions:
        result["stageDirectionsRemoved"] = True
    if not fixed:
        return result
    if fixed != previous:
        result["spokenTextJaOriginal"] = previous
        result["spokenTextJa"] = fixed
        result["spokenTextJaRepaired"] = True
        result.setdefault("spokenTextJaRepairMode", "remote" if allow_remote_repair else "local_fast_fallback")
        result["spokenTextJaMissingFromModel"] = False
    else:
        result["spokenTextJaRepaired"] = False
    return result


def generate_spoken_text_ja(
    settings: dict[str, Any],
    reply: str,
    previous: str = "",
    *,
    include_delivery_plan: bool = False,
    persona_snapshot: PersonaContextSnapshot | None = None,
    reference_ledger: Mapping[str, Any] | None = None,
) -> str | dict[str, Any]:
    reference_bindings = ""
    if isinstance(reference_ledger, Mapping):
        ledger = DiscourseLedger.from_dict(reference_ledger)
        reference_bindings = render_discourse_context(
            ledger,
            resolve_discourse_references(
                ledger,
                message_id=ledger.current_message_id,
            ),
            max_chars=2600,
        )
    payload: dict[str, Any] = {
        "model": settings["apiModel"],
        "temperature": 0.25,
        "messages": [
            *persona_repair_prefix(persona_snapshot, legacy_system_prompt=False),
            {"role": "system", "content": SPOKEN_JA_ALIGNMENT_RULE},
            {"role": "user", "content": json.dumps({
                "replyZh": reply,
                "previousSpokenTextJa": previous,
                "pronunciationGlossary": spoken_ja_pronunciation_glossary(reply, previous),
                "referenceBindings": reference_bindings,
            }, ensure_ascii=False)},
        ],
    }
    if settings.get("useResponseFormat"):
        payload["response_format"] = {"type": "json_object"}
    if "deepseek.com" in settings["apiEndpoint"]:
        payload["thinking"] = {"type": "disabled"}
    try:
        content = send_upstream_chat_payload(settings, payload, timeout=90, purpose="spoken_ja_alignment")
        parsed = parse_json_object(content)
        spoken = str((parsed or {}).get("spokenTextJa") or "").strip()
        if include_delivery_plan:
            return {
                "spokenTextJa": spoken,
                "speechSegmentCount": valid_speech_segment_count(
                    (parsed or {}).get("speechSegmentCount")
                ),
            }
        return spoken
    except Exception:
        return {"spokenTextJa": "", "speechSegmentCount": None} if include_delivery_plan else ""


def valid_speech_segment_count(value: Any) -> int | None:
    if isinstance(value, bool) or value is None:
        return None
    try:
        number = int(str(value).strip())
    except (TypeError, ValueError):
        return None
    return number if 1 <= number <= MAX_SPEECH_UNITS else None


MEMORY_CANDIDATE_TYPES = {
    "user_memory", "task_state", "correction", "episode",
    "shared_reference", "relationship_state",
}


def normalize_memory_candidate(value: Any) -> dict[str, Any] | None:
    """Normalize a model/backend proposal without declaring it true.

    A candidate is deliberately distinct from a MemoryRecord: normalization
    only preserves provenance and slot metadata.  Grounding later decides
    whether the proposal is supported by the user's actual utterance.
    """

    if isinstance(value, str):
        content = value.strip()
        raw: Mapping[str, Any] = {}
    elif isinstance(value, Mapping):
        content = str(value.get("content") or "").strip()
        raw = value
    else:
        return None
    if not content:
        return None
    raw_type = str(raw.get("type") or raw.get("domain") or "").strip()
    type_aliases = {
        "user_profile": "user_memory",
        "preference": "user_memory",
        "project": "task_state",
        "relationship": "relationship_state",
    }
    memory_type = type_aliases.get(raw_type, raw_type)
    if memory_type not in MEMORY_CANDIDATE_TYPES:
        memory_type = ""
    polarity = str(raw.get("polarity") or "positive").strip().lower()
    if polarity not in {"positive", "negative"}:
        polarity = "positive"
    modality = str(raw.get("modality") or "asserted").strip().lower()
    if modality not in {"asserted", "requested", "corrected"}:
        modality = "asserted"
    temporal = str(raw.get("temporal") or "current").strip().lower()
    if temporal not in {"current", "habitual", "future", "historical"}:
        temporal = "current"
    importance = clamp_float(raw.get("importance"), 0, 1, 0.72)
    cardinality = str(raw.get("cardinality") or "multi").strip().lower()
    if cardinality not in {"single", "multi"}:
        cardinality = "multi"
    should_save = bool(raw.get("should_save", raw.get("shouldSave", True)))
    source_turn_values = raw.get("sourceTurnIds", raw.get("source_turn_ids", ()))
    if not isinstance(source_turn_values, (list, tuple)):
        source_turn_values = ()
    evidence_values = raw.get("evidence")
    evidence: list[dict[str, str]] = []
    if isinstance(evidence_values, list):
        for item in evidence_values[:8]:
            if not isinstance(item, Mapping):
                continue
            turn_id = str(item.get("turnId") or item.get("turn_id") or "").strip()[:120]
            quote = str(item.get("quote") or "").strip()[:800]
            if turn_id and quote:
                evidence.append({"turnId": turn_id, "quote": quote})
    return {
        "content": content[:600],
        "type": memory_type,
        "importance": importance,
        "shouldSave": should_save,
        "subject": str(raw.get("subject") or "").strip()[:120],
        "predicate": str(raw.get("predicate") or "").strip()[:120],
        "object": str(raw.get("object") or raw.get("objectValue") or "").strip()[:300],
        "polarity": polarity,
        "modality": modality,
        "temporal": temporal,
        "cardinality": cardinality,
        "sourceSpan": str(raw.get("sourceSpan") or raw.get("source_span") or "").strip()[:600],
        "validUntil": str(raw.get("validUntil") or "").strip()[:80],
        "userPinned": bool(raw.get("userPinned", False)),
        "sourceTurnIds": list(dict.fromkeys(
            str(item).strip()[:120]
            for item in source_turn_values
            if str(item).strip()
        )),
        "evidence": evidence,
    }


def memory_candidates_from_model(candidates: Any) -> list[dict[str, Any]]:
    if not isinstance(candidates, list):
        return []
    updates: list[dict[str, Any]] = []
    for item in candidates:
        candidate = normalize_memory_candidate(item)
        if (
            candidate is not None
            and candidate["shouldSave"]
            and candidate["importance"] >= 0.68
            and candidate["type"] in MEMORY_CANDIDATE_TYPES
        ):
            updates.append(candidate)
    return updates[:4]


def memory_updates_from_candidates(candidates: Any) -> list[str]:
    """Compatibility projection for clients that still display string updates."""

    return [item["content"] for item in memory_candidates_from_model(candidates)]


def normalize_claim_patches(value: Any) -> list[dict[str, str]]:
    """Keep only the claim-level patch protocol understood by the backend."""

    if not isinstance(value, list):
        return []
    allowed_actions = {"DELETE", "DOWNGRADE_CERTAINTY", "MARK_UNRESOLVED"}
    patches: list[dict[str, str]] = []
    seen: set[str] = set()
    for item in value:
        if not isinstance(item, dict):
            continue
        claim_id = str(item.get("claimId") or "").strip()
        action = str(item.get("action") or "").strip().upper()
        if not claim_id or claim_id in seen or action not in allowed_actions:
            continue
        seen.add(claim_id)
        patches.append({"claimId": claim_id, "action": action})
    return patches


def normalize_model_reply(value: Any, settings: dict[str, Any] | None = None) -> dict[str, Any]:
    structured_output_recovered = False
    structured_output_invalid = False
    structured_output_missing = False
    if isinstance(value, str):
        original = value
        value = parse_json_object(value)
        if value is None:
            structured_output_missing = True
            if looks_like_incomplete_structured_reply(original):
                recovered_reply = extract_complete_json_string_field(original, "reply")
                structured_output_recovered = bool(recovered_reply)
                structured_output_invalid = True
                value = {"reply": recovered_reply}
            else:
                value = {"reply": original}
    if not isinstance(value, dict):
        value = {}
    value = synchronize_response_waiting(value)
    semantic_kind = str(value.get("semanticKind") or value.get("kind") or "").strip().lower()
    if semantic_kind in {"clarification", "clarify"}:
        # A clarification is still one visible bilingual utterance. Project
        # compact V3 fields into the established internal delivery model.
        clarification_zh = str(value.get("zh") or value.get("textZh") or "").strip()
        clarification_ja = str(value.get("ja") or value.get("spokenTextJa") or "").strip()
        if clarification_zh and not isinstance(value.get("speechUnits"), list):
            value = {
                **value,
                "speechUnits": [{
                    "zh": clarification_zh,
                    "ja": clarification_ja,
                    "boundaryAfter": "turn_pause",
                }],
                "requiresUserResponse": True,
                "expectedResponseType": "free_text",
            }
    proactive_directive_provided = (
        str(value.get("proactiveDirective") or "").strip().lower()
        in PROACTIVE_DIRECTIVES
    )
    proactive_directive = normalize_proactive_directive(
        value.get("proactiveDirective")
    )
    raw_model_speech_units: list[dict[str, Any]] = []
    raw_units_value = (
        value.get("speechUnits")
        if isinstance(value.get("speechUnits"), list)
        else value.get("utterances")
    )
    if isinstance(raw_units_value, list):
        parsed_units = [dict(item) for item in raw_units_value if isinstance(item, dict)]
        raw_model_speech_units = (
            parsed_units
            if len(parsed_units) == len(raw_units_value)
            and 1 <= len(parsed_units) <= MAX_SPEECH_UNITS
            else []
        )
        if raw_model_speech_units and not str(value.get("reply") or "").strip():
            joined_reply = "\n\n".join(
                str(item.get("zh") or item.get("textZh") or item.get("reply") or "").strip()
                for item in raw_model_speech_units
            ).strip()
        else:
            joined_reply = ""
        if raw_model_speech_units and not str(value.get("spokenTextJa") or "").strip():
            joined_spoken = "\n\n".join(
                str(item.get("ja") or item.get("spokenTextJa") or "").strip()
                for item in raw_model_speech_units
            ).strip()
        else:
            joined_spoken = ""
        if joined_reply or joined_spoken:
            value = {
                **value,
                **({"reply": joined_reply} if joined_reply else {}),
                **({"spokenTextJa": joined_spoken} if joined_spoken else {}),
            }
    elif isinstance(value.get("_modelSpeechUnits"), list):
        parsed_units = [
            dict(item) for item in value["_modelSpeechUnits"] if isinstance(item, dict)
        ]
        raw_model_speech_units = (
            parsed_units
            if len(parsed_units) == len(value["_modelSpeechUnits"])
            and 1 <= len(parsed_units) <= MAX_SPEECH_UNITS
            else []
        )
    requires_user_response_provided = (
        bool(value.get("requiresUserResponseProvided"))
        if isinstance(value.get("requiresUserResponseProvided"), bool)
        else isinstance(value.get("requiresUserResponse"), bool)
    )
    requires_user_response = (
        bool(value.get("requiresUserResponse"))
        if requires_user_response_provided else False
    )
    expected_response_type = str(value.get("expectedResponseType") or "").strip()
    if expected_response_type not in {"free_text", "confirmation", "browser_target", "choice"}:
        expected_response_type = ""
    completed_acts_value = value.get("completedActs")
    completed_acts = (
        [
            str(item).strip()
            for item in completed_acts_value
            if str(item).strip()
        ]
        if isinstance(completed_acts_value, (list, tuple))
        else []
    )
    standalone_provided = isinstance(value.get("standalone"), bool)
    depends_on_prefix_provided = isinstance(
        value.get("dependsOnUndeliveredPrefix"),
        bool,
    )
    turn_complete_provided = isinstance(value.get("turnComplete"), bool)
    nested_reply = value.get("reply")
    if isinstance(nested_reply, str):
        nested_value = parse_json_object(nested_reply)
        if isinstance(nested_value, dict) and isinstance(nested_value.get("reply"), str):
            # Some OpenAI-compatible providers occasionally JSON-encode the
            # whole structured response into the reply field. Decode that
            # transport wrapper instead of showing raw JSON to the user.
            value = synchronize_response_waiting({**value, **nested_value})
            proactive_directive_provided = (
                str(value.get("proactiveDirective") or "").strip().lower()
                in PROACTIVE_DIRECTIVES
            )
            proactive_directive = normalize_proactive_directive(
                value.get("proactiveDirective")
            )
            requires_user_response_provided = (
                bool(value.get("requiresUserResponseProvided"))
                if isinstance(value.get("requiresUserResponseProvided"), bool)
                else isinstance(value.get("requiresUserResponse"), bool)
            )
            requires_user_response = (
                bool(value.get("requiresUserResponse"))
                if requires_user_response_provided else False
            )
            expected_response_type = str(
                value.get("expectedResponseType") or ""
            ).strip()
            if expected_response_type not in {
                "free_text", "confirmation", "browser_target", "choice",
            }:
                expected_response_type = ""
            completed_acts_value = value.get("completedActs")
            completed_acts = (
                [
                    str(item).strip()
                    for item in completed_acts_value
                    if str(item).strip()
                ]
                if isinstance(completed_acts_value, (list, tuple))
                else []
            )
            standalone_provided = isinstance(value.get("standalone"), bool)
            depends_on_prefix_provided = isinstance(
                value.get("dependsOnUndeliveredPrefix"),
                bool,
            )
            turn_complete_provided = isinstance(value.get("turnComplete"), bool)
    emotion_missing_from_model = not bool(model_emotion_label(value))
    raw_reply = str(value.get("reply") or "").strip()
    reply, reply_stage_directions = sanitize_roleplay_text(raw_reply)
    raw_spoken_text_ja = normalize_spoken_japanese_terms(value.get("spokenTextJa") or value.get("spoken_text_ja"))
    spoken_text_ja, spoken_stage_directions = sanitize_roleplay_text(raw_spoken_text_ja)
    spoken_text_ja_missing_from_model = not bool(spoken_text_ja)
    visual_hints = roleplay_visual_hints(reply_stage_directions + spoken_stage_directions)
    raw_emotion = str(value.get("emotion") or value.get("expression") or "neutral").strip()
    emotion = raw_emotion if raw_emotion in ALLOWED_EMOTIONS else EMOTION_ALIASES.get(raw_emotion, "neutral")
    if emotion == "neutral" and visual_hints.get("emotion"):
        emotion = str(visual_hints["emotion"])
    raw_gesture = str(value.get("gesture") or value.get("motion") or "idle").strip().casefold()
    gesture = GESTURE_ALIASES.get(raw_gesture, raw_gesture)
    if gesture == "idle" and visual_hints.get("gesture"):
        gesture = str(visual_hints["gesture"])
    if gesture not in ALLOWED_GESTURES:
        gesture = "idle"
    memory_update_keys = ("memoryUpdates", "memory_candidates", "memoryCandidates")
    memory_updates_provided = (
        bool(value.get("memoryUpdatesProvided"))
        if isinstance(value.get("memoryUpdatesProvided"), bool)
        else any(key in value for key in memory_update_keys)
    )
    raw_memory_action = str(value.get("memoryAction") or "").strip().lower()
    memory_action_provided = (
        bool(value.get("memoryActionProvided"))
        if isinstance(value.get("memoryActionProvided"), bool)
        else raw_memory_action in {"none", "save"}
    )
    memory_action = raw_memory_action if raw_memory_action in {"none", "save"} else "none"
    raw_memory_candidates = value.get("memoryUpdates")
    if not isinstance(raw_memory_candidates, list):
        raw_memory_candidates = value.get("memory_candidates") or value.get("memoryCandidates")
    structured_memory_candidates = memory_candidates_from_model(raw_memory_candidates)
    memories = [item["content"] for item in structured_memory_candidates]
    relation_event_provided = (
        bool(value.get("relationEventProvided"))
        if isinstance(value.get("relationEventProvided"), bool)
        else "relationEvent" in value
    )
    relation_event = normalize_relation_event(value.get("relationEvent"))
    memory_update_types = {
        str(item.get("content") or "").strip(): str(item.get("type") or "").strip()
        for item in (raw_memory_candidates if isinstance(raw_memory_candidates, list) else [])
        if isinstance(item, dict)
        and str(item.get("content") or "").strip()
        and str(item.get("type") or "").strip() in {
            "user_memory", "task_state", "correction", "episode",
            "shared_reference", "relationship_state",
        }
    }
    empty_reply = not reply
    if not reply:
        reply = EMPTY_REPLY_FALLBACK
    if not spoken_text_ja:
        needs_semantic_spoken_alignment = bool(
            configured(settings)
            and str((settings or {}).get("ttsProvider") or "").strip().lower() == "gpt-sovits"
        )
        if not needs_semantic_spoken_alignment:
            spoken_text_ja = fallback_spoken_text_ja(reply)
    # The legacy scalar count carries no boundary information and therefore
    # cannot authorize segmentation.  Only explicit ordered units do.
    model_speech_segment_count = (
        len(raw_model_speech_units) if raw_model_speech_units else None
    )
    speech_segment_count_missing_from_model = (
        not raw_model_speech_units
    )
    speech_segment_count = (
        model_speech_segment_count or 1
    )
    speech_pace = normalize_speech_pace(value.get("speechPace") or value.get("speech_pace"), value.get("speechSpeed"))
    speech_speed = clamp_float(value.get("speechSpeed"), 0.62, 1.45, SPEECH_PACE_SPEED[speech_pace])
    voice_style = str(value.get("voiceStyle") or "calm")
    delivery_mode = str(value.get("deliveryMode") or value.get("delivery_mode") or "normal").strip().lower()
    delivery_mode = "outburst" if delivery_mode == "outburst" else "normal"
    emotion_intensity = clamp_float(
        value.get("emotionIntensity") or value.get("emotion_intensity") or visual_hints.get("emotionIntensity"),
        0.2,
        2.5 if delivery_mode == "outburst" else 1.25,
        1.0,
    )
    emotion_delta = clamp_float(
        value.get("emotionDelta") if value.get("emotionDelta") is not None else value.get("emotion_delta"),
        -0.45,
        0.45,
        0.0,
    )
    voice_intensity, voice_intensity_source = resolve_voice_intensity(
        value.get("voiceIntensity") if value.get("voiceIntensity") is not None else value.get("voice_intensity"),
        emotion_intensity,
        emotion_delta,
    )
    requested_hold_ms = clamp_int(value.get("holdMs") or value.get("hold_ms"), 0, 120000, 0 if emotion == "neutral" else 45000)
    requested_fade_ms = clamp_int(value.get("fadeMs") or value.get("fade_ms"), 500, 30000, 1200 if emotion == "neutral" else 10000)
    hold_ms = 0 if emotion == "neutral" else max(42000, requested_hold_ms)
    fade_ms = requested_fade_ms if emotion == "neutral" else max(8000, requested_fade_ms)
    voice_tone = normalize_voice_tone(value.get("voiceTone") or value.get("voice_tone"), voice_style)
    if emotion == "shy" and voice_tone not in {"shy", "shy_annoyed"}:
        voice_tone = "shy"
        if voice_style == "calm":
            voice_style = "soft"
    elif emotion == "flustered" and voice_tone != "flustered":
        voice_tone = "flustered"
        if voice_style == "calm":
            voice_style = "energetic"
    elif emotion == "startled":
        voice_tone = "startled"
        if voice_style == "calm":
            voice_style = "energetic"
    elif emotion == "laughing":
        voice_tone = "laughing"
    elif emotion == "furious":
        voice_tone = "cold"
        gesture = "look_away"
        voice_style = "sharp"
        voice_intensity = "strong" if delivery_mode == "outburst" else voice_intensity
    speech_profile = speech_language_profile(settings or DEFAULT_SETTINGS)
    speech_text = reply if speech_profile["speechLanguage"] == "zh-CN" else spoken_text_ja
    if attachment_request_stopped(value):
        # The model's terminal capability decision is authoritative even when
        # it omitted the redundant waiting flag or used a rhetorical question.
        requires_user_response = False
        requires_user_response_provided = True
        expected_response_type = ""
    return {
        "reply": reply,
        "spokenTextJa": spoken_text_ja,
        "speechText": speech_text,
        "speechLanguage": speech_profile["speechLanguage"],
        "emotion": emotion,
        "gesture": gesture,
        "voiceStyle": voice_style,
        "voiceTone": voice_tone,
        "voiceIntensity": voice_intensity,
        "voiceIntensitySource": voice_intensity_source,
        "speechPace": speech_pace,
        "speechSpeed": speech_speed,
        "speechSegmentCount": speech_segment_count,
        "speechSegmentCountMissingFromModel": speech_segment_count_missing_from_model,
        "speechSegmentCountSource": (
            "model_semantic_units"
            if raw_model_speech_units
            else "legacy_model_count"
            if model_speech_segment_count is not None
            else "missing_pending_alignment"
        ),
        "emotionIntensity": emotion_intensity,
        "emotionDelta": emotion_delta,
        "blushIntensity": clamp_float(value.get("blushIntensity") or value.get("blush") or visual_hints.get("blushIntensity"), 0.0, 1.0, 0.78 if emotion == "shy" else 0.88 if emotion == "flustered" else 0.0),
        "eyeContact": clamp_float(value.get("eyeContact") if value.get("eyeContact") is not None else visual_hints.get("eyeContact"), 0.0, 1.0, 0.18 if emotion == "furious" else 0.42 if emotion == "shy" else 0.31 if emotion == "flustered" else 0.68),
        "gazeX": clamp_float(value.get("gazeX") if value.get("gazeX") is not None else visual_hints.get("gazeX"), -0.6, 0.6, 0.5 if emotion == "furious" else -0.16 if emotion == "shy" else -0.24 if emotion == "flustered" else 0.0),
        "gazeY": clamp_float(value.get("gazeY") if value.get("gazeY") is not None else visual_hints.get("gazeY"), -0.6, 0.6, -0.04 if emotion == "furious" else 0.13 if emotion == "shy" else 0.18 if emotion == "flustered" else 0.0),
        "tension": clamp_float(value.get("tension") if value.get("tension") is not None else visual_hints.get("tension"), 0.0, 1.0, 0.92 if emotion == "furious" else 0.55 if emotion == "annoyed" else 0.0),
        "deliveryMode": delivery_mode,
        "outburst": delivery_mode == "outburst",
        "coldShoulder": bool(value.get("coldShoulder") or value.get("cold_shoulder")),
        "boundaryAssessment": normalize_boundary_assessment(
            value.get("boundaryAssessment") or value.get("boundary_assessment")
        ),
        "holdMs": hold_ms,
        "fadeMs": fade_ms,
        "memoryUpdates": memories[:4] if isinstance(memories, list) else [],
        "memoryUpdatesProvided": memory_updates_provided,
        "memoryAction": memory_action,
        "memoryActionProvided": memory_action_provided,
        "_memoryCandidates": structured_memory_candidates[:4],
        "_memoryUpdateTypes": memory_update_types,
        "relationEvent": relation_event,
        "relationEventProvided": relation_event_provided,
        "source": value.get("source") or ("api" if configured(settings) else "local"),
        "emptyReply": empty_reply,
        "structuredOutputRecovered": structured_output_recovered,
        "structuredOutputInvalid": structured_output_invalid,
        "structuredOutputMissingFromModel": structured_output_missing,
        "spokenTextJaMissingFromModel": spoken_text_ja_missing_from_model,
        "emotionMissingFromModel": emotion_missing_from_model,
        "stageDirectionsRemoved": bool(reply_stage_directions or spoken_stage_directions),
        "requiresUserResponse": requires_user_response,
        "requiresUserResponseProvided": requires_user_response_provided,
        "semanticKind": str(value.get("semanticKind") or value.get("kind") or semantic_kind).strip().lower()[:40],
        "outcome": deepcopy(value.get("outcome")) if isinstance(value.get("outcome"), Mapping) else None,
        "questionRelation": question_relation(value.get("questionRelation")),
        "proactiveDirective": proactive_directive,
        "proactiveDirectiveProvided": proactive_directive_provided,
        "expectedResponseType": expected_response_type,
        "clarificationActionId": str(value.get("clarificationActionId") or "")[:100],
        "completedActs": list(dict.fromkeys(completed_acts))[:12],
        "completedActsProvided": isinstance(completed_acts_value, (list, tuple)),
        "standalone": value.get("standalone") is True,
        "standaloneProvided": standalone_provided,
        "dependsOnUndeliveredPrefix": bool(value.get("dependsOnUndeliveredPrefix")),
        "dependsOnUndeliveredPrefixProvided": depends_on_prefix_provided,
        "turnComplete": value.get("turnComplete") is True,
        "turnCompleteProvided": turn_complete_provided,
        "_fileOutputs": deepcopy(value.get("fileOutputs", value.get("_fileOutputs", []))),
        "attachmentAction": deepcopy(value.get("attachmentAction")) if isinstance(value.get("attachmentAction"), Mapping) else None,
        "_modelSpeechUnits": raw_model_speech_units,
        "claimPatches": normalize_claim_patches(value.get("claimPatches")),
    }


