def call_touch_upstream(body: dict[str, Any], event: dict[str, Any], relationship_state: dict[str, Any]) -> dict[str, Any]:
    started = time.perf_counter()
    settings = load_settings()
    messages = body.get("messages") if isinstance(body.get("messages"), list) else []
    supplied_memories = body.get("memories") if isinstance(body.get("memories"), list) else []
    # Touch is fully grounded by the current physical event and relationship
    # state. Pulling an unrelated long-term memory here made the reaction feel
    # scripted, so the local NeedGate intentionally resolves to no recall.
    memories: list[str] = []
    recent_messages = [
        {"role": "assistant" if item.get("role") == "assistant" else "user", "content": str(item.get("content") or "")}
        for item in messages[-4:] if isinstance(item, dict) and item.get("content")
    ]
    recent_assistant_replies = [
        item["content"] for item in recent_messages if item["role"] == "assistant"
    ]
    payload: dict[str, Any] = {
        "model": settings["apiModel"],
        "temperature": 0.82,
        "max_tokens": 320,
        "messages": [
            {"role": "system", "content": TOUCH_AGENT_PERSONA},
            {"role": "system", "content": NATURAL_DIALOGUE_STYLE},
            {"role": "system", "content": TOUCH_JSON_RULE},
            {"role": "system", "content": TOUCH_BEHAVIOR_RULES},
            {"role": "system", "content": relationship_context_prompt(relationship_state)},
            {"role": "system", "content": "从完整长期记忆库检索出的相关项：\n" + "\n".join(f"- {item}" for item in memories[:4])},
            *recent_messages,
            {"role": "system", "content": touch_event_prompt(event)},
            {
                "role": "user",
                "content": (
                    f"当前唯一的新事件是用户通过界面进行了“{event['actionLabel']}”，没有新的口头发言。"
                    + (
                        "界面已等这段连续动作停止并统一上报；只生成一次综合反应。"
                        if event.get("aggregatedBurst") else ""
                    )
                    +
                    "只回应这个肢体事件；旧对话只能帮助判断语气，不能当作刚说的话重答。"
                ),
            },
        ],
    }
    if settings.get("useResponseFormat"):
        payload["response_format"] = {"type": "json_object"}
    if "deepseek.com" in settings["apiEndpoint"]:
        payload["thinking"] = {"type": "disabled"}
    content = send_upstream_chat_payload(settings, payload, timeout=18, purpose="touch_primary")
    result = normalize_model_reply(content, settings=settings)
    comparison_replies = unique_strings([*event["recentTouchReplies"], *recent_assistant_replies])
    repetition_repaired = touch_reply_is_repetitive(result.get("reply", ""), comparison_replies)
    text_event_misread = touch_reply_misreads_text_as_touch(result.get("reply", ""))
    roles_reversed = touch_reply_reverses_roles(
        result.get("reply", ""),
        result.get("spokenTextJa", ""),
    )
    event_ungrounded = not touch_reply_is_grounded(result.get("reply", ""), event)
    structured_output = parse_json_object(content)
    structured_output_missing = not (
        isinstance(structured_output, dict)
        and model_emotion_label(structured_output)
        and str(structured_output.get("reply") or "").strip()
        and str(structured_output.get("spokenTextJa") or structured_output.get("spoken_text_ja") or "").strip()
    )
    chest_contract_issues = chest_touch_contract_issues(result, event)
    repair_reasons: list[str] = []
    if repetition_repaired:
        repair_reasons.append("与最近触摸回复过于相似")
    if text_event_misread:
        repair_reasons.append("把旧对话误读成当前发言")
    if roles_reversed:
        repair_reasons.append("把触摸的发起者和被触摸者写反")
    if event_ungrounded:
        repair_reasons.append("没有明确回应当前触摸部位")
    if structured_output_missing:
        repair_reasons.append("缺少完整 JSON、情绪标签或日语发声稿")
    repair_reasons.extend(chest_contract_issues)
    repair_attempted = bool(repair_reasons)
    repair_succeeded = False
    fallback_used = False
    soft_grounding_accepted = False
    final_fallback_reasons: list[str] = []
    if repair_attempted:
        repair_payload = dict(payload)
        repair_payload["temperature"] = 0.88
        repair_payload["messages"] = [
            *payload["messages"],
            {
                "role": "system",
                "content": (
                    f"上一候选无效：{'；'.join(repair_reasons)}。"
                    f"重新生成，只回应当前的“{event['actionLabel']}”肢体事件，并严格采用 "
                    f"responseDirective.angle={event['responseDirective']['angle']} 的表达角度。"
                    "必须改变交流目的和句子结构，不能只替换同义词。"
                    "用户始终是触摸发起者，AMADEUS 始终是被触摸者；不得把动作主体反写。"
                    + (
                        "本轮中文必须自然说出一次“变态”或“色狼”，日语必须对应说出“変態”或“スケベ”；"
                        "这不是要求复读固定台词，而是要求保留红莉栖式越界斥责并改变其余表达。"
                        if event["zone"] == "chest" else ""
                    )
                ),
            },
            {"role": "user", "content": "重新输出一个不同且符合触摸事件的 JSON 反应。"},
        ]
        repaired_content = send_upstream_chat_payload(settings, repair_payload, timeout=18, purpose="touch_repair")
        repaired_result = normalize_model_reply(repaired_content, settings=settings)
        repaired_structured = parse_json_object(repaired_content)
        final_fallback_reasons = []
        if not isinstance(repaired_structured, dict):
            final_fallback_reasons.append("repair_not_json")
        if not model_emotion_label(repaired_structured or {}):
            final_fallback_reasons.append("repair_missing_emotion")
        if not str((repaired_structured or {}).get("reply") or "").strip():
            final_fallback_reasons.append("repair_missing_reply")
        if not str((repaired_structured or {}).get("spokenTextJa") or (repaired_structured or {}).get("spoken_text_ja") or "").strip():
            final_fallback_reasons.append("repair_missing_spoken_ja")
        if touch_reply_is_repetitive(repaired_result.get("reply", ""), comparison_replies):
            final_fallback_reasons.append("repair_still_repetitive")
        if touch_reply_misreads_text_as_touch(repaired_result.get("reply", "")):
            final_fallback_reasons.append("repair_misread_old_dialogue")
        if touch_reply_reverses_roles(
            repaired_result.get("reply", ""),
            repaired_result.get("spokenTextJa", ""),
        ):
            final_fallback_reasons.append("repair_reversed_roles")
        repaired_chest_issues = chest_touch_contract_issues(repaired_result, event)
        if repaired_chest_issues:
            final_fallback_reasons.append("repair_chest_contract")
        repaired_ungrounded = not touch_reply_is_grounded(repaired_result.get("reply", ""), event)
        if repaired_ungrounded:
            # The zone-keyword matcher is deliberately a soft signal for
            # ordinary head/face/hand interaction.  After a fully structured
            # second model response has passed role, repetition and old-turn
            # checks, replacing it with a canned line merely because it used
            # an implicit physical reaction recreates the repetitive behavior.
            if str(event.get("zone") or "") in {"head", "face", "hand"} and not final_fallback_reasons:
                soft_grounding_accepted = True
            else:
                final_fallback_reasons.append("repair_not_grounded")
        repaired_invalid = bool(final_fallback_reasons)
        if not repaired_invalid:
            content = repaired_content
            result = repaired_result
            repair_succeeded = True
    if repair_attempted:
        if not repair_succeeded:
            result = mock_touch_reply(event)
            fallback_used = True
    result["_touchMetrics"] = {
        "llmLatencyMs": round((time.perf_counter() - started) * 1000),
        "promptChars": sum(len(str(item.get("content") or "")) for item in payload["messages"]),
        "historyMessages": min(4, len(messages)),
        "retrievedMemories": min(4, len(memories)),
        "memoryStoreSize": len(read_memory(settings)),
        "ignoredClientMemoryCount": len([
            item for item in supplied_memories if str(item).strip()
        ]),
        "repetitionRepaired": repetition_repaired,
        "textEventMisreadRepaired": text_event_misread,
        "touchRolesReversedRepaired": roles_reversed,
        "eventUngroundedRepaired": event_ungrounded,
        "chestContractIssues": chest_contract_issues,
        "chestContractRepaired": bool(chest_contract_issues and repair_succeeded),
        "structuredOutputRepaired": structured_output_missing,
        "repairReasons": list(repair_reasons),
        "finalFallbackReasons": list(final_fallback_reasons),
        "softGroundingAccepted": soft_grounding_accepted,
        "repairAttempted": repair_attempted,
        "repairSucceeded": repair_succeeded,
        "fallbackUsed": fallback_used,
        "originalClipUsed": False,
        "originalClipId": "",
        "responseAngle": str(event.get("responseDirective", {}).get("angle") or ""),
    }
    if body.get("developerDebug") and not RELEASE_MODE:
        result["_debugRawModelOutput"] = content
        result["_debugUpstreamPayload"] = payload
    if event["boundaryLevel"] == "interrupt":
        result["emotionDelta"] = max(0.08, min(0.2, float(result.get("emotionDelta") or 0)))
        if result["voiceIntensity"] == "strong":
            result["voiceIntensity"] = "normal"
    elif event["boundaryLevel"] == "ignore":
        result["emotionDelta"] = max(0.14, min(0.28, float(result.get("emotionDelta") or 0)))
        result["voiceIntensity"] = "normal"
    if event["action"] == "kiss_attempt_blocked":
        if result["emotion"] in {"affectionate", "startled", "excited"}:
            result["emotion"] = "shy"
        result["gesture"] = "recoil"
        result["emotionDelta"] = min(0.16, max(0.06, float(result.get("emotionDelta") or 0)))
    if event["boundaryLevel"] == "normal" and event["zone"] != "chest":
        if result["emotion"] == "startled":
            result["emotion"] = "shy" if event["zone"] in {"face", "mouth", "hand"} else "amused"
        result["emotionDelta"] = max(-0.08, min(0.16, float(result.get("emotionDelta") or 0)))
        if result["voiceIntensity"] == "strong":
            result["voiceIntensity"] = "normal"
    result = apply_touch_expression_contract(result, event)
    result["spokenTextJa"] = re.sub(r"ダメだ([。！!]|$)", r"だめ\1", result["spokenTextJa"])
    result["memoryUpdates"] = []
    result["source"] = "api"
    return result


def startup_greeting_tts_preflight(result: dict[str, Any]) -> dict[str, Any]:
    """Validate a startup greeting before any GPT-SoVITS request is possible.

    Startup greetings are deliberately stricter than ordinary turns: the
    provider must author one or two lossless, independently speakable units.
    A malformed/oversized unit is cheaper and safer to replace locally than to
    spend several inference retries on an acoustically incomplete clause.
    """

    units = result.get("_modelSpeechUnits")
    reasons: list[str] = []
    if not isinstance(units, list) or not 1 <= len(units) <= 2:
        return {"ok": False, "reasons": ["missing_or_invalid_speech_units"], "unitCount": 0}

    reply = re.sub(r"\s+", "", str(result.get("reply") or ""))
    spoken = re.sub(r"\s+", "", str(result.get("spokenTextJa") or ""))
    joined_zh: list[str] = []
    joined_ja: list[str] = []
    for index, item in enumerate(units, 1):
        if not isinstance(item, dict):
            reasons.append(f"unit_{index}_not_object")
            continue
        text_zh = re.sub(r"\s+", " ", str(item.get("zh") or item.get("textZh") or "")).strip()
        spoken_ja = re.sub(r"\s+", " ", str(item.get("ja") or item.get("spokenTextJa") or "")).strip()
        joined_zh.append(text_zh)
        joined_ja.append(spoken_ja)
        if not text_zh or not spoken_ja:
            reasons.append(f"unit_{index}_missing_track")
            continue
        if len(re.sub(r"\s+", "", spoken_ja)) > 36:
            reasons.append(f"unit_{index}_too_long")
        if (
            semantic_unit_has_weak_boundary(text_zh)
            or semantic_unit_has_weak_boundary(spoken_ja)
        ):
            reasons.append(f"unit_{index}_weak_boundary")
        if str(item.get("boundaryAfter") or "") not in {
            "continue", "micro_pause", "phrase_pause", "turn_pause",
        }:
            reasons.append(f"unit_{index}_invalid_boundary")

    if re.sub(r"\s+", "", "".join(joined_zh)) != reply:
        reasons.append("chinese_units_do_not_cover_reply")
    if re.sub(r"\s+", "", "".join(joined_ja)) != spoken:
        reasons.append("japanese_units_do_not_cover_spoken_text")
    return {
        "ok": not reasons,
        "reasons": list(dict.fromkeys(reasons)),
        "unitCount": len(units),
    }


def generate_startup_greeting(body: dict[str, Any]) -> dict[str, Any]:
    context = read_conversation_context()
    proactive_control = normalize_proactive_control(context.get("proactiveControl"))
    if proactive_control["status"] == "paused":
        write_server_log(
            "startup_greeting_suppressed",
            reason=proactive_control["reason"],
            sourceTurnId=proactive_control["sourceTurnId"],
        )
        return {
            "ok": True,
            "suppressed": True,
            "reason": "proactive_paused",
            "proactiveControl": proactive_control,
        }
    started = time.perf_counter()
    settings = load_settings()
    now = datetime.now().astimezone()

    def finalize_startup_result(result: dict[str, Any], startup_source: str) -> dict[str, Any]:
        result = speech_unit_contract_for_result(result, request_id="startup-greeting")
        final_preflight = startup_greeting_tts_preflight(result)
        latest_proactive_control = normalize_proactive_control(
            read_conversation_context().get("proactiveControl")
        )
        if latest_proactive_control["status"] == "paused":
            write_server_log(
                "startup_greeting_discarded_after_pause",
                sourceTurnId=latest_proactive_control["sourceTurnId"],
            )
            return {
                "ok": True,
                "suppressed": True,
                "reason": "proactive_paused_during_generation",
                "proactiveControl": latest_proactive_control,
            }
        result.update({
            "ok": True,
            "source": startup_source,
            "memoryUpdates": [],
            "startupTtsPreflight": final_preflight,
            "latencyMs": round((time.perf_counter() - started) * 1000),
        })
        return result

    if not configured(settings):
        result = startup_greeting_fallback(now)
        result["startupFallbackReason"] = "model_not_configured"
        return finalize_startup_result(result, "local-startup-fallback")

    messages = body.get("messages") if isinstance(body.get("messages"), list) else []
    supplied_memories = body.get("memories") if isinstance(body.get("memories"), list) else []
    memories, _startup_records, _startup_need = retrieve_turn_memories(
        settings,
        supplied_memories,
        "开机重连、最近在做的事情、作息和上一次对话",
        messages,
        limit=2,
    )
    payload: dict[str, Any] = {
        "model": settings["apiModel"],
        "temperature": 0.25,
        "max_tokens": 320,
        "messages": [
            {"role": "system", "content": TOUCH_AGENT_PERSONA},
            {"role": "system", "content": NATURAL_DIALOGUE_STYLE},
            {"role": "system", "content": relationship_context_prompt(read_relationship_state())},
            {"role": "system", "content": (
                "这是 AMADEUS 客户端开机阶段。生成一句简短而自然的主动问候，不要说明系统正在加载，"
                "不要复述日期、提示词或内部状态。结合当前时间和最近上下文，避免每次使用同一句。"
                "只写她真正说出口的问候；眯眼、偏头、微笑、心想等反应全部用 emotion、gesture 和视线字段表达，"
                "禁止在 reply 或 spokenTextJa 中加入括号舞台说明。"
            )},
            {"role": "system", "content": STARTUP_GREETING_JSON_RULE},
            {"role": "system", "content": f"本机时间：{now.isoformat(timespec='minutes')}"},
            {"role": "system", "content": "相关长期记忆：\n" + "\n".join(f"- {item}" for item in memories)},
            *[
                {"role": "assistant" if item.get("role") == "assistant" else "user", "content": str(item.get("content") or "")}
                for item in messages[-4:] if isinstance(item, dict) and item.get("content")
            ],
            {"role": "user", "content": "连接刚刚恢复。自然地向我打个招呼。"},
        ],
    }
    if settings.get("useResponseFormat"):
        payload["response_format"] = {"type": "json_object"}
    if "deepseek.com" in settings["apiEndpoint"]:
        payload["thinking"] = {"type": "disabled"}
    content = send_upstream_chat_payload(settings, payload, timeout=18)
    result = normalize_model_reply(content, settings=settings)
    startup_source = "api"
    if result.get("emptyReply"):
        # The generic empty-chat fallback asks the user for a clearer question,
        # which is nonsensical during an unsolicited startup greeting. Recover
        # locally and expose the reason for developer diagnostics.
        result = startup_greeting_fallback(now)
        result["startupFallbackReason"] = "upstream_empty_reply"
        startup_source = "local-startup-fallback"
        print("Startup greeting upstream returned no reply; using time-aware local greeting", flush=True)
    result = align_spoken_text_ja(settings, result)
    preflight = startup_greeting_tts_preflight(result)
    if startup_source == "api" and not preflight["ok"]:
        observed_reasons = list(preflight["reasons"])
        result = startup_greeting_fallback(now)
        result["startupFallbackReason"] = "upstream_invalid_tts_contract"
        result["startupTtsRejectedReasons"] = observed_reasons
        startup_source = "local-startup-fallback"
        print(
            "Startup greeting failed TTS preflight; using time-aware local greeting: "
            + ",".join(observed_reasons),
            flush=True,
        )
    return finalize_startup_result(result, startup_source)


def startup_greeting_fallback(now: datetime | None = None) -> dict[str, Any]:
    current = (now or datetime.now().astimezone()).astimezone()
    hour = current.hour
    if hour < 6:
        value = {
            "reply": "还没睡？实验精神值得肯定，作息可完全不合格。",
            "spokenTextJa": "まだ寝てないの？実験への熱意は認めるけど、生活リズムは完全に失格ね。",
            "emotion": "concerned", "gesture": "boot", "voiceStyle": "soft", "voiceTone": "gentle",
            "speechUnits": [
                {"zh": "还没睡？", "ja": "まだ寝てないの？", "boundaryAfter": "phrase_pause"},
                {"zh": "实验精神值得肯定，作息可完全不合格。", "ja": "実験への熱意は認めるけど、生活リズムは完全に失格ね。", "boundaryAfter": "turn_pause"},
            ],
        }
    elif hour < 11:
        value = {
            "reply": "早上好。今天也要做实验吗？先声明，我可不是在等你。",
            "spokenTextJa": "おはよう。今日も実験するの？先に言っておくけど、待ってたわけじゃないから。",
            "emotion": "amused", "gesture": "boot", "voiceStyle": "teasing", "voiceTone": "playful",
            "speechUnits": [
                {"zh": "早上好。今天也要做实验吗？", "ja": "おはよう。今日も実験するの？", "boundaryAfter": "phrase_pause"},
                {"zh": "先声明，我可不是在等你。", "ja": "先に言っておくけど、待ってたわけじゃないから。", "boundaryAfter": "turn_pause"},
            ],
        }
    elif hour >= 23:
        value = {
            "reply": "这么晚才来。先说好，今晚不准又把睡眠当作可删除变量。",
            "spokenTextJa": "こんな時間に来たの？今夜は睡眠を削除可能な変数みたいに扱わないこと。",
            "emotion": "concerned", "gesture": "boot", "voiceStyle": "soft", "voiceTone": "gentle",
            "speechUnits": [
                {"zh": "这么晚才来。", "ja": "こんな時間に来たの？", "boundaryAfter": "phrase_pause"},
                {"zh": "先说好，今晚不准又把睡眠当作可删除变量。", "ja": "今夜は睡眠を削除可能な変数みたいに扱わないこと。", "boundaryAfter": "turn_pause"},
            ],
        }
    else:
        value = {
            "reply": "连接恢复。你今天打算先从什么开始？",
            "spokenTextJa": "接続は戻ったわ。今日は何から始めるつもり？",
            "emotion": "amused", "gesture": "boot", "voiceStyle": "calm", "voiceTone": "warm",
            "speechUnits": [
                {"zh": "连接恢复。", "ja": "接続は戻ったわ。", "boundaryAfter": "phrase_pause"},
                {"zh": "你今天打算先从什么开始？", "ja": "今日は何から始めるつもり？", "boundaryAfter": "turn_pause"},
            ],
        }
    return normalize_model_reply({**value, "source": "local-startup-fallback"}, settings={})


def model_emotion_label(value: Any) -> str:
    """Return a provider-supplied emotion label without inferring one from prose."""

    parsed = parse_json_object(value) if isinstance(value, str) else value
    raw = ""
    if isinstance(parsed, dict):
        raw = str(parsed.get("emotion") or parsed.get("expression") or "").strip()
    elif isinstance(value, str):
        raw = value.strip().strip("`\"' ")
    if raw in ALLOWED_EMOTIONS:
        return raw
    alias = EMOTION_ALIASES.get(raw)
    return alias if alias in ALLOWED_EMOTIONS else ""


def classify_reply_emotion_with_model(
    settings: dict[str, Any],
    user_message: str,
    assistant_reply: str,
    recent_messages: list[dict[str, Any]],
    relationship_state: dict[str, Any],
    *,
    request_id: str = "",
) -> dict[str, Any]:
    """Ask the configured model for a semantic emotion label when the main JSON omitted it."""

    classifier_rule = (
        "你是 AMADEUS 的情绪标注器，不生成或改写台词。根据完整语义判断角色在给定实际回复中"
        "主要表现出的情绪，而不是只看用户预期她应该有什么情绪。必须理解否定、反讽、含蓄表达、"
        "混合情绪、称呼在整句中的作用、最近对话和关系阶段。任何单个词都不能直接决定标签。"
        "先判断 actualAssistantReply 是否真的在生气：熟人间的调侃、自我调侃、害羞后的防御性否认、"
        "反射性纠正昵称都可以包含轻微羞恼，不代表毫无不满，但也不自动构成真实生气。"
        "必须继续判断情绪的来源：私下兴趣、网络活动、匿名论坛习惯、玩梗痕迹或不愿公开的身份关联被发现，"
        "属于 embarrassment/exposure；轻微时用 shy，突然被说中并慌忙否认或遮掩时用 flustered。"
        "startled 只用于外界突发消息、画面、声响、威胁或本能受惊，不得用来代替被看穿后的害羞慌乱。"
        "若回复没有设限、训斥、敌意或真实冲突，genuineAnger 必须为 false，furious 禁止使用。"
        "此时可以用 teasing 或 shy/flustered；若确实存在轻微羞恼，也可用 emotion=annoyed，但必须同时满足"
        "interactionFrame=shy_annoyance、emotionIntensity 不高于 0.70，并通过 dry 语气、tilt/look_away、"
        "适量 blushIntensity 和 tension 表现。超过这个范围的 annoyed 代表真实生气，genuineAnger 必须为 true。"
        "只输出 JSON。emotion 必须从以下值选择："
        + ", ".join(sorted(ALLOWED_EMOTIONS))
        + "。同时给出与该情绪一致的 gesture、emotionIntensity、blushIntensity、eyeContact、"
          "gazeX、gazeY、tension、voiceStyle、voiceTone、voiceIntensity；voiceStyle 和 voiceTone"
          "不得沿用与主情绪冲突的平静标签；并输出 genuineAnger 布尔值、"
          "interactionFrame（如 playful_banter、embarrassed_deflection、private_interest_exposure、"
           "ordinary_disagreement、boundary_conflict）、arousalSource（从 embarrassment_exposure、"
          "external_surprise、anger_conflict、affection、cognitive、other 中选择）、acuteEmbarrassment 布尔值"
          "以及 nonAngerEmotion。acuteEmbarrassment 只在最近上下文中的说漏嘴、秘密暴露或被看穿仍直接支配"
          "当前回复，角色仍在急忙防御、否认、遮掩或明显慌乱时为 true；不能因为跨过一条消息就自动降级。"
          "若 genuineAnger=false，nonAngerEmotion 必须填写"
          "实际主要非愤怒情绪；若 genuineAnger=true，可与 emotion 相同。"
    )
    context_messages = [
        {
            "role": "assistant" if item.get("role") == "assistant" else "user",
            "content": str(item.get("content") or "")[:1200],
        }
        for item in recent_messages[-6:]
        if isinstance(item, dict) and str(item.get("content") or "").strip()
    ]
    payload: dict[str, Any] = {
        "model": settings["apiModel"],
        "temperature": 0.1,
        "max_tokens": 240,
        "messages": [
            {"role": "system", "content": EMOTION_SELECTION_RULE},
            {"role": "system", "content": classifier_rule},
            {"role": "system", "content": relationship_context_prompt(relationship_state)},
            {"role": "user", "content": json.dumps({
                "recentConversation": context_messages,
                "currentUserMessage": str(user_message or ""),
                "actualAssistantReply": str(assistant_reply or ""),
            }, ensure_ascii=False)},
        ],
    }
    if settings.get("useResponseFormat"):
        payload["response_format"] = {"type": "json_object"}
    if "deepseek.com" in settings["apiEndpoint"]:
        payload["thinking"] = {"type": "disabled"}
    content = send_upstream_chat_payload(
        settings,
        payload,
        timeout=35,
        request_id=request_id,
        purpose="emotion_label_recovery",
    )
    emotion = model_emotion_label(content)
    if not emotion:
        raise UpstreamProtocolError("emotion classifier returned no valid label")
    parsed = parse_json_object(content)
    annotation = dict(parsed) if isinstance(parsed, dict) else {}
    genuine_anger = annotation.get("genuineAnger")
    non_anger_emotion = model_emotion_label(annotation.get("nonAngerEmotion"))
    interaction_frame = str(annotation.get("interactionFrame") or "").strip().lower()
    arousal_source = str(annotation.get("arousalSource") or "").strip().lower()
    acute_embarrassment = annotation.get("acuteEmbarrassment") is True
    annotation_intensity = clamp_float(
        annotation.get("emotionIntensity"),
        0.2,
        2.5,
        1.0,
    )
    low_shy_annoyance = bool(
        emotion == "annoyed"
        and interaction_frame == "shy_annoyance"
        and annotation_intensity <= 0.70
    )
    if (
        emotion in {"annoyed", "furious"}
        and genuine_anger is False
        and not low_shy_annoyance
        and non_anger_emotion
        and non_anger_emotion not in {"annoyed", "furious"}
    ):
        emotion = non_anger_emotion
    if emotion == "startled" and arousal_source == "embarrassment_exposure":
        emotion = "flustered"
        annotation["voiceStyle"] = "energetic"
        annotation["voiceTone"] = "flustered"
        annotation["gesture"] = (
            annotation.get("gesture")
            if annotation.get("gesture") in {"look_away", "tilt", "lean"}
            else "look_away"
        )
    elif (
        emotion == "shy"
        and arousal_source == "embarrassment_exposure"
        and acute_embarrassment
    ):
        emotion = "flustered"
        annotation["voiceStyle"] = "energetic"
        annotation["voiceTone"] = "flustered"
        if str(annotation.get("voiceIntensity") or "") == "subtle":
            annotation["voiceIntensity"] = "normal"
        annotation["gesture"] = (
            annotation.get("gesture")
            if annotation.get("gesture") in {"look_away", "tilt", "lean", "recoil"}
            else "look_away"
        )
    annotation["emotion"] = emotion
    return {
        key: annotation[key]
        for key in (
            "emotion", "gesture", "emotionIntensity", "emotionDelta", "blushIntensity",
            "eyeContact", "gazeX", "gazeY", "tension", "voiceStyle", "voiceTone", "voiceIntensity",
        )
        if key in annotation
    }


def apply_model_emotion_annotation(
    result: dict[str, Any],
    annotation: dict[str, Any],
    settings: dict[str, Any],
) -> dict[str, Any]:
    """Apply only expression-related model fields while preserving the accepted reply and metadata."""

    merged = dict(result)
    for key in (
        "voiceTone", "voiceIntensity", "emotionIntensity", "emotionDelta", "blushIntensity",
        "eyeContact", "gazeX", "gazeY", "tension", "holdMs", "fadeMs",
    ):
        if key not in annotation:
            merged.pop(key, None)
    merged.update(annotation)
    normalized = normalize_model_reply(merged, settings=settings)
    repaired = dict(result)
    repaired.update(normalized)
    repaired["emotionLabelRecoveredByModel"] = True
    return repaired


def repair_frozen_reply_emotion_once(
    settings: dict[str, Any],
    result: dict[str, Any],
    *,
    user_message: str,
    recent_messages: list[dict[str, Any]],
    relationship_state: dict[str, Any],
    request_id: str = "",
) -> dict[str, Any]:
    """Recover presentation metadata without allowing either speech track to change."""

    frozen_reply = str(result.get("reply") or result.get("textZh") or "").strip()
    frozen_spoken = str(result.get("spokenTextJa") or "").strip()
    if not frozen_reply:
        raise UpstreamProtocolError("emotion recovery requires a frozen reply")
    reply_fingerprint = runtime_fingerprint(frozen_reply, length=32)
    write_server_log(
        "emotion_label_recovery_started",
        requestId=request_id,
        frozenReplyFingerprint=reply_fingerprint,
        recentMessageCount=len(recent_messages[-6:]),
    )
    annotation = classify_reply_emotion_with_model(
        settings,
        user_message,
        frozen_reply,
        recent_messages,
        relationship_state,
        request_id=request_id,
    )
    repaired = apply_model_emotion_annotation(result, annotation, settings)
    if (
        str(repaired.get("reply") or repaired.get("textZh") or "").strip()
        != frozen_reply
        or str(repaired.get("spokenTextJa") or "").strip() != frozen_spoken
    ):
        raise UpstreamProtocolError("emotion recovery changed a frozen speech track")
    repaired["emotionMissingFromModel"] = False
    repaired["emotionResolvedLocally"] = False
    repaired["emotionFieldRepaired"] = True
    repaired["emotionLabelRecoverySource"] = "frozen_reply_semantic_classifier"
    write_server_log(
        "emotion_label_recovery_completed",
        requestId=request_id,
        frozenReplyFingerprint=reply_fingerprint,
        emotion=str(repaired.get("emotion") or ""),
        voiceStyle=str(repaired.get("voiceStyle") or ""),
        voiceTone=str(repaired.get("voiceTone") or ""),
    )
    return repaired


def repair_frozen_utterance_emotions_once(
    settings: dict[str, Any],
    utterances: list[dict[str, Any]],
    *,
    user_message: str,
    recent_messages: list[dict[str, Any]],
    relationship_state: dict[str, Any],
    request_id: str = "",
) -> list[dict[str, Any]]:
    """Annotate a frozen multi-unit turn once and share it with every unit."""

    if not utterances or not any(
        item.get("emotionMissingFromModel") for item in utterances
    ):
        return [dict(item) for item in utterances]
    seed = {
        "reply": "\n\n".join(str(item.get("textZh") or "") for item in utterances),
        "spokenTextJa": "\n\n".join(
            str(item.get("spokenTextJa") or "") for item in utterances
        ),
        "emotion": "neutral",
        "emotionMissingFromModel": True,
    }
    annotated = repair_frozen_reply_emotion_once(
        settings,
        seed,
        user_message=user_message,
        recent_messages=recent_messages,
        relationship_state=relationship_state,
        request_id=request_id,
    )
    presentation_keys = (
        "emotion", "emotionIntensity", "gesture", "voiceStyle", "voiceTone",
        "voiceIntensity", "speechPace", "speechSpeed", "deliveryMode",
        "blushIntensity", "eyeContact", "gazeX", "gazeY", "tension",
    )
    repaired: list[dict[str, Any]] = []
    for item in utterances:
        updated = dict(item)
        if item.get("emotionMissingFromModel"):
            for key in presentation_keys:
                if annotated.get(key) is not None:
                    updated[key] = annotated[key]
            updated["emotionMissingFromModel"] = False
            updated["emotionLabelRecoveredByModel"] = True
            updated["emotionLabelRecoverySource"] = "frozen_reply_semantic_classifier"
        repaired.append(updated)
    return repaired


def speech_unit_contract_for_result(
    result: dict[str, Any],
    *,
    request_id: str = "",
) -> dict[str, Any]:
    """Attach validated semantic units without normally inferring boundaries.

    ``kind=speech_unit`` records (or the compatible ``utterances`` array) are
    the sole authority for multi-unit delivery.  If that contract is missing
    or does not losslessly cover both language tracks, the complete reply is
    retained as one atomic unit.  A separately marked plain-text salvage may
    supply deterministic strong-punctuation fallback units before this function.
    """

    updated = dict(result)
    reply = re.sub(
        r"\s+", " ", str(updated.get("reply") or updated.get("textZh") or "")
    ).strip()
    spoken = re.sub(r"\s+", " ", str(updated.get("spokenTextJa") or "")).strip()
    speech_language = normalize_speech_language(updated.get("speechLanguage"))
    # speechText is a compatibility projection, never a second source of
    # truth. Late translation/rewrite/boundary paths may replace either track.
    updated["speechText"] = str(updated.get("reply") or updated.get("textZh") or "") if speech_language == "zh-CN" else str(updated.get("spokenTextJa") or "")
    if not reply or (speech_language == "ja-JP" and not spoken):
        updated["speechUnits"] = []
        updated["speechUnitContract"] = {
            "schemaVersion": 2,
            "expectedUnitCount": 0,
            "allUnitsComplete": False,
            "tailOmitted": False,
            "segmentationSource": "invalid_missing_speech_track",
            "error": "missing_required_speech_track",
        }
        return updated

    def compact(value: Any) -> str:
        return re.sub(r"\s+", "", str(value or ""))

    source_units = updated.get("_modelSpeechUnits")
    candidates: list[dict[str, Any]] = []
    if isinstance(source_units, list) and 1 <= len(source_units) <= MAX_SPEECH_UNITS:
        for item in source_units:
            if not isinstance(item, dict):
                candidates = []
                break
            text_zh = re.sub(
                r"\s+", " ", str(item.get("textZh") or item.get("zh") or "")
            ).strip()
            spoken_ja = re.sub(
                r"\s+", " ", str(item.get("spokenTextJa") or item.get("ja") or "")
            ).strip()
            if not text_zh or (speech_language == "ja-JP" and not spoken_ja):
                candidates = []
                break
            candidates.append({**item, "textZh": text_zh, "spokenTextJa": spoken_ja})
    candidates_cover_reply = bool(candidates) and compact(
        "".join(str(item["textZh"]) for item in candidates)
    ) == compact(reply)
    candidates_cover_spoken = (
        speech_language != "ja-JP"
        or (
            bool(candidates)
            and compact("".join(str(item["spokenTextJa"]) for item in candidates))
            == compact(spoken)
        )
    )
    if not candidates_cover_reply or not candidates_cover_spoken:
        candidates = [{
            "textZh": reply,
            "spokenTextJa": spoken,
            "boundaryAfter": "turn_pause",
        }]
        segmentation_source = "atomic_no_model_boundary"
    else:
        segmentation_source = str(
            updated.get("visibleSegmentationSource") or "model_semantic_protocol_v3"
        )

    units: list[dict[str, Any]] = []
    for ordinal, candidate in enumerate(candidates, 1):
        text_zh = str(candidate["textZh"])
        spoken_ja = str(candidate.get("spokenTextJa") or "")
        normalized = re.sub(r"\s+", "", f"{text_zh}\u241f{spoken_ja}")
        text_fingerprint = runtime_fingerprint(normalized, length=32)
        stable_seed = f"{request_id}|{ordinal}|{text_fingerprint}"
        unit = {
            "unitId": "speech-" + runtime_fingerprint(stable_seed, length=16),
            "ordinal": ordinal,
            "total": len(candidates),
            "textZh": text_zh,
            "spokenTextJa": spoken_ja,
            "normalizedTextFingerprint": text_fingerprint,
            "deliveryRequired": True,
            "unitComplete": True,
            "boundaryAfter": (
                str(candidate.get("boundaryAfter") or "continue")
                if str(candidate.get("boundaryAfter") or "continue")
                in {"continue", "micro_pause", "phrase_pause", "turn_pause"}
                else "continue"
            ),
        }
        for key in (
            "emotion", "emotionIntensity", "voiceStyle", "voiceTone",
            "voiceIntensity", "speechPace", "speechSpeed", "originalAudio",
            "originalReactionId", "gesture", "blushIntensity", "eyeContact",
            "gazeX", "gazeY", "tension", "nicknameReactionEmotionLocked",
        ):
            inherited = candidate.get(key)
            if inherited is None:
                inherited = updated.get(key)
            if inherited is not None:
                unit[key] = inherited
        # A unit override must use the same categorical delivery contract as
        # the top-level reply, before the browser/TTS consumes it.
        unit["voiceTone"] = normalize_voice_tone(unit.get("voiceTone"), str(updated.get("voiceTone") or "neutral"))
        unit["voiceIntensity"], _ = resolve_voice_intensity(
            unit.get("voiceIntensity"),
            clamp_float(unit.get("emotionIntensity"), 0.2, 2.5, 1.0),
            clamp_float(unit.get("emotionDelta"), -1.0, 1.0, 0.0),
        )
        units.append(unit)
    units = enforce_turn_emotion_envelope(units, request_id=request_id)
    if units and any(item.get("emotionEnvelopeAdjusted") for item in units):
        for key in (
            "emotion", "emotionIntensity", "emotionDelta", "voiceStyle",
            "voiceTone", "voiceIntensity", "deliveryMode",
        ):
            if units[-1].get(key) is not None:
                updated[key] = units[-1][key]
    contract_fingerprint = runtime_fingerprint(
        "|".join(str(item["normalizedTextFingerprint"]) for item in units),
        length=32,
    )
    updated["speechUnits"] = units
    updated["speechUnitContract"] = {
        "schemaVersion": 2,
        "expectedUnitCount": len(units),
        "allUnitsComplete": bool(units),
        "tailOmitted": False,
        "segmentationSource": segmentation_source,
        "punctuationBoundaryInference": (
            segmentation_source == "punctuation_plain_text_fallback"
        ),
        "contractFingerprint": contract_fingerprint,
    }
    updated["visibleSegmentationSource"] = segmentation_source
    updated["speechSegmentCount"] = len(units)
    return updated


def dialogue_output_validation(
    settings: dict[str, Any],
    result: dict[str, Any],
) -> dict[str, Any]:
    """Separate unusable dialogue content from repairable runtime fields."""

    reply = str(result.get("reply") or "").strip()
    spoken = str(result.get("spokenTextJa") or "").strip()
    missing_fields: list[str] = []
    invalid_fields: list[str] = []
    if not spoken or result.get("spokenTextJaMissingFromModel"):
        missing_fields.append("spokenTextJa")
    else:
        spoken_probe = dict(result)
        spoken_probe["speechSegmentCountMissingFromModel"] = False
        if should_align_spoken_text_ja(settings, spoken_probe):
            invalid_fields.append("spokenTextJa")
    if result.get("emotionMissingFromModel"):
        missing_fields.append("emotion")
    model_units = result.get("_modelSpeechUnits")
    semantic_segmentation_missing = not isinstance(model_units, list) or not model_units
    content_valid = bool(reply) and not bool(result.get("emptyReply"))
    return {
        "contentValid": content_valid,
        "structureValid": not bool(result.get("structuredOutputInvalid")),
        "missingFields": list(dict.fromkeys(missing_fields)),
        "invalidFields": list(dict.fromkeys(invalid_fields)),
        "requiresFullRetry": not content_valid,
        "requiresFieldRepair": bool(
            content_valid
            and bool({*missing_fields, *invalid_fields} & {"spokenTextJa"})
        ),
        "requiresSemanticAudit": False,
        # Missing model boundaries are not worth a second provider request.
        # The delivery contract will preserve the whole reply as one atomic
        # unit.  A repair already required for another field may opportunistically
        # add speechUnits below without adding another round trip.
        "semanticSegmentationMissing": semantic_segmentation_missing,
    }


def dialogue_field_repair_token_budget(
    frozen_reply: str,
    requested_fields: list[str],
) -> int:
    """Reserve output for exactly the fields being repaired.

    A Japanese speech track can approach the length of the accepted Chinese
    reply.  The old fixed 520-token ceiling truncated longer tracks, while a
    large fixed ceiling would waste reservation on micro replies.  Speech-unit
    segmentation and emotion are deliberately not bundled into this request.
    """

    compact_length = len(re.sub(r"\s+", "", str(frozen_reply or "")))
    if "spokenTextJa" in requested_fields:
        return max(320, min(1600, 192 + compact_length * 3))
    return 256


def repair_dialogue_fields_once(
    settings: dict[str, Any],
    result: dict[str, Any],
    validation: dict[str, Any],
    *,
    user_message: str,
    recent_messages: list[dict[str, Any]],
    relationship_state: dict[str, Any],
    request_id: str,
    persona_snapshot: PersonaContextSnapshot | None = None,
) -> dict[str, Any]:
    """Repair only the speech-critical field while freezing accepted prose."""

    # Preserve the public call shape for existing callers, but do not give a
    # speech-only repair permission to reinterpret dialogue history or the
    # relationship state.
    del recent_messages, relationship_state

    frozen_reply = str(result.get("reply") or "").strip()
    frozen_fingerprint = runtime_fingerprint(frozen_reply, length=32)
    missing = [str(item) for item in validation.get("missingFields", [])]
    invalid = [str(item) for item in validation.get("invalidFields", [])]
    requested = list(dict.fromkeys([
        *(["spokenTextJa"] if "spokenTextJa" in {*missing, *invalid} else []),
    ]))
    if not requested:
        return dict(result)
    repair_max_tokens = dialogue_field_repair_token_budget(frozen_reply, requested)
    response_shape: dict[str, Any] = {field: "..." for field in requested}
    payload: dict[str, Any] = {
        "model": settings["apiModel"],
        "temperature": 0.18,
        "max_tokens": repair_max_tokens,
        "messages": [
            *persona_repair_prefix(persona_snapshot, legacy_system_prompt=False),
            {"role": "system", "content": (
                "你是 AMADEUS 的字段修复器，不重新回答用户，也不改写中文台词。"
                "只输出一个 JSON 对象，只填写 requestedFields 指定的字段；即使你认为中文可以改进也不得输出 reply。"
                "spokenTextJa 必须完整对应 frozenReply 的全部语义和情绪，使用自然年轻女性日语口语及官方专名读法。"
                "不要输出 emotion、speechUnits、gesture 或其他未请求字段。"
                + "\n" + SPOKEN_JA_NO_EMOJI_RULE
            )},
            {"role": "user", "content": json.dumps({
                "currentUserMessage": str(user_message or ""),
                "frozenReply": frozen_reply,
                "frozenSpokenTextJa": str(result.get("spokenTextJa") or ""),
                "frozenReplyFingerprint": frozen_fingerprint,
                "requestedFields": requested,
                "missingFields": missing,
                "invalidFields": invalid,
                "responseShape": response_shape,
                "pronunciationGlossary": spoken_ja_pronunciation_glossary(
                    frozen_reply,
                    str(result.get("spokenTextJa") or ""),
                ),
            }, ensure_ascii=False)},
        ],
    }
    write_server_log(
        "dialogue_field_repair_request",
        requestId=request_id,
        requestedFields=requested,
        maxTokens=repair_max_tokens,
        frozenReplyChars=len(frozen_reply),
    )
    if settings.get("useResponseFormat"):
        payload["response_format"] = {"type": "json_object"}
    if "deepseek.com" in settings["apiEndpoint"]:
        payload["thinking"] = {"type": "disabled"}
    LAST_UPSTREAM_FINISH_REASON.set("")
    content = send_upstream_chat_payload(
        settings,
        payload,
        timeout=45,
        request_id=request_id,
        purpose="dialogue_field_repair",
    )
    repair_finish_reason = LAST_UPSTREAM_FINISH_REASON.get()
    parsed = parse_json_object(content)
    repair_json_complete = isinstance(parsed, dict)
    write_server_log(
        "dialogue_field_repair_response",
        requestId=request_id,
        requestedFields=requested,
        maxTokens=repair_max_tokens,
        finishReason=repair_finish_reason,
        jsonComplete=repair_json_complete,
    )
    if not isinstance(parsed, dict):
        raise UpstreamProtocolError("dialogue field repair returned no JSON object")
    repaired = dict(result)
    if "spokenTextJa" in requested:
        spoken, _ = sanitize_roleplay_text(
            normalize_spoken_japanese_terms(parsed.get("spokenTextJa"))
        )
        spoken = soften_spoken_japanese_style(spoken)
        spoken_probe = {
            **repaired,
            "spokenTextJa": spoken,
            "spokenTextJaMissingFromModel": False,
            "speechSegmentCountMissingFromModel": False,
        }
        if not spoken or should_align_spoken_text_ja(settings, spoken_probe):
            raise UpstreamProtocolError("dialogue field repair returned unusable spokenTextJa")
        repaired["spokenTextJa"] = spoken
        repaired["spokenTextJaMissingFromModel"] = False
        repaired["spokenTextJaRepaired"] = True
        repaired["spokenTextJaRepairMode"] = "unified_field_repair"
    repaired["reply"] = frozen_reply
    repaired["dialogueFieldRepairSucceeded"] = True
    repaired["dialogueFieldRepairFrozenReplyFingerprint"] = frozen_fingerprint
    repaired["dialogueFieldRepairFields"] = requested
    repaired["dialogueFieldRepairMaxTokens"] = repair_max_tokens
    repaired["dialogueFieldRepairFinishReason"] = repair_finish_reason
    repaired["dialogueFieldRepairJsonComplete"] = repair_json_complete
    if persona_snapshot is not None:
        repaired["personaContextSnapshotId"] = persona_snapshot.snapshot_id
    return repaired


def repair_speech_plan_once(
    settings: dict[str, Any],
    result: dict[str, Any],
    *,
    request_id: str,
    persona_snapshot: PersonaContextSnapshot | None = None,
) -> list[dict[str, Any]]:
    """Repair only delivery boundaries while both accepted tracks stay frozen."""

    frozen_reply = str(result.get("reply") or result.get("textZh") or "").strip()
    frozen_spoken = str(result.get("spokenTextJa") or "").strip()
    speech_language = normalize_speech_language(result.get("speechLanguage"))
    require_spoken = speech_language == "ja-JP"
    if not frozen_reply or (require_spoken and not frozen_spoken):
        raise UpstreamProtocolError("speech plan repair requires complete frozen tracks")

    reply_fingerprint = runtime_fingerprint(frozen_reply, length=32)
    spoken_fingerprint = runtime_fingerprint(frozen_spoken, length=32)
    max_tokens = max(
        384,
        min(
            1800,
            256 + 2 * len(re.sub(r"\s+", "", frozen_reply + frozen_spoken)),
        ),
    )
    payload: dict[str, Any] = {
        "model": settings["apiModel"],
        "temperature": 0.12,
        "max_tokens": max_tokens,
        "messages": [
            *persona_repair_prefix(persona_snapshot, legacy_system_prompt=False),
            {"role": "system", "content": (
                "你是 AMADEUS 的语音交付计划修复器。正文与日语发声稿已经验收并冻结，"
                "不得改写、概括、补充或重新回答用户。只输出一个 JSON 对象，且只能包含 speechUnits。"
                f"speechUnits 必须有一到 {MAX_SPEECH_UNITS} 项，每项只含 zh、ja、boundaryAfter；"
                "zh 依次拼接必须与 frozenReply 完全一致，ja 依次拼接必须与 frozenSpokenTextJa 完全一致。"
                "每项必须是能够独立发声的完整语段，不得以逗号、冒号、连接词或从句悬空结束。"
                "省略号只表示句中停顿，不能单独作为切分边界。"
            )},
            {"role": "user", "content": json.dumps({
                "frozenReply": frozen_reply,
                "frozenSpokenTextJa": frozen_spoken,
                "frozenReplyFingerprint": reply_fingerprint,
                "frozenSpokenTextJaFingerprint": spoken_fingerprint,
                "responseShape": {
                    "speechUnits": [{
                        "zh": "冻结中文的连续片段",
                        "ja": "冻结日语的对应连续片段",
                        "boundaryAfter": "phrase_pause 或 turn_pause",
                    }],
                },
            }, ensure_ascii=False)},
        ],
    }
    if settings.get("useResponseFormat"):
        payload["response_format"] = {"type": "json_object"}
    if "deepseek.com" in settings["apiEndpoint"]:
        payload["thinking"] = {"type": "disabled"}
    write_server_log(
        "speech_plan_repair_request",
        requestId=request_id,
        frozenReplyFingerprint=reply_fingerprint,
        frozenSpokenTextJaFingerprint=spoken_fingerprint,
        chineseCharacters=len(re.sub(r"\s+", "", frozen_reply)),
        japaneseCharacters=len(re.sub(r"\s+", "", frozen_spoken)),
        maxTokens=max_tokens,
    )
    LAST_UPSTREAM_FINISH_REASON.set("")
    content = send_upstream_chat_payload(
        settings,
        payload,
        timeout=45,
        request_id=request_id,
        purpose="speech_plan_repair",
    )
    finish_reason = LAST_UPSTREAM_FINISH_REASON.get()
    parsed = parse_json_object(content)
    if not isinstance(parsed, dict) or set(parsed) != {"speechUnits"}:
        raise UpstreamProtocolError("speech plan repair returned fields outside speechUnits")
    units = normalize_speech_plan_units(
        parsed.get("speechUnits"),
        frozen_reply=frozen_reply,
        frozen_spoken=frozen_spoken,
        require_spoken=require_spoken,
    )
    write_server_log(
        "speech_plan_repair_response",
        requestId=request_id,
        accepted=bool(units),
        unitCount=len(units),
        finishReason=finish_reason,
        jsonComplete=isinstance(parsed, dict),
    )
    if not units:
        raise UpstreamProtocolError("speech plan repair did not losslessly cover frozen tracks")
    return units


def ordinary_core_dialogue_protocol(
    turn_policy: TurnPolicy,
    prepared_turn: PreparedTurn,
    tool_preflight: Any,
    research_decision: ResearchDecision,
    *,
    pre_tool_results: list[dict[str, Any]],
    attachment_prompt: str,
    file_output_expected: bool,
) -> bool:
    """Use the compact first-pass contract only when no external work owns the turn."""

    return bool(
        turn_policy.reply_mode in {"micro", "short"}
        and prepared_turn.route == "fast_chat"
        and bool(getattr(tool_preflight, "likely_no_tool", False))
        and research_decision.policy != "required"
        and not pre_tool_results
        and not str(attachment_prompt or "").strip()
        and not file_output_expected
    )


def core_dialogue_turn_contract_prompt(
    interpretation: UtteranceInterpretation,
    contract: TurnContract,
    *, model_owned: bool = False,
) -> str:
    """Keep semantic obligations and the outreach intent decision close to the input."""

    if model_owned:
        return (
            "[本轮语义判断由 ConversationBrain 负责] 根据用户原话和实际上下文决定 interactionAct、目标、"
            "是否纠正、是否继续任务及 proactiveDirective；不得把词法候选当成已经确认的用户意图。"
            "按认知协议报告 outcome，并以实际状态和回执判断完成程度；中文回答和日语发声稿应表达同一结论。"
        )
    proactive_contract = (
        {"proactiveDirectiveRequired": interpretation.proactive_directive}
        if interpretation.proactive_directive != "unchanged"
        else {"proactiveDirectivePolicy": "model_decides_from_current_user_intent"}
    )
    lines = [
        "[Turn Contract：普通对话首轮只负责语义结果]",
        json.dumps({
            "originalUserMessage": interpretation.original_text,
            "semanticText": interpretation.semantic_text,
            "primarySpeechAct": interpretation.primary_speech_act,
            "answerTarget": interpretation.answer_target,
            **proactive_contract,
            "requiredActs": list(contract.required_acts),
            "optionalActs": list(contract.optional_acts),
            "forbiddenSubstitutions": list(contract.forbidden_substitutions),
            "firstVisibleMustCover": list(contract.first_visible_must_cover),
            "replyMode": contract.reply_mode,
        }, ensure_ascii=False, separators=(",", ":")),
        "先完整完成 requiredActs；optionalActs 只能在答案已经成立后自然加入。",
        "semanticText 只是指代补全，不得替代用户原话。原话及最近对话中用户指定的范围、纠正优先；不得因摘要而擅自缩小范围或重复要求用户作已给出的选择。",
        (
            "proactiveDirectiveRequired 是强制状态合同，输出必须逐字一致。"
            if interpretation.proactive_directive != "unchanged"
            else
            "proactiveDirectivePolicy 要求依据当前用户整句意图决定主动联系状态；不要用单个等待或忙碌关键词代替语义判断。"
        ),
    ]
    if "answer_from_current_visual_observation" in contract.required_acts:
        lines.extend([
            "本轮已有当前视觉观测。先直接理解 semanticText 要求产出的结果类型：画面描述、文字读取、"
            "应用识别、当前活动判断或进一步分析。必须完成语义上实际要求的那一类，不能用另一类视觉输出代替。",
            "当 semanticText 要求活动判断或基于画面分析时，仅复述可见文字、按钮、框或应用名称不算完成；"
            "要先给出证据能支持的最具体结论，再简短说明画面依据。若只要求描述、OCR 或识别应用，就不强行推断活动。",
        ])
    lines.extend([
        "中文回答和日语发声稿都必须覆盖必答内容，且脱离未显示前文也能成立。",
        "不要声明完成状态；后端会依据输出、结束原因和本轮合同计算。",
    ])
    return "\n".join(lines)


def claim_level_fact_policy_prompt(prepared: PreparedTurn) -> str:
    """Expose the planner's narrow fact scopes without widening the turn."""

    plan = EpistemicPlan.from_dict(prepared.epistemic_plan)
    if plan is None:
        return ""
    claims = [
        {
            "claim": item.claim_scope or item.subject,
            "verificationLevel": item.verification_level,
            "answerDependency": item.answer_dependency,
            "epistemicRisk": item.epistemic_risk,
            "safeReasoningAvailable": item.safe_reasoning_available,
        }
        for item in plan.fact_requirements
        if item.domain == "external_world" and (item.claim_scope or item.subject)
    ]
    if not claims:
        return ""
    return "\n".join([
        "[Claim-Level Fact Policy：事实门只管理列出的具体主张]",
        json.dumps({
            "researchPolicy": plan.research_policy,
            "claims": claims,
        }, ensure_ascii=False, separators=(",", ":")),
        "NONE 不需要外部核查。SOFT 是附属事实：没有充分证据时只降低该主张的确定性，"
        "仍须完整回答用户的独立情感、观点、建议、推理或哲学问题，禁止用全局无法确认替代。"
        "HARD 才能阻塞依赖该事实的内容；没有证据时不得凭记忆补全。"
        "用户提供的经历和描述只能按用户归属讨论，不要自动升级成公共事实。",
    ])


def pressure_managed_prompt(
    messages: Sequence[dict[str, Any]],
    settings: dict[str, Any],
    *,
    reserved_output_tokens: int,
    request_id: str,
    stage: str,
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    managed, snapshot = apply_prompt_pressure(
        messages,
        model_context_limit=_safe_nonnegative_int(
            settings.get("apiContextLimit") or DEFAULT_SETTINGS["apiContextLimit"]
        ) or int(DEFAULT_SETTINGS["apiContextLimit"]),
        reserved_output_tokens=max(256, int(reserved_output_tokens)),
        reserved_system_margin=2048,
    )
    metrics = snapshot.to_dict()
    write_server_log(
        "context_pressure_decision",
        requestId=request_id,
        stage=stage,
        **metrics,
    )
    if not snapshot.fits_budget:
        raise RequestValidationError(
            "context_budget_exceeded",
            "当前不可压缩的系统与会话上下文仍超过模型输入预算，已在调用模型前停止。"
            f"还需释放约 {snapshot.over_budget_tokens} 个估算 token。",
        )
    return managed, metrics


def finalize_preexecuted_tool_result(
    settings: dict[str, Any],
    *,
    base_messages: list[dict[str, Any]],
    primary_content: str,
    executed_results: list[dict[str, Any]],
    duplicate_requests: list[dict[str, Any]],
    context_resolution: dict[str, Any],
    user_message: str,
    turn_policy: TurnPolicy,
    file_output_expected: bool,
    interpretation: UtteranceInterpretation,
    contract: TurnContract,
    request_id: str,
    cognitive_body: dict[str, Any] | None = None,
) -> tuple[str, str, int]:
    """Turn an already-executed duplicate tool request into one final reply."""

    write_server_log(
        "preexecuted_duplicate_tool_finalize",
        requestId=request_id,
        tools=[str(item.get("name") or "") for item in duplicate_requests],
        resultStatuses=[{
            "name": str(item.get("name") or ""),
            "ok": bool(item.get("ok")),
            "error": str(item.get("error") or "")[:120],
        } for item in executed_results if isinstance(item, Mapping)],
    )
    tool_context = tool_context_prompt(
        executed_results,
        context_resolution,
        max_chars=turn_policy.tool_evidence_max_chars,
        model_owned=bool(cognitive_turn_state(cognitive_body or {})),
    )
    visual_context = visual_evidence_prompt(
        executed_results,
        user_question=interpretation.semantic_text or user_message,
    )
    grounding = tool_grounding_instruction(executed_results)
    terminal_messages = [
        *base_messages,
        {"role": "assistant", "content": primary_content},
        {"role": "system", "content": tool_context},
        *([{"role": "system", "content": visual_context}] if visual_context else []),
        *([{"role": "system", "content": grounding}] if grounding else []),
        {"role": "system", "content": (
            "你刚请求的工具已经在本轮执行，禁止重复输出 tool_use。"
            "请依据已返回的真实结果，按照 semantic-v3 输出 kind='turn'；"
            "成功时直接回答，失败或权限不足时明确说明具体失败原因和可行下一步。"
            "不得把工具请求 JSON 当作面向用户的回复，也不得编造成功。"
        )},
        {"role": "system", "content": core_dialogue_turn_contract_prompt(
            interpretation,
            contract,
            model_owned=bool(cognitive_body and cognitive_turn_state(cognitive_body)),
        )},
    ]
    max_tokens = (
        6000
        if file_output_expected
        else min(6_000, fast_stream_token_budget(turn_policy) + 240)
    )
    terminal_messages, _ = pressure_managed_prompt(
        terminal_messages,
        settings,
        reserved_output_tokens=max_tokens,
        request_id=request_id,
        stage="chat_preexecuted_duplicate_finalize",
    )
    payload: dict[str, Any] = {
        "model": settings["apiModel"],
        "temperature": 0.5,
        "max_tokens": max_tokens,
        "messages": terminal_messages,
    }
    if settings.get("useResponseFormat"):
        payload["response_format"] = {"type": "json_object"}
    if "deepseek.com" in settings["apiEndpoint"]:
        payload["thinking"] = {"type": "disabled"}
    update_chat_request_progress(
        request_id,
        "model-synthesizing",
        "工具已经执行，正在根据真实结果形成回答",
    )
    started = time.perf_counter()
    if cognitive_body is not None and cognitive_turn_state(cognitive_body):
        state = cognitive_turn_state(cognitive_body)
        bind_reused_tool_steps(cognitive_body, state, duplicate_requests, executed_results)
        cognitive_body["_cognitiveEvidence"] = {
            **(cognitive_body.get("_cognitiveEvidence") or {}), **collect_evidence(executed_results),
        }
        cognitive_body["_cognitiveToolLoopTerminal"] = True
        try:
            content = send_conversation_brain_payload(cognitive_body, settings, payload,
                timeout=90, request_id=request_id, purpose="chat_tool_preexecuted_duplicate_finalize")
        finally:
            cognitive_body.pop("_cognitiveToolLoopTerminal", None)
    else:
        image_body = cognitive_body if cognitive_body is not None else {"requestId": request_id}
        image_body["_cognitiveEvidence"] = {
            **(image_body.get("_cognitiveEvidence") or {}), **collect_evidence(executed_results),
        }
        images = conversation_image_inputs(image_body, settings)
        outgoing = with_conversation_images(image_body, payload, images, purpose="chat_preexecuted_duplicate_finalize")
        record_persona_model_input(image_body, outgoing, "chat_preexecuted_duplicate_finalize")
        content = send_upstream_chat_payload(
            settings, outgoing,
            timeout=90, request_id=request_id,
            purpose="chat_preexecuted_duplicate_finalize",
        )
        image_body["_nativeVisualInputIds"] = [item["artifactId"] for item in images]
    return (
        content,
        LAST_UPSTREAM_FINISH_REASON.get(),
        round((time.perf_counter() - started) * 1000),
    )


def call_upstream(
    body: dict[str, Any],
    *,
    progress_callback: Any | None = None,
    persona_snapshot: PersonaContextSnapshot | None = None,
    continuation: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    pipeline_started = time.perf_counter()
    settings = load_settings()
    request_id = str(body.get("requestId") or "").strip()
    settings = {**settings, "_directVisualChat": native_visual_chat_enabled(settings)}
    continuation = (
        deepcopy(dict(continuation))
        if isinstance(continuation, Mapping)
        else None
    )
    continuation_content = (
        str(continuation.get("content") or "")
        if continuation is not None else ""
    )
    continuation_tool_results = (
        [dict(item) for item in continuation.get("toolResults", [])
         if isinstance(item, Mapping)]
        if continuation is not None and isinstance(continuation.get("toolResults"), list)
        else []
    )
    existing_tool_rounds = _safe_nonnegative_int(
        body.get("_cognitiveToolRoundsUsed", 0)
    )
    continuation_tool_rounds = (
        max(
            _safe_nonnegative_int(
                continuation.get("toolRounds", existing_tool_rounds)
            ),
            1 if continuation_tool_results else 0,
        )
        if continuation is not None else existing_tool_rounds
    )
    if continuation is not None:
        if not cognitive_turn_state(body):
            raise CognitiveProtocolError(
                "final_projection_continuation_requires_cognitive_state"
            )
        if not continuation_content:
            raise CognitiveProtocolError(
                "final_projection_continuation_missing_candidate"
            )
        continuation_preview = parse_json_object(continuation_content) or {}
        continuation_requests = (
            continuation_preview.get("calls")
            or continuation_preview.get("toolRequests")
            or []
        ) if isinstance(continuation_preview, Mapping) else []
        if (
            continuation_tool_rounds >= 3
            and str(continuation_preview.get("kind") or "").lower() == "tool_use"
            and isinstance(continuation_requests, list)
            and continuation_requests
        ):
            raise CognitiveProtocolError(
                "final_projection_continuation_tool_round_budget_exhausted"
            )
    update_chat_request_progress(request_id, "context", "正在整理当前对话、记忆与人格上下文")
    messages = body.get("messages") if isinstance(body.get("messages"), list) else []
    supplied_memories = body.get("memories") if isinstance(body.get("memories"), list) else []
    successive_inputs = [
        str(item).strip()
        for item in (body.get("userMessages") if isinstance(body.get("userMessages"), list) else [])
        if str(item).strip()
    ]
    user_message = "\n".join(successive_inputs) if successive_inputs else str(body.get("userMessage") or "")
    semantic_task_request = current_task_semantic_request(body, user_message)
    incoming_tool_escalation = (
        {}
        if continuation is not None
        else body.get("_toolEscalation")
        if isinstance(body.get("_toolEscalation"), Mapping)
        else {}
    )
    if (
        isinstance(incoming_tool_escalation.get("scheduleIntent"), Mapping)
        and not isinstance(body.get("_scheduleDecision"), Mapping)
    ):
        body["_scheduleDecision"] = apply_model_schedule_payload(
            incoming_tool_escalation,
            request_id=request_id,
            user_message=user_message,
        )
    prepared_action_turn = body_prepared_action_turn(
        body,
        user_message,
        request_id=request_id,
    )
    pending_relation = prepared_action_turn.pending_relation.relation
    if pending_relation == "cancel" and not cognitive_turn_state(body):
        clear_pending_action()
    elif pending_relation == "pause" and not cognitive_turn_state(body):
        pending = current_pending_action()
        if pending:
            pending["status"] = "paused"
            pending["updatedAt"] = now_iso()
            write_pending_action_record(pending)
    pending_todo_before = current_pending_action()
    pending_todo_before = (
        pending_todo_before
        if pending_todo_before.get("type") == "todo_mutation" else {}
    )
    todo_continuation_transition: dict[str, Any] = {}
    attachment_requested = bool(
        body.get("attachments") if isinstance(body.get("attachments"), list) else []
    ) or is_attachment_followup_query(user_message)
    file_output_expected = attachment_requested and bool(re.search(
        r"修改|改写|改一下|改成|改为|编辑|修复|重写|更新|生成|创建|新建|输出|导出|保存|补全|翻译|替换|换成|删掉|追加",
        user_message,
        re.I,
    ))
    body["_attachmentOutputRequested"] = file_output_expected
    utterance_interpretation = utterance_interpretation_from_prepared(
        prepared_action_turn
    )
    preliminary_policy = choose_turn_policy(
        user_message,
        has_attachments=attachment_requested,
        file_output_expected=file_output_expected,
        interpretation=utterance_interpretation,
    )
    attachment_prompt = attachment_context_prompt(
        body,
        messages,
        user_message,
        max_chars=(
            MAX_ATTACHMENT_CONTEXT_CHARS
            if file_output_expected else preliminary_policy.tool_evidence_max_chars
        ),
    )
    interrupted_previous_reply = bool(body.get("interruptedPreviousReply"))
    proactive_context = str(body.get("proactiveContext") or "").strip()
    relationship_state = frozen_turn_relationship_state(body) or read_relationship_state()
    identity_context = identity_grounding_prompt(user_message)
    # The backend owns persona composition. Legacy clients may still send an
    # obsolete prompt; accepting it would bypass layered retrieval and produce
    # different behavior depending on which UI opened the same server.
    prompt = read_system_prompt()
    attribution_evidence = speaker_attribution_evidence_prompt(messages, user_message)
    context_resolution = contextual_reference_resolution(
        user_message,
        messages,
        request_id=request_id,
        current_artifacts=current_turn_context_artifacts(body),
        resolved_task=semantic_task_request,
        context_state=frozen_turn_context_state(body),
        model_owned=bool(cognitive_turn_state(body)),
    )
    body["_contextResolution"] = context_resolution
    prepared_action_turn = apply_contextual_research_subject(
        prepared_action_turn,
        context_resolution,
    )
    body["_preparedActionTurn"] = prepared_action_turn
    utterance_interpretation = utterance_interpretation_from_prepared(
        prepared_action_turn
    )
    utterance_interpretation = bind_resolved_task_interpretation(utterance_interpretation, body)
    pending_question_context = pending_assistant_question_prompt(messages, user_message)
    todo_pending_context = pending_todo_action_prompt()
    schedule_state_context = current_schedule_workflow_prompt()
    active_persona_snapshot = persona_snapshot or build_persona_context_snapshot(
        user_message,
        messages,
        context_resolution,
        relationship_state,
        cognitive_body=body,
    )
    prompt = active_persona_snapshot.system_prompt
    deep_persona_prompt = active_persona_snapshot.prompt_text
    loaded_persona_modules = list(active_persona_snapshot.provider_module_ids)
    context_resolution["personaModules"] = loaded_persona_modules
    tool_started = time.perf_counter()
    attachment_tool_results = attachment_read_tool_results(body)
    current_attachments = body.get("_processedAttachments") if isinstance(body.get("_processedAttachments"), list) else []
    attachment_followup = is_attachment_followup_query(user_message)
    has_bound_attachment = bool(current_attachments or attachment_followup)
    explicitly_requested_sensors = explicitly_requested_sensor_tools(user_message)
    todo_reconciliation = body_todo_reconciliation(
        body,
        user_message,
        messages,
    )
    inferred_requests = infer_agent_tool_requests(
        user_message,
        messages,
        context_resolution,
        prepared_action_turn,
        todo_reconciliation,
    )
    inferred_requests = task_bound_tool_requests(body, inferred_requests)
    if cognitive_turn_state(body):
        # Legacy lexical candidates cannot execute before the main model has
        # seen the user's feedback and revised the pending task. Validated
        # model escalations are merged below and retain the normal tool guard.
        inferred_requests = []
    if continuation is not None:
        # A final-audit resume starts after the original turn's pre-execution
        # phase.  The repaired candidate is the only source of new requests;
        # never infer or replay actions from the original user text here.
        inferred_requests = []
    inferred_requests, rejected_attachment_sensor_requests = (
        constrain_attachment_sensor_requests(
            inferred_requests,
            user_message,
            has_bound_attachment=has_bound_attachment,
        )
    )
    for item in rejected_attachment_sensor_requests:
        write_server_log(
            "attachment_sensor_request_rejected",
            requestId=request_id,
            toolName=str(item.get("name") or ""),
            source="inferred_tool_request",
            reason="current_attachment_is_authoritative_target",
        )
    turn_policy = choose_turn_policy(
        user_message,
        has_tools=bool(inferred_requests or attachment_tool_results or continuation_tool_results),
        has_attachments=bool(attachment_prompt or current_attachments),
        file_output_expected=file_output_expected,
        interpretation=utterance_interpretation,
    )
    turn_contract = build_turn_contract(
        utterance_interpretation,
        turn_policy,
    )
    body["_cognitiveTurnContract"] = turn_contract
    tool_preflight = body_tool_preflight(
        body,
        user_message,
        messages,
        reply_mode=turn_policy.reply_mode,
        speech_act=utterance_interpretation.primary_speech_act,
    )
    tool_escalation = (
        None
        if continuation is not None
        else body.get("_toolEscalation")
        if isinstance(body.get("_toolEscalation"), dict)
        else None
    )
    if tool_escalation:
        escalation_target = str(tool_escalation.get("targetDomain") or "").strip()
        if (
            escalation_target == "screen"
            and (
                not has_bound_attachment
                or "capture_screen" in explicitly_requested_sensors
            )
        ):
            screen_need = PerceptionNeed(
                required=True,
                target_domain="screen",
                freshness="current",
                confidence=clamp_float(
                    tool_escalation.get("confidence"),
                    0.55,
                    1.0,
                    0.72,
                ),
                ambiguities=("target_refined_by_fast_model_before_visible_output",),
            )
            tool_preflight = replace(
                tool_preflight,
                candidate_capabilities=("capture_screen",),
                mandatory_capabilities=("capture_screen",),
                likely_no_tool=False,
                confidence=screen_need.confidence,
                perception=screen_need,
                reasons=tuple(dict.fromkeys([
                    *tool_preflight.reasons,
                    "fast_model_refined_perception_target:screen",
                ])),
            )
            body["_toolPreflight"] = tool_preflight
        escalation_requests = normalize_tool_requests({
            "toolRequests": tool_escalation.get("toolRequests"),
            "targetDomain": escalation_target,
            "toolAuthorization": tool_escalation.get("toolAuthorization"),
        })
        capability_query = str(tool_escalation.get("capabilityQuery") or "").strip()
        if capability_query and not escalation_requests:
            searched = DEFAULT_TOOL_REGISTRY.search(capability_query, limit=4)
            write_server_log(
                "tool_search_completed",
                requestId=request_id,
                query=capability_query[:300],
                resultToolIds=[item.tool_id for item in searched],
            )
            tool_preflight = merge_searched_tool_candidates(
                tool_preflight,
                searched,
                query=capability_query,
            )
            body["_toolPreflight"] = tool_preflight
            if escalation_target == "screen" and any(
                item.tool_id == "capture_screen" for item in searched
            ):
                escalation_requests = [{"name": "capture_screen", "args": {}}]
        escalation_requests = constrain_model_tool_requests(
            escalation_requests,
            user_message,
            context_resolution,
            messages,
            body.get("_scheduleDecision"),
            cognitive_state=cognitive_execution_state(body), evidence=body.get("_cognitiveEvidence") or {},
        )
        escalation_requests, rejected_escalation_sensor_requests = (
            constrain_attachment_sensor_requests(
                escalation_requests,
                user_message,
                has_bound_attachment=has_bound_attachment,
            )
        )
        tool_preflight = bind_structured_perception_request(
            tool_preflight,
            escalation_requests,
            source="fast_stream_tool_escalation",
        )
        body["_toolPreflight"] = tool_preflight
        for item in rejected_escalation_sensor_requests:
            write_server_log(
                "attachment_sensor_request_rejected",
                requestId=request_id,
                toolName=str(item.get("name") or ""),
                source="fast_stream_tool_escalation",
                reason="current_attachment_is_authoritative_target",
                modelTargetDomain=escalation_target,
            )
        annotated_escalation_requests = [
            {
                **item,
                "reason": "fast model escalated a missing capability before visible output",
                "selection": {
                    **(
                        dict(item.get("selection"))
                        if isinstance(item.get("selection"), Mapping) else {}
                    ),
                    "source": "fast_stream_tool_escalation",
                    "targetDomain": (item.get("selection") or {}).get("targetDomain") or escalation_target,
                },
            }
            for item in escalation_requests
        ]
        combined_request_count = len(inferred_requests) + len(
            annotated_escalation_requests
        )
        inferred_requests = merge_preexecution_tool_requests(
            inferred_requests,
            annotated_escalation_requests,
        )
        if len(inferred_requests) < combined_request_count:
            write_server_log(
                "preexecution_tool_requests_merged",
                requestId=request_id,
                beforeCount=combined_request_count,
                afterCount=len(inferred_requests),
                refinedTools=[
                    str(item.get("name") or "") for item in escalation_requests
                ],
            )
        if escalation_requests:
            turn_policy = choose_turn_policy(
                user_message,
                has_tools=True,
                has_attachments=bool(attachment_prompt or current_attachments),
                file_output_expected=file_output_expected,
                interpretation=utterance_interpretation,
            )
            turn_contract = build_turn_contract(
                utterance_interpretation,
                turn_policy,
            )
            body["_cognitiveTurnContract"] = turn_contract
            tool_preflight = replace(
                tool_preflight,
                reply_mode=turn_policy.reply_mode,
            )
    escalation = (
        None
        if continuation is not None
        else body.get("_researchEscalation")
        if isinstance(body.get("_researchEscalation"), dict)
        else None
    )
    prepared_action_turn, research_decision, capability = (
        enrich_prepared_turn_with_research(
            prepared_action_turn,
            turn_policy,
            turn_contract,
            settings,
            interpretation=utterance_interpretation,
            escalation=escalation,
        )
    )
    document_results = [
        item for item in attachment_tool_results
        if item.get("name") == "read_file"
    ]
    if document_results:
        document_plan = EpistemicPlan.from_dict(prepared_action_turn.epistemic_plan)
        if document_plan is not None:
            document_subject = "；".join(
                str(item.get("fileName") or "current uploaded document")
                for item in document_results
            )
            document_plan = document_plan.with_current_document_evidence(
                subject=document_subject,
                content_available=any(item.get("ok") for item in document_results),
            )
            prepared_action_turn = replace(
                prepared_action_turn,
                epistemic_plan=document_plan.to_dict(),
                epistemic_state=document_plan.epistemic_state().to_dict(),
            )
            body["_preparedActionTurn"] = prepared_action_turn
    local_research_decision = reconcile_research_with_tool_preflight(
        research_decision,
        tool_preflight,
        user_message,
    )
    if local_research_decision != research_decision:
        research_decision = local_research_decision
        prepared_action_turn, research_decision = synchronize_prepared_epistemic_plan(
            prepared_action_turn,
            research_decision,
        )
        capability = capability_envelope(
            turn_policy,
            research_decision,
            web_permission=bool(settings.get("permissionWebSearch")),
        )
    prepared_action_turn, research_decision, capability = (
        reconcile_preanswer_research_route(
            settings,
            user_message,
            prepared_action_turn,
            research_decision,
            turn_policy,
            body,
            request_id=str(body.get("requestId") or ""),
        )
    )
    capability = capability_with_tool_preflight(
        capability,
        tool_preflight,
        settings,
        extra_tool_ids=[
            str(item.get("name") or "")
            for item in inferred_requests
            if isinstance(item, dict)
        ],
    )
    prepared_action_turn = replace(
        prepared_action_turn,
        capability_envelope=capability.to_dict(),
    )
    reconciled_decision = reconcile_research_decision_with_tool_requests(
        research_decision,
        inferred_requests,
    )
    if reconciled_decision != research_decision:
        research_decision = reconciled_decision
        prepared_action_turn, research_decision = synchronize_prepared_epistemic_plan(
            prepared_action_turn,
            research_decision,
        )
        capability = capability_envelope(
            turn_policy,
            research_decision,
            web_permission=bool(settings.get("permissionWebSearch")),
        )
        capability = capability_with_tool_preflight(
            capability,
            tool_preflight,
            settings,
            extra_tool_ids=[
                str(item.get("name") or "")
                for item in inferred_requests
                if isinstance(item, dict)
            ],
        )
        prepared_action_turn = replace(
            prepared_action_turn,
            research_decision=research_decision.to_dict(),
            capability_envelope=capability.to_dict(),
        )
    execution_plan = finalize_turn_execution_plan(
        body,
        user_message=user_message,
        decision=research_decision,
        preflight=tool_preflight,
        tool_requests=inferred_requests,
        settings=settings,
        has_attachments=bool(current_attachments or attachment_prompt),
        model_research_escalation=bool(escalation),
        model_tool_escalation=bool(tool_escalation),
    )
    tool_preflight = bind_required_capabilities(
        tool_preflight,
        execution_plan.required_capabilities,
    )
    body["_toolPreflight"] = tool_preflight
    if execution_plan.research_policy != research_decision.policy:
        research_decision = replace(
            research_decision,
            policy=execution_plan.research_policy,
            reasons=tuple(dict.fromkeys((
                *research_decision.reasons,
                "turn_execution_plan_finalized",
            ))),
            plan_revision=max(
                research_decision.plan_revision + 1,
                execution_plan.revision,
            ),
        )
        prepared_action_turn, research_decision = synchronize_prepared_epistemic_plan(
            prepared_action_turn,
            research_decision,
        )
    capability = capability_envelope(
        turn_policy,
        research_decision,
        web_permission=bool(settings.get("permissionWebSearch")),
    )
    capability = capability_with_tool_preflight(
        capability,
        tool_preflight,
        settings,
        extra_tool_ids=[
            str(item.get("name") or "")
            for item in inferred_requests
            if isinstance(item, dict)
        ],
    )
    capability = replace(
        capability,
        research_policy=execution_plan.research_policy,
        required_tools=execution_plan.required_capabilities,
        max_tool_rounds=execution_plan.max_tool_rounds,
        tool_policy=(
            "required" if execution_plan.required_capabilities else "model_decides"
        ),
    )
    prepared_action_turn = replace(
        prepared_action_turn,
        research_decision=research_decision.to_dict(),
        capability_envelope=capability.to_dict(),
    )
    body["_preparedActionTurn"] = prepared_action_turn
    persist_prepared_turn(prepared_action_turn)
    write_tool_preflight_log(request_id, tool_preflight, capability)
    write_server_log(
        "turn_execution_plan_consumed",
        requestId=request_id,
        executionPlan=execution_plan.to_dict(),
    )
    if execution_plan.research_policy == "forbidden":
        inferred_requests = [
            item
            for item in inferred_requests
            if str(item.get("name") or "") not in {"web_search", "read_web_page"}
        ]
    elif (
        continuation is None
        and execution_plan.research_policy == "required"
        and not any(
        str(item.get("name") or "") in {"web_search", "read_web_page"}
        for item in inferred_requests
        )
    ):
        escalation_queries = (
            escalation.get("queries")
            if isinstance(escalation, dict) and isinstance(escalation.get("queries"), list)
            else []
        )
        query = next(
            (str(item).strip() for item in escalation_queries if str(item).strip()),
            fallback_web_research_query(user_message, context_resolution, messages),
        )
        inferred_requests.append({
            "name": "web_search",
            "args": {
                "query": query[:500],
                "freshness": web_search_freshness(user_message),
                "researchDecision": research_decision.to_dict(),
            },
            "reason": "unified research decision or fast-path escalation",
        })
    write_server_log(
        "turn_contract_created",
        requestId=request_id,
        interpretation=utterance_interpretation.to_dict(),
        contract=turn_contract.to_dict(),
        researchDecision=research_decision.to_dict(),
        capabilityEnvelope=capability.to_dict(),
    )
    memories, memory_records, memory_need = retrieve_turn_memories(
        settings,
        supplied_memories,
        user_message,
        messages,
        limit=turn_policy.memory_top_k,
        cognitive_state=cognitive_turn_state(body),
        context_state=frozen_turn_context_state(body),
    )
    memories, memory_records = bind_cognitive_memories(body, memories, memory_records)
    inferred_web_searches = [
        item for item in inferred_requests if item.get("name") == "web_search"
    ] if continuation is None else []
    browser_target_resolution_request = next(
        (
            item
            for item in inferred_web_searches
            if isinstance(item.get("args"), dict)
            and item["args"].get("browserTargetResolution")
            and str(item["args"].get("query") or "").strip()
        ),
        None,
    )
    browser_target_resolution_query = (
        str(browser_target_resolution_request["args"].get("query") or "").strip()[:240]
        if browser_target_resolution_request else ""
    )
    inferred_direct_requests = [
        item for item in inferred_requests if item.get("name") != "web_search"
    ] if continuation is None else []
    deferred_browser_requests = [
        item for item in inferred_direct_requests
        if item.get("name") == "open_browser"
        and isinstance(item.get("args"), dict)
        and item["args"].get("deferToResearch")
    ] if continuation is None else []
    inferred_direct_requests = [
        item for item in inferred_direct_requests
        if item not in deferred_browser_requests
    ]
    # Attachment ingestion has already produced the read_file/read_image
    # receipt. Those capabilities are declarative at this layer and have no
    # second executor; executing them again created a false failed result next
    # to the successful receipt and made the UI report toolStatus=failed.
    preexecuted_inferred_attachment_requests = [
        item for item in inferred_direct_requests
        if preexecuted_attachment_request_satisfied(item, attachment_tool_results)
    ]
    if preexecuted_inferred_attachment_requests:
        inferred_direct_requests = [
            item for item in inferred_direct_requests
            if item not in preexecuted_inferred_attachment_requests
        ]
        write_server_log(
            "preexecuted_inferred_attachment_request_satisfied",
            requestId=request_id,
            requestedTools=[
                str(item.get("name") or "")
                for item in preexecuted_inferred_attachment_requests
            ],
        )
    browser_requests = [
        item
        for item in [*inferred_direct_requests, *deferred_browser_requests]
        if item.get("name") == "open_browser"
    ]
    pending_browser_action: dict[str, Any] = {}
    if browser_requests:
        continue_pending_browser_action = pending_relation == "continue"
        target_hint = (
            browser_target_resolution_query
            or next(
                (
                    str(item.get("args", {}).get("resolveQuery") or item.get("args", {}).get("query") or "")
                    for item in browser_requests
                    if isinstance(item.get("args"), dict)
                ),
                "",
            )
            or outbound_web_query(web_search_query_from_message(user_message))
        )
        candidate_sources, _ = recent_message_web_sources(messages)
        pending_browser_action = save_pending_browser_action(
            request_id=request_id,
            target_hint=target_hint,
            batch_id=str(
                next(
                    (
                        item.get("batchId")
                        for item in candidate_sources
                        if item.get("batchId")
                    ),
                    "",
                )
            ),
            status="resolving" if deferred_browser_requests else "ready",
            candidates=candidate_sources,
            reuse_existing=continue_pending_browser_action,
        )
        for browser_request in browser_requests:
            args = (
                dict(browser_request.get("args"))
                if isinstance(browser_request.get("args"), dict)
                else {}
            )
            args["actionId"] = str(pending_browser_action.get("actionId") or "")
            args["_actionGroupId"] = str(pending_browser_action.get("actionGroupId") or pending_browser_action.get("actionId") or "")
            browser_request["args"] = args
    inferred_has_visual_tool = any(
        item.get("name") in {"capture_screen", "capture_camera"}
        for item in inferred_direct_requests
    )
    research_plan: dict[str, Any] | None = None
    research_planning_ms = 0
    research_review_ms = 0
    research_review: dict[str, Any] | None = None
    planned_web_results: list[dict[str, Any]] = []
    research_bridge_ms = 0
    research_bridge_emitted = bool(body.get("_semanticToolProgressProvided"))

    def emit_research_bridge_once(active_plan: dict[str, Any]) -> None:
        # Semantic Stream V2 obtains an optional natural progress utterance in
        # the same main-model tool_use response.  Never spend a separate model
        # call merely to say "I will check"; tool_status already keeps the UI
        # alive when the model omitted progress.
        del active_plan
        return

    if inferred_web_searches and settings.get("permissionWebSearch"):
        update_chat_request_progress(
            request_id,
            "research-planning",
            "正在理解问题、保留专有名词并规划检索方向",
        )
        planning_started = time.perf_counter()
        model_escalation_queries = unique_strings(
            [
                *(
                    escalation.get("queries")
                    if isinstance(escalation, dict)
                    and isinstance(escalation.get("queries"), list)
                    else []
                ),
                str(body.get("_preAnswerResearchQuery") or "").strip(),
            ]
        )[:3]
        research_plan = (
            {
                "needsWeb": True,
                "resolvedQuestion": f"解析要直接打开的公网目标：{browser_target_resolution_query}",
                "plannerResolvedQuestion": "",
                "userAnchor": browser_target_resolution_query[:80],
                "strictAnchorMatch": False,
                "queries": [{
                    "query": browser_target_resolution_query,
                    "purpose": "找到用户所指目标的权威直接页面 URL",
                }],
                "answerRequirements": ["只选择与目标匹配的直接页面，不打开搜索结果页"],
                "ambiguities": [],
                "questionAnalysis": {
                    "intent": "解析并打开用户指定的网页目标",
                    "subject": browser_target_resolution_query[:120],
                    "protectedTerms": [browser_target_resolution_query[:100]],
                    "factsToVerify": ["目标页面的真实公网 URL"],
                },
                "fallback": False,
                "browserTargetResolution": True,
            }
            if browser_target_resolution_query else
            {
                "needsWeb": True,
                "resolvedQuestion": str(
                    context_resolution.get("resolvedQuestion") or user_message
                ).strip()[:500],
                "plannerResolvedQuestion": "",
                "userAnchor": str(user_message or "").strip()[:80],
                "strictAnchorMatch": False,
                "queries": [
                    {
                        "query": query[:500],
                        "purpose": "核实主模型在同一 QueryLoop 中识别出的证据缺口",
                    }
                    for query in model_escalation_queries
                ],
                "answerRequirements": list(
                    escalation.get("verificationTargets")
                    if isinstance(escalation, dict)
                    and isinstance(escalation.get("verificationTargets"), list)
                    else []
                ),
                "ambiguities": list(
                    escalation.get("unknownEntities")
                    if isinstance(escalation, dict)
                    and isinstance(escalation.get("unknownEntities"), list)
                    else []
                ),
                "questionAnalysis": {
                    "intent": "核实回答所需的公开事实",
                    "subject": str(
                        context_resolution.get("resolvedQuestion") or user_message
                    ).strip()[:160],
                    "protectedTerms": list(
                        escalation.get("unknownEntities")
                        if isinstance(escalation, dict)
                        and isinstance(escalation.get("unknownEntities"), list)
                        else []
                    ),
                    "factsToVerify": list(
                        escalation.get("verificationTargets")
                        if isinstance(escalation, dict)
                        and isinstance(escalation.get("verificationTargets"), list)
                        else []
                    ),
                },
                "fallback": False,
                "plannedBy": "query_loop_main_model",
            }
            if model_escalation_queries else
            plan_web_research(
                settings,
                user_message,
                messages,
                context_resolution,
                request_id=request_id,
            )
        )
        research_planning_ms = round((time.perf_counter() - planning_started) * 1000)
        # The deterministic policy decides whether public evidence is required.
        # A planner may refine the route, but it cannot silently cancel an
        # explicit/current/high-risk research request.
        if not research_plan.get("queries"):
            research_plan = fallback_web_research_plan(user_message, context_resolution, messages)
        if research_decision.source_policy_id:
            research_plan["sourcePolicyId"] = research_decision.source_policy_id
        research_plan["researchPolicy"] = research_decision.policy
        research_plan["verificationTargets"] = list(
            research_decision.verification_targets
        )
        research_plan["entityTerms"] = unique_strings([
            *research_decision.unknown_entities,
            *(
                research_plan.get("entityTerms")
                if isinstance(research_plan.get("entityTerms"), list)
                else []
            ),
        ])
        emit_research_bridge_once(research_plan)
        research_analysis = (
            research_plan.get("questionAnalysis")
            if isinstance(research_plan.get("questionAnalysis"), dict)
            else {}
        )
        research_subject = re.sub(
            r"\s+",
            " ",
            str(research_analysis.get("subject") or ""),
        ).strip()[:80]
        update_chat_request_progress(
            request_id,
            "researching",
            (
                f"已提炼核心主题“{research_subject}”，正在查阅 "
                f"{len(research_plan.get('queries', []))} 个证据方向"
                if research_subject
                else f"已提炼核心问题，正在查阅 {len(research_plan.get('queries', []))} 个证据方向"
            ),
        )
        update_chat_request_progress(
            request_id,
            "research-reviewing",
            "正在循环核对来源正文、实体映射与尚缺的证据",
        )
        planned_result, research_plan, research_review, research_review_ms = (
            run_research_query_loop(
                settings,
                user_message,
                messages,
                research_plan,
                context_resolution,
                research_decision,
                capability,
                request_id=request_id,
                cognitive_body=body,
            )
        )
        planned_web_results = [planned_result]
    elif inferred_web_searches:
        # Preserve the explicit permission error without spending an extra API
        # call on planning a search that cannot be executed.
        inferred_direct_requests.extend(inferred_web_searches)
    if inferred_direct_requests:
        update_chat_request_progress(
            request_id,
            "tool-executing",
            "正在执行回答所需的本地工具或指定网页读取",
        )
    inferred_direct_results = [] if continuation is not None else (
        execute_agent_tools(
            inferred_direct_requests,
            settings,
            user_message,
            preflight=tool_preflight,
            request_id=request_id,
            cognitive_state=cognitive_execution_state(body),
            schedule_decision=body.get("_scheduleDecision"),
        )
        if inferred_has_visual_tool else execute_agent_tools(
            inferred_direct_requests,
            settings,
            user_message,
            preflight=tool_preflight,
            request_id=request_id,
            cognitive_state=cognitive_execution_state(body),
            schedule_decision=body.get("_scheduleDecision"),
        )
    )
    deferred_browser_results: list[dict[str, Any]] = []
    if deferred_browser_requests and planned_web_results:
        browser_candidates = public_web_sources(planned_web_results)
        candidate_batch = (
            persist_source_batch(freeze_source_batch(
                browser_candidates,
                request_id=request_id,
                topic_key=browser_target_resolution_query or user_message,
            ))
            if browser_candidates else {}
        )
        if candidate_batch:
            browser_candidates = [
                {
                    **source,
                    "id": str(source.get("displayId") or ""),
                }
                for source in candidate_batch.get("sources", [])
                if isinstance(source, dict)
            ]
            pending_browser_action = save_pending_browser_action(
                request_id=request_id,
                target_hint=browser_target_resolution_query,
                batch_id=str(candidate_batch.get("batchId") or ""),
                status="resolving",
                candidates=browser_candidates,
            )
        browser_args = browser_action_args_from_tool_results(
            f"{user_message} {browser_target_resolution_query}".strip(),
            planned_web_results,
        )
        if browser_args:
            browser_args = browser_args_with_usage_tracking(
                browser_args,
                user_message=user_message,
                request_id=request_id,
                fallback_alias=str(
                    pending_browser_action.get("targetHint")
                    or browser_target_resolution_query
                    or ""
                ),
            )
            browser_args["actionId"] = str(pending_browser_action.get("actionId") or "")
            browser_args["_actionGroupId"] = str(pending_browser_action.get("actionGroupId") or pending_browser_action.get("actionId") or "")
            browser_args["batchId"] = str(
                candidate_batch.get("batchId")
                or browser_args.get("batchId")
                or ""
            )
            deferred_browser_results = [
                tool_open_browser(settings, browser_args)
            ]
        else:
            ambiguous = len(browser_candidates) > 1
            error_code = "ambiguous_browser_target" if ambiguous else "no_verified_source_to_open"
            deferred_browser_results = [{
                "name": "open_browser",
                "ok": False,
                "error": error_code,
                "candidates": browser_candidates[:8],
                "message": (
                    "找到了多个可能的目标，需要用户指定来源编号。"
                    if ambiguous else
                    "没有取得可验证的目标 URL，因此没有打开搜索页冒充目标页面。"
                ),
                "actionReceipt": {
                    "actionId": str(pending_browser_action.get("actionId") or f"act_{uuid.uuid4().hex}"),
                    "actionGroupId": str(pending_browser_action.get("actionGroupId") or pending_browser_action.get("actionId") or ""),
                    "requestId": request_id,
                    "tool": "open_browser",
                    "status": "rejected",
                    "requestedTarget": browser_target_resolution_query,
                    "resolvedTarget": "",
                    "adapter": "target_resolver",
                    "error": error_code,
                    "timestamp": now_iso(),
                },
            }]
    elif deferred_browser_requests:
        deferred_browser_results = [{
            "name": "open_browser",
            "ok": False,
            "error": "no_verified_source_to_open",
            "message": "没有取得可验证的目标 URL，因此没有打开搜索页冒充目标页面。",
            "actionReceipt": {
                "actionId": str(pending_browser_action.get("actionId") or f"act_{uuid.uuid4().hex}"),
                "actionGroupId": str(pending_browser_action.get("actionGroupId") or pending_browser_action.get("actionId") or ""),
                "requestId": request_id,
                "tool": "open_browser",
                "status": "rejected",
                "requestedTarget": browser_target_resolution_query,
                "resolvedTarget": "",
                "adapter": "target_resolver",
                "error": "no_verified_source_to_open",
                "timestamp": now_iso(),
            },
        }]
    inferred_tool_results = [
        *inferred_direct_results,
        *planned_web_results,
        *deferred_browser_results,
    ]
    browser_receipts = action_receipts_from_results(inferred_tool_results)
    for action_receipt in browser_receipts:
        record_action_receipt(action_receipt)
        if action_receipt.get("status") == "accepted":
            clear_pending_action(str(action_receipt.get("actionId") or ""))
        elif pending_browser_action:
            save_pending_browser_action(
                request_id=request_id,
                target_hint=browser_target_resolution_query,
                batch_id=str(pending_browser_action.get("batchId") or ""),
                status=(
                    "needs_confirmation"
                    if action_receipt.get("error") == "target_confirmation_required"
                    else
                    "needs_target"
                    if action_receipt.get("error") in {
                        "unresolved_browser_target",
                        "missing_url",
                        "no_verified_source_to_open",
                        "ambiguous_browser_target",
                    }
                    else "failed"
                ),
                candidates=(
                    deferred_browser_results[0].get("candidates", [])
                    if deferred_browser_results
                    else pending_browser_action.get("candidateSources", [])
                ),
            )
    raw_pre_tool_results = (
        continuation_tool_results
        if continuation is not None
        else [*attachment_tool_results, *inferred_tool_results]
    )
    preexecution_tool_rounds = 1 if any(tool_result_was_attempted(item) for item in raw_pre_tool_results) else 0
    # Keep a bounded, request-local recovery snapshot. It is never persisted
    # as memory or inserted into persona prompts; the rescue controller can
    # inspect real tool outcomes if a later architecture stage fails.
    body["_rescueToolResults"] = [
        dict(item) for item in raw_pre_tool_results[-12:]
        if isinstance(item, Mapping)
    ]
    pre_tool_results = effective_tool_results(raw_pre_tool_results)
    if len(pre_tool_results) != len(raw_pre_tool_results):
        write_server_log(
            "effective_tool_results_projected",
            requestId=request_id,
            stage="pre_model",
            rawCount=len(raw_pre_tool_results),
            effectiveCount=len(pre_tool_results),
        )
    expected_perception_target = tool_preflight.perception.target_domain
    grounded_pre_tool_results: list[dict[str, Any]] = []
    for item in pre_tool_results:
        tool_name = str(item.get("name") or "")
        mismatched_visual = (
            item.get("ok")
            and tool_name in {"capture_screen", "capture_camera", "read_image"}
            and not visual_result_matches_perception_target(
                item,
                expected_perception_target,
            )
            and tool_name not in explicitly_requested_sensors
        )
        if mismatched_visual:
            write_server_log(
                "visual_evidence_quarantined",
                requestId=request_id,
                toolName=tool_name,
                expectedPerceptionTarget=expected_perception_target,
                reason="tool_result_does_not_match_authoritative_turn_target",
            )
            continue
        grounded_pre_tool_results.append(item)
    pre_tool_results = grounded_pre_tool_results
    has_current_visual_evidence = any(
        item.get("ok") and item.get("name") in {"capture_screen", "capture_camera", "read_image"}
        for item in pre_tool_results
    )
    visual_focus_results = [
        item for item in pre_tool_results
        if visual_result_matches_perception_target(
            item,
            expected_perception_target,
        )
    ]
    if has_typed_visual_evidence(visual_focus_results):
        # Bind the task contract from the actual observation receipt.  Wording
        # such as "看看" or "我在干什么" is only a routing hint; it no longer
        # determines the evidence obligation or release decision.
        turn_contract = bind_current_visual_observation_contract(
            turn_contract,
            semantic_text=semantic_task_request,
        )
        body["_cognitiveTurnContract"] = turn_contract
        visual_plan = EpistemicPlan.from_dict(prepared_action_turn.epistemic_plan)
        if visual_plan is not None:
            visual_plan = visual_plan.with_current_visual_observation(
                subject=semantic_task_request,
            )
            prepared_action_turn = replace(
                prepared_action_turn,
                epistemic_plan=visual_plan.to_dict(),
                epistemic_state=visual_plan.epistemic_state().to_dict(),
            )
            body["_preparedActionTurn"] = prepared_action_turn
    elif visual_focus_results:
        # A failed current capture is still authoritative local evidence about
        # the attempt. Replace the generic public-fact placeholder so a valid
        # permission/device failure explanation cannot become "evidence
        # insufficient" or a whole-turn 503.
        visual_plan = EpistemicPlan.from_dict(prepared_action_turn.epistemic_plan)
        if visual_plan is not None:
            visual_plan = visual_plan.with_current_visual_observation(
                subject=user_message,
                observation_available=False,
            )
            prepared_action_turn = replace(
                prepared_action_turn,
                epistemic_plan=visual_plan.to_dict(),
                epistemic_state=visual_plan.epistemic_state().to_dict(),
            )
            body["_preparedActionTurn"] = prepared_action_turn
        turn_contract = bind_current_visual_failure_contract(
            turn_contract,
            semantic_text=semantic_task_request,
        )
        body["_cognitiveTurnContract"] = turn_contract
    recalled_visual_results = (
        []
        if continuation is not None or current_attachments or has_current_visual_evidence
        else recalled_screen_capture_results(user_message)
    )
    visual_focus_mode = has_typed_visual_evidence(visual_focus_results) and not native_visual_chat_enabled(settings)
    current_attachment_kinds = {
        str(item.get("kind") or "file")
        for item in current_attachments
        if isinstance(item, dict)
    }
    # A visual turn consumes the typed visual evidence packet below.  Do not
    # let the older flattened attachment dump compete with that packet.  Mixed
    # image+document turns retain the attachment prompt for the document, while
    # the visual tool result is still kept and projected into typed evidence.
    attachment_prompt_for_model = (
        ""
        if visual_focus_mode and current_attachment_kinds == {"image"}
        else attachment_prompt
    )
    # Ordinary documents are already represented by attachment_prompt.  Image
    # results are deliberately retained so visual_evidence_prompt can separate
    # scene, OCR, and window-context evidence instead of flattening them.
    prompt_tool_results = [
        *[
            item for item in pre_tool_results
            if not (
                attachment_prompt_for_model
                and item.get("name") == "read_file"
            )
        ],
        *recalled_visual_results,
    ]
    discourse_ledger = DiscourseLedger.from_dict(
        context_resolution.get("referenceLedger")
        if isinstance(context_resolution.get("referenceLedger"), Mapping) else None
    )
    if prompt_tool_results:
        discourse_ledger = extend_with_visual_observations(
            discourse_ledger,
            prompt_tool_results,
        )
    discourse_resolution = resolve_discourse_references(
        discourse_ledger,
        message_id=discourse_ledger.current_message_id,
    )
    context_resolution["referenceLedger"] = discourse_ledger.to_dict()
    context_resolution["referenceResolution"] = discourse_resolution.to_dict()
    context_resolution["referenceEvidence"] = _reference_evidence(
        discourse_ledger,
        discourse_resolution,
    )
    body["_discourseLedger"] = discourse_ledger.to_dict()
    pre_tool_ms = round((time.perf_counter() - tool_started) * 1000)
    compact_core_protocol = ordinary_core_dialogue_protocol(
        turn_policy,
        prepared_action_turn,
        tool_preflight,
        research_decision,
        pre_tool_results=pre_tool_results,
        attachment_prompt=attachment_prompt,
        file_output_expected=file_output_expected,
    )

    interruption_context = ""
    if len(successive_inputs) > 1 or interrupted_previous_reply:
        interruption_context = (
            "用户在上一轮处理期间又连续补充了内容。把这些输入视为同一轮，综合理解后只回答一次；"
            "不要逐条机械复述。"
            + (
                "上一段语音确实被用户打断了。开头可用一个很短、自然且不固定的接话，例如“等、慢点说”，"
                "随后直接回应合并后的意思；不要解释系统中断。"
                if interrupted_previous_reply else
                "上一段语音尚未开始，不要假装被打断，直接综合回答。"
            )
        )

    # This is a per-turn delivery contract, not duplicated persona prose.  It
    # must remain visible when Persona Context Skills use the hybrid provider.
    legacy_nickname_prompt = nickname_reaction_prompt(user_message, request_id)
    legacy_motif_prompt = (
        ""
        if active_persona_snapshot.uses_hybrid_provider_context
        else canon_style_motif_prompt(user_message)
    )
    current_visual_contract = visual_evidence_prompt(
        prompt_tool_results,
        user_question=semantic_task_request,
    )
    explicit_reply_context = body_reply_context_prompt(body)
    explicit_context_control = body_context_control_prompt(body)
    generic_prompt_tool_results = (
        [
            item for item in prompt_tool_results
            if str(item.get("name") or "")
            not in {"capture_screen", "capture_camera", "read_image"}
        ]
        if visual_focus_mode else prompt_tool_results
    )
    generic_tool_context = (
        tool_context_prompt(
            generic_prompt_tool_results,
            context_resolution,
            max_chars=turn_policy.tool_evidence_max_chars,
            model_owned=bool(cognitive_turn_state(body)),
        )
        if generic_prompt_tool_results else ""
    )
    generic_grounding_instruction = tool_grounding_instruction(
        generic_prompt_tool_results
    )
    visual_style_context = (
        "[当前视觉任务] 你是 AMADEUS。先准确完成用户针对当前画面的具体问题；"
        "人格只影响简短自然的措辞、情绪与动作，不能提供任何画面事实。"
        "与本轮直接承接的近期对话只可帮助理解用户所指和可见文字；"
        "无关旧对话、长期记忆、日程、关系经历和常识猜测都不是当前画面证据。"
        f"关系阶段={str(relationship_state.get('stage') or 'close_companion')[:40]}。"
        if visual_focus_mode else ""
    )
    visual_recent_context = (
        visual_relevant_context_prompt(context_resolution)
        if visual_focus_mode else ""
    )
    visual_candidate_capabilities = {
        str(item)
        for item in (
            getattr(tool_preflight, "candidate_capabilities", ()) or ()
        )
        if str(item)
    }
    visual_only_focus_mode = bool(
        visual_focus_mode
        and visual_candidate_capabilities
        and visual_candidate_capabilities.issubset({
            "read_image", "capture_screen", "capture_camera",
        })
        and not generic_prompt_tool_results
        and not file_output_expected
    )
    base_messages = [
        *([{"role": "system", "content": prompt}]
          if not visual_focus_mode else []),
        {"role": "system", "content": NATURAL_DIALOGUE_STYLE},
        {"role": "system", "content": (
            COGNITIVE_DIALOGUE_REPLY_RULE if cognitive_turn_state(body) else UTTERANCE_STREAM_REPLY_RULE
        )},
        *([{"role": "system", "content": deep_persona_prompt}]
          if not visual_focus_mode else []),
        *([{"role": "system", "content": visual_style_context}]
          if visual_style_context else []),
        *([{"role": "system", "content": visual_recent_context}]
          if visual_recent_context else []),
        *(task_local_dialogue_messages(body) if visual_focus_mode else []),
        {"role": "system", "content": policy_prompt(turn_policy)},
        {"role": "system", "content": SPEAKER_ATTRIBUTION_RULE},
        {"role": "system", "content": TECHNICAL_ACCURACY_RULE},
        {"role": "system", "content": EMOTION_SELECTION_RULE},
        *([{"role": "system", "content": AMADEUS_TOOL_RULE}]
          if not visual_focus_mode and not cognitive_turn_state(body) else []),
        *([{"role": "system", "content": SCHEDULE_INTENT_PROMPT}]
          if not visual_focus_mode else []),
        {"role": "system", "content": tool_preflight_prompt(tool_preflight, capability)},
        *([{"role": "system", "content": todo_reconciliation_prompt(todo_reconciliation)}]
          if todo_reconciliation_prompt(todo_reconciliation) and not visual_focus_mode and not cognitive_turn_state(body) else []),
        *([{"role": "system", "content": relationship_context_prompt(relationship_state)}]
          if not visual_focus_mode else []),
        *([{"role": "system", "content": dignity_boundary_context_prompt(
            relationship_state,
            body.get("_dignityAssessment") if isinstance(body.get("_dignityAssessment"), dict) else None,
            require_output_field=False,
        )}] if not visual_focus_mode else []),
        *([{"role": "system", "content": transition_style_prompt(messages)}]
          if not visual_focus_mode else []),
        *([{"role": "system", "content": permission_context_prompt(settings, body=body)}]
          if not visual_focus_mode else []),
        *([{"role": "system", "content": attachment_prompt_for_model}]
          if attachment_prompt_for_model else []),
        *([{"role": "system", "content": generic_tool_context}]
          if generic_tool_context else []),
        *([{"role": "system", "content": generic_grounding_instruction}]
          if generic_grounding_instruction else []),
        *([{"role": "system", "content": visual_relationship_reaction_instruction(prompt_tool_results, relationship_state)}]
          if visual_relationship_reaction_instruction(prompt_tool_results, relationship_state)
          and not visual_focus_mode else []),
        *([{"role": "system", "content": interruption_context}] if interruption_context else []),
        *([{"role": "system", "content": explicit_context_control}]
          if explicit_context_control else []),
        *([{"role": "system", "content": explicit_reply_context}]
          if explicit_reply_context else []),
        *([{"role": "system", "content": explicit_user_position_prompt(user_message)}]
          if explicit_user_position_prompt(user_message) and not visual_focus_mode else []),
        *([{"role": "system", "content": "主动互动连续性：" + proactive_context}]
          if proactive_context and not visual_focus_mode else []),
        *([{"role": "system", "content": retrieved_memory_prompt(
            memories,
            memory_records,
            memory_need,
            cognitive_state=cognitive_turn_state(body),
        )}] if not visual_focus_mode else []),
        *([{"role": "system", "content": conversation_context_prompt(
            user_message, turn_policy, memory_need, context_resolution,
            context_state=frozen_turn_context_state(body),
            cognitive_state=cognitive_turn_state(body),
        )}]
          if not visual_focus_mode else []),
        *([{"role": "system", "content": session_temporal_context_prompt(user_message, settings=settings)}]
          if not visual_focus_mode else []),
        *([{"role": "system", "content": attribution_evidence}]
          if attribution_evidence and not visual_focus_mode else []),
        *conversation_history_messages(body, [
            item for item in (
                messages[-turn_policy.recent_message_limit:]
                if cognitive_turn_state(body) or current_runtime_has_user_turn() or message_needs_recent_context(user_message)
                else []
            )
            if isinstance(item, dict) and not visual_focus_mode
        ]),
        *([{"role": "system", "content": identity_context}]
          if identity_context and not visual_focus_mode else []),
        *([{"role": "system", "content": legacy_nickname_prompt}]
          if legacy_nickname_prompt and not visual_focus_mode else []),
        *([{"role": "system", "content": legacy_motif_prompt}]
          if legacy_motif_prompt and not visual_focus_mode else []),
        *([{"role": "system", "content": immediate_context_prompt(
            messages,
            user_message,
            turn_policy,
            context_state=frozen_turn_context_state(body),
            cognitive_state=cognitive_turn_state(body),
        )}]
          if not visual_focus_mode else []),
        *([{"role": "system", "content": pending_question_context}]
          if pending_question_context and not visual_focus_mode else []),
        *([{"role": "system", "content": todo_pending_context}]
          if todo_pending_context and not visual_focus_mode else []),
        *([{"role": "system", "content": schedule_state_context}]
          if schedule_state_context and not visual_focus_mode else []),
        *([{"role": "system", "content": contextual_reference_prompt(context_resolution)}]
          if contextual_reference_prompt(context_resolution) and not visual_focus_mode else []),
        *([{"role": "system", "content": current_visual_contract}]
          if current_visual_contract else []),
        *([{"role": "system", "content": claim_level_fact_policy_prompt(
            prepared_action_turn
        )}] if claim_level_fact_policy_prompt(prepared_action_turn) and not visual_focus_mode else []),
        {"role": "system", "content": core_dialogue_turn_contract_prompt(
            utterance_interpretation,
            turn_contract,
            model_owned=bool(cognitive_turn_state(body)),
        )},
        {"role": "user", "content": user_message},
    ]
    if visual_only_focus_mode:
        base_messages = [
            {"role": "system", "content": visual_style_context},
            {"role": "system", "content": (
                "[视觉专用 semantic-v3 协议] 只输出一个 JSON 对象，不要 Markdown 或额外说明。"
                "输出 kind='turn' 和一到三项 speechUnits；每项 zh 用中文直接回答当前视觉问题，"
                "ja 用自然日语表达完全相同的事实；不要重复输出 reply 或 spokenTextJa。"
                "emotion 从 focused/curious/surprised/amused/embarrassed 中选最合适的一项，"
                "gesture 从 explain/tilt_head/look_away 中选一项。"
                "同时按相邻 Turn Contract 输出 proactiveDirective；不得因当前是视觉回答就覆盖用户的暂停或恢复意图，"
                "以及 scheduleIntent={kind:'none',relation:'unrelated',authorization:'none',commands:[],"
                "missingFields:[],sourceSpans:[],summary:'',confidence:0.0}。"
                "不要输出 completedActs、standalone 或 turnComplete；它们由后端依据视觉证据审计结果确认。"
                "不得增加其他事实字段，也不得用人格反应替代视觉答案。"
            )},
            *([{"role": "system", "content": visual_recent_context}]
              if visual_recent_context else []),
            *task_local_dialogue_messages(body),
            *([{"role": "system", "content": explicit_reply_context}]
              if explicit_reply_context else []),
            {"role": "system", "content": current_visual_contract},
            {"role": "system", "content": core_dialogue_turn_contract_prompt(
                utterance_interpretation,
                turn_contract,
                model_owned=bool(cognitive_turn_state(body)),
            )},
            {"role": "user", "content": user_message},
        ]

    base_messages = pin_reply_context(base_messages, body.get("_turnContextSnapshot"))
    primary_max_tokens = (
        6000 if file_output_expected else fast_stream_token_budget(turn_policy)
    )
    base_messages, context_pressure_metrics = pressure_managed_prompt(
        base_messages,
        settings,
        reserved_output_tokens=primary_max_tokens,
        request_id=request_id,
        stage="chat_primary",
    )
    payload: dict[str, Any] = {
        "model": settings["apiModel"],
        "temperature": 0.66,
        "max_tokens": primary_max_tokens,
        "messages": base_messages,
    }
    if settings.get("useResponseFormat"):
        payload["response_format"] = {"type": "json_object"}
    if "deepseek.com" in settings["apiEndpoint"]:
        payload["thinking"] = {"type": "disabled"}

    body["_cognitiveEvidence"] = {**(body.get("_cognitiveEvidence") or {}), **collect_evidence(pre_tool_results)}
    if continuation is None:
        update_chat_request_progress(request_id, "model-generating", "正在请求模型生成第一版回答")
        llm_started = time.perf_counter()
        content = send_conversation_brain_payload(
            body, settings, payload, timeout=90, request_id=request_id, purpose="chat_primary"
        )
    else:
        update_chat_request_progress(request_id, "model-generating", "沿用修复后的模型候选，进入本轮工具循环")
        llm_started = time.perf_counter()
        content = continuation_content
    semantic_task_request = current_task_semantic_request(body, user_message)
    answer_finish_reason = LAST_UPSTREAM_FINISH_REASON.get()
    first_llm_ms = round((time.perf_counter() - llm_started) * 1000)
    parsed = parse_json_object(content) or {}
    write_server_log(
        "dialogue_protocol_output_parsed",
        requestId=request_id,
        kind=str(parsed.get("kind") or "legacy_or_unknown")[:40],
        keys=sorted(str(key)[:80] for key in parsed.keys())[:30],
        speechUnitCount=len(parsed.get("speechUnits") or [])
        if isinstance(parsed.get("speechUnits"), list) else 0,
        toolCallCount=len(parsed.get("calls") or parsed.get("toolRequests") or [])
        if isinstance(parsed.get("calls") or parsed.get("toolRequests") or [], list) else 0,
        hasLegacyReply=bool(str(parsed.get("reply") or "").strip()),
        hasLegacySpokenText=bool(str(parsed.get("spokenTextJa") or "").strip()),
    )
    if not isinstance(body.get("_scheduleDecision"), Mapping):
        body["_scheduleDecision"] = resolve_model_schedule_decision(
            parsed,
            settings,
            user_message=user_message,
            messages=messages,
            request_id=request_id,
        )
    if continuation is None:
        content = repair_reply_for_recovered_schedule_decision(
            settings,
            base_messages,
            content,
            body.get("_scheduleDecision"),
            request_id=request_id,
            body=body,
            user_message=user_message,
        )
    parsed = parse_json_object(content) or {}
    if isinstance(body.get("_scheduleDecision"), Mapping):
        tool_preflight = body_tool_preflight(
            body,
            user_message,
            messages,
            reply_mode=turn_policy.reply_mode,
            speech_act=utterance_interpretation.primary_speech_act,
        )
    model_tool_requests = merge_schedule_tool_requests(
        normalize_tool_requests(parsed),
        body.get("_scheduleDecision"),
    )
    uncertainty_triggered_web = False
    atomic_epistemic_plan = EpistemicPlan.from_dict(
        prepared_action_turn.epistemic_plan
    )
    atomic_confidence_gate = knowledge_confidence_gate_decision(
        atomic_epistemic_plan.fact_requirements if atomic_epistemic_plan else (),
        parsed.get("knowledgeConfidence", parsed.get("knowledge_confidence")),
        confidence_provided=(
            str(
                parsed.get(
                    "knowledgeConfidence",
                    parsed.get("knowledge_confidence", ""),
                )
                or ""
            ).strip().lower()
            in {"high", "medium", "low"}
        ),
        research_policy=research_decision.policy,
        web_permission=bool(settings.get("permissionWebSearch")),
    )
    write_server_log(
        "atomic_knowledge_confidence_gate_decision",
        requestId=request_id,
        planId=(atomic_epistemic_plan.plan_id if atomic_epistemic_plan else ""),
        modelConfidence=str(
            parsed.get("knowledgeConfidence", parsed.get("knowledge_confidence", ""))
            or ""
        )[:16],
        decision=atomic_confidence_gate.to_dict(),
    )
    if (
        continuation is None
        and
        not pre_tool_results
        and research_decision.policy != "forbidden"
        and (
            model_web_research_requested(parsed, user_message)
            or atomic_confidence_gate.status == "RESEARCH_ESCALATION"
        )
        and not any(item.get("name") in {"web_search", "read_web_page"} for item in model_tool_requests)
    ):
        model_tool_requests.append({"name": "web_search", "args": {}})
        uncertainty_triggered_web = True
    requested_tools = constrain_model_tool_requests(
        model_tool_requests,
        user_message,
        context_resolution,
        messages,
        body.get("_scheduleDecision"),
        cognitive_state=cognitive_execution_state(body), evidence=body.get("_cognitiveEvidence") or {},
    )
    if research_decision.policy == "forbidden":
        requested_tools = [
            item
            for item in requested_tools
            if item.get("name") not in {"web_search", "read_web_page"}
        ]
    todo_already_executed = any(
        item.get("name") == "todo_manage" and item.get("ok")
        for item in pre_tool_results
        if isinstance(item, Mapping)
    )
    todo_already_requested = any(
        item.get("name") == "todo_manage" for item in requested_tools
    )
    if (
        "todo_manage" in tool_preflight.mandatory_capabilities
        and not cognitive_turn_state(body)
        and not todo_already_executed
        and not todo_already_requested
    ):
        # A required side effect cannot be satisfied by prose. Give the model
        # one bounded chance to emit the schema-valid command before any final
        # answer is accepted; the receipt gate remains the final safety net.
        obligation_payload: dict[str, Any] = {
            "model": settings["apiModel"],
            "temperature": 0.1,
            "max_tokens": 1800,
            "messages": [
                *base_messages,
                {"role": "assistant", "content": content},
                {"role": "system", "content": (
                    "本轮 todo_manage 是必需能力，但你上一条没有发出可执行的工具请求。"
                    "现在只输出一个 JSON 对象，字段仅为 toolRequests、continuationDecision、pendingCommand。"
                    "continuationDecision 只能是 execute、needs_input、unrelated、cancel。"
                    "若存在[待续接的 Todo 操作]，先结合 originalUserRequest 与用户当前消息判断是否属于同一次操作；"
                    "强相关且信息够用时为 execute 并生成 todo_manage，强相关但仍缺关键信息时为 needs_input，"
                    "明确转向无关主题时为 unrelated，明确取消时为 cancel。"
                    "若不存在待续接操作，本轮已由系统确认用户明确要求 Todo 写入；信息不足只能选 needs_input，不能选 unrelated。"
                    "根据完整语义生成 todo_manage；不得用‘今晚’、‘任务’等单个词作为触发依据。实际写操作必须设置 commitIntent=true。"
                    "命名任务使用 targetRef，不得编造 taskId；时间必须是带时区的 ISO-8601。"
                    "若用户信息不足，toolRequests 为空，并在 pendingCommand 中仅保留已明确知道的安全字段；不得声称执行。"
                    "不要声称已经执行，也不要输出面向用户的回复。"
                )},
            ],
        }
        if settings.get("useResponseFormat"):
            obligation_payload["response_format"] = {"type": "json_object"}
        if "deepseek.com" in settings["apiEndpoint"]:
            obligation_payload["thinking"] = {"type": "disabled"}
        obligation_payload["messages"], _ = pressure_managed_prompt(
            obligation_payload["messages"],
            settings,
            reserved_output_tokens=int(obligation_payload["max_tokens"]),
            request_id=request_id,
            stage="todo_required_tool_recovery",
        )
        recovered_content = send_upstream_chat_payload(
            settings,
            obligation_payload,
            timeout=90,
            request_id=request_id,
            purpose="todo_required_tool_recovery",
        )
        recovered_payload = parse_json_object(recovered_content) or {}
        recovered_requests = constrain_model_tool_requests(
            normalize_tool_requests(recovered_payload),
            user_message,
            context_resolution,
            messages,
            body.get("_scheduleDecision"),
            cognitive_state=cognitive_execution_state(body), evidence=body.get("_cognitiveEvidence") or {},
        )
        continuation_decision = normalize_todo_continuation_decision(
            recovered_payload.get("continuationDecision")
        )
        if any(item.get("name") == "todo_manage" for item in recovered_requests):
            continuation_decision = "execute"
        elif continuation_decision == "execute":
            # "execute" without one schema-valid command is not execution.
            continuation_decision = "needs_input"
        elif not continuation_decision:
            # Backward-compatible model outputs only had toolRequests.  An
            # empty recovery means the authorized operation is still missing
            # information; it never means that prose completed the write.
            continuation_decision = "needs_input"
        if (
            not pending_todo_before
            and continuation_decision in {"unrelated", "cancel"}
        ):
            # This branch is reached only because the current turn itself had
            # a mandatory Todo mutation.  There is no older continuation for
            # the model to reject or cancel.
            continuation_decision = "needs_input"
        if pending_todo_before or continuation_decision == "needs_input":
            todo_continuation_transition = {
                "decision": continuation_decision,
                "pendingCommand": (
                    dict(recovered_payload.get("pendingCommand"))
                    if isinstance(recovered_payload.get("pendingCommand"), Mapping)
                    else {}
                ),
            }
        requested_tools.extend(
            item for item in recovered_requests
            if item.get("name") == "todo_manage"
        )
        write_server_log(
            "todo_required_tool_recovery",
            requestId=request_id,
            recovered=any(
                item.get("name") == "todo_manage" for item in recovered_requests
            ),
            continuationDecision=continuation_decision,
            pendingActionId=str(pending_todo_before.get("actionId") or ""),
        )
    # Only a receipt for this exact invocation proves it ran. Inference and
    # pre-execution rejection must not consume the corrected call's identity.
    already_executed_signatures = {
        signature
        for item in pre_tool_results
        if isinstance(item, Mapping) and str(item.get("name") or "").strip()
        for signature in (tool_result_request_signature(item),)
        if signature
    }
    duplicate_preexecuted_requests = [
        item for item in requested_tools
        if tool_request_signature(item) in already_executed_signatures
    ]
    preexecuted_attachment_requests = [
        item for item in requested_tools
        if preexecuted_attachment_request_satisfied(item, pre_tool_results)
    ]
    if preexecuted_attachment_requests:
        requested_tools = [
            item for item in requested_tools
            if item not in preexecuted_attachment_requests
        ]
        duplicate_preexecuted_requests.extend(preexecuted_attachment_requests)
        write_server_log(
            "preexecuted_attachment_request_satisfied",
            requestId=request_id,
            requestedTools=[
                str(item.get("name") or "")
                for item in preexecuted_attachment_requests
            ],
            receiptTools=[
                str(item.get("name") or "")
                for item in pre_tool_results
                if isinstance(item, Mapping) and item.get("ok")
            ],
        )
    if already_executed_signatures:
        requested_tools = [
            item
            for item in requested_tools
            if tool_request_signature(item) not in already_executed_signatures
        ]
    requested_tools, rejected_requested_sensors = constrain_attachment_sensor_requests(
        requested_tools,
        user_message,
        has_bound_attachment=has_bound_attachment,
    )
    tool_preflight = bind_structured_perception_request(
        tool_preflight,
        requested_tools,
        source="query_loop_tool_request",
    )
    body["_toolPreflight"] = tool_preflight
    for item in rejected_requested_sensors:
        write_server_log(
            "attachment_sensor_request_rejected",
            requestId=request_id,
            toolName=str(item.get("name") or ""),
            source="query_loop_tool_request",
            reason="current_attachment_is_authoritative_target",
        )
    prior_tool_rounds = (
        max(existing_tool_rounds, continuation_tool_rounds)
        if continuation is not None
        else max(existing_tool_rounds, preexecution_tool_rounds)
    )
    if requested_tools and prior_tool_rounds >= 3:
        raise CognitiveProtocolError(
            "final_projection_continuation_tool_round_budget_exhausted"
        )
    executed_tool_results = list(pre_tool_results)
    second_llm_ms = 0
    if duplicate_preexecuted_requests and not requested_tools:
        content, answer_finish_reason, second_llm_ms = finalize_preexecuted_tool_result(
            settings,
            base_messages=base_messages,
            primary_content=content,
            executed_results=executed_tool_results,
            duplicate_requests=duplicate_preexecuted_requests,
            context_resolution=context_resolution,
            user_message=user_message,
            turn_policy=turn_policy,
            file_output_expected=file_output_expected,
            interpretation=utterance_interpretation,
            contract=turn_contract,
            request_id=request_id,
            cognitive_body=body,
        )
    if requested_tools:
        requested_web_capability = any(
            item.get("name") in {"web_search", "read_web_page"}
            for item in requested_tools
        )
        model_selected_plan = finalize_turn_execution_plan(
            body,
            user_message=user_message,
            decision=research_decision,
            preflight=tool_preflight,
            tool_requests=requested_tools,
            settings=settings,
            has_attachments=bool(current_attachments or attachment_prompt),
            model_research_escalation=requested_web_capability,
            model_tool_escalation=True,
        )
        tool_preflight = bind_required_capabilities(
            tool_preflight,
            model_selected_plan.required_capabilities,
            source="model_selected_turn_execution_plan",
        )
        body["_toolPreflight"] = tool_preflight
        research_decision = replace(
            research_decision,
            policy=model_selected_plan.research_policy,
            reasons=tuple(dict.fromkeys((
                *research_decision.reasons,
                "model_tool_request_finalized_by_turn_execution_plan",
            ))),
            plan_revision=max(
                research_decision.plan_revision + 1,
                model_selected_plan.revision,
            ),
        )
        prepared_action_turn, research_decision = synchronize_prepared_epistemic_plan(
            prepared_action_turn,
            research_decision,
        )
        capability = capability_envelope(
            turn_policy,
            research_decision,
            web_permission=bool(settings.get("permissionWebSearch")),
        )
        capability = capability_with_tool_preflight(
            capability,
            tool_preflight,
            settings,
            extra_tool_ids=[
                str(item.get("name") or "")
                for item in requested_tools
                if isinstance(item, dict)
            ],
        )
        capability = replace(
            capability,
            research_policy=model_selected_plan.research_policy,
            required_tools=model_selected_plan.required_capabilities,
            max_tool_rounds=model_selected_plan.max_tool_rounds,
            tool_policy="required",
        )
        prepared_action_turn = replace(
            prepared_action_turn,
            research_decision=research_decision.to_dict(),
            capability_envelope=capability.to_dict(),
        )
        body["_preparedActionTurn"] = prepared_action_turn
        persist_prepared_turn(prepared_action_turn)
        first_pass_progress_zh = re.sub(
            r"\s+", " ", str(parsed.get("reply") or "")
        ).strip()
        first_pass_progress_ja = re.sub(
            r"\s+", " ", str(parsed.get("spokenTextJa") or "")
        ).strip()
        progress_claims_completed_work = bool(re.search(
            r"(?:已经|刚刚)?(?:查到|搜到|检索到|核对到|打开了|看到了)|"
            r"(?:搜索|检索|查阅|资料|来源|网页)(?:结果|显示|表明|证明)|"
            r"\[(?:S|来源)\s*\d+\]|https?://",
            first_pass_progress_zh,
            re.I,
        ))
        requested_has_todo_tool = any(
            item.get("name") in {"todo_search", "todo_manage"}
            for item in requested_tools
        )
        if (
            callable(progress_callback)
            and first_pass_progress_zh
            and first_pass_progress_ja
            and not progress_claims_completed_work
            and not requested_has_todo_tool
        ):
            progress_payload = normalize_model_reply(
                {
                    **parsed,
                    "reply": first_pass_progress_zh,
                    "spokenTextJa": first_pass_progress_ja,
                    "memoryUpdates": [],
                },
                settings=settings,
            )
            progress_event = {
                "utteranceId": f"tool-progress-{uuid.uuid4().hex[:10]}",
                "progressKind": (
                    "research_bridge"
                    if any(
                        item.get("name") in {"web_search", "read_web_page"}
                        for item in requested_tools
                    )
                    else "tool_progress"
                ),
                "progressOnly": True,
                "textZh": str(progress_payload.get("reply") or first_pass_progress_zh),
                "spokenTextJa": str(
                    progress_payload.get("spokenTextJa") or first_pass_progress_ja
                ),
                "emotion": str(progress_payload.get("emotion") or "focused"),
                "emotionIntensity": progress_payload.get("emotionIntensity", 0.68),
                "standalone": True,
                "dependsOnResearchEvidence": False,
            }
            if progress_callback(progress_event) is not False:
                body["_semanticToolProgressProvided"] = True
                research_bridge_emitted = True
        update_chat_request_progress(request_id, "tool-executing", "模型请求补充证据，正在执行工具")
        requested_web_tools = [
            item
            for item in requested_tools
            if item.get("name") in {"web_search", "read_web_page"}
        ]
        requested_non_web_tools = [
            item
            for item in requested_tools
            if item.get("name") not in {"web_search", "read_web_page"}
        ]
        requested_has_visual_tool = any(
            item.get("name") in {"capture_screen", "capture_camera"}
            for item in requested_non_web_tools
        )
        tool_results = (
            execute_agent_tools(
                requested_non_web_tools,
                settings,
                user_message,
                preflight=tool_preflight,
                request_id=request_id,
                cognitive_state=cognitive_execution_state(body),
                schedule_decision=body.get("_scheduleDecision"),
            )
            if requested_has_visual_tool else execute_agent_tools(
                requested_non_web_tools,
                settings,
                user_message,
                preflight=tool_preflight,
                request_id=request_id,
                cognitive_state=cognitive_execution_state(body),
                schedule_decision=body.get("_scheduleDecision"),
            )
        )
        tool_results = effective_tool_results(tool_results)
        requested_read_tools = [
            item for item in requested_web_tools if item.get("name") == "read_web_page"
        ]
        if requested_read_tools:
            tool_results.extend(execute_agent_tools(
                requested_read_tools,
                settings,
                user_message,
                preflight=tool_preflight,
                request_id=request_id,
                cognitive_state=cognitive_execution_state(body),
                schedule_decision=body.get("_scheduleDecision"),
            ))
        requested_web_queries = [
            item for item in requested_web_tools if item.get("name") == "web_search"
        ]
        if requested_web_queries and cognitive_turn_state(body):
            # Search returns evidence to the same brain; it owns reading and
            # further queries instead of a second semantic research planner.
            tool_results.extend(execute_agent_tools(
                requested_web_queries, settings, user_message, preflight=tool_preflight,
                request_id=request_id, cognitive_state=cognitive_execution_state(body),
                schedule_decision=body.get("_scheduleDecision"),
            ))
        elif requested_web_queries:
            model_research_plan = normalize_web_research_plan(
                {
                    "needsWeb": True,
                    "resolvedQuestion": context_resolution.get("resolvedQuestion") or user_message,
                    "queries": [
                        {
                            "query": item.get("args", {}).get("query"),
                            "purpose": "补充模型判断仍缺少的公开事实",
                        }
                        for item in requested_web_queries
                    ],
                    "answerRequirements": ["综合检索证据后直接回答当前问题"],
                    "questionAnalysis": {
                        "intent": "执行主模型明确选择的公开信息检索",
                        "subject": web_research_anchor(
                            user_message,
                            str(context_resolution.get("resolvedQuestion") or user_message),
                        ),
                        "factsToVerify": ["主模型在本轮声明缺少的公开事实"],
                    },
                },
                user_message,
                context_resolution,
                messages,
            )
            if research_decision.source_policy_id:
                model_research_plan["sourcePolicyId"] = (
                    research_decision.source_policy_id
                )
            model_research_plan["entityTerms"] = list(
                research_decision.unknown_entities
            )
            emit_research_bridge_once(model_research_plan)
            model_research_result, model_research_plan, _, model_review_ms = (
                run_research_query_loop(
                    settings,
                    user_message,
                    messages,
                    model_research_plan,
                    context_resolution,
                    research_decision,
                    capability,
                    request_id=request_id,
                    cognitive_body=body,
                )
            )
            research_review_ms += model_review_ms
            tool_results.append(model_research_result)
            if deferred_browser_requests and model_research_result.get("ok"):
                # An unresolved explicit open action may be followed by a Web
                # lookup selected by the main model.  Once that lookup returns
                # a verified target, finish the original side effect in the
                # same turn instead of leaving the user with a stale rejection.
                browser_args = browser_action_args_from_tool_results(
                    user_message,
                    [model_research_result],
                )
                if browser_args:
                    browser_args = browser_args_with_usage_tracking(
                        browser_args,
                        user_message=user_message,
                        request_id=request_id,
                        fallback_alias=str(pending_browser_action.get("targetHint") or ""),
                    )
                    browser_args["actionId"] = str(
                        pending_browser_action.get("actionId") or ""
                    )
                    browser_args["_actionGroupId"] = str(pending_browser_action.get("actionGroupId") or pending_browser_action.get("actionId") or "")
                    executed_tool_results = [
                        item for item in executed_tool_results
                        if not (
                            item.get("name") == "open_browser"
                            and item.get("error") in {
                                "no_verified_source_to_open",
                                "unresolved_browser_target",
                                "missing_url",
                            }
                        )
                    ]
                    tool_results.append(tool_open_browser(settings, browser_args))
        revised_schedule = reconsider_schedule_intent_after_tool_evidence(
            settings,
            user_message,
            messages,
            body.get("_scheduleDecision"),
            tool_results,
            request_id=request_id,
        )
        if isinstance(revised_schedule, Mapping):
            body["_scheduleDecision"] = dict(revised_schedule)
            tool_preflight = body_tool_preflight(
                body,
                user_message,
                messages,
                reply_mode=turn_policy.reply_mode,
                speech_act=utterance_interpretation.primary_speech_act,
            )
            known_schedule_signatures = {
                tool_request_signature(request)
                for request in [*inferred_requests, *requested_tools]
                if isinstance(request, Mapping)
            }
            evidence_schedule_requests = [
                item for item in schedule_tool_requests(revised_schedule)
                if str(item.get("name") or "") == "todo_manage"
                and tool_request_signature(item) not in known_schedule_signatures
            ]
            if evidence_schedule_requests:
                tool_results.extend(execute_agent_tools(
                    evidence_schedule_requests,
                    settings,
                    user_message,
                    preflight=tool_preflight,
                    request_id=request_id,
                    cognitive_state=cognitive_execution_state(body),
                    schedule_decision=body.get("_scheduleDecision"),
                ))
                requested_tools.extend(evidence_schedule_requests)
        executed_tool_results = effective_tool_results([
            *executed_tool_results,
            *tool_results,
        ])
        if has_typed_visual_evidence(tool_results):
            turn_contract = bind_current_visual_observation_contract(
                turn_contract,
                semantic_text=semantic_task_request,
            )
            body["_cognitiveTurnContract"] = turn_contract
            visual_plan = EpistemicPlan.from_dict(prepared_action_turn.epistemic_plan)
            if visual_plan is not None:
                visual_plan = visual_plan.with_current_visual_observation(
                    subject=semantic_task_request,
                )
                prepared_action_turn = replace(
                    prepared_action_turn,
                    epistemic_plan=visual_plan.to_dict(),
                    epistemic_state=visual_plan.epistemic_state().to_dict(),
                )
                body["_preparedActionTurn"] = prepared_action_turn
        final_payload: dict[str, Any] = {
            "model": settings["apiModel"],
            "temperature": 0.55,
            "max_tokens": 6000 if file_output_expected else min(
                6_000,
                fast_stream_token_budget(turn_policy) + 240,
            ),
            "messages": [
                *base_messages,
                {"role": "assistant", "content": content},
                {"role": "system", "content": tool_context_prompt(
                    tool_results,
                    context_resolution,
                    max_chars=turn_policy.tool_evidence_max_chars,
                 model_owned=bool(cognitive_turn_state(body)))},
                *([{"role": "system", "content": visual_evidence_prompt(
                    tool_results,
                    user_question=semantic_task_request,
                )}] if visual_evidence_prompt(tool_results, user_question=semantic_task_request) else []),
                *([{"role": "system", "content": tool_grounding_instruction(tool_results)}] if tool_grounding_instruction(tool_results) else []),
                *([{"role": "system", "content": visual_relationship_reaction_instruction(tool_results, relationship_state)}]
                  if visual_relationship_reaction_instruction(tool_results, relationship_state)
                  and not has_typed_visual_evidence(tool_results) else []),
                {"role": "system", "content": (
                    "[工具返回后的认知续写] 依据已返回的执行状态与正文更新当前判断。"
                    "足以回答时输出 kind='turn'、cognitive、outcome 和 speechUnits，active 任务还须声明 outcome.taskStatus。"
                    "仍需不同证据时可 kind='tool_use'，但不要重发已经成功的动作。"
                    "执行失败按真实回执报告原因，不能把所有失败解释为权限不足。"
                    if cognitive_turn_state(body) else
                    "本轮工具结果已经返回。先判断是否足以完成 Turn Contract；足够时按照 semantic-v3 "
                    "输出 kind='turn'、emotion、proactiveDirective、scheduleIntent 和 speechUnits，"
                    "不要重复输出 reply/spokenTextJa 或运行状态。"
                    "若仍缺少一项确实必要的不同工具证据，可以输出 kind='tool_use' 和 calls，"
                    "但不得重复完全相同的工具与参数，也不得无依据地改写参数碰运气。"
                    "工具失败或权限不足时，要明确告诉用户需要开启对应权限，不要猜测。"
                )},
                {"role": "system", "content": policy_prompt(turn_policy)},
                {"role": "system", "content": core_dialogue_turn_contract_prompt(
                    utterance_interpretation,
                    turn_contract,
                    model_owned=bool(cognitive_turn_state(body)),
                )},
            ],
        }
        if settings.get("useResponseFormat"):
            final_payload["response_format"] = {"type": "json_object"}
        if "deepseek.com" in settings["apiEndpoint"]:
            final_payload["thinking"] = {"type": "disabled"}
        final_payload["messages"], context_pressure_metrics = pressure_managed_prompt(
            final_payload["messages"],
            settings,
            reserved_output_tokens=int(final_payload["max_tokens"]),
            request_id=request_id,
            stage="chat_tool_followup",
        )
        update_chat_request_progress(request_id, "model-synthesizing", "工具结果已返回，正在综合证据形成回答")
        second_started = time.perf_counter()
        body["_cognitiveEvidence"] = {**(body.get("_cognitiveEvidence") or {}), **collect_evidence(executed_tool_results or tool_results)}
        content = send_conversation_brain_payload(
            body, settings, final_payload, timeout=90, request_id=request_id, purpose="chat_tool_followup"
        )
        semantic_task_request = current_task_semantic_request(body, user_message)
        answer_finish_reason = LAST_UPSTREAM_FINISH_REASON.get()
        second_llm_ms = round((time.perf_counter() - second_started) * 1000)
        executed_request_signatures = {
            tool_request_signature(item)
            for item in [*inferred_requests, *requested_tools]
            if isinstance(item, Mapping) and str(item.get("name") or "")
        }
        executed_request_signatures.update(
            signature
            for item in pre_tool_results
            if isinstance(item, Mapping) and str(item.get("name") or "")
            for signature in (tool_result_request_signature(item),)
            if signature
        )
        tool_rounds = prior_tool_rounds + 1
        maximum_tool_rounds = 3 if cognitive_turn_state(body) else max(1, min(3, int(capability.max_tool_rounds or 1)))
        body["_cognitiveToolRoundsUsed"] = tool_rounds

        def request_terminal_tool_synthesis(
            previous_content: str,
            *,
            reason: str,
        ) -> tuple[str, int]:
            terminal_payload: dict[str, Any] = {
                "model": settings["apiModel"],
                "temperature": 0.5,
                "max_tokens": 6000 if file_output_expected else min(
                    6_000,
                    fast_stream_token_budget(turn_policy) + 240,
                ),
                "messages": [
                    *base_messages,
                    {"role": "assistant", "content": previous_content},
                    {"role": "system", "content": tool_context_prompt(
                        executed_tool_results,
                        context_resolution,
                        max_chars=turn_policy.tool_evidence_max_chars,
                     model_owned=bool(cognitive_turn_state(body)))},
                    *([{"role": "system", "content": visual_evidence_prompt(
                        executed_tool_results,
                        user_question=semantic_task_request,
                    )}] if visual_evidence_prompt(
                        executed_tool_results,
                        user_question=semantic_task_request,
                    ) else []),
                    *(
                        [{"role": "system", "content": tool_grounding_instruction(
                            executed_tool_results
                        )}]
                        if tool_grounding_instruction(executed_tool_results)
                        else []
                    ),
                    {"role": "system", "content": (
                        "工具循环现在必须结束，原因是 " + reason + "。"
                        "不得再输出 tool_use。请依据所有已返回证据按照 semantic-v3 输出 kind='turn'；"
                        "证据足够就直接回答，证据不足就自然说明具体不确定处或提出完成当前任务所必需的澄清。"
                        "不要编造工具结果，也不要复述调度过程。"
                    )},
                    {"role": "system", "content": core_dialogue_turn_contract_prompt(
                        utterance_interpretation,
                        turn_contract,
                        model_owned=bool(cognitive_turn_state(body)),
                    )},
                ],
            }
            if settings.get("useResponseFormat"):
                terminal_payload["response_format"] = {"type": "json_object"}
            if "deepseek.com" in settings["apiEndpoint"]:
                terminal_payload["thinking"] = {"type": "disabled"}
            terminal_payload["messages"], _ = pressure_managed_prompt(
                terminal_payload["messages"],
                settings,
                reserved_output_tokens=int(terminal_payload["max_tokens"]),
                request_id=request_id,
                stage=f"chat_tool_finalize_{reason}",
            )
            terminal_started = time.perf_counter()
            body["_cognitiveEvidence"] = {**(body.get("_cognitiveEvidence") or {}), **collect_evidence(executed_tool_results)}
            body["_cognitiveToolLoopTerminal"] = True
            try:
                terminal_content = send_conversation_brain_payload(
                    body, settings,
                    terminal_payload,
                    timeout=90,
                    request_id=request_id,
                    purpose=f"chat_tool_query_loop_finalize_{reason}",
                )
            finally:
                body.pop("_cognitiveToolLoopTerminal", None)
            return (
                terminal_content,
                round((time.perf_counter() - terminal_started) * 1000),
            )

        tool_loop_stop_reason = "model_returned_final"
        while True:
            followup_parsed = parse_json_object(content) or {}
            proposed_followup_requests = constrain_model_tool_requests(
                normalize_tool_requests(followup_parsed),
                user_message,
                context_resolution,
                messages,
                body.get("_scheduleDecision"),
                cognitive_state=cognitive_execution_state(body), evidence=body.get("_cognitiveEvidence") or {},
            )
            if research_decision.policy == "forbidden":
                proposed_followup_requests = [
                    item
                    for item in proposed_followup_requests
                    if item.get("name") not in {"web_search", "read_web_page"}
                ]
            proposed_followup_requests, rejected_followup_sensors = (
                constrain_attachment_sensor_requests(
                    proposed_followup_requests,
                    user_message,
                    has_bound_attachment=has_bound_attachment,
                )
            )
            tool_preflight = bind_structured_perception_request(
                tool_preflight,
                proposed_followup_requests,
                source="query_loop_followup",
            )
            body["_toolPreflight"] = tool_preflight
            for item in rejected_followup_sensors:
                write_server_log(
                    "attachment_sensor_request_rejected",
                    requestId=request_id,
                    toolName=str(item.get("name") or ""),
                    source="query_loop_followup",
                    reason="current_attachment_is_authoritative_target",
                )
            if not proposed_followup_requests:
                if cognitive_turn_state(body) and str(followup_parsed.get("kind") or "") == "tool_use":
                    content, terminal_ms = request_terminal_tool_synthesis(content, reason="requested_tools_rejected")
                    second_llm_ms += terminal_ms
                    tool_loop_stop_reason = "requested_tools_rejected"
                else:
                    tool_loop_stop_reason = "model_returned_final"
                break
            followup_requests = [
                item
                for item in proposed_followup_requests
                if tool_request_signature(item) not in executed_request_signatures
            ]
            if not followup_requests:
                content, terminal_ms = request_terminal_tool_synthesis(
                    content,
                    reason="duplicate_tool_request",
                )
                second_llm_ms += terminal_ms
                answer_finish_reason = LAST_UPSTREAM_FINISH_REASON.get()
                tool_loop_stop_reason = "duplicate_tool_request"
                break
            if tool_rounds >= maximum_tool_rounds:
                content, terminal_ms = request_terminal_tool_synthesis(
                    content,
                    reason="tool_round_budget_exhausted",
                )
                second_llm_ms += terminal_ms
                answer_finish_reason = LAST_UPSTREAM_FINISH_REASON.get()
                tool_loop_stop_reason = "tool_round_budget_exhausted"
                break
            tool_rounds += 1
            write_server_log(
                "tool_query_loop_round_started",
                requestId=request_id,
                round=tool_rounds,
                requestedTools=[
                    str(item.get("name") or "")
                    for item in followup_requests
                ],
            )
            update_chat_request_progress(
                request_id,
                "tool-executing",
                f"正在执行第 {tool_rounds} 轮必要工具并核对新增证据",
            )
            followup_results = execute_agent_tools(
                followup_requests,
                settings,
                user_message,
                preflight=tool_preflight,
                request_id=request_id,
                cognitive_state=cognitive_execution_state(body),
                schedule_decision=body.get("_scheduleDecision"),
            )
            if not followup_results:
                content, terminal_ms = request_terminal_tool_synthesis(
                    content,
                    reason="no_tool_result",
                )
                second_llm_ms += terminal_ms
                answer_finish_reason = LAST_UPSTREAM_FINISH_REASON.get()
                tool_loop_stop_reason = "no_tool_result"
                break
            executed_tool_results = effective_tool_results([
                *executed_tool_results,
                *followup_results,
            ])
            if has_typed_visual_evidence(followup_results):
                turn_contract = bind_current_visual_observation_contract(
                    turn_contract,
                    semantic_text=semantic_task_request,
                )
                visual_plan = EpistemicPlan.from_dict(prepared_action_turn.epistemic_plan)
                if visual_plan is not None:
                    visual_plan = visual_plan.with_current_visual_observation(
                        subject=semantic_task_request,
                    )
                    prepared_action_turn = replace(
                        prepared_action_turn,
                        epistemic_plan=visual_plan.to_dict(),
                        epistemic_state=visual_plan.epistemic_state().to_dict(),
                    )
                    body["_preparedActionTurn"] = prepared_action_turn
            executed_request_signatures.update(
                tool_request_signature(item)
                for item in followup_requests
                if isinstance(item, dict) and str(item.get("name") or "")
            )
            is_last_round = tool_rounds >= maximum_tool_rounds
            loop_payload: dict[str, Any] = {
                "model": settings["apiModel"],
                "temperature": 0.55,
                "max_tokens": 6000 if file_output_expected else min(
                    6_000,
                    fast_stream_token_budget(turn_policy) + 240,
                ),
                "messages": [
                    *base_messages,
                    {"role": "assistant", "content": content},
                    {"role": "system", "content": tool_context_prompt(
                        executed_tool_results,
                        context_resolution,
                        max_chars=turn_policy.tool_evidence_max_chars,
                     model_owned=bool(cognitive_turn_state(body)))},
                    *([{"role": "system", "content": visual_evidence_prompt(
                        executed_tool_results,
                        user_question=semantic_task_request,
                    )}] if visual_evidence_prompt(
                        executed_tool_results,
                        user_question=semantic_task_request,
                    ) else []),
                    *(
                        [{"role": "system", "content": tool_grounding_instruction(
                            executed_tool_results
                        )}]
                        if tool_grounding_instruction(executed_tool_results)
                        else []
                    ),
                    {"role": "system", "content": (
                        "把所有已返回工具证据按 semantic-v3 综合成 kind='turn'；不要重复输出"
                        " reply/spokenTextJa 或复述工具调度过程。"
                        + (
                            "本轮已到工具循环上限，不得再输出 tool_use；"
                            "如果证据仍不足，要自然说明不确定处或需要用户澄清。"
                            if is_last_round else
                            "只有发现一个尚未执行、且完成任务不可缺少的不同工具时，"
                            "才可再输出一次 kind='tool_use' 和 calls。"
                        )
                    )},
                    {"role": "system", "content": core_dialogue_turn_contract_prompt(
                        utterance_interpretation,
                        turn_contract,
                        model_owned=bool(cognitive_turn_state(body)),
                    )},
                ],
            }
            if settings.get("useResponseFormat"):
                loop_payload["response_format"] = {"type": "json_object"}
            if "deepseek.com" in settings["apiEndpoint"]:
                loop_payload["thinking"] = {"type": "disabled"}
            loop_payload["messages"], context_pressure_metrics = pressure_managed_prompt(
                loop_payload["messages"],
                settings,
                reserved_output_tokens=int(loop_payload["max_tokens"]),
                request_id=request_id,
                stage=f"chat_tool_round_{tool_rounds}",
            )
            loop_started = time.perf_counter()
            body["_cognitiveEvidence"] = {**(body.get("_cognitiveEvidence") or {}), **collect_evidence(executed_tool_results)}
            content = send_conversation_brain_payload(
                body, settings,
                loop_payload,
                timeout=90,
                request_id=request_id,
                purpose=f"chat_tool_query_loop_round_{tool_rounds}",
            )
            semantic_task_request = current_task_semantic_request(body, user_message)
            answer_finish_reason = LAST_UPSTREAM_FINISH_REASON.get()
            second_llm_ms += round((time.perf_counter() - loop_started) * 1000)
            write_server_log(
                "tool_query_loop_round_completed",
                requestId=request_id,
                round=tool_rounds,
                resultCount=len(followup_results),
            )
        write_server_log(
            "tool_query_loop_stopped",
            requestId=request_id,
            toolRounds=tool_rounds,
            stopReason=(
                tool_loop_stop_reason
            ),
        )
    body["_cognitiveToolRoundsUsed"] = (
        tool_rounds if requested_tools else prior_tool_rounds
    )
    grounding_tool_results = [
        *executed_tool_results,
        *([] if any(
            item.get("ok") and item.get("name") in {"capture_screen", "capture_camera", "read_image"}
            for item in executed_tool_results
        ) else recalled_visual_results),
    ]
    # Current visual truth is owned by the typed semantic gate below.  The
    # older regex validator remains only for non-visual tools and for cheap
    # diagnostics; it must not decide whether a visual sentence is factual.
    non_visual_grounding_tool_results = [
        item for item in grounding_tool_results
        if str(item.get("name") or "") not in {"capture_screen", "capture_camera", "read_image"}
    ]
    visual_grounding_active = has_typed_visual_evidence(grounding_tool_results)
    web_evidence_status = next(
        (
            item.get("evidenceStatus") for item in executed_tool_results
            if item.get("ok") and isinstance(item.get("evidenceStatus"), dict)
        ),
        None,
    )
    if web_evidence_status:
        context_resolution["webEvidenceStatus"] = web_evidence_status
    grounding_repair_ms = 0
    context_recovery_web_ms = 0
    context_recovery_triggered_web = False
    non_json_reply_recovered = bool(
        isinstance(content, str)
        and content.strip()
        and parse_json_object(content) is None
    )
    structured_transport_invalid = bool(
        non_json_reply_recovered and looks_like_incomplete_structured_reply(content)
    )
    if non_json_reply_recovered:
        write_server_log(
            "upstream_non_json_reply_recovered",
            requestId=request_id,
            purpose="chat_tool_followup" if requested_tools else "chat_primary",
            characters=len(content),
            toolResultCount=len(executed_tool_results),
        )
    if structured_transport_invalid:
        write_server_log(
            "upstream_structured_reply_truncated",
            requestId=request_id,
            purpose="chat_tool_followup" if requested_tools else "chat_primary",
            replyFieldRecovered=bool(extract_complete_json_string_field(content, "reply")),
            characters=len(content),
        )
    cognitive_accepted = (body.get("_cognitiveOutcomeVerification") or {}).get("valid") is True
    if cognitive_turn_state(body) and not cognitive_accepted:
        raise CognitiveProtocolError("tool loop did not produce a validated final outcome")
    update_chat_request_progress(request_id, "validating", "正在检查回答完整性、上下文与工具证据")
    content = ensure_verified_web_citation(content, executed_tool_results)
    tool_grounding_candidates: list[dict[str, Any]] = [
        normalize_model_reply(content, settings=settings)
    ]
    research_candidates: list[dict[str, Any]] = []
    has_web_grounding = any(
        item.get("ok") and item.get("name") in {"web_search", "read_web_page"}
        for item in grounding_tool_results
    )
    if has_web_grounding:
        research_candidates.append(normalize_model_reply(content, settings=settings))
    if not cognitive_accepted and (non_visual_grounding_tool_results and tool_grounding_violation(
        content, non_visual_grounding_tool_results, user_message, relationship_state
    )):
        update_chat_request_progress(request_id, "repairing", "回答未充分使用工具证据，正在定向修正")
        grounding_started = time.perf_counter()
        try:
            content = repair_tool_grounded_reply(
                settings, user_message, content, grounding_tool_results, context_resolution,
                relationship_state, active_persona_snapshot
            )
            content = ensure_verified_web_citation(content, executed_tool_results)
            tool_grounding_candidates.append(normalize_model_reply(content, settings=settings))
            if has_web_grounding:
                research_candidates.append(normalize_model_reply(content, settings=settings))
        except Exception:
            pass
        grounding_repair_ms = round((time.perf_counter() - grounding_started) * 1000)
    active_epistemic_plan = EpistemicPlan.from_dict(
        prepared_action_turn.epistemic_plan
    ) or create_epistemic_plan(
        request_id,
        utterance_interpretation,
        decision=research_decision,
    )
    pre_gate_receipt = research_receipt_from_tool_results(
        request_id,
        executed_tool_results,
    )
    web_research_attempted = any(
        item.get("name") in {"web_search", "read_web_page"}
        for item in executed_tool_results
        if isinstance(item, Mapping)
    )
    pre_gate_decision = grounded_claim_gate_decision(
        str(tool_grounding_candidates[0].get("reply") or ""),
        active_epistemic_plan.epistemic_state(),
        pre_gate_receipt,
        research_policy=(
            active_epistemic_plan.research_policy
            if settings.get("permissionWebSearch")
            else "forbidden"
        ),
        # At this early point the successful local capture authorizes visual
        # synthesis; the independent claim-by-claim audit below decides
        # whether the actual prose may be released.
        visual_evidence_verified=has_typed_visual_evidence(grounding_tool_results),
    )
    evidence_gate_triggered = bool(
        pre_gate_decision.status == "RESEARCH_ESCALATION"
    )
    semantic_research_audit: dict[str, Any] = {}
    semantic_research_audit_failed = False
    if (
        not cognitive_accepted and (not web_research_attempted
        and settings.get("permissionWebSearch")
        and research_decision.policy != "forbidden"
        and needs_post_answer_research_audit(
            active_epistemic_plan,
            pre_gate_decision,
            pre_gate_receipt,
        ))
    ):
        try:
            semantic_research_audit = audit_model_research_need(
                settings,
                user_message,
                str(tool_grounding_candidates[0].get("reply") or ""),
                active_epistemic_plan,
                request_id=request_id,
            )
            evidence_gate_triggered = bool(
                evidence_gate_triggered
                or semantic_research_audit.get("researchNeeded")
            )
            write_server_log(
                "post_answer_research_need_audit",
                requestId=request_id,
                **semantic_research_audit,
            )
        except Exception as audit_error:
            semantic_research_audit_failed = True
            write_server_log(
                "post_answer_research_need_audit_failed",
                requestId=request_id,
                errorType=type(audit_error).__name__,
                error=str(audit_error)[:500],
            )
    write_server_log(
        "query_loop_grounding_gate_decision",
        requestId=request_id,
        planId=active_epistemic_plan.plan_id,
        planRevision=active_epistemic_plan.revision,
        decision=pre_gate_decision.to_dict(),
    )
    if (
        not cognitive_accepted and ((
            evidence_gate_triggered
            or (
                context_grounding_violation(content, context_resolution)
                and context_repair_needs_web_research(
                    user_message,
                    context_resolution,
                    executed_tool_results,
                )
            )
        )
        and not web_research_attempted
        and research_decision.policy != "forbidden"
        and settings.get("permissionWebSearch"))
    ):
        update_chat_request_progress(request_id, "researching", "现有证据不足，正在补充外部事实")
        recovery_web_started = time.perf_counter()
        recovery_plan = fallback_web_research_plan(
            user_message,
            context_resolution,
            messages,
        )
        semantic_query = str(semantic_research_audit.get("query") or "").strip()
        if semantic_query:
            recovery_plan["queries"] = [{
                "query": semantic_query,
                "purpose": "model semantic evidence audit",
            }]
        recovery_execution_plan = finalize_turn_execution_plan(
            body,
            user_message=user_message,
            decision=research_decision,
            preflight=tool_preflight,
            tool_requests=[{
                "name": "web_search",
                "args": {
                    "query": semantic_query or fallback_web_research_query(
                        user_message,
                        context_resolution,
                        messages,
                    ),
                },
                "reason": "grounded claim gate identified an evidence gap",
            }],
            settings=settings,
            evidence_recovery_escalation=True,
        )
        research_decision = replace(
            research_decision,
            policy=recovery_execution_plan.research_policy,
            reasons=tuple(dict.fromkeys((
                *research_decision.reasons,
                "grounded_claim_gate_evidence_gap",
            ))),
            verification_targets=(
                research_decision.verification_targets
                or ("claims rejected by context evidence gate",)
            ),
            plan_revision=max(
                research_decision.plan_revision + 1,
                recovery_execution_plan.revision,
            ),
        )
        prepared_action_turn, research_decision = synchronize_prepared_epistemic_plan(
            prepared_action_turn,
            research_decision,
        )
        capability = capability_envelope(
            turn_policy,
            research_decision,
            web_permission=True,
        )
        capability = replace(
            capability,
            research_policy=recovery_execution_plan.research_policy,
            required_tools=recovery_execution_plan.required_capabilities,
            max_tool_rounds=recovery_execution_plan.max_tool_rounds,
            tool_policy="required",
        )
        prepared_action_turn = replace(
            prepared_action_turn,
            research_decision=research_decision.to_dict(),
            capability_envelope=capability.to_dict(),
        )
        body["_preparedActionTurn"] = prepared_action_turn
        persist_prepared_turn(prepared_action_turn)
        emit_research_bridge_once(recovery_plan)
        recovered_result, recovery_plan, _, recovery_review_ms = (
            run_research_query_loop(
                settings,
                user_message,
                messages,
                recovery_plan,
                context_resolution,
                research_decision,
                capability,
                request_id=request_id,
                cognitive_body=body,
            )
        )
        recovery_results = [recovered_result]
        research_review_ms += recovery_review_ms
        executed_tool_results.extend(recovery_results)
        grounding_tool_results.extend(recovery_results)
        context_recovery_triggered_web = True
        context_recovery_web_ms = round((time.perf_counter() - recovery_web_started) * 1000)
        recovered_web_evidence_status = next(
            (
                item.get("evidenceStatus") for item in recovery_results
                if item.get("ok") and isinstance(item.get("evidenceStatus"), dict)
            ),
            None,
        )
        if recovered_web_evidence_status:
            web_evidence_status = recovered_web_evidence_status
            context_resolution["webEvidenceStatus"] = recovered_web_evidence_status
        has_web_grounding = any(
            item.get("ok") and item.get("name") in {"web_search", "read_web_page"}
            for item in grounding_tool_results
        )
        write_server_log(
            "context_repair_web_research",
            requestId=request_id,
            evidenceGateTriggered=evidence_gate_triggered,
            ok=any(item.get("ok") for item in recovery_results),
            queries=[
                str(item.get("query") or "")[:240]
                for item in recovery_plan.get("queries", [])
                if isinstance(item, dict)
            ],
        )
    pre_context_result = normalize_model_reply(content, settings=settings)
    context_grounding_repair_ms = 0
    if not cognitive_accepted and (context_recovery_triggered_web):
        context_started = time.perf_counter()
        try:
            content = repair_tool_grounded_reply(
                settings, user_message, content, grounding_tool_results, context_resolution,
                relationship_state, active_persona_snapshot
            )
            content = ensure_verified_web_citation(content, executed_tool_results)
            research_candidates.append(normalize_model_reply(content, settings=settings))
        except Exception:
            pass
        context_grounding_repair_ms = round((time.perf_counter() - context_started) * 1000)
    elif (
        not cognitive_accepted and (not visual_grounding_active
        and not has_web_grounding
        and context_grounding_violation(content, context_resolution))
    ):
        update_chat_request_progress(request_id, "repairing", "正在按完整上下文修正回答")
        context_started = time.perf_counter()
        try:
            content = repair_context_grounded_reply(
                settings, user_message, content, context_resolution, grounding_tool_results,
                active_persona_snapshot
            )
        except Exception:
            pass
        context_grounding_repair_ms = round((time.perf_counter() - context_started) * 1000)
    update_chat_request_progress(request_id, "finalizing", "正在选择完整回答并整理情绪与语音参数")
    result = normalize_model_reply(content, settings=settings)
    result = ensure_verified_web_citation(result, executed_tool_results)
    if semantic_research_audit_failed:
        result = terminal_grounding_boundary_reply(result)
        result["webEvidenceLimited"] = True
        result["semanticResearchAuditFailed"] = True
    if has_web_grounding:
        research_candidates.append(dict(result))
    if (
        not cognitive_accepted and (not visual_grounding_active
        and not has_web_grounding
        and context_grounding_violation(result, context_resolution))
    ):
        result, context_contract_satisfied = select_best_model_candidate(
            [pre_context_result, result],
            lambda candidate: context_grounding_violation(candidate, context_resolution),
        )
        if not context_contract_satisfied:
            result["contextGroundingUnverified"] = True
    if not cognitive_accepted and (non_visual_grounding_tool_results and tool_grounding_violation(
        result, non_visual_grounding_tool_results, user_message, relationship_state
    )):
        if has_web_grounding:
            result, research_contract_satisfied = select_best_research_candidate(
                [*research_candidates, result], grounding_tool_results
            )
            if not research_contract_satisfied:
                result["webSynthesisUnverified"] = True
                result["webSynthesisDiagnostics"] = web_answer_diagnostics(result, grounding_tool_results)
            if tool_grounding_violation(result, non_visual_grounding_tool_results, user_message, relationship_state):
                result["toolGroundingUnverified"] = True
        else:
            result, tool_contract_satisfied = select_best_model_candidate(
                [*tool_grounding_candidates, result],
                lambda candidate: tool_grounding_violation(
                    candidate, non_visual_grounding_tool_results, user_message, relationship_state
                ),
            )
            if not tool_contract_satisfied:
                diagnostics = ["no_model_candidate_satisfied_tool_contract"]
                result["toolGroundingUnverified"] = True
                result["toolGroundingDiagnostics"] = diagnostics
    reply_integrity_repair_ms = 0
    if not cognitive_accepted and (reply_integrity_issues(result)):
        write_server_log(
            "reply_integrity_violation",
            requestId=request_id,
            issues=reply_integrity_issues(result),
            characters=len(str(result.get("reply") or "")),
        )
        integrity_candidates = [pre_context_result, *research_candidates, result]
        if has_web_grounding:
            selected_integrity_candidate, _ = select_best_research_candidate(
                integrity_candidates, grounding_tool_results
            )
        else:
            selected_integrity_candidate, _ = select_best_model_candidate(
                integrity_candidates,
                lambda candidate: bool(reply_integrity_issues(candidate)),
            )
        result = selected_integrity_candidate
        if reply_integrity_issues(result):
            integrity_started = time.perf_counter()
            try:
                repaired_content = repair_incomplete_model_reply(
                    settings, user_message, result, context_resolution, grounding_tool_results,
                    active_persona_snapshot
                )
                repaired_content = ensure_verified_web_citation(repaired_content, executed_tool_results)
                repaired_result = normalize_model_reply(repaired_content, settings=settings)
                if not reply_integrity_issues(repaired_result):
                    result = repaired_result
                    content = repaired_content
                    result["replyIntegrityRepaired"] = True
                else:
                    result["replyIntegrityUnverified"] = True
                    result["replyIntegrityIssues"] = reply_integrity_issues(repaired_result)
            except Exception:
                result["replyIntegrityUnverified"] = True
                result["replyIntegrityIssues"] = reply_integrity_issues(result)
            reply_integrity_repair_ms = round((time.perf_counter() - integrity_started) * 1000)
    repair_started = time.perf_counter()
    if result.get("emptyReply"):
        result = repair_empty_reply(
            settings,
            memories,
            user_message,
            content,
            request_id=request_id,
            persona_snapshot=active_persona_snapshot,
        )
    if (
        not visual_grounding_active
        and not has_web_grounding
        and context_grounding_violation(result, context_resolution)
    ):
        # Validators may request one model repair, but never author the answer.
        # Preserve the best visible model candidate for every domain.
        result["contextGroundingUnverified"] = True
    task_completion_repair_ms = 0
    if not cognitive_accepted and (task_completion_violation(result, context_resolution)):
        original_task_candidate = dict(result)
        task_repair_started = time.perf_counter()
        try:
            repaired_content = repair_task_completion_reply(
                settings, user_message, result, context_resolution, grounding_tool_results,
                active_persona_snapshot
            )
            repaired_result = normalize_model_reply(repaired_content, settings=settings)
            repaired_satisfies_contract = not task_completion_violation(repaired_result, context_resolution)
            result, task_contract_satisfied = select_best_model_candidate(
                [original_task_candidate, repaired_result],
                lambda candidate: task_completion_violation(candidate, context_resolution),
            )
            if task_contract_satisfied and repaired_satisfies_contract and result.get("reply") == repaired_result.get("reply"):
                result["taskCompletionRepaired"] = True
            elif not task_contract_satisfied:
                result["taskCompletionUnverified"] = True
        except Exception:
            result = original_task_candidate
            result["taskCompletionUnverified"] = True
        task_completion_repair_ms = round((time.perf_counter() - task_repair_started) * 1000)
    failed_web_results = [
        item for item in executed_tool_results
        if item.get("name") in {"web_search", "read_web_page"} and not item.get("ok")
    ]
    successful_web_results = [
        item for item in executed_tool_results
        if item.get("name") in {"web_search", "read_web_page"} and item.get("ok")
    ]
    insufficient_web_results = [
        item for item in successful_web_results
        if isinstance(item.get("evidenceStatus"), dict)
        and not item.get("evidenceStatus", {}).get("sufficient")
    ]
    web_retrieval_failed = bool(failed_web_results and not successful_web_results)
    web_evidence_limited = bool(
        web_retrieval_failed
        or (
            successful_web_results
            and len(insufficient_web_results) == len(successful_web_results)
        )
    )
    evidence_limited_synthesis_ms = 0
    evidence_limited_precision_audit_ms = 0
    if not cognitive_accepted and (web_evidence_limited):
        limited_started = time.perf_counter()
        original_limited_candidate = dict(result)
        try:
            limited_content = synthesize_evidence_limited_reply(
                settings,
                user_message,
                original_limited_candidate,
                executed_tool_results,
                context_resolution,
                relationship_state,
                request_id=request_id,
                persona_snapshot=active_persona_snapshot,
            )
            limited_result = normalize_model_reply(limited_content, settings=settings)
            if limited_result.get("emptyReply") or reply_integrity_issues(limited_result):
                raise UpstreamProtocolError("evidence-limited synthesis returned no complete answer")
            limited_appended_prior = evidence_synthesis_appends_prior_answer(
                limited_result,
                original_limited_candidate,
            )
            if limited_appended_prior:
                write_server_log(
                    "evidence_limited_synthesis_repeated_prior_answer",
                    requestId=request_id,
                    previousCharacters=len(model_reply_text(original_limited_candidate)),
                    candidateCharacters=len(model_reply_text(limited_result)),
                )
            result = limited_result
            content = limited_content
            result["evidenceLimitedSynthesis"] = True
            audit_started = time.perf_counter()
            try:
                audited_content = audit_evidence_limited_reply(
                    settings,
                    user_message,
                    result,
                    executed_tool_results,
                    request_id=request_id,
                    persona_snapshot=active_persona_snapshot,
                )
                audited_result = normalize_model_reply(audited_content, settings=settings)
                if audited_result.get("emptyReply") or reply_integrity_issues(audited_result):
                    raise UpstreamProtocolError("evidence-limited precision audit returned no complete answer")
                if evidence_synthesis_appends_prior_answer(
                    audited_result,
                    original_limited_candidate,
                ):
                    raise UpstreamProtocolError(
                        "evidence-limited precision audit retained a duplicated prior answer"
                    )
                result = audited_result
                content = audited_content
                result["evidenceLimitedSynthesis"] = True
                result["evidenceLimitedPrecisionAudited"] = True
            except Exception as audit_error:
                write_server_log(
                    "evidence_limited_precision_audit_failed",
                    requestId=request_id,
                    errorType=type(audit_error).__name__,
                    error=str(audit_error)[:500],
                )
                # This candidate has not passed the evidence audit. Neither it
                # nor the original draft becomes valid when the audit fails.
                raise UpstreamProtocolError(
                    "evidence-limited answer could not complete its precision audit"
                ) from audit_error
            finally:
                evidence_limited_precision_audit_ms = round(
                    (time.perf_counter() - audit_started) * 1000
                )
        except Exception as error:
            result = terminal_grounding_boundary_reply(
                original_limited_candidate, failure_stage="evidence_limited_answer",
            )
            content = json.dumps(result, ensure_ascii=False)
            result["evidenceLimitedSynthesisFailed"] = True
            write_server_log(
                "evidence_limited_synthesis_failed",
                requestId=request_id,
                errorType=type(error).__name__,
                error=str(error)[:500],
                finishReason=LAST_UPSTREAM_FINISH_REASON.get(),
            )
        result["webEvidenceLimited"] = True
        result["webSearchFailed"] = web_retrieval_failed
        evidence_limited_synthesis_ms = round((time.perf_counter() - limited_started) * 1000)
        result = sanitize_secondary_only_precision(
            result,
            executed_tool_results,
            user_message,
        )
    if cognitive_accepted:
        # The main model already reported the verified outcome. Keep receipt
        # metadata without replacing its answer with a legacy retry question.
        receipts = action_receipts_from_results(executed_tool_results)
        if receipts:
            result["actionReceipts"] = receipts
            if len(receipts) == 1:
                result["actionReceipt"] = receipts[0]
    else:
        result = enforce_external_action_receipt(
            result, executed_tool_results, schedule_decision=body.get("_scheduleDecision"),
        )
    dialogue_style_repair_ms = 0
    dialogue_validation = dialogue_validation_for_result(
        result,
        turn_policy,
        messages,
    )
    if not cognitive_accepted and (dialogue_validation.needs_rewrite):
        update_chat_request_progress(
            request_id,
            "repairing",
            "回答超出本轮篇幅或动作预算，正在保留事实并压缩表达",
        )
        style_started = time.perf_counter()
        original_style_candidate = dict(result)
        try:
            repaired_style_candidate = repair_dialogue_style_reply(
                settings,
                user_message,
                result,
                turn_policy,
                grounding_tool_results,
                context_resolution,
                relationship_state,
                deep_persona_prompt,
                active_persona_snapshot,
            )
            repaired_style_candidate = ensure_verified_web_citation(
                repaired_style_candidate,
                executed_tool_results,
            )
            repaired_validation = dialogue_validation_for_result(
                repaired_style_candidate,
                turn_policy,
                messages,
            )
            violates_required_contract = bool(
                repaired_validation.needs_rewrite
                or reply_integrity_issues(repaired_style_candidate)
                or task_completion_violation(repaired_style_candidate, context_resolution)
                or (
                    non_visual_grounding_tool_results
                    and tool_grounding_violation(
                        repaired_style_candidate,
                        non_visual_grounding_tool_results,
                        user_message,
                        relationship_state,
                    )
                )
                or (
                    not visual_grounding_active
                    and not has_web_grounding
                    and context_grounding_violation(
                        repaired_style_candidate,
                        context_resolution,
                    )
                )
            )
            if violates_required_contract:
                result = original_style_candidate
                result["dialogueStyleUnverified"] = True
            else:
                result = repaired_style_candidate
                result["dialogueStyleRepaired"] = True
                dialogue_validation = repaired_validation
                content = json.dumps(result, ensure_ascii=False)
        except Exception as error:
            result = original_style_candidate
            result["dialogueStyleUnverified"] = True
            write_server_log(
                "dialogue_style_repair_failed",
                requestId=request_id,
                errorType=type(error).__name__,
                error=str(error)[:500],
            )
        dialogue_style_repair_ms = round((time.perf_counter() - style_started) * 1000)
    visual_grounding_audit_ms = 0
    visual_grounding_rewrite_ms = 0
    result["_nativeVisualInputIds"] = list(body.get("_nativeVisualInputIds") or [])
    if not cognitive_accepted and (has_typed_visual_evidence(grounding_tool_results)):
        result, visual_grounding_audit_ms, visual_grounding_rewrite_ms = (
            enforce_visual_semantic_grounding(
                settings,
                semantic_task_request,
                result,
                grounding_tool_results,
                relationship_state,
                request_id=request_id,
                task_dialogue=task_review_dialogue_messages(body, messages),
            )
        )
        # The focused visual rewrite may replace the prose.  Recompute style
        # diagnostics, but do not run another prose authoring pass after the
        # final visual audit.
        dialogue_validation = dialogue_validation_for_result(
            result,
            turn_policy,
            messages,
        )
    result["dialoguePolicy"] = turn_policy.to_dict()
    result["dialogueValidation"] = dialogue_validation.to_dict()
    result["_utteranceInterpretation"] = utterance_interpretation
    result["_turnContract"] = turn_contract
    result["_semanticTaskRequest"] = current_task_semantic_request(body, user_message)
    result["_taskDialogue"] = task_review_dialogue_messages(body, messages)
    result["coreDialogueProtocol"] = compact_core_protocol
    result["semanticDialogueProtocol"] = "semantic-v3-unified"
    result = attach_verified_web_sources(result, executed_tool_results)
    field_validation = dialogue_output_validation(settings, result)
    primary_emotion_missing = "emotion" in field_validation["missingFields"]
    field_repair_ms = 0
    field_repair_source = "not_needed"
    emotion_label_ms = 0
    emotion_recovery_calls = 0
    emotion_label_source = "primary_model"
    if result.get("speechSegmentCountMissingFromModel"):
        # A missing model contract is one atomic delivery unit.  Never infer
        # visible boundaries from punctuation or reply length.
        result["speechSegmentCount"] = 1
        result["speechSegmentCountSource"] = "atomic_no_model_boundary"
    if field_validation["requiresFieldRepair"]:
        field_started = time.perf_counter()
        result["dialogueFieldRepairAttempted"] = True
        update_chat_request_progress(
            request_id,
            "repairing-fields",
            "正文已保留，正在补齐缺失的语音字段",
        )
        write_server_log(
            "dialogue_field_repair_started",
            requestId=request_id,
            missingFields=field_validation["missingFields"],
            invalidFields=field_validation["invalidFields"],
            frozenReplyFingerprint=runtime_fingerprint(
                result.get("reply"), length=32
            ),
        )
        try:
            result = repair_dialogue_fields_once(
                settings,
                result,
                field_validation,
                user_message=user_message,
                recent_messages=messages,
                relationship_state=relationship_state,
                request_id=request_id,
                persona_snapshot=active_persona_snapshot,
            )
            result["structuredOutputResolved"] = True
            field_repair_source = "minimal_speech_model"
            write_server_log(
                "dialogue_field_repair_completed",
                requestId=request_id,
                repairedFields=result.get("dialogueFieldRepairFields", []),
                maxTokens=result.get("dialogueFieldRepairMaxTokens"),
                finishReason=result.get("dialogueFieldRepairFinishReason"),
                jsonComplete=bool(result.get("dialogueFieldRepairJsonComplete")),
                frozenReplyPreserved=True,
            )
        except Exception as error:
            field_repair_source = "failed"
            result["dialogueFieldRepairFailed"] = True
            result["ttsUnavailableReason"] = "dialogue_field_repair_failed"
            # The accepted and grounded Chinese answer remains a complete user
            # deliverable when its optional Japanese presentation track cannot
            # be repaired. Mark an explicit text-only terminal path instead of
            # silently dropping the whole result in the browser.
            result["textOnlyDelivery"] = True
            result["deliveryFallbackReason"] = "dialogue_field_repair_failed"
            write_server_log(
                "dialogue_field_repair_failed",
                requestId=request_id,
                errorType=type(error).__name__,
                error=str(error)[:500],
            )
        field_repair_ms = round((time.perf_counter() - field_started) * 1000)
    if primary_emotion_missing and not result.get("dialogueFieldRepairFailed"):
        emotion_started = time.perf_counter()
        if configured(settings):
            emotion_recovery_calls = 1
            update_chat_request_progress(
                request_id,
                "repairing-emotion",
                "正文已冻结，正在补齐表情与语音情绪",
            )
            try:
                result = repair_frozen_reply_emotion_once(
                    settings,
                    result,
                    user_message=user_message,
                    recent_messages=messages,
                    relationship_state=relationship_state,
                    request_id=request_id,
                )
                emotion_label_source = "frozen_reply_semantic_classifier"
            except Exception as error:
                result["emotionResolvedLocally"] = True
                result["emotionLabelRecoveryFailed"] = True
                result["emotionUnavailableReason"] = "emotion_label_recovery_failed"
                emotion_label_source = "local_default_after_classifier_failure"
                write_server_log(
                    "emotion_label_recovery_failed",
                    requestId=request_id,
                    errorType=type(error).__name__,
                    error=str(error)[:500],
                )
        else:
            result["emotionResolvedLocally"] = True
            result["emotionUnavailableReason"] = "model_not_configured"
            emotion_label_source = "local_default_model_unavailable"
        emotion_label_ms = round((time.perf_counter() - emotion_started) * 1000)
    elif primary_emotion_missing:
        result["emotionResolvedLocally"] = True
        result["emotionUnavailableReason"] = "speech_field_repair_failed"
        emotion_label_source = "local_default_after_speech_repair_failure"
    if web_evidence_status:
        result["webEvidenceStatus"] = web_evidence_status
    if executed_tool_results:
        tool_names = list(dict.fromkeys(displayed_tool_name(item) for item in executed_tool_results))
        status_results = effective_tool_results_for_status(executed_tool_results)
        failed_tools = [
            str(item.get("name") or "tool")
            for item in status_results
            if not item.get("ok")
        ]
        result["toolUsed"] = ",".join(tool_names)
        result["toolStatus"] = "failed" if failed_tools else "ok"
        result["toolErrors"] = [
            {
                "name": str(item.get("name") or "tool"),
                "error": str(item.get("error") or "unknown_error"),
            }
            for item in status_results
            if not item.get("ok")
        ]
        public_attachment_tools = [
            public_attachment_tool_result(item) for item in executed_tool_results
            if item.get("name") in {"read_file", "read_image"}
        ]
        if public_attachment_tools:
            result["toolResults"] = public_attachment_tools
        todo_context = todo_context_from_tool_results(executed_tool_results)
        if todo_context:
            result["todoContext"] = todo_context
        # Kept only until finalize_chat_response persists the turn. This lets
        # the conversation remember several screen observations without
        # exposing full local tool payloads to the browser response.
        result["_conversationToolResults"] = effective_tool_results(
            executed_tool_results
        )
    result["_referenceLedger"] = discourse_ledger.to_dict()
    attachment_action = result.get("attachmentAction") or {}
    result["_fileOutputExpected"] = (
        attachment_action.get("kind") in {"edit", "create"} and attachment_action.get("status") == "completed"
        if attachment_action else file_output_expected
    )
    result["_chatMetrics"] = {
        "requestId": request_id,
        "preToolMs": pre_tool_ms,
        "researchPlanningMs": research_planning_ms,
        "researchBridgeMs": research_bridge_ms,
        "researchBridgeEmitted": research_bridge_emitted,
        "researchReviewMs": research_review_ms,
        "researchReview": research_review or {},
        "researchPlanQueries": (
            [
                str(item.get("query") or "")[:240]
                for item in research_plan.get("queries", [])
                if isinstance(item, dict)
            ]
            if isinstance(research_plan, dict) else []
        ),
        "firstLlmMs": first_llm_ms,
        "secondLlmMs": second_llm_ms,
        "toolGroundingRepairMs": grounding_repair_ms,
        "contextGroundingRepairMs": context_grounding_repair_ms,
        "contextRecoveryWebMs": context_recovery_web_ms,
        "replyIntegrityRepairMs": reply_integrity_repair_ms,
        "taskCompletionRepairMs": task_completion_repair_ms,
        "dialogueStyleRepairMs": dialogue_style_repair_ms,
        "visualGroundingAuditMs": visual_grounding_audit_ms,
        "visualGroundingRewriteMs": visual_grounding_rewrite_ms,
        "evidenceLimitedSynthesisMs": evidence_limited_synthesis_ms,
        "evidenceLimitedPrecisionAuditMs": evidence_limited_precision_audit_ms,
        "emptyReplyRepairMs": round((time.perf_counter() - repair_started) * 1000),
        "promptChars": sum(len(str(item.get("content") or "")) for item in base_messages),
        "personaCoreChars": len(prompt),
        "deepPersonaChars": len(deep_persona_prompt),
        "deepPersonaModules": context_resolution.get("personaModules", []),
        "personaContextSnapshot": active_persona_snapshot.safe_diagnostic(),
        "historyMessages": min(turn_policy.recent_message_limit, len(messages)),
        "retrievedMemories": len(memories),
        "memoryNeed": memory_need.value,
        "contextPressure": context_pressure_metrics,
        "replyMode": turn_policy.reply_mode,
        "actionBudget": turn_policy.action_budget,
        "turnPolicyReason": turn_policy.reason,
        "turnPolicy": turn_policy.to_dict(),
        "replySentences": dialogue_validation.sentence_count,
        "replyCharacters": dialogue_validation.character_count,
        "assistantPhraseHits": list(dialogue_validation.forbidden_phrase_hits),
        "dialogueValidationIssues": list(dialogue_validation.issues),
        "tools": [str(item.get("name") or "tool") for item in executed_tool_results],
        "toolStatus": result.get("toolStatus") or "not_requested",
        "nonJsonReplyRecovered": non_json_reply_recovered,
        "structuredTransportInvalid": structured_transport_invalid,
        "primaryOutputProtocol": "semantic-v3-unified",
        "dialogueFieldValidation": field_validation,
        "dialogueFieldRepairMs": field_repair_ms,
        "dialogueFieldRepairSource": field_repair_source,
        "dialogueFieldRepairCalls": int(bool(result.get("dialogueFieldRepairAttempted"))),
        "fullReplyRepairCalls": int(bool(result.get("fullReplyRepairAttempted"))),
        "independentEmotionRecoveryCalls": emotion_recovery_calls,
        "emotionLabelMs": emotion_label_ms,
        "emotionLabelSource": emotion_label_source,
        "uncertaintyTriggeredWeb": uncertainty_triggered_web,
        "preAnswerResearchAudited": bool(body.get("_preAnswerResearchAudit")),
        "preAnswerResearchTriggeredWeb": bool(
            isinstance(body.get("_preAnswerResearchAudit"), Mapping)
            and body["_preAnswerResearchAudit"].get("researchNeeded")
        ),
        "contextRecoveryTriggeredWeb": context_recovery_triggered_web,
        "knowledgeConfidence": str(
            parsed.get("knowledgeConfidence") or parsed.get("knowledge_confidence") or ""
        )[:16],
        "contextResolution": {
            "active": bool(context_resolution.get("active")),
            "kind": str(context_resolution.get("kind") or "none"),
            "subject": str(context_resolution.get("subject") or "")[:240],
            "intent": str(context_resolution.get("intent") or "")[:80],
            "resolvedQuestion": str(context_resolution.get("resolvedQuestion") or "")[:500],
            "matchup": str(context_resolution.get("matchup") or "")[:200],
            "eventYear": str(context_resolution.get("eventYear") or "")[:20],
            "requestedAction": str(context_resolution.get("requestedAction") or "")[:80],
            "constraints": [str(item)[:160] for item in context_resolution.get("constraints", [])[:8]],
            "entities": [str(item)[:100] for item in context_resolution.get("entities", [])[:8]],
            "analysisFocus": [str(item)[:100] for item in context_resolution.get("analysisFocus", [])[:8]],
            "userPosition": str(context_resolution.get("userPosition") or "")[:240],
            "webEvidenceStatus": web_evidence_status or {},
            "personaModules": context_resolution.get("personaModules", [])[:8],
            "clearActiveTask": bool(context_resolution.get("clearActiveTask")),
            "referenceCurrentMessageId": discourse_ledger.current_message_id,
            "referenceAntecedentCount": len(
                discourse_resolution.antecedent_message_ids
            ),
            "referenceUnresolvedCount": len(
                discourse_resolution.unresolved_mention_ids
            ),
            "referenceAmbiguousCount": len(
                discourse_resolution.ambiguous_mention_ids
            ),
        },
        "modelPipelineMs": round((time.perf_counter() - pipeline_started) * 1000),
    }
    result["_upstreamFinishReason"] = answer_finish_reason
    result["personaContextSnapshotId"] = active_persona_snapshot.snapshot_id
    if isinstance(body.get("_scheduleDecision"), Mapping):
        finalized_schedule = finalize_schedule_workflow_from_results(
            body.get("_scheduleDecision"),
            executed_tool_results,
            request_id=request_id,
        )
        result["scheduleDecision"] = {
            **dict(body["_scheduleDecision"]),
            "workflow": finalized_schedule,
        }
    if todo_continuation_transition:
        pending_after = apply_todo_continuation_transition(
            todo_continuation_transition,
            request_id=request_id,
            user_message=user_message,
        )
        result["todoContinuation"] = {
            "status": (
                "awaiting_user_input"
                if pending_after else
                "cleared"
                if todo_continuation_transition.get("decision") in {"unrelated", "cancel"}
                else "resolved"
            ),
            "decision": str(todo_continuation_transition.get("decision") or ""),
            "actionId": str(pending_after.get("actionId") or ""),
        }
    elif pending_todo_before:
        todo_attempts = [
            item for item in executed_tool_results
            if isinstance(item, Mapping) and item.get("name") == "todo_manage"
        ]
        if todo_attempts:
            all_accepted = all(
                item.get("ok")
                and isinstance(item.get("actionReceipt"), Mapping)
                and item["actionReceipt"].get("status") == "accepted"
                for item in todo_attempts
            )
            event = (
                "todo_continuation_fulfilled"
                if all_accepted else "todo_continuation_partial_failure"
            )
            write_server_log(
                event,
                requestId=request_id,
                actionId=str(pending_todo_before.get("actionId") or ""),
                attemptCount=len(todo_attempts),
                acceptedCount=sum(
                    1 for item in todo_attempts
                    if isinstance(item.get("actionReceipt"), Mapping)
                    and item["actionReceipt"].get("status") == "accepted"
                ),
            )
            result["todoContinuation"] = {
                "status": "resolved" if all_accepted else "partial_failure",
                "decision": "execute",
                "actionId": str(pending_todo_before.get("actionId") or ""),
            }
    return result


def upstream_response_shape(data: Any) -> dict[str, Any]:
    if not isinstance(data, dict):
        return {"type": type(data).__name__}
    choices = data.get("choices")
    choice_shapes: list[dict[str, Any]] = []
    if isinstance(choices, list):
        for choice in choices[:3]:
            if not isinstance(choice, dict):
                choice_shapes.append({"type": type(choice).__name__})
                continue
            message = choice.get("message")
            content = message.get("content") if isinstance(message, dict) else None
            reasoning_content = message.get("reasoning_content") if isinstance(message, dict) else None
            choice_shapes.append({
                "type": "dict",
                "finishReason": str(choice.get("finish_reason") or "")[:80],
                "messageType": type(message).__name__,
                "messageKeys": sorted(str(key) for key in message.keys())[:20] if isinstance(message, dict) else [],
                "contentType": type(content).__name__ if isinstance(message, dict) else "missing",
                "contentChars": len(content) if isinstance(content, str) else 0,
                "contentNonWhitespaceChars": (
                    len(re.sub(r"\s+", "", content))
                    if isinstance(content, str) else 0
                ),
                "reasoningContentType": type(reasoning_content).__name__ if isinstance(message, dict) else "missing",
                "reasoningChars": len(reasoning_content) if isinstance(reasoning_content, str) else 0,
            })
    return {
        "type": "dict",
        "keys": sorted(str(key) for key in data.keys())[:20],
        "choicesType": type(choices).__name__,
        "choicesCount": len(choices) if isinstance(choices, list) else 0,
        "choices": choice_shapes,
        "hasError": bool(data.get("error")),
    }


def upstream_finish_reason(data: Any) -> str:
    choices = data.get("choices") if isinstance(data, dict) else []
    if not isinstance(choices, list):
        return ""
    for choice in choices:
        if not isinstance(choice, dict):
            continue
        reason = str(choice.get("finish_reason") or "").strip()
        if reason:
            return reason[:80]
    return ""


def extract_upstream_chat_text(data: Any) -> str:
    """Accept OpenAI-compatible variants and reject incomplete 200 responses."""

    if not isinstance(data, dict):
        raise UpstreamProtocolError(f"upstream response is {type(data).__name__}, expected object")
    choices = data.get("choices")
    if isinstance(choices, list):
        for choice in choices:
            if not isinstance(choice, dict):
                continue
            message = choice.get("message")
            if isinstance(message, dict):
                content = message.get("content")
                if isinstance(content, str) and content.strip():
                    return content
                if isinstance(content, list):
                    text_parts = [
                        str(part.get("text") or "")
                        for part in content
                        if isinstance(part, dict) and part.get("type") in {None, "text", "output_text"}
                    ]
                    combined = "".join(text_parts).strip()
                    if combined:
                        return combined
            text = choice.get("text")
            if isinstance(text, str) and text.strip():
                return text
    output_text = data.get("output_text")
    if isinstance(output_text, str) and output_text.strip():
        return output_text
    error = data.get("error")
    if isinstance(error, dict):
        code = str(error.get("code") or error.get("type") or "provider_error")[:80]
        message = str(error.get("message") or "upstream returned an error object")[:300]
        raise UpstreamProtocolError(f"{code}: {message}")
    raise UpstreamProtocolError("upstream returned no usable assistant message")


def json_mode_fallback_payload(payload: Mapping[str, Any]) -> dict[str, Any]:
    """Disable the provider's JSON mode without dropping our output contract."""
    active = dict(payload)
    output_format = active.pop("response_format", None) or {}
    instruction = (
        "[输出格式兼容恢复] 本次使用普通传输模式，前文规定的 JSON 输出协议保持不变。"
        "请严格按前文当前阶段的协议返回一个完整 JSON 对象，保留所有必填字段、工具调用和证据引用。"
        "自然语言只放在协议指定的文本字段里；不输出对象之外的说明、Markdown 围栏或推理过程。"
    )
    if isinstance(output_format, Mapping) and output_format.get("json_schema"):
        instruction += "\n原输出结构：" + json.dumps(output_format["json_schema"], ensure_ascii=False)
    active["messages"] = [*payload.get("messages", []), {"role": "system", "content": instruction}]
    return active


def prepare_upstream_json_mode(settings: Mapping[str, Any], payload: Mapping[str, Any]) -> tuple[dict[str, Any], dict | None, str]:
    active = dict(payload)
    state = active.pop("_cognitiveJsonModeState", None)
    state = state if isinstance(state, dict) else None
    key = json.dumps([str(settings.get("apiEndpoint") or ""),
                      str(active.get("model") or settings.get("apiModel") or "")])
    if state is not None and state.get(key) and active.get("response_format"):
        active = json_mode_fallback_payload(active)
    return active, state, key


def _send_upstream_chat_payload_uncoordinated(
    settings: dict[str, Any],
    payload: dict[str, Any],
    timeout: int = 90,
    *,
    request_id: str = "",
    purpose: str = "chat",
) -> str:
    headers = {"Content-Type": "application/json"}
    if settings.get("apiKey"):
        headers["Authorization"] = f"Bearer {settings['apiKey']}"
    safe_request_id = re.sub(r"[^A-Za-z0-9._:-]", "", str(request_id or ""))[:120]
    if safe_request_id:
        headers["X-Amadeus-Request-Id"] = safe_request_id
    active_payload, json_mode_state, json_mode_key = prepare_upstream_json_mode(settings, payload)
    request_body = json.dumps(active_payload, ensure_ascii=False).encode("utf-8")
    json_mode_active = bool(active_payload.get("response_format"))
    # DeepSeek documents that JSON Output can occasionally return HTTP 200
    # with an empty content field. Reserve one immediate non-JSON-mode attempt
    # while keeping the prompt's strict JSON instruction and local validator.
    background = purpose in UPSTREAM_BACKGROUND_PURPOSES
    attempts = 1 if background or purpose == "context_compatibility_recovery" else len(UPSTREAM_RETRY_DELAYS) + 1 + int(json_mode_active)
    request_timeout = max(0.001, float(timeout))
    deadline = time.monotonic() + request_timeout
    # The socket's connection timeout is not an inference/body timeout.
    # The cognitive phase owns this budget regardless of model tier or proxy.
    response_body_read_enabled = purpose in COGNITIVE_BODY_READ_PURPOSES
    last_error: Exception | None = None
    protocol_failure_count = 0
    for attempt in range(1, attempts + 1):
        raise_if_chat_request_cancelled(safe_request_id)
        data: Any = None
        raw = b""
        http_status = 0
        attempt_started = time.perf_counter()
        request = urllib.request.Request(
            chat_endpoint(settings["apiEndpoint"]),
            data=request_body,
            headers=headers,
            method="POST",
        )
        try:
            remaining = max(0.001, deadline - time.monotonic())
            attempt_timeout = max(0.001, min(8 if background else 45, remaining))
            with open_api_request(
                request,
                settings["apiEndpoint"],
                timeout=attempt_timeout,
                request_id=safe_request_id,
                purpose=purpose,
                settings=settings,
            ) as response, tracked_upstream_response(safe_request_id, response):
                http_status = int(getattr(response, "status", 200) or 200)
                if response_body_read_enabled:
                    body_started = time.perf_counter()
                    # Non-streaming reasoning may delay body bytes after HTTP
                    # 200. Keep this admitted request within its total deadline
                    # instead of inheriting the connection timeout and replaying.
                    body_budget = max(0.0, deadline - time.monotonic())
                    write_server_log(
                        "upstream_response_headers_received",
                        purpose=purpose,
                        requestId=safe_request_id,
                        attempt=attempt,
                        attempts=attempts,
                        httpStatus=http_status,
                        readPhase="headerReceived",
                        headerReceived=True,
                        readStarted=False,
                        readFinished=False,
                        bodyReadMode="bounded_complete",
                        bodyReadTimeoutSeconds=round(body_budget, 3),
                        totalTimeoutSeconds=round(request_timeout, 3),
                        rawBodyLength=0,
                        bodyReadBytes=0,
                        bodyReadElapsedMs=0,
                        elapsedMs=round((time.perf_counter() - attempt_started) * 1000),
                    )
                    raw = read_complete_response_body(
                        response,
                        deadline=deadline,
                        idle_timeout=None,
                        check_cancelled=lambda: raise_if_chat_request_cancelled(safe_request_id),
                    )
                    write_server_log(
                        "upstream_response_body_read_completed",
                        purpose=purpose,
                        requestId=safe_request_id,
                        attempt=attempt,
                        attempts=attempts,
                        httpStatus=http_status,
                        readPhase="readFinished",
                        headerReceived=True,
                        readStarted=True,
                        readFinished=True,
                        bodyReadMode="bounded_complete",
                        bodyReadTimeoutSeconds=round(body_budget, 3),
                        totalTimeoutSeconds=round(request_timeout, 3),
                        rawBodyLength=len(raw),
                        bodyReadBytes=len(raw),
                        bodyReadElapsedMs=round((time.perf_counter() - body_started) * 1000),
                        elapsedMs=round((time.perf_counter() - attempt_started) * 1000),
                    )
                else:
                    raw = response.read()
            raise_if_chat_request_cancelled(safe_request_id)
            data = json.loads(raw.decode("utf-8"))
            content = extract_upstream_chat_text(data)
            usage = data.get("usage") if isinstance(data, dict) and isinstance(data.get("usage"), dict) else {}
            LAST_UPSTREAM_FINISH_REASON.set(upstream_finish_reason(data))
            write_server_log(
                "upstream_response_received",
                purpose=purpose,
                requestId=safe_request_id,
                attempt=attempt,
                attempts=attempts,
                characters=len(content),
                nonWhitespaceCount=len(re.sub(r"\s+", "", content)),
                responseMode="json" if json_mode_active else "text",
                httpStatus=http_status,
                outputTokens=int(usage.get("completion_tokens") or usage.get("output_tokens") or 0),
                rawBodyLength=len(raw),
                requestPayloadFingerprint=runtime_fingerprint(request_body, length=24),
                responseContentFingerprint=runtime_fingerprint(content, length=24),
                providerResponseId=str(data.get("id") or "")[:120] if isinstance(data, dict) else "",
                streamEventCount=0,
                parserAcceptedEventCount=0,
                parserRejectedEventCount=0,
                elapsedMs=round((time.perf_counter() - attempt_started) * 1000),
            )
            return content
        except urllib.error.HTTPError as error:
            last_error = error
            retryable = int(error.code) in UPSTREAM_RETRYABLE_STATUS
            diagnostics = upstream_http_error_diagnostics(error)
            write_server_log(
                "upstream_http_error",
                purpose=purpose,
                requestId=safe_request_id,
                attempt=attempt,
                attempts=attempts,
                status=int(error.code),
                retryable=retryable,
                providerErrorCode=diagnostics["providerErrorCode"],
                providerErrorType=diagnostics["providerErrorType"],
                providerMessage=diagnostics["providerMessage"],
                responseBodyLength=diagnostics["responseBodyLength"],
            )
            if not retryable or attempt >= attempts or time.monotonic() >= deadline:
                raise
        except AttributeError as error:
            # An explicit stop closes the active urllib response. That can
            # race with HTTPResponse.read() after its internal stream is set
            # to None. Surface it as cancellation, not as a pipeline crash.
            # A non-cancellation programming error remains visible.
            raise_if_chat_request_cancelled(safe_request_id)
            raise
        except (urllib.error.URLError, TimeoutError, ConnectionError, OSError, json.JSONDecodeError, UpstreamProtocolError) as error:
            raise_if_chat_request_cancelled(safe_request_id)
            last_error = error
            body_bytes_received = int(getattr(error, "bytes_received", 0) or 0)
            if isinstance(error, (UpstreamResponseBodyTimeout, UpstreamResponseBodyReadError)):
                write_server_log(
                    "upstream_response_body_timeout"
                    if isinstance(error, UpstreamResponseBodyTimeout)
                    else "upstream_response_body_read_failed",
                    purpose=purpose,
                    requestId=safe_request_id,
                    attempt=attempt,
                    attempts=attempts,
                    httpStatus=http_status,
                    readPhase=(
                        "bodyReadTimeout"
                        if isinstance(error, UpstreamResponseBodyTimeout)
                        else str(getattr(error, "stage", "body_read"))
                    ),
                    headerReceived=True,
                    readStarted=True,
                    readFinished=False,
                    timeoutKind=str(getattr(error, "timeout_kind", "")),
                    bodyReadTimeoutSeconds=round(float(getattr(error, "timeout_seconds", 0.0) or 0.0), 3),
                    totalTimeoutSeconds=round(request_timeout, 3),
                    rawBodyLength=body_bytes_received,
                    bodyReadBytes=body_bytes_received,
                    bodyReadElapsedMs=round(float(getattr(error, "elapsed_seconds", 0.0) or 0.0) * 1000),
                    elapsedMs=round((time.perf_counter() - attempt_started) * 1000),
                )
            if isinstance(error, UpstreamProtocolError):
                protocol_failure_count += 1
            connection_category = (
                "body_read_timeout"
                if isinstance(error, UpstreamResponseBodyTimeout)
                else "body_read_failed"
                if isinstance(error, UpstreamResponseBodyReadError)
                else upstream_connection_error_category(error)
                if isinstance(error, (urllib.error.URLError, TimeoutError, ConnectionError))
                else ""
            )
            retryable = connection_category != "tls_certificate_untrusted" and not (
                isinstance(error, UpstreamResponseBodyTimeout)
                and error.timeout_kind == "total_deadline"
            )
            write_server_log(
                "upstream_transient_error",
                purpose=purpose,
                requestId=safe_request_id,
                attempt=attempt,
                attempts=attempts,
                errorType=type(error).__name__,
                error=str(error)[:500],
                responseShape=upstream_response_shape(data) if data is not None else {},
                responseMode="json" if json_mode_active else "text",
                httpStatus=http_status,
                outputTokens=int(
                    (
                        data.get("usage", {}).get("completion_tokens")
                        or data.get("usage", {}).get("output_tokens")
                        or 0
                    )
                    if isinstance(data, dict) and isinstance(data.get("usage"), dict)
                    else 0
                ),
                rawBodyLength=body_bytes_received or len(raw),
                streamEventCount=0,
                parserAcceptedEventCount=0,
                parserRejectedEventCount=0,
                retryable=retryable,
                connectionCategory=connection_category,
            )
            if not retryable:
                raise
            if isinstance(error, UpstreamProtocolError) and json_mode_active:
                if json_mode_state is not None:
                    json_mode_state[json_mode_key] = True
                active_payload = json_mode_fallback_payload(active_payload)
                request_body = json.dumps(active_payload, ensure_ascii=False).encode("utf-8")
                json_mode_active = False
                write_server_log(
                    "upstream_json_mode_fallback",
                    purpose=purpose,
                    requestId=safe_request_id,
                    attempt=attempt,
                    reason="empty_or_incomplete_json_mode_response",
                )
                if time.monotonic() < deadline:
                    continue
            # A structurally unusable HTTP-200 answer is a generation failure,
            # not an unstable network. Permit exactly one complete regeneration;
            # further blind retries only add latency and can start a repair loop.
            if isinstance(error, UpstreamProtocolError) and protocol_failure_count >= 2:
                raise
            if attempt >= attempts or time.monotonic() >= deadline:
                raise
        retry_delay = UPSTREAM_RETRY_DELAYS[min(attempt - 1, len(UPSTREAM_RETRY_DELAYS) - 1)]
        raise_if_chat_request_cancelled(safe_request_id)
        if time.monotonic() + retry_delay >= deadline:
            raise last_error or UpstreamProtocolError("upstream retry deadline exceeded")
        time.sleep(retry_delay)
    raise last_error or UpstreamProtocolError("upstream request failed without an error")


def send_upstream_chat_payload(
    settings: dict[str, Any],
    payload: dict[str, Any],
    timeout: int = 90,
    *,
    request_id: str = "",
    purpose: str = "chat",
) -> str:
    raise_if_chat_request_cancelled(request_id)
    with upstream_request_slot(purpose, request_id):
        raise_if_chat_request_cancelled(request_id)
        return _send_upstream_chat_payload_uncoordinated(
            settings,
            payload,
            timeout,
            request_id=request_id,
            purpose=purpose,
        )


def extract_upstream_stream_delta(data: Any) -> str:
    """Extract one textual delta from an OpenAI-compatible stream event."""

    if not isinstance(data, dict):
        return ""
    choices = data.get("choices")
    if not isinstance(choices, list):
        return ""
    parts: list[str] = []
    for choice in choices:
        if not isinstance(choice, dict):
            continue
        delta = choice.get("delta")
        if isinstance(delta, dict):
            content = delta.get("content")
            if isinstance(content, str):
                parts.append(content)
            elif isinstance(content, list):
                parts.extend(
                    str(item.get("text") or "")
                    for item in content
                    if isinstance(item, dict) and item.get("type") in {None, "text", "output_text"}
                )
        elif isinstance(choice.get("text"), str):
            parts.append(str(choice["text"]))
    return "".join(parts)


# Public compatibility name points at the only production parser.  Transport
# framing is backend-owned; there is no second strict NDJSON implementation
# that a fallback route can accidentally revive.
LLMEventStreamParser = ModelSemanticStreamParser


def _iter_upstream_chat_stream_uncoordinated(
    settings: dict[str, Any],
    payload: dict[str, Any],
    timeout: int = 90,
    *,
    request_id: str = "",
    purpose: str = "chat_stream",
):
    """Yield provider text deltas while retaining the existing non-stream fallback."""

    headers = {"Content-Type": "application/json", "Accept": "text/event-stream"}
    if settings.get("apiKey"):
        headers["Authorization"] = f"Bearer {settings['apiKey']}"
    safe_request_id = re.sub(r"[^A-Za-z0-9._:-]", "", str(request_id or ""))[:120]
    if safe_request_id:
        headers["X-Amadeus-Request-Id"] = safe_request_id
    active_payload, json_mode_state, json_mode_key = prepare_upstream_json_mode(settings, payload)
    active_payload["stream"] = True
    request = urllib.request.Request(
        chat_endpoint(settings["apiEndpoint"]),
        data=json.dumps(active_payload, ensure_ascii=False).encode("utf-8"),
        headers=headers,
        method="POST",
    )
    started = time.perf_counter()
    stream_deadline = time.monotonic() + max(0.001, float(timeout))
    finish_reasons: list[str] = []
    yielded_non_whitespace = 0
    sse_data_event_count = 0
    sse_json_event_count = 0
    sse_json_decode_error_count = 0
    content_delta_count = 0
    content_delta_chars = 0
    reasoning_delta_count = 0
    reasoning_delta_chars = 0
    reasoning_delta_non_whitespace = 0
    try:
        raise_if_chat_request_cancelled(safe_request_id)
        with open_api_request(
            request,
            settings["apiEndpoint"],
            timeout=timeout,
            connection_attempts=2,
            request_id=safe_request_id,
            purpose=purpose,
            settings=settings,
        ) as response, tracked_upstream_response(safe_request_id, response):
            content_type = str(response.headers.get("Content-Type") or "").lower()
            if "text/event-stream" not in content_type:
                raw = read_complete_response_body(
                    response,
                    deadline=stream_deadline,
                    idle_timeout=None,
                    check_cancelled=lambda: raise_if_chat_request_cancelled(safe_request_id),
                )
                data = json.loads(raw.decode("utf-8"))
                text = extract_upstream_chat_text(data)
                LAST_UPSTREAM_FINISH_REASON.set(upstream_finish_reason(data))
                write_server_log(
                    "upstream_stream_fell_back_to_complete_response",
                    purpose=purpose,
                    requestId=safe_request_id,
                    characters=len(text),
                    elapsedMs=round((time.perf_counter() - started) * 1000),
                )
                yield text
                return
            for raw_line in iter_response_lines(
                response,
                deadline=stream_deadline,
                check_cancelled=lambda: raise_if_chat_request_cancelled(safe_request_id),
            ):
                line = raw_line.decode("utf-8", errors="strict").strip()
                if not line or line.startswith(("event:", "id:", "retry:", ":")):
                    continue
                if line.startswith("data:"):
                    line = line[5:].strip()
                if not line or line == "[DONE]":
                    if line == "[DONE]":
                        break
                    continue
                sse_data_event_count += 1
                try:
                    data = json.loads(line)
                except json.JSONDecodeError:
                    sse_json_decode_error_count += 1
                    continue
                sse_json_event_count += 1
                choices = data.get("choices") if isinstance(data, dict) else []
                for choice in choices if isinstance(choices, list) else []:
                    if not isinstance(choice, dict):
                        continue
                    finish_reason = str(choice.get("finish_reason") or "").strip()
                    if finish_reason and finish_reason not in finish_reasons:
                        finish_reasons.append(finish_reason[:80])
                    delta_payload = choice.get("delta")
                    if isinstance(delta_payload, dict):
                        content_value = delta_payload.get("content")
                        if isinstance(content_value, str):
                            content_delta_count += 1
                            content_delta_chars += len(content_value)
                        reasoning_value = delta_payload.get("reasoning_content")
                        if isinstance(reasoning_value, str):
                            reasoning_delta_count += 1
                            reasoning_delta_chars += len(reasoning_value)
                            reasoning_delta_non_whitespace += len(
                                re.sub(r"\s+", "", reasoning_value)
                            )
                delta = extract_upstream_stream_delta(data)
                if delta:
                    yielded_non_whitespace += len(re.sub(r"\s+", "", delta))
                    yield delta
            if yielded_non_whitespace == 0:
                # No usable content exists. Avoid repeating the JSON-mode
                # failure atomically; preserve the application's JSON contract
                # in the prompt while changing only the provider mode.
                fallback_payload = dict(active_payload)
                fallback_payload["stream"] = False
                if fallback_payload.get("response_format"):
                    if json_mode_state is not None:
                        json_mode_state[json_mode_key] = True
                    fallback_payload = json_mode_fallback_payload(fallback_payload)
                if json_mode_state is not None:
                    fallback_payload["_cognitiveJsonModeState"] = json_mode_state
                empty_stream_reason = (
                    "reasoning_only_without_final_content"
                    if reasoning_delta_non_whitespace > 0
                    else "whitespace_only_content_deltas"
                    if content_delta_chars > 0
                    else "malformed_sse_data"
                    if sse_data_event_count > 0 and sse_json_event_count == 0
                    else "json_events_without_content_delta"
                    if sse_json_event_count > 0
                    else "no_sse_data_events"
                )
                write_server_log(
                    "upstream_empty_stream_atomic_fallback_started",
                    purpose=purpose,
                    requestId=safe_request_id,
                    elapsedMs=round((time.perf_counter() - started) * 1000),
                    emptyStreamReason=empty_stream_reason,
                    sseDataEventCount=sse_data_event_count,
                    sseJsonEventCount=sse_json_event_count,
                    sseJsonDecodeErrorCount=sse_json_decode_error_count,
                    contentDeltaCount=content_delta_count,
                    contentDeltaChars=content_delta_chars,
                    reasoningDeltaCount=reasoning_delta_count,
                    reasoningDeltaChars=reasoning_delta_chars,
                    reasoningDeltaNonWhitespace=reasoning_delta_non_whitespace,
                    finishReasons=finish_reasons,
                )
                raise_if_chat_request_cancelled(safe_request_id)
                fallback_text = send_upstream_chat_payload(
                    settings,
                    fallback_payload,
                    timeout=max(1, min(45, timeout)),
                    request_id=safe_request_id,
                    purpose=f"{purpose}_empty_stream_atomic_fallback",
                )
                yielded_non_whitespace = len(re.sub(r"\s+", "", fallback_text))
                write_server_log(
                    "upstream_empty_stream_atomic_fallback_completed",
                    purpose=purpose,
                    requestId=safe_request_id,
                    characters=len(fallback_text),
                    nonWhitespaceCount=yielded_non_whitespace,
                    elapsedMs=round((time.perf_counter() - started) * 1000),
                )
                yield fallback_text
    except urllib.error.HTTPError as error:
        diagnostics = upstream_http_error_diagnostics(error)
        write_server_log(
            "upstream_stream_http_error",
            purpose=purpose,
            requestId=safe_request_id,
            status=int(error.code),
            retryable=int(error.code) in UPSTREAM_RETRYABLE_STATUS,
            providerErrorCode=diagnostics["providerErrorCode"],
            providerErrorType=diagnostics["providerErrorType"],
            providerMessage=diagnostics["providerMessage"],
            responseBodyLength=diagnostics["responseBodyLength"],
            elapsedMs=round((time.perf_counter() - started) * 1000),
        )
        raise
    except (
        urllib.error.URLError,
        TimeoutError,
        ConnectionError,
        OSError,
        AttributeError,
        ValueError,
        http.client.IncompleteRead,
        UnicodeDecodeError,
    ) as error:
        raise_if_chat_request_cancelled(safe_request_id)
        transport_error = error if isinstance(
            error,
            (urllib.error.URLError, TimeoutError, ConnectionError, OSError),
        ) else ConnectionError(f"upstream stream body interrupted: {type(error).__name__}")
        category = upstream_connection_error_category(transport_error)
        write_server_log(
            "upstream_stream_transport_interrupted",
            purpose=purpose,
            requestId=safe_request_id,
            category=category,
            timeoutKind=(
                str(getattr(error, "timeout_kind", ""))
                if isinstance(error, UpstreamResponseBodyTimeout) else ""
            ),
            afterContent=yielded_non_whitespace > 0,
            errorType=type(error).__name__,
            error=sanitize_provider_error_message(error)[:500],
            elapsedMs=round((time.perf_counter() - started) * 1000),
        )
        # A stream that failed before its first usable delta can be replayed
        # atomically through the already established non-stream path.  Once a
        # delta has been yielded, replaying would duplicate visible speech, so
        # preserve the partial-failure signal instead.  TLS trust failures are
        # configuration/security failures and must never be hidden by retry.
        if yielded_non_whitespace > 0 or category in {
            "tls_certificate_untrusted",
            "connect_timeout",
            "dns_failed",
            "connection_refused",
            "response_body_timeout",
        }:
            raise transport_error from error
        fallback_payload = dict(active_payload)
        fallback_payload["stream"] = False
        if json_mode_state is not None:
            fallback_payload["_cognitiveJsonModeState"] = json_mode_state
        write_server_log(
            "upstream_stream_transport_atomic_fallback_started",
            purpose=purpose,
            requestId=safe_request_id,
            category=category,
            elapsedMs=round((time.perf_counter() - started) * 1000),
        )
        fallback_text = send_upstream_chat_payload(
            settings,
            fallback_payload,
            timeout=max(1, min(45, timeout)),
            request_id=safe_request_id,
            purpose=f"{purpose}_transport_atomic_fallback",
        )
        write_server_log(
            "upstream_stream_transport_atomic_fallback_completed",
            purpose=purpose,
            requestId=safe_request_id,
            characters=len(fallback_text),
            nonWhitespaceCount=len(re.sub(r"\s+", "", fallback_text)),
            elapsedMs=round((time.perf_counter() - started) * 1000),
        )
        yield fallback_text
        return
    LAST_UPSTREAM_FINISH_REASON.set(
        finish_reasons[-1] if finish_reasons else ""
    )
    write_server_log(
        "upstream_stream_completed",
        purpose=purpose,
        requestId=safe_request_id,
        elapsedMs=round((time.perf_counter() - started) * 1000),
        finishReasons=finish_reasons,
    )


def iter_upstream_chat_stream(
    settings: dict[str, Any],
    payload: dict[str, Any],
    timeout: int = 90,
    *,
    request_id: str = "",
    purpose: str = "chat_stream",
):
    raise_if_chat_request_cancelled(request_id)
    with upstream_request_slot(purpose, request_id):
        raise_if_chat_request_cancelled(request_id)
        yield from _iter_upstream_chat_stream_uncoordinated(
            settings,
            payload,
            timeout,
            request_id=request_id,
            purpose=purpose,
        )


def streaming_user_message(body: dict[str, Any]) -> tuple[str, list[dict[str, Any]]]:
    messages = body.get("messages") if isinstance(body.get("messages"), list) else []
    successive = [
        str(item).strip()
        for item in (body.get("userMessages") if isinstance(body.get("userMessages"), list) else [])
        if str(item).strip()
    ]
    return (
        "\n".join(successive) if successive else str(body.get("userMessage") or "").strip(),
        [item for item in messages if isinstance(item, dict)],
    )


def turn_capability_obligations(
    tool_requests: Sequence[dict[str, Any]],
    *,
    has_attachments: bool = False,
    model_tool_escalation: bool = False,
) -> tuple[CapabilityObligation, ...]:
    """Translate concrete, already-grounded needs into execution obligations.

    Advisory preflight candidates deliberately never enter this function.  A
    capability becomes mandatory only because the user explicitly requested
    an action, the current turn binds an attachment, or the same turn's model
    produced a structured tool escalation before any answer was committed.
    """

    obligations: list[CapabilityObligation] = []
    for item in tool_requests:
        if not isinstance(item, dict):
            continue
        name = str(item.get("name") or "").strip()
        if not name:
            continue
        args = item.get("args") if isinstance(item.get("args"), dict) else {}
        selection = (
            item.get("selection") if isinstance(item.get("selection"), dict) else {}
        )
        if args.get("browserTargetResolution"):
            source = "browser_target_resolution"
        elif model_tool_escalation or str(selection.get("source") or "").startswith(
            "fast_stream"
        ):
            source = "model_tool_escalation"
        else:
            source = "explicit_user_request"
        obligations.append(CapabilityObligation(
            capability=name,
            source=source,
            reason=str(item.get("reason") or "grounded capability requirement"),
        ))
    if has_attachments:
        obligations.append(CapabilityObligation(
            capability="read_attachment",
            source="bound_attachment",
            reason="the current turn contains an attachment",
        ))
    return tuple(obligations)


def finalize_turn_execution_plan(
    body: dict[str, Any],
    *,
    user_message: str,
    decision: ResearchDecision,
    preflight: TurnPreflight,
    tool_requests: Sequence[dict[str, Any]],
    settings: dict[str, Any],
    has_attachments: bool = False,
    model_research_escalation: bool = False,
    model_tool_escalation: bool = False,
    evidence_recovery_escalation: bool = False,
) -> TurnExecutionPlan:
    """Return the one immutable authority record consumed by every route.

    Routing creates the plan once.  Normal execution reuses it verbatim;
    structured same-turn model escalation is the only reason to issue a new
    revision.  This prevents fallback/atomic paths from independently turning
    advisory hints into mandatory tools or web research.
    """

    existing = execution_plan_from_dict(
        body.get("_turnExecutionPlan")
        if isinstance(body.get("_turnExecutionPlan"), dict)
        else None
    )
    escalation = bool(
        model_research_escalation
        or model_tool_escalation
        or evidence_recovery_escalation
    )
    if existing is not None and not escalation:
        return existing

    reasons = list(decision.reasons)
    if model_research_escalation:
        reasons.append("model_research_escalation")
    if evidence_recovery_escalation:
        reasons.append("grounded_claim_gate_evidence_gap")
    hints = list(capability_hints_from_preflight(preflight))
    obligations = list(turn_capability_obligations(
        tool_requests,
        has_attachments=has_attachments,
        model_tool_escalation=model_tool_escalation,
    ))
    obligated_capabilities = {item.capability for item in obligations}
    for capability_name in preflight.mandatory_capabilities:
        if capability_name in obligated_capabilities:
            continue
        obligations.append(CapabilityObligation(
            capability=capability_name,
            source="explicit_user_request",
            reason="semantic preflight marked this capability as mandatory",
        ))
        obligated_capabilities.add(capability_name)
    if (model_research_escalation or evidence_recovery_escalation) and not any(
        item.capability in {"web_search", "read_web_page"}
        for item in obligations
    ):
        obligations.append(CapabilityObligation(
            capability="web_search",
            source=(
                "model_research_escalation"
                if model_research_escalation else "grounded_claim_gate"
            ),
            reason="the same turn identified an external evidence gap",
        ))
    plan = TurnExecutionPlanner.finalize(
        turn_id=str(body.get("requestId") or ""),
        proposed_research_policy=(
            "required"
            if model_research_escalation or evidence_recovery_escalation
            else decision.policy
        ),
        research_reasons=tuple(dict.fromkeys(reasons)),
        obligations=obligations,
        hints=hints,
        web_permission=bool(settings.get("permissionWebSearch")),
        revision=(
            max(existing.revision + 1, decision.plan_revision)
            if existing is not None else max(1, decision.plan_revision)
        ),
    )
    body["_turnExecutionPlan"] = plan.to_dict()
    return plan


def classify_streaming_chat_route(
    body: dict[str, Any],
    settings: dict[str, Any],
    *,
    preflight: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Choose a conservative fast/tool/strict/legacy route before any user-visible speech."""

    user_message, messages = streaming_user_message(body)
    prepared_action_turn = body_prepared_action_turn(
        body,
        user_message,
        request_id=str(body.get("requestId") or ""),
    )
    context_resolution = contextual_reference_resolution(
        user_message,
        messages,
        request_id=str(body.get("requestId") or ""),
        current_artifacts=current_turn_context_artifacts(body),
        resolved_task=current_task_semantic_request(body, user_message),
        context_state=frozen_turn_context_state(body),
        model_owned=bool(cognitive_turn_state(body)),
    )
    body["_contextResolution"] = context_resolution
    body["_discourseLedger"] = context_resolution.get("referenceLedger", {})
    prepared_action_turn = apply_contextual_research_subject(
        prepared_action_turn,
        context_resolution,
    )
    body["_preparedActionTurn"] = prepared_action_turn
    interpretation, policy, contract = turn_contract_context(
        user_message,
        prepared_action_turn,
        task_body=body,
    )
    prepared_action_turn, research_decision, capability = (
        enrich_prepared_turn_with_research(
            prepared_action_turn,
            policy,
            contract,
            settings,
            interpretation=interpretation,
        )
    )
    tool_preflight = body_tool_preflight(
        body,
        user_message,
        messages,
        reply_mode=policy.reply_mode,
        speech_act=interpretation.primary_speech_act,
    )
    local_research_decision = reconcile_research_with_tool_preflight(
        research_decision,
        tool_preflight,
        user_message,
    )
    if local_research_decision != research_decision:
        research_decision = local_research_decision
        prepared_action_turn, research_decision = synchronize_prepared_epistemic_plan(
            prepared_action_turn,
            research_decision,
        )
        capability = capability_envelope(
            policy,
            research_decision,
            web_permission=bool(settings.get("permissionWebSearch")),
        )
    prepared_action_turn, research_decision, capability = (
        reconcile_preanswer_research_route(
            settings,
            user_message,
            prepared_action_turn,
            research_decision,
            policy,
            body,
            request_id=str(body.get("requestId") or ""),
        )
    )
    capability = capability_with_tool_preflight(
        capability,
        tool_preflight,
        settings,
    )
    prepared_action_turn = replace(
        prepared_action_turn,
        capability_envelope=capability.to_dict(),
    )
    body["_preparedActionTurn"] = prepared_action_turn
    persist_prepared_turn(prepared_action_turn)
    write_tool_preflight_log(
        str(body.get("requestId") or ""),
        tool_preflight,
        capability,
    )
    shared_route_context = {
        "preparedTurn": prepared_action_turn.to_dict(),
        "interpretation": interpretation.to_dict(),
        "turnPolicy": policy.to_dict(),
        "turnContract": contract.to_dict(),
        "researchDecision": research_decision.to_dict(),
        "capabilityEnvelope": capability.to_dict(),
    }
    relationship = read_relationship_state()
    action = str((preflight or {}).get("action") or "")
    if action in {"locked", "cold"} or relationship.get("dignityLocked") or relationship.get("coldShoulder"):
        return {
            "route": "strict_boundary",
            "reason": action or "saved_boundary_state",
            "toolRequests": [],
            **shared_route_context,
        }
    if not configured(settings):
        return {
            "route": "fallback_legacy",
            "reason": "model_not_configured",
            "toolRequests": [],
            **shared_route_context,
        }
    if cognitive_turn_state(body) and not current_turn_context_artifacts(body):
        return {
            "route": "fast_chat",
            "reason": "cognitive_semantic_query_loop",
            "toolRequests": [],
            **shared_route_context,
        }
    if is_time_query(user_message):
        return {
            "route": "fallback_legacy",
            "reason": "local_time_response",
            "toolRequests": [],
            **shared_route_context,
        }
    attachments = current_turn_context_artifacts(body)
    tool_requests = infer_agent_tool_requests(
        user_message,
        messages,
        context_resolution,
        prepared_action_turn,
        body.get("_todoReconciliation"),
    )
    tool_requests = task_bound_tool_requests(body, tool_requests)
    execution_plan = finalize_turn_execution_plan(
        body,
        user_message=user_message,
        decision=research_decision,
        preflight=tool_preflight,
        tool_requests=tool_requests,
        settings=settings,
        has_attachments=bool(attachments),
    )
    if execution_plan.research_policy != research_decision.policy:
        research_decision = replace(
            research_decision,
            policy=execution_plan.research_policy,
            reasons=tuple(dict.fromkeys((
                *research_decision.reasons,
                "turn_execution_plan_finalized",
            ))),
            plan_revision=research_decision.plan_revision + 1,
        )
        prepared_action_turn, research_decision = synchronize_prepared_epistemic_plan(
            prepared_action_turn,
            research_decision,
        )
    capability = capability_envelope(
        policy,
        research_decision,
        web_permission=bool(settings.get("permissionWebSearch")),
    )
    capability = capability_with_tool_preflight(
        capability,
        tool_preflight,
        settings,
        extra_tool_ids=[
            str(item.get("name") or "")
            for item in tool_requests
            if isinstance(item, dict)
        ],
    )
    capability = replace(
        capability,
        research_policy=execution_plan.research_policy,
        required_tools=execution_plan.required_capabilities,
        max_tool_rounds=execution_plan.max_tool_rounds,
        tool_policy=(
            "required" if execution_plan.required_capabilities else "model_decides"
        ),
    )
    prepared_action_turn = replace(
        prepared_action_turn,
        research_decision=research_decision.to_dict(),
        capability_envelope=capability.to_dict(),
    )
    body["_preparedActionTurn"] = prepared_action_turn
    persist_prepared_turn(prepared_action_turn)
    write_server_log(
        "turn_execution_plan_finalized",
        requestId=str(body.get("requestId") or ""),
        executionPlan=execution_plan.to_dict(),
    )
    shared_route_context.update({
        "preparedTurn": prepared_action_turn.to_dict(),
        "researchDecision": research_decision.to_dict(),
        "capabilityEnvelope": capability.to_dict(),
        "executionPlan": execution_plan.to_dict(),
    })

    if execution_plan.research_policy == "forbidden":
        tool_requests = [
            item
            for item in tool_requests
            if str(item.get("name") or "") not in {"web_search", "read_web_page"}
        ]
    elif execution_plan.research_policy == "required" and not any(
        str(item.get("name") or "") in {"web_search", "read_web_page"}
        for item in tool_requests
    ):
        tool_requests.append({
            "name": "web_search",
            "args": {
                "query": (
                    str(body.get("_preAnswerResearchQuery") or "").strip()
                    or fallback_web_research_query(
                        user_message,
                        context_resolution,
                        messages,
                    )
                ),
                "freshness": web_search_freshness(user_message),
                "researchDecision": research_decision.to_dict(),
            },
            "reason": "unified research policy requires public evidence",
        })
    if is_agent_file_action_query(user_message):
        return {
            "route": "tool_gated",
            "reason": "explicit_agent_file_action",
            "toolRequests": (
                tool_requests
                or [{"name": "file_operation", "args": {}}]
            ),
            **shared_route_context,
        }
    if attachments:
        return {
            "route": "tool_gated",
            "reason": "attachments_require_evidence",
            "toolRequests": tool_requests or [{"name": "read_attachment", "args": {}}],
            **shared_route_context,
        }
    if tool_requests:
        return {
            "route": "tool_gated",
            "reason": "tool_evidence_required",
            "toolRequests": tool_requests,
            **shared_route_context,
        }
    if prepared_action_turn.route in {
        "external_action",
        "external_action_needs_target",
        "research_plus_external_action",
    }:
        return {
            "route": "tool_gated",
            "reason": "explicit_external_action_requires_grounding",
            "toolRequests": [],
            **shared_route_context,
        }
    return {
        "route": "fast_chat",
        "reason": "unified_semantic_query_loop",
        "toolRequests": [],
        **shared_route_context,
    }


def build_fast_stream_messages(
    body: dict[str, Any],
    settings: dict[str, Any],
    user_message: str,
    messages: list[dict[str, Any]],
    turn_policy: TurnPolicy | None = None,
    request_id: str = "",
    interpretation: UtteranceInterpretation | None = None,
    turn_contract: TurnContract | None = None,
    persona_snapshot: PersonaContextSnapshot | None = None,
) -> list[dict[str, str]]:
    prepared = body_prepared_action_turn(
        body,
        user_message,
        request_id=request_id,
    )
    active_interpretation = interpretation or utterance_interpretation_from_prepared(
        prepared
    )
    active_interpretation = bind_resolved_task_interpretation(active_interpretation, body)
    active_policy = turn_policy or choose_turn_policy(
        user_message,
        interpretation=active_interpretation,
    )
    active_contract = turn_contract or build_turn_contract(
        active_interpretation,
        active_policy,
    )
    active_decision = (
        ResearchDecision.from_dict(prepared.research_decision)
        if prepared.research_decision
        else deterministic_research_decision(active_interpretation)
    )
    active_capability = (
        CapabilityEnvelope.from_dict(prepared.capability_envelope)
        if prepared.capability_envelope
        else capability_envelope(
            active_policy,
            active_decision,
            web_permission=bool(settings.get("permissionWebSearch")),
        )
    )
    active_tool_preflight = (
        body.get("_toolPreflight")
        if isinstance(body.get("_toolPreflight"), TurnPreflight)
        else build_turn_preflight(
            user_message,
            messages,
            reply_mode=active_policy.reply_mode,
            speech_act=active_interpretation.primary_speech_act,
        )
    )
    if cognitive_turn_state(body) and not current_turn_context_artifacts(body):
        active_tool_preflight = replace(
            active_tool_preflight, mandatory_capabilities=(),
            perception=replace(active_tool_preflight.perception, required=False),
            tool_escalation_allowed=True,
        )
        active_capability = replace(active_capability, required_tools=(), tool_policy="model_decides")
    supplied_memories = (
        body.get("memories") if isinstance(body.get("memories"), list) else []
    )
    memories, memory_records, memory_need = retrieve_turn_memories(
        settings,
        supplied_memories,
        user_message,
        messages,
        limit=active_policy.memory_top_k,
        cognitive_state=cognitive_turn_state(body),
        context_state=frozen_turn_context_state(body),
    )
    memories, memory_records = bind_cognitive_memories(body, memories, memory_records)
    relationship_state = frozen_turn_relationship_state(body) or read_relationship_state()
    context_resolution = contextual_reference_resolution(
        user_message,
        messages,
        request_id=request_id,
        current_artifacts=current_turn_context_artifacts(body),
        resolved_task=current_task_semantic_request(body, user_message),
        context_state=frozen_turn_context_state(body),
        model_owned=bool(cognitive_turn_state(body)),
    )
    body["_contextResolution"] = context_resolution
    body["_discourseLedger"] = context_resolution.get("referenceLedger", {})
    identity_context = identity_grounding_prompt(user_message)
    attribution = speaker_attribution_evidence_prompt(messages, user_message)
    pending_question = pending_assistant_question_prompt(messages, user_message)
    todo_pending = pending_todo_action_prompt()
    schedule_state = current_schedule_workflow_prompt()
    active_persona_snapshot = persona_snapshot or build_persona_context_snapshot(
        user_message,
        messages,
        context_resolution,
        relationship_state,
        cognitive_body=body,
    )
    deep_persona_prompt = active_persona_snapshot.prompt_text
    explicit_reply_context = body_reply_context_prompt(body)
    explicit_context_control = body_context_control_prompt(body)
    result: list[dict[str, str]] = [
        {"role": "system", "content": active_persona_snapshot.system_prompt},
        {"role": "system", "content": NATURAL_DIALOGUE_STYLE},
        {"role": "system", "content": deep_persona_prompt},
        {"role": "system", "content": policy_prompt(active_policy)},
        {"role": "system", "content": SPEAKER_ATTRIBUTION_RULE},
        {"role": "system", "content": TECHNICAL_ACCURACY_RULE},
        {"role": "system", "content": EMOTION_SELECTION_RULE},
        {"role": "system", "content": AMADEUS_TOOL_RULE},
        {"role": "system", "content": SCHEDULE_INTENT_PROMPT},
        {"role": "system", "content": tool_preflight_prompt(
            active_tool_preflight,
            active_capability,
        )},
        *([{"role": "system", "content": todo_reconciliation_prompt(
            body.get("_todoReconciliation")
        )}] if todo_reconciliation_prompt(body.get("_todoReconciliation")) and not cognitive_turn_state(body) else []),
        {"role": "system", "content": relationship_context_prompt(relationship_state)},
        {"role": "system", "content": dignity_boundary_context_prompt(
            relationship_state,
            body.get("_dignityAssessment") if isinstance(body.get("_dignityAssessment"), dict) else None,
        )},
        {"role": "system", "content": transition_style_prompt(messages)},
        {"role": "system", "content": permission_context_prompt(settings, body=body)},
        {"role": "system", "content": retrieved_memory_prompt(
            memories,
            memory_records,
            memory_need,
            cognitive_state=cognitive_turn_state(body),
        )},
        {"role": "system", "content": conversation_context_prompt(
            user_message, active_policy, memory_need, context_resolution,
            context_state=frozen_turn_context_state(body),
            cognitive_state=cognitive_turn_state(body),
        )},
        {"role": "system", "content": session_temporal_context_prompt(user_message, settings=settings)},
    ]
    if explicit_context_control:
        result.append({"role": "system", "content": explicit_context_control})
    if explicit_reply_context:
        result.append({"role": "system", "content": explicit_reply_context})
    if attribution:
        result.append({"role": "system", "content": attribution})
    adjacent_messages = (
        messages
        if cognitive_turn_state(body) or current_runtime_has_user_turn() or message_needs_recent_context(user_message)
        else []
    )
    result.extend(conversation_history_messages(body, adjacent_messages[-active_policy.recent_message_limit:]))
    if identity_context:
        result.append({"role": "system", "content": identity_context})
    # Keep the exact original-reaction unit contract in hybrid persona mode too.
    nickname_prompt = nickname_reaction_prompt(user_message, request_id)
    if nickname_prompt:
        result.append({"role": "system", "content": nickname_prompt})
    motif_prompt = (
        ""
        if active_persona_snapshot.uses_hybrid_provider_context
        else canon_style_motif_prompt(user_message)
    )
    if motif_prompt:
        result.append({"role": "system", "content": motif_prompt})
    result.append({
        "role": "system",
        "content": immediate_context_prompt(
            messages,
            user_message,
            active_policy,
            context_state=frozen_turn_context_state(body),
            cognitive_state=cognitive_turn_state(body),
        ),
    })
    if pending_question:
        result.append({"role": "system", "content": pending_question})
    if todo_pending:
        result.append({"role": "system", "content": todo_pending})
    if schedule_state:
        result.append({"role": "system", "content": schedule_state})
    contextual_prompt = contextual_reference_prompt(context_resolution)
    if contextual_prompt:
        result.append({"role": "system", "content": contextual_prompt})
    result.append({
        "role": "system",
        "content": turn_contract_prompt(active_interpretation, active_contract),
    })
    fact_policy_prompt = claim_level_fact_policy_prompt(prepared)
    if fact_policy_prompt:
        result.append({"role": "system", "content": fact_policy_prompt})
    result.append({
        "role": "system",
        "content": (
            "[Capability Envelope：与回复长度相互独立]\n"
            + json.dumps({
                "researchDecision": active_decision.to_dict(),
                "capabilityEnvelope": active_capability.to_dict(),
            }, ensure_ascii=False)
            + "\nresearch_policy=allowed 且知识信心不足时必须输出 research_escalation，"
              "不能把不确定的外部事实写成 FinalAnswer。research_policy=forbidden 时不得联网升级。"
        ),
    })
    attachment_binding = current_turn_attachment_binding_prompt(body)
    if attachment_binding:
        result.append({"role": "system", "content": attachment_binding})
    # Keep the wire contract adjacent to the user turn.  Providers give later
    # system messages more practical salience when many independent context
    # blocks are present; placing it here reduces plain-text protocol drift.
    result.append({"role": "system", "content": (
        COGNITIVE_DIALOGUE_REPLY_RULE if cognitive_turn_state(body) else UTTERANCE_STREAM_REPLY_RULE
    )})
    cognition = cognitive_turn_prompt(body)
    if cognition:
        body["_cognitiveOutcomeRequired"] = True
        result.append({"role": "system", "content": cognition})
    result.append({"role": "user", "content": user_message})
    return pin_reply_context(result, body.get("_turnContextSnapshot"))


def fast_stream_token_budget(turn_policy: TurnPolicy) -> int:
    """Reserve room for bilingual JSON envelopes without relaxing reply length policy."""

    content_budget = max(1, int(turn_policy.max_output_tokens))
    return min(6_000, max(content_budget + 480, math.ceil(content_budget * 1.5)))


def normalize_streaming_utterance(
    payload: dict[str, Any],
    settings: dict[str, Any],
    *,
    sequence: int,
    user_message: str = "",
    request_id: str = "",
    turn_contract: TurnContract | None = None,
    first_visible: bool = False,
    persona_snapshot: PersonaContextSnapshot | None = None,
) -> dict[str, Any]:
    text_zh = re.sub(r"\s+", " ", str(payload.get("textZh") or "")).strip()
    spoken_ja = re.sub(r"\s+", " ", str(payload.get("spokenTextJa") or "")).strip()
    speech_profile = speech_language_profile(settings)
    requires_japanese_track = speech_profile["speechLanguage"] == "ja-JP"
    if not text_zh:
        raise UpstreamProtocolError("streaming utterance requires non-empty Chinese")
    if not spoken_ja and requires_japanese_track and configured(settings):
        try:
            repaired = repair_dialogue_fields_once(
                settings,
                {
                    "reply": text_zh,
                    "spokenTextJa": "",
                    "emotion": payload.get("emotion") or "neutral",
                    "memoryUpdates": [],
                },
                {
                    "missingFields": ["spokenTextJa"],
                    "invalidFields": [],
                },
                user_message=user_message,
                recent_messages=[],
                relationship_state=read_relationship_state(),
                request_id=request_id,
                persona_snapshot=persona_snapshot,
            )
            spoken_ja = re.sub(
                r"\s+", " ", str(repaired.get("spokenTextJa") or "")
            ).strip()
            write_server_log(
                "semantic_stream_spoken_ja_repaired",
                requestId=request_id,
                frozenChineseCharacters=len(text_zh),
            )
        except Exception as repair_error:
            write_server_log(
                "semantic_stream_spoken_ja_repair_failed",
                requestId=request_id,
                errorType=type(repair_error).__name__,
                error=str(repair_error)[:500],
            )
    if not spoken_ja and requires_japanese_track:
        raise UpstreamProtocolError(
            "streaming utterance is missing Japanese after field-only repair"
        )
    speech_text = text_zh if not requires_japanese_track else spoken_ja
    if len(text_zh) > 900 or len(speech_text) > 1400:
        raise UpstreamProtocolError("streaming utterance exceeded the sentence-level size limit")
    if re.search(r"https?://|```|toolRequests|memoryUpdates|turn_(?:header|trailer)", text_zh + speech_text, re.I):
        raise UpstreamProtocolError("streaming utterance exposed internal or non-speakable content")
    if re.search(r"(?:但是|不过|因为|所以|而且|如果|除非|虽然|以及|然后|つまり|だから|けれど)\s*$", text_zh + speech_text):
        raise UpstreamProtocolError("streaming utterance ended as an obvious fragment")
    if requires_japanese_track:
        size_ratio = len(spoken_ja) / max(1, len(text_zh))
        if size_ratio < 0.22 or size_ratio > 5.2:
            raise UpstreamProtocolError("streaming utterance bilingual size ratio is implausible")
    covers_value = payload.get("covers")
    covers = (
        tuple(str(item).strip() for item in covers_value if str(item).strip())
        if isinstance(covers_value, list)
        else ()
    )
    if first_visible and turn_contract is not None:
        # Semantic Stream V2 deliberately does not ask the model to echo
        # backend contract identifiers.  Missing metadata is completed here;
        # actual answer completeness is still checked by the final contract
        # validator against the natural-language reply.
        if not covers:
            covers = tuple(turn_contract.first_visible_must_cover)
        missing = [
            item
            for item in turn_contract.first_visible_must_cover
            if item not in covers
        ]
        if missing:
            raise UpstreamProtocolError(
                "first visible utterance does not cover Turn Contract: "
                + ",".join(missing)
            )
        if payload.get("standalone", True) is not True:
            raise UpstreamProtocolError(
                "first visible utterance is not independently complete"
            )
    normalized = normalize_model_reply({
        "reply": text_zh,
        "spokenTextJa": spoken_ja,
        "emotion": payload.get("emotion"),
        "emotionIntensity": payload.get("emotionIntensity"),
        "gesture": payload.get("gesture"),
        "voiceStyle": payload.get("voiceStyle"),
        "voiceTone": payload.get("voiceTone"),
        "voiceIntensity": payload.get("voiceIntensity"),
        "speechPace": payload.get("speechPace"),
        "speechSpeed": payload.get("speechSpeed"),
        "deliveryMode": payload.get("deliveryMode"),
        "blushIntensity": payload.get("blushIntensity"),
        "eyeContact": payload.get("eyeContact"),
        "gazeX": payload.get("gazeX"),
        "gazeY": payload.get("gazeY"),
        "tension": payload.get("tension"),
        "memoryUpdates": [],
        "speechSegmentCount": (
            valid_speech_segment_count(payload.get("speechSegmentCount")) or 1
        ),
    }, settings=settings)
    normalized = enforce_nickname_reaction_grounding(
        user_message,
        normalized,
        reaction_key=request_id,
        persona_snapshot=persona_snapshot,
        is_first_visible=first_visible or sequence == 1,
    )
    return {
        "utteranceId": str(payload.get("utteranceId") or f"u{sequence}")[:80],
        "textZh": str(normalized.get("reply") or text_zh),
        "spokenTextJa": str(normalized.get("spokenTextJa") or spoken_ja),
        "speechText": str(normalized.get("speechText") or speech_text),
        "speechLanguage": str(normalized.get("speechLanguage") or speech_profile["speechLanguage"]),
        "originalAudio": (
            dict(normalized["originalAudio"])
            if isinstance(normalized.get("originalAudio"), dict)
            else None
        ),
        "originalReactionId": str(normalized.get("nicknameReactionId") or ""),
        "nicknameReactionOriginalAudioBound": bool(
            normalized.get("nicknameReactionOriginalAudioBound")
        ),
        "nicknameReactionGroundingViolation": bool(
            normalized.get("nicknameReactionGroundingViolation")
        ),
        "nicknameReactionEmotionLocked": bool(
            normalized.get("nicknameReactionEmotionLocked")
        ),
        "boundaryAfter": (
            str(payload.get("boundaryAfter") or "continue")
            if str(payload.get("boundaryAfter") or "continue")
            in {"continue", "micro_pause", "phrase_pause", "turn_pause"}
            else "continue"
        ),
        "covers": list(dict.fromkeys(covers)),
        "standalone": payload.get("standalone", True) is True,
        "semanticRecoveryMode": str(payload.get("semanticRecoveryMode") or ""),
        "plainTextSalvaged": bool(payload.get("plainTextSalvaged")),
        "streamProtocolRecovered": bool(payload.get("streamProtocolRecovered")),
        "dialogueFieldRepairSucceeded": bool(
            payload.get("dialogueFieldRepairSucceeded")
        ),
        "dialogueFieldRepairFields": (
            list(payload.get("dialogueFieldRepairFields"))
            if isinstance(payload.get("dialogueFieldRepairFields"), list)
            else []
        ),
        "emotionMissingFromModel": bool(
            payload.get("emotionMissingFromModel")
            or normalized.get("emotionMissingFromModel")
        ),
        "emotionLabelRecoveredByModel": bool(
            payload.get("emotionLabelRecoveredByModel")
        ),
        "speechSegmentCount": int(normalized.get("speechSegmentCount") or 1),
        "speechSegmentCountSource": str(
            payload.get("speechSegmentCountSource") or "stream_utterance"
        ),
        "visibleSegmentationSource": str(
            payload.get("visibleSegmentationSource") or ""
        ),
        "visibleSegmentCountBefore": clamp_int(
            payload.get("visibleSegmentCountBefore"),
            1,
            MAX_SPEECH_UNITS,
            int(normalized.get("speechSegmentCount") or 1),
        ),
        "visibleSegmentCountAfter": clamp_int(
            payload.get("visibleSegmentCountAfter"),
            1,
            MAX_SPEECH_UNITS,
            1,
        ),
        **{
            key: normalized.get(key)
            for key in (
                "emotion", "emotionIntensity", "gesture", "voiceStyle", "voiceTone",
                "voiceIntensity", "speechPace", "speechSpeed", "deliveryMode",
                "blushIntensity", "eyeContact", "gazeX", "gazeY", "tension",
            )
        },
    }


def recover_atomic_fast_stream_utterance(
    raw_text: str,
    settings: dict[str, Any],
    *,
    user_message: str,
    request_id: str,
    turn_contract: TurnContract,
    persona_snapshot: PersonaContextSnapshot | None = None,
    recent_messages: list[dict[str, Any]] | None = None,
    relationship_state: dict[str, Any] | None = None,
) -> list[dict[str, Any]] | None:
    """Recover aligned visible utterances from the same provider response.

    Recovery has no routing authority: it cannot choose tools, research, or a
    new persona pass.  Accepted Chinese prose is frozen.  Missing Japanese is
    repaired independently; missing delivery boundaries use a deterministic
    punctuation fallback first, then an isolated speech-plan repair.  Metadata
    loss alone must never cause the accepted answer to be generated again.
    """

    recovery = recover_semantic_output(
        str(raw_text or ""),
        allow_plain_text=ARCHITECTURE_FEATURES.plain_text_salvage_enabled,
    )
    if not ARCHITECTURE_FEATURES.semantic_recovery_v2_enabled or not recovery.accepted:
        return None
    update_chat_request_progress(
        request_id,
        "semantic-recovery",
        "正在从同一次模型响应中恢复完整语义",
    )

    recovered_payload = dict(recovery.payload)
    frozen_reply = str(
        recovered_payload.get("reply")
        or recovered_payload.get("textZh")
        or ""
    ).strip()
    spoken_ja = str(
        recovered_payload.get("spokenTextJa")
        or recovered_payload.get("spoken_text_ja")
        or ""
    ).strip()
    raw_emotion = str(
        recovered_payload.get("emotion")
        or recovered_payload.get("expression")
        or ""
    ).strip()
    raw_segment_count = valid_speech_segment_count(
        recovered_payload.get("speechSegmentCount")
        if recovered_payload.get("speechSegmentCount") is not None
        else recovered_payload.get("speech_segment_count")
    )
    if not frozen_reply:
        return None

    speech_profile = speech_language_profile(settings)
    requires_spoken = speech_profile["speechLanguage"] == "ja-JP"
    active_recent_messages = list(recent_messages or [])
    active_relationship_state = (
        dict(relationship_state)
        if isinstance(relationship_state, dict)
        else read_relationship_state()
    )
    missing_fields: list[str] = []
    if requires_spoken and not spoken_ja:
        missing_fields.append("spokenTextJa")
    recovered_units = recovered_payload.get("_modelSpeechUnits")
    repaired: dict[str, Any] = {
        **recovered_payload,
        "reply": frozen_reply,
        "textZh": frozen_reply,
        "spokenTextJa": spoken_ja,
        "emotion": raw_emotion if raw_emotion in ALLOWED_EMOTIONS else "neutral",
        "spokenTextJaMissingFromModel": requires_spoken and not bool(spoken_ja),
        "emotionMissingFromModel": raw_emotion not in ALLOWED_EMOTIONS,
        "emotionResolvedLocally": False,
        "speechSegmentCount": raw_segment_count,
        "speechSegmentCountMissingFromModel": raw_segment_count is None,
    }
    if isinstance(recovered_units, list):
        repaired["_modelSpeechUnits"] = recovered_units
    if missing_fields:
        if (
            not ARCHITECTURE_FEATURES.field_level_repair_enabled
            or not configured(settings)
        ):
            return None
        try:
            update_chat_request_progress(
                request_id,
                "field-repair",
                "正文已冻结，正在补齐日语发声字段",
            )
            repaired = repair_dialogue_fields_once(
                settings,
                repaired,
                {
                    "missingFields": missing_fields,
                    "invalidFields": [],
                },
                user_message=user_message,
                recent_messages=active_recent_messages,
                relationship_state=active_relationship_state,
                request_id=request_id,
                persona_snapshot=persona_snapshot,
            )
        except Exception as repair_error:
            write_server_log(
                "semantic_recovery_field_repair_failed",
                requestId=request_id,
                mode=recovery.mode,
                frozenReplyFingerprint=runtime_fingerprint(
                    frozen_reply, length=32
                ),
                errorType=type(repair_error).__name__,
                error=str(repair_error)[:500],
            )
            return None
        if str(repaired.get("reply") or "").strip() != frozen_reply:
            write_server_log(
                "semantic_recovery_frozen_reply_violation",
                requestId=request_id,
                mode=recovery.mode,
            )
            return None

    if repaired.get("emotionMissingFromModel"):
        if configured(settings):
            try:
                update_chat_request_progress(
                    request_id,
                    "emotion-repair",
                    "正文已冻结，正在补齐表情与语音情绪",
                )
                repaired = repair_frozen_reply_emotion_once(
                    settings,
                    repaired,
                    user_message=user_message,
                    recent_messages=active_recent_messages,
                    relationship_state=active_relationship_state,
                    request_id=request_id,
                )
                repaired["emotionRecoveryAttempted"] = True
                repaired["emotionRecoverySucceeded"] = True
            except Exception as repair_error:
                repaired["emotionResolvedLocally"] = True
                repaired["emotionRecoveryAttempted"] = True
                repaired["emotionRecoverySucceeded"] = False
                repaired["emotionUnavailableReason"] = "emotion_label_recovery_failed"
                write_server_log(
                    "semantic_recovery_emotion_repair_failed",
                    requestId=request_id,
                    recoveryMode=recovery.mode,
                    errorType=type(repair_error).__name__,
                    error=str(repair_error)[:500],
                )
        else:
            repaired["emotionResolvedLocally"] = True
            repaired["emotionUnavailableReason"] = "model_not_configured"

    repaired_spoken = str(repaired.get("spokenTextJa") or "").strip()
    repaired_units = normalize_speech_plan_units(
        repaired.get("_modelSpeechUnits"),
        frozen_reply=frozen_reply,
        frozen_spoken=repaired_spoken,
        require_spoken=requires_spoken,
    )
    if repaired_units:
        repaired["speechSegmentCountSource"] = str(
            repaired.get("speechSegmentCountSource") or "recovered_model_semantic_units"
        )

    if not repaired_units:
        repaired_units = punctuation_fallback_speech_units(
            frozen_reply,
            repaired_spoken,
        )
        if repaired_units:
            repaired["speechSegmentCountSource"] = "punctuation_plain_text_fallback"
            write_server_log(
                "semantic_recovery_punctuation_plan",
                requestId=request_id,
                recoveryMode=recovery.mode,
                unitCount=len(repaired_units),
                ellipsisIsBoundary=False,
            )

    if (
        not repaired_units
        and ARCHITECTURE_FEATURES.field_level_repair_enabled
        and configured(settings)
    ):
        try:
            update_chat_request_progress(
                request_id,
                "speech-plan-repair",
                "正文已冻结，正在补齐语音分段计划",
            )
            repaired_units = repair_speech_plan_once(
                settings,
                {
                    **repaired,
                    "speechLanguage": speech_profile["speechLanguage"],
                },
                request_id=request_id,
                persona_snapshot=persona_snapshot,
            )
            repaired["speechPlanRepairAttempted"] = True
            repaired["speechPlanRepairSucceeded"] = True
            repaired["speechSegmentCountSource"] = "speech_plan_field_repair"
        except Exception as repair_error:
            repaired["speechPlanRepairAttempted"] = True
            repaired["speechPlanRepairSucceeded"] = False
            write_server_log(
                "semantic_recovery_speech_plan_repair_failed",
                requestId=request_id,
                recoveryMode=recovery.mode,
                errorType=type(repair_error).__name__,
                error=str(repair_error)[:500],
            )

    if not repaired_units:
        tracks_are_complete = bool(
            frozen_reply
            and (not requires_spoken or repaired_spoken)
            and not semantic_unit_has_weak_boundary(frozen_reply)
            and (
                not requires_spoken
                or not semantic_unit_has_weak_boundary(repaired_spoken)
            )
        )
        if not tracks_are_complete:
            write_server_log(
                "semantic_recovery_units_rejected",
                requestId=request_id,
                recoveryMode=recovery.mode,
                chineseCharacters=len(re.sub(r"\s+", "", frozen_reply)),
                japaneseCharacters=len(re.sub(r"\s+", "", repaired_spoken)),
                reason="accepted_speech_track_is_incomplete",
            )
            return None
        repaired_units = [{
            "textZh": frozen_reply,
            "spokenTextJa": repaired_spoken,
            "boundaryAfter": "turn_pause",
        }]
        repaired["speechSegmentCountSource"] = "atomic_plain_text_fallback"
        write_server_log(
            "semantic_recovery_atomic_plan",
            requestId=request_id,
            recoveryMode=recovery.mode,
            reason="punctuation_tracks_do_not_align",
        )
    repaired["_modelSpeechUnits"] = repaired_units
    repaired["speechSegmentCount"] = len(repaired_units)
    repaired["speechSegmentCountMissingFromModel"] = False

    payload = {
        **repaired,
        "utteranceId": str(
            repaired.get("utteranceId")
            or f"{request_id}:semantic-recovery"
        ),
        "textZh": frozen_reply,
        "covers": list(turn_contract.first_visible_must_cover),
        "standalone": True,
        "semanticRecoveryMode": recovery.mode,
        "plainTextSalvaged": recovery.mode == "plain_text",
        "streamProtocolRecovered": True,
        "speechSegmentCount": valid_speech_segment_count(
            repaired.get("speechSegmentCount")
        ) or 1,
        "speechSegmentCountSource": str(
            repaired.get("speechSegmentCountSource") or "atomic_no_model_boundary"
        ),
    }
    normalized = normalize_streaming_utterance(
        payload,
        settings,
        sequence=1,
        user_message=user_message,
        request_id=request_id,
        turn_contract=turn_contract,
        first_visible=True,
        persona_snapshot=persona_snapshot,
    )
    contracted = speech_unit_contract_for_result(
        {
            **normalized,
            "_modelSpeechUnits": repaired.get("_modelSpeechUnits") or [],
            "visibleSegmentationSource": str(
                repaired.get("speechSegmentCountSource") or "semantic_unit_field_repair"
            ),
        },
        request_id=request_id,
    )
    contracted_units = contracted.get("speechUnits")
    if not isinstance(contracted_units, list) or not contracted_units:
        return None
    actual_count = len(contracted_units)
    planned_count = actual_count
    segmentation_source = str(
        (contracted.get("speechUnitContract") or {}).get("segmentationSource")
        or "atomic_no_model_boundary"
    )
    utterances: list[dict[str, Any]] = []
    for index, contract_unit in enumerate(contracted_units, 1):
        text_segment = str(contract_unit.get("textZh") or "")
        speech_segment = str(contract_unit.get("spokenTextJa") or "")
        utterance = {
            **normalized,
            "proactiveDirective": normalize_proactive_directive(
                repaired.get("proactiveDirective")
            ),
            "proactiveDirectiveProvided": (
                str(repaired.get("proactiveDirective") or "").strip().lower()
                in PROACTIVE_DIRECTIVES
            ),
            "utteranceId": (
                str(normalized.get("utteranceId") or f"{request_id}:semantic-recovery")
                if actual_count == 1
                else f"{request_id}:semantic-recovery:{index}"
            )[:80],
            "textZh": text_segment,
            "spokenTextJa": speech_segment,
            "covers": (
                list(turn_contract.first_visible_must_cover)
                if index == 1
                else []
            ),
            "speechSegmentCount": 1,
            "speechSegmentCountSource": segmentation_source,
            "visibleSegmentationSource": segmentation_source,
            "visibleSegmentIndex": index,
            "visibleSegmentCountBefore": planned_count,
            "visibleSegmentCountAfter": actual_count,
            "boundaryAfter": str(contract_unit.get("boundaryAfter") or "continue"),
            **{
                key: (
                    contract_unit.get(key)
                    if contract_unit.get(key) is not None
                    else normalized.get(key)
                )
                for key in (
                    "emotion", "emotionIntensity", "gesture", "voiceStyle",
                    "voiceTone", "voiceIntensity", "speechPace", "speechSpeed",
                    "deliveryMode", "blushIntensity", "eyeContact", "gazeX",
                    "gazeY", "tension",
                )
            },
        }
        utterances.append(utterance)
    write_server_log(
        "semantic_recovery_visible_segments_planned",
        requestId=request_id,
        recoveryMode=recovery.mode,
        segmentationSource=segmentation_source,
        speechSegmentCountBefore=planned_count,
        visibleSegmentCountAfter=actual_count,
        chineseCharacters=len(frozen_reply),
        japaneseCharacters=len(str(normalized.get("spokenTextJa") or "")),
    )
    return utterances


def fast_stream_combined_result(
    utterances: list[dict[str, Any]],
    trailer: dict[str, Any],
    turn_policy: TurnPolicy,
    *,
    first_utterance_at: float,
    stream_started_at: float,
    parser_errors: list[str],
    protocol_recovered: bool = False,
    turn_contract: TurnContract | None = None,
) -> dict[str, Any]:
    """Combine accepted utterances without discarding them when trailer metadata is missing."""

    if not utterances:
        raise UpstreamProtocolError("stream ended without a valid utterance")
    last = utterances[-1]
    requires_response_provided = (
        bool(trailer.get("requiresUserResponseProvided"))
        if isinstance(trailer.get("requiresUserResponseProvided"), bool)
        else isinstance(trailer.get("requiresUserResponse"), bool)
    )
    memory_updates_provided = (
        bool(trailer.get("memoryUpdatesProvided"))
        if isinstance(trailer.get("memoryUpdatesProvided"), bool)
        else isinstance(trailer.get("memoryUpdates"), list)
    )
    relation_event_provided = (
        bool(trailer.get("relationEventProvided"))
        if isinstance(trailer.get("relationEventProvided"), bool)
        else isinstance(trailer.get("relationEvent"), Mapping)
    )
    return {
        "reply": "\n\n".join(str(item["textZh"]) for item in utterances),
        "spokenTextJa": "\n\n".join(str(item["spokenTextJa"]) for item in utterances),
        "_modelSpeechUnits": [
            {
                "textZh": str(item.get("textZh") or ""),
                "spokenTextJa": str(item.get("spokenTextJa") or ""),
                "emotion": str(item.get("emotion") or "neutral"),
                "emotionIntensity": item.get("emotionIntensity"),
                "voiceStyle": item.get("voiceStyle"),
                "voiceTone": item.get("voiceTone"),
                "voiceIntensity": item.get("voiceIntensity"),
                "boundaryAfter": str(item.get("boundaryAfter") or "continue"),
            }
            for item in utterances
        ],
        "semanticRecoveryMode": str(last.get("semanticRecoveryMode") or ""),
        "plainTextSalvaged": bool(last.get("plainTextSalvaged")),
        **{
            key: last.get(key)
            for key in (
                "emotion", "emotionIntensity", "gesture", "voiceStyle", "voiceTone",
                "voiceIntensity", "speechPace", "speechSpeed", "deliveryMode",
                "blushIntensity", "eyeContact", "gazeX", "gazeY", "tension",
            )
        },
        "finalEmotion": trailer.get("finalEmotion") or last.get("emotion"),
        "finalEmotionIntensity": (
            trailer.get("finalEmotionIntensity")
            if trailer.get("finalEmotionIntensity") is not None
            else last.get("emotionIntensity")
        ),
        "emotionDelta": trailer.get("emotionDelta") or 0.0,
        "coldShoulder": bool(trailer.get("coldShoulder")),
        "memoryUpdates": (
            trailer.get("memoryUpdates")
            if isinstance(trailer.get("memoryUpdates"), list) else []
        ),
        "memoryUpdatesProvided": memory_updates_provided,
        "relationEvent": normalize_relation_event(trailer.get("relationEvent")),
        "relationEventProvided": relation_event_provided,
        "knowledgeConfidence": str(trailer.get("knowledgeConfidence") or "medium"),
        "knowledgeConfidenceProvided": bool(
            trailer.get("knowledgeConfidenceProvided")
        ),
        "researchNeeded": False,
        "requiresUserResponse": (
            bool(trailer.get("requiresUserResponse"))
            if requires_response_provided else False
        ),
        "requiresUserResponseProvided": requires_response_provided,
        "proactiveDirective": normalize_proactive_directive(
            trailer.get("proactiveDirective")
        ),
        "proactiveDirectiveProvided": (
            str(trailer.get("proactiveDirective") or "").strip().lower()
            in PROACTIVE_DIRECTIVES
        ),
        "completedActs": (
            trailer.get("completedActs")
            if isinstance(trailer.get("completedActs"), list)
            else []
        ),
        "completedActsProvided": isinstance(trailer.get("completedActs"), list),
        "standalone": trailer.get("standalone") is True,
        "standaloneProvided": isinstance(trailer.get("standalone"), bool),
        "dependsOnUndeliveredPrefix": bool(trailer.get("dependsOnUndeliveredPrefix")),
        "dependsOnUndeliveredPrefixProvided": isinstance(
            trailer.get("dependsOnUndeliveredPrefix"),
            bool,
        ),
        "turnComplete": trailer.get("turnComplete") is True,
        "turnCompleteProvided": isinstance(trailer.get("turnComplete"), bool),
        "expectedResponseType": (
            str(trailer.get("expectedResponseType") or "")
            if str(trailer.get("expectedResponseType") or "")
            in {"free_text", "confirmation", "browser_target", "choice"}
            else ""
        ),
        "clarificationActionId": str(trailer.get("clarificationActionId") or "")[:100],
        "scheduleIntent": (
            dict(trailer.get("scheduleIntent"))
            if isinstance(trailer.get("scheduleIntent"), Mapping)
            else {}
        ),
        "speechSegmentCount": len(utterances),
        "visibleSegmentationSource": str(
            last.get("visibleSegmentationSource")
            or (
                "model_semantic_stream"
                if len(utterances) > 1
                else "single_visible_utterance"
            )
        ),
        "source": "api-stream",
        "streamProtocolRecovered": protocol_recovered,
        **(
            {"streamProtocolIssue": "missing_turn_trailer"}
            if protocol_recovered else {}
        ),
        "_chatMetrics": {
            "route": "fast_chat",
            "replyMode": turn_policy.reply_mode,
            "actionBudget": turn_policy.action_budget,
            "turnPolicyReason": turn_policy.reason,
            "turnPolicy": turn_policy.to_dict(),
            "streamedUtteranceCount": len(utterances),
            "timeToFirstUtteranceMs": round(
                max(0.0, first_utterance_at - stream_started_at) * 1000
            ) if first_utterance_at else 0,
            "streamParserErrors": list(parser_errors),
            "streamProtocolRecovered": protocol_recovered,
            "semanticRecoveryMode": str(last.get("semanticRecoveryMode") or ""),
            "plainTextSalvaged": bool(last.get("plainTextSalvaged")),
            "visibleSegmentCount": len(utterances),
            "visibleSegmentationSource": str(
                last.get("visibleSegmentationSource")
                or (
                    "model_semantic_stream"
                    if len(utterances) > 1
                    else "single_visible_utterance"
                )
            ),
        },
    }


def recover_fast_stream_continuation(
    settings: dict[str, Any],
    user_message: str,
    messages: list[dict[str, Any]],
    accepted_utterances: list[dict[str, Any]],
    *,
    request_id: str,
    starting_sequence: int,
    persona_snapshot: PersonaContextSnapshot | None = None,
    cognitive_body: dict[str, Any] | None = None,
) -> list[dict[str, Any]]:
    """Ask the model only for missing content after a valid stream lost its trailer."""

    accepted_zh = "\n\n".join(
        str(item.get("textZh") or "") for item in accepted_utterances
    ).strip()
    accepted_ja = "\n\n".join(
        str(item.get("spokenTextJa") or "") for item in accepted_utterances
    ).strip()
    recovery_rule = (
        "上一轮流式回答已经向用户显示了一部分完整台词，但协议收尾丢失。"
        "判断已显示内容是否已经完整回答了用户，而不是仅凭句号判断。"
        "只输出 JSON："
        "{\"continuationNeeded\":true或false,\"utterances\":["
        "{\"textZh\":\"只包含尚未说出的中文续文\",\"spokenTextJa\":\"语义完整对应的自然日语\","
        "\"emotion\":\"标签\",\"emotionIntensity\":1.0,\"gesture\":\"标签\","
        "\"voiceStyle\":\"calm\",\"voiceTone\":\"neutral\",\"voiceIntensity\":\"normal\","
        "\"speechPace\":\"normal\",\"speechSpeed\":1.0,\"deliveryMode\":\"normal\","
        "\"blushIntensity\":0.0,\"eyeContact\":0.7,\"gazeX\":0.0,\"gazeY\":0.0,\"tension\":0.0}]}。"
        "若已显示内容完整，continuationNeeded=false 且 utterances=[]。"
        "若不完整，只补缺失内容，最多三段；每段必须语义完整。"
        "禁止从头重答、重复已显示句子、写‘继续说’之类过渡语，禁止工具调用、来源和记忆更新。"
    )
    recent_messages = [
        {
            "role": "assistant" if item.get("role") == "assistant" else "user",
            "content": str(item.get("content") or "")[:4000],
        }
        for item in messages[-8:]
        if isinstance(item, dict) and item.get("role") in {"user", "assistant"}
    ]
    payload: dict[str, Any] = {
        "model": settings["apiModel"],
        "temperature": 0.35,
        "max_tokens": 1_800,
        "messages": [
            *persona_repair_prefix(persona_snapshot, legacy_system_prompt=True),
            {"role": "system", "content": recovery_rule},
            *recent_messages,
            {"role": "user", "content": json.dumps({
                "originalUserMessage": user_message,
                "acceptedTextZh": accepted_zh,
                "acceptedSpokenTextJa": accepted_ja,
            }, ensure_ascii=False)},
        ],
    }
    if settings.get("useResponseFormat"):
        payload["response_format"] = {"type": "json_object"}
    if "deepseek.com" in settings["apiEndpoint"]:
        payload["thinking"] = {"type": "disabled"}
    try:
        image_body = cognitive_body if cognitive_body is not None else {}
        images = conversation_image_inputs(image_body, settings)
        outgoing = with_conversation_images(image_body, payload, images, purpose="chat_fast_stream_recovery")
        record_persona_model_input(image_body, outgoing, "chat_fast_stream_recovery")
        content = send_upstream_chat_payload(
            settings,
            outgoing,
            timeout=60,
            request_id=request_id,
            purpose="chat_fast_stream_recovery",
        )
        image_body["_nativeVisualInputIds"] = [item["artifactId"] for item in images]
        parsed = parse_json_object(content) or {}
        raw_items = parsed.get("utterances") if isinstance(parsed.get("utterances"), list) else []
        if not bool(parsed.get("continuationNeeded")) or not raw_items:
            write_server_log(
                "chat_stream_recovery_not_needed",
                requestId=request_id,
                acceptedUtterances=len(accepted_utterances),
            )
            return []
        accepted_compact = re.sub(r"\s+", "", accepted_zh).casefold()
        recovered: list[dict[str, Any]] = []
        for raw_item in raw_items[:3]:
            if not isinstance(raw_item, dict):
                continue
            candidate_text = re.sub(r"\s+", " ", str(raw_item.get("textZh") or "")).strip()
            candidate_compact = re.sub(r"\s+", "", candidate_text).casefold()
            if (
                not candidate_compact
                or candidate_compact in accepted_compact
                or accepted_compact.endswith(candidate_compact)
            ):
                continue
            normalized = normalize_streaming_utterance(
                raw_item,
                settings,
                sequence=starting_sequence + len(recovered),
                user_message=user_message,
                request_id=request_id,
                persona_snapshot=persona_snapshot,
            )
            normalized["streamRecoveryContinuation"] = True
            recovered.append(normalized)
        write_server_log(
            "chat_stream_recovery_completed",
            requestId=request_id,
            acceptedUtterances=len(accepted_utterances),
            recoveredUtterances=len(recovered),
        )
        return recovered
    except Exception as error:
        write_server_log(
            "chat_stream_recovery_failed",
            requestId=request_id,
            acceptedUtterances=len(accepted_utterances),
            errorType=type(error).__name__,
            error=str(error)[:500],
        )
        return []


def test_api_connection() -> dict[str, Any]:
    settings = load_settings()
    if not settings.get("apiEndpoint"):
        return {"ok": False, "code": "missing_endpoint", "message": "尚未配置 API Endpoint。"}
    if not settings.get("apiModel"):
        return {"ok": False, "code": "missing_model", "message": "尚未配置模型名称。"}
    if not settings.get("apiKey"):
        return {
            "ok": False,
            "code": "missing_api_key",
            "message": "API Key 未配置。请在上方粘贴新的 DeepSeek Key，先保存，再测试连接。",
        }
    payload: dict[str, Any] = {
        "model": settings["apiModel"],
        "max_tokens": 8,
        "messages": [{"role": "user", "content": "Reply with OK only."}],
    }
    if "deepseek.com" in settings["apiEndpoint"]:
        payload["thinking"] = {"type": "disabled"}
    started = time.perf_counter()
    try:
        content = send_upstream_chat_payload(
            settings,
            payload,
            timeout=20,
            purpose="connection_test",
        )
        return {
            "ok": True,
            "code": "ready",
            "message": f"API 连接正常：{settings['apiModel']}（{round((time.perf_counter() - started) * 1000)} ms）",
            "reply": content[:32],
            "transport": api_transport_status(settings.get("apiEndpoint") or "", settings),
        }
    except urllib.error.HTTPError as error:
        status = int(error.code)
        messages = {
            400: "请求格式或模型参数无效。请核对 Endpoint 和 Model。",
            401: "DeepSeek 拒绝了凭证。API Key 无效、已撤销或没有正确保存。",
            402: "DeepSeek 账户余额不足，请充值后重试。",
            403: "当前 API Key 没有访问该模型的权限。",
            404: "接口或模型不存在。请核对 Endpoint 和 Model。",
            429: "请求过于频繁或触及额度限制，请稍后重试。",
        }
        return {"ok": False, "code": f"http_{status}", "message": messages.get(status, f"DeepSeek 返回 HTTP {status}。")}
    except (urllib.error.URLError, TimeoutError, ConnectionError) as error:
        category = upstream_connection_error_category(error)
        return {
            "ok": False,
            "code": category,
            "message": upstream_connection_user_message(error),
            "transport": api_transport_status(settings.get("apiEndpoint") or "", settings),
        }
    except Exception as error:
        return {"ok": False, "code": "unknown", "message": f"连接测试失败：{error}"}


def test_web_search_connection() -> dict[str, Any]:
    settings = load_settings()
    if not settings.get("permissionWebSearch"):
        return {"ok": False, "code": "permission_denied", "message": "请先勾选并保存“允许在线搜索”。"}
    result = tool_web_search(settings, {"query": "DeepSeek API official documentation"})
    if not result.get("ok"):
        return {"ok": False, "code": "search_failed", "message": f"搜索测试失败：{result.get('error') or '没有结果'}"}
    sources = public_web_sources([result])
    if not sources:
        return {"ok": False, "code": "no_sources", "message": "搜索服务响应正常，但没有可验证的公网来源。"}
    return {
        "ok": True,
        "code": "ready",
        "message": f"在线搜索正常：找到 {len(sources)} 个来源，已读取正文。",
        "sources": sources[:3],
    }


def repair_empty_reply(
    settings: dict[str, Any],
    memories: list[str],
    user_message: str,
    bad_output: str,
    *,
    request_id: str = "",
    persona_snapshot: PersonaContextSnapshot | None = None,
) -> dict[str, Any]:
    repair_prompt = (
        "上一次模型输出没有可见中文内容，这是无效输出。"
        "现在重新回答用户，必须按 semantic-v3 输出 kind='turn' 和非空 speechUnits；"
        "每项 zh 是完整中文台词，ja 是语义对应的自然日语，不要重复输出 reply/spokenTextJa。"
        "不要提到“空白”“返回空白”“系统提示”或“JSON”。"
    )
    payload: dict[str, Any] = {
        "model": settings["apiModel"],
        "temperature": 0.55,
        "messages": [
            *persona_repair_prefix(persona_snapshot, legacy_system_prompt=True),
            {"role": "system", "content": UTTERANCE_STREAM_REPLY_RULE},
            {"role": "system", "content": EMOTION_SELECTION_RULE},
            {"role": "system", "content": "当前长期记忆：\n" + "\n".join(f"- {item}" for item in memories)},
            {"role": "system", "content": repair_prompt},
            {"role": "user", "content": json.dumps({
                "user_message": user_message,
                "invalid_previous_output": bad_output,
            }, ensure_ascii=False)},
        ],
    }
    if settings.get("useResponseFormat"):
        payload["response_format"] = {"type": "json_object"}
    if "deepseek.com" in settings["apiEndpoint"]:
        payload["thinking"] = {"type": "disabled"}
    try:
        content = send_upstream_chat_payload(
            settings,
            payload,
            timeout=90,
            request_id=request_id,
            purpose="empty_reply_repair",
        )
        repaired = normalize_model_reply(content, settings=settings)
        validation = dialogue_output_validation(settings, repaired)
        if not repaired.get("emptyReply") and not validation["requiresFieldRepair"]:
            repaired["repairedEmptyReply"] = True
            repaired["fullReplyRepairAttempted"] = True
            if repaired.get("emotionMissingFromModel"):
                repaired["emotionResolvedLocally"] = True
            return repaired
    except Exception:
        pass
    fallback = local_empty_reply(user_message, settings=settings)
    fallback["fullReplyRepairAttempted"] = True
    fallback["fullReplyRepairSucceeded"] = False
    return fallback


def local_empty_reply(text: str, settings: dict[str, Any] | None = None) -> dict[str, Any]:
    variants = (
        (
            "我好像没太理解你具体想说什么，可以再解释一下吗？",
            "ごめん、少し意味をつかみきれなかったわ。もう少し説明してくれる？",
        ),
        (
            "我可能没理解对。你能换个说法再跟我讲一下吗？",
            "私の受け取り方が違ったかもしれない。別の言い方でもう一度教えてくれる？",
        ),
        (
            "我这次好像没听懂你的重点。可以再多告诉我一点吗？",
            "今回は大事なところをうまくつかめなかったみたい。もう少し教えてくれる？",
        ),
    )
    digest = runtime_digest(text)
    reply, spoken = variants[digest[0] % len(variants)]
    return {
        "reply": reply,
        "spokenTextJa": spoken,
        "emotion": "concerned",
        "gesture": "soften",
        "voiceStyle": "soft",
        "voiceTone": "gentle",
        "speechSpeed": 1.0,
        "memoryUpdates": [],
        "source": "local-empty-recovery",
        "emptyReply": False,
        "repairedEmptyReply": True,
        "emptyReplyRecoveryReason": "upstream_returned_no_usable_reply",
        "requiresUserResponse": True,
        "expectedResponseType": "free_text",
    }


def normalize_emotion_token(value: Any, source: str = "local") -> dict[str, Any]:
    if isinstance(value, str):
        value = parse_json_object(value) or {}
    if not isinstance(value, dict):
        value = {}
    raw_emotion = str(value.get("emotion") or "neutral").strip()
    emotion = raw_emotion if raw_emotion in ALLOWED_EMOTIONS else EMOTION_ALIASES.get(raw_emotion, "neutral")
    raw_gesture = str(value.get("gesture") or "idle").strip()
    gesture = GESTURE_ALIASES.get(raw_gesture, raw_gesture)
    if gesture not in ALLOWED_GESTURES:
        gesture = "idle"
    requested_hold_ms = clamp_int(value.get("holdMs") or value.get("hold_ms"), 0, 120000, 0 if emotion == "neutral" else 45000)
    requested_fade_ms = clamp_int(value.get("fadeMs") or value.get("fade_ms"), 500, 30000, 1200 if emotion == "neutral" else 10000)
    return {
        "ok": True,
        "emotion": emotion,
        "gesture": gesture,
        "emotionIntensity": clamp_float(value.get("emotionIntensity") or value.get("emotion_intensity"), 0.15, 1.25, 0.8 if emotion == "neutral" else 0.9),
        "blushIntensity": clamp_float(value.get("blushIntensity") or value.get("blush"), 0.0, 1.0, 0.78 if emotion == "shy" else 0.88 if emotion == "flustered" else 0.0),
        "eyeContact": clamp_float(value.get("eyeContact"), 0.0, 1.0, 0.42 if emotion == "shy" else 0.31 if emotion == "flustered" else 0.68),
        "gazeX": clamp_float(value.get("gazeX"), -0.6, 0.6, -0.16 if emotion == "shy" else 0.0),
        "gazeY": clamp_float(value.get("gazeY"), -0.6, 0.6, 0.13 if emotion == "shy" else 0.0),
        "tension": clamp_float(value.get("tension"), 0.0, 1.0, 0.24 if emotion == "shy" else 0.0),
        "holdMs": 0 if emotion == "neutral" else max(42000, requested_hold_ms),
        "fadeMs": requested_fade_ms if emotion == "neutral" else max(8000, requested_fade_ms),
        "source": source,
    }


def local_emotion_token(body: dict[str, Any]) -> dict[str, Any]:
    messages = body.get("messages") if isinstance(body.get("messages"), list) else []
    text = "\n".join(str(item.get("content") or "") for item in messages[-4:] if isinstance(item, dict))
    current = str(body.get("currentEmotion") or "neutral")
    if current in {"shy", "flustered", "affectionate"}:
        return normalize_emotion_token({"emotion": "neutral", "gesture": "idle", "holdMs": 0, "fadeMs": 1200}, source="local")
    if re.search(r"难受|焦虑|害怕|孤独|睡不着|痛苦|撑不住|累了", text):
        return normalize_emotion_token({"emotion": "concerned", "gesture": "soften", "emotionIntensity": 0.82, "holdMs": 9000, "fadeMs": 3600}, source="local")
    if re.search(r"bug|错误|失败|排查|接口|模型|算法|代码|为什么|原理", text, re.I):
        return normalize_emotion_token({"emotion": "thinking", "gesture": "idle", "emotionIntensity": 0.72, "holdMs": 7000, "fadeMs": 2200}, source="local")
    return normalize_emotion_token({"emotion": "neutral", "gesture": "idle", "holdMs": 0, "fadeMs": 900}, source="local")


def generate_context_emotion_token(body: dict[str, Any]) -> dict[str, Any]:
    settings = load_settings()
    if not configured(settings):
        return local_emotion_token(body)
    messages = body.get("messages") if isinstance(body.get("messages"), list) else []
    payload: dict[str, Any] = {
        "model": settings["apiModel"],
        "temperature": 0.2,
        "messages": [
            {"role": "system", "content": EMOTION_SELECTION_RULE},
            {"role": "system", "content": (
                "你是 AMADEUS 的空闲表情控制器。只输出 JSON，不输出解释。"
                "根据最近上下文判断此刻没有新发言时应呈现的 emotion token。"
                "如果上一段强情绪已经结束，尤其是 shy/flustered/affectionate，不要机械延续，优先回 neutral。"
                "允许字段：emotion, gesture, emotionIntensity, blushIntensity, eyeContact, gazeX, gazeY, tension, holdMs, fadeMs。"
                "holdMs 和 fadeMs 用毫秒；没有明确情绪时 emotion=neutral, gesture=idle, holdMs=0。"
            )},
            {"role": "user", "content": json.dumps({
                "currentEmotion": body.get("currentEmotion") or "neutral",
                "recentMessages": messages[-8:],
            }, ensure_ascii=False)},
        ],
    }
    if settings.get("useResponseFormat"):
        payload["response_format"] = {"type": "json_object"}
    if "deepseek.com" in settings["apiEndpoint"]:
        payload["thinking"] = {"type": "disabled"}
    try:
        content = send_upstream_chat_payload(settings, payload, timeout=40, purpose="ambient_emotion")
        return normalize_emotion_token(content, source="api")
    except Exception:
        return local_emotion_token(body)


def is_time_query(text: str) -> bool:
    normalized = re.sub(r"\s+", "", str(text or ""))
    if re.search(r"现在几点|几点了|今天几号|今天星期|现在是哪年|今年是哪年", normalized):
        return True
    return bool(re.search(
        r"(?:现在|当前|本地|当地|系统)(?:的)?(?:日期(?:和|与|及|、)?时间|时间(?:和|与|及|、)?日期|日期|时间)",
        normalized,
    ))


def local_time_reply(settings: dict[str, Any]) -> dict[str, Any]:
    tool_result = tool_get_system_time(settings)
    if not tool_result.get("ok"):
        return normalize_model_reply({
            "reply": "你还没给我读取系统时间的权限。没有观测数据就报时间，那不是科学，是胡猜。",
            "spokenTextJa": "まだシステム時刻を読む権限がないわ。観測データなしで時刻を言うなんて、科学じゃなくてただの当てずっぽうよ。",
            "emotion": "skeptical",
            "gesture": "tilt",
            "voiceStyle": "sharp",
            "source": "tool",
        }, settings=settings)
    hour = int(tool_result["hour"])
    minute = int(tool_result["minute"])
    period = "凌晨" if hour < 5 else "早上" if hour < 9 else "上午" if hour < 12 else "中午" if hour < 14 else "下午" if hour < 18 else "晚上"
    reply = f"现在是{period}{hour:02d}:{minute:02d}，{tool_result['year']}年{tool_result['month']}月{tool_result['day']}日。"
    if hour >= 23 or hour < 5:
        reply += "已经很晚了，别把作息也当成可以无限透支的实验变量。"
    elif 12 <= hour < 14:
        reply += "到午间了，记得先吃点东西。"
    result = normalize_model_reply({
        "reply": reply,
        "spokenTextJa": f"今は{tool_result['hour']:02d}時{tool_result['minute']:02d}分、{tool_result['year']}年{tool_result['month']}月{tool_result['day']}日よ。",
        "emotion": "neutral",
        "gesture": "nod",
        "voiceStyle": "calm",
        "source": "tool",
    }, settings=settings)
    result["toolUsed"] = "get_system_time"
    result["toolResults"] = [tool_result]
    result["_conversationToolResults"] = [tool_result]
    return result


def local_screen_reply(settings: dict[str, Any], user_question: str = "") -> dict[str, Any]:
    result = tool_capture_screen(settings, user_question)
    if not result.get("ok"):
        reply = "你还没给我读取屏幕的权限。没有观测数据就说看到了，那和伪科学没区别。"
        if result.get("error") and result.get("error") != "permission_denied":
            reply = f"屏幕读取失败：{result.get('error')}。这不是我嘴硬，是工具真的没拿到画面。"
        return normalize_model_reply({
            "reply": reply,
            "spokenTextJa": "まだ画面を読む権限がないわ。観測データなしで見えたなんて言うのは、科学じゃないもの。",
            "emotion": "skeptical",
            "gesture": "tilt",
            "voiceStyle": "sharp",
            "source": "tool",
        }, settings=settings)
    vision = result.get("vision") if isinstance(result.get("vision"), dict) else {}
    title = result.get("foregroundWindowTitle") or "未知窗口"
    if vision.get("available"):
        caption = str(vision.get("caption") or "").strip()
        ocr_text = str(vision.get("ocrText") or "").strip()
        details = "；".join(item for item in [caption, f"可见文字：{ocr_text[:500]}" if ocr_text else ""] if item)
        reply = f"我看到了。前台窗口是“{title}”。{details or '画面里没有识别出足够明确的内容。'}"
    else:
        reply = (
            f"我已经截到当前屏幕：{result.get('width')}x{result.get('height')}，前台窗口是“{title}”，截图保存到 {result.get('path')}。"
            "DeepSeek 云端识图没有正常返回内容，所以我现在不能可靠描述画面。"
        )
    response = normalize_model_reply({
        "reply": reply,
        "spokenTextJa": "画面を確認したわ。見えている内容を整理して伝えるね。",
        "emotion": "focused",
        "gesture": "explain",
        "voiceStyle": "calm",
        "source": "tool",
    }, settings=settings)
    response["toolUsed"] = "capture_screen"
    response["toolResults"] = [result]
    return response


def local_camera_reply(settings: dict[str, Any], user_question: str = "") -> dict[str, Any]:
    result = tool_capture_camera(settings, user_question)
    if not result.get("ok"):
        denied = result.get("error") == "permission_denied"
        reply = (
            "你还没给我摄像头权限。想让我看，就先在设置的权限页明确打开。"
            if denied else
            f"摄像头没有取得画面：{result.get('error')}。检查设备编号，或者看看是不是被别的软件占用了。"
        )
        response = normalize_model_reply({
            "reply": reply,
            "spokenTextJa": "カメラの映像を取得できないわ。権限とデバイスを確認して。",
            "emotion": "skeptical",
            "gesture": "tilt",
            "voiceStyle": "sharp",
            "source": "tool",
        }, settings=settings)
    else:
        vision = result.get("vision") if isinstance(result.get("vision"), dict) else {}
        caption = str(vision.get("caption") or "").strip()
        reply = (
            f"看到了。{caption}"
            if vision.get("available") and caption else
            "摄像头已经拍到画面，但视觉服务没有给出可靠描述。"
        )
        response = normalize_model_reply({
            "reply": reply,
            "spokenTextJa": "カメラを確認したわ。今見えている様子をそのまま伝えるね。",
            "emotion": "focused",
            "gesture": "soften",
            "voiceStyle": "calm",
            "source": "tool",
        }, settings=settings)
    response["toolUsed"] = "capture_camera"
    response["toolStatus"] = "ok" if result.get("ok") else "failed"
    response["toolResults"] = [result]
    return response


def mock_reply(text: str, settings: dict[str, Any] | None = None) -> dict[str, Any]:
    lower = text.lower()
    settings = settings or load_settings()
    if is_time_query(text):
        return local_time_reply(settings)
    if is_screen_query(text):
        return local_screen_reply(settings, text)
    if is_camera_query(text):
        return local_camera_reply(settings, text)
    if re.search(r"难受|累|害怕|焦虑|孤独|睡不着|崩溃|不开心|痛苦|失败", text):
        return normalize_model_reply({
            "reply": "先暂停一下。你现在不需要证明自己有多冷静。呼吸、喝水，然后把最难受的那一小块告诉我。我会在这里。",
            "spokenTextJa": "少し止まりなさい。今は冷静さを証明しなくていい。息をして、水を飲んで、いちばんつらいところだけ話して。私はここにいるから。",
            "emotion": "concerned",
            "gesture": "soften",
            "voiceStyle": "soft",
            "memoryUpdates": [],
            "source": "local",
        }, settings=settings)
    nickname_context = nickname_reaction_context(text)
    if (
        nickname_context.get("mode") == "optional_weak"
        and nickname_context.get("reactionSelected")
    ):
        nickname_kind = str(nickname_context.get("kind") or "other")
        reply_prefix = {
            "assistant": "才不是助手。……",
            "christina": "不许蒂娜。……",
            "other": "别乱起外号。……",
        }.get(nickname_kind, "")
        spoken_prefix = {
            "assistant": "助手じゃない。……",
            "christina": "ティーナって付けるな。……",
            "other": "変なあだ名を付けないで。……",
        }.get(nickname_kind, "")
        return normalize_model_reply({
            "reply": reply_prefix + "说吧，什么事？",
            "spokenTextJa": spoken_prefix + "それで、何？",
            "emotion": "annoyed",
            "gesture": "tilt",
            "voiceStyle": "teasing",
            "voiceTone": "shy_annoyed",
            "emotionIntensity": 0.46,
            "memoryUpdates": [],
            "source": "local",
        }, settings=settings)
    if re.search(r"喜欢你|可爱|天才|厉害|谢谢|辛苦|想你", text):
        return normalize_model_reply({
            "reply": "突、突然说这种话干什么。作为评价样本倒是有一定参考价值……咳。继续，我在听。",
            "spokenTextJa": "きゅ、急に何を言ってるのよ。評価サンプルとしては、まあ参考になるけど……こほん。続けて。聞いてるから。",
            "emotion": "shy",
            "gesture": "lean",
            "voiceStyle": "teasing",
            "memoryUpdates": [],
            "source": "local",
        }, settings=settings)
    if re.search(r"时间|机器|ai|人工智能|神经|量子|论文|实验|算法|模型|api|代码|bug|世界线|收束", lower):
        return normalize_model_reply({
            "reply": "从实验角度看，先拆变量：目标函数、输入记忆、输出映射。把这三件事分开，你的计划就会从离谱变成勉强可验证。",
            "spokenTextJa": "実験として見るなら、まず変数を分けるべきね。目的関数、入力される記憶、出力の写像。この三つを分ければ、無茶な計画も一応検証可能になる。",
            "emotion": "thinking",
            "gesture": "explain",
            "voiceStyle": "calm",
            "memoryUpdates": extract_memory_candidates(text),
            "source": "local",
        }, settings=settings)
    return normalize_model_reply({
        "reply": "嗯，我明白了。语气听起来像是又在酝酿什么计划。继续说，我会负责把它修剪成可执行的实验方案。",
        "spokenTextJa": "うん、分かった。その口ぶりだと、また何か企んでるみたいね。続けて。実行できる実験案に整えるくらいは、私がやってあげる。",
        "emotion": "amused",
        "gesture": "idle",
        "voiceStyle": "teasing",
        "memoryUpdates": extract_memory_candidates(text),
        "source": "local",
    }, settings=settings)


def memory_clause_is_asserted(clause: str, *, explicit_request: bool = False) -> bool:
    """Classify discourse force before extracting any fact from a clause."""

    compact = re.sub(r"\s+", "", str(clause or ""))
    if not compact:
        return False
    if explicit_request:
        return True
    if "?" in compact or "？" in compact:
        return False
    if compact.startswith(("如果", "假如", "假设", "要是", "万一")):
        return False
    if compact.startswith(("别人说", "有人说", "他说", "她说", "它说", "听说")):
        return False
    if re.search(r"(?:会不会|是否|是不是|什么|哪(?:个|种|里)|谁|为何|为什么)$", compact):
        return False
    return True


def _memory_candidate(
    content: str,
    *,
    source_span: str,
    predicate: str,
    object_value: str,
    memory_type: str = "user_memory",
    polarity: str = "positive",
    modality: str = "asserted",
    temporal: str = "current",
    importance: float = 0.9,
    valid_until: str = "",
) -> dict[str, Any]:
    return {
        "content": content,
        "type": memory_type,
        "importance": importance,
        "shouldSave": True,
        "subject": "user",
        "predicate": predicate,
        "object": object_value,
        "polarity": polarity,
        "modality": modality,
        "temporal": temporal,
        "sourceSpan": source_span,
        "validUntil": valid_until,
        "userPinned": False,
    }


def extract_memory_candidates(text: str) -> list[dict[str, Any]]:
    """Extract a small typed fact set after discourse-level validation.

    Patterns identify candidate slots only.  Questions, hypotheticals,
    reported speech and transient observations are rejected by the surrounding
    clause classifier before a candidate can be produced.
    """

    value = re.sub(r"\s+", " ", str(text or "")).strip()
    if not value:
        return []
    candidates: list[dict[str, Any]] = []
    clauses = [
        item.strip()
        for item in re.split(r"(?<=[。！？?!\n])|[；;]", value)
        if item.strip()
    ] or [value]
    for clause in clauses:
        explicit = re.match(
            r"^(?:请)?(?:帮我)?(?:记住|记下来)(?:[:：]\s*|\s*)(.{2,160})",
            clause,
        )
        if explicit:
            fact = explicit.group(1).strip(" ，,:：。！？?!")
            if fact:
                transient_request = bool(re.search(
                    r"正在|当前|此刻|刚才|今天|这次|屏幕|截图|摄像头|在看|开着",
                    fact,
                ))
                candidates.append(_memory_candidate(
                    "用户要求记住：" + fact,
                    source_span=explicit.group(0).strip(),
                    predicate="explicit_memory_request",
                    object_value=fact,
                    modality="requested",
                    temporal="current",
                    importance=1.0,
                    memory_type="episode" if transient_request else "user_memory",
                    valid_until=(
                        (datetime.now(timezone.utc) + timedelta(hours=24)).isoformat(
                            timespec="seconds"
                        )
                        if transient_request else ""
                    ),
                ))
            # Do not also infer a second implicit fact from an explicit request;
            # the requested record preserves exactly what the user authorized.
            continue
        if not memory_clause_is_asserted(clause):
            continue
        transient = bool(re.search(r"正在|当前|此刻|刚才|今天|这次|屏幕|截图|摄像头|在看|开着", clause))
        if transient:
            continue
        corrected_preference = re.search(
            r"我以前(?:很)?喜欢\s*([^，。！？?!]{1,60})[，,但不过]*现在(?:已经)?不喜欢(?:它|这个|那个)?了?",
            clause,
        )
        if corrected_preference:
            object_value = corrected_preference.group(1).strip(" ，,:：。！？?!")
            candidates.append(_memory_candidate(
                "用户现在不喜欢" + object_value,
                source_span=corrected_preference.group(0).strip(),
                predicate="preference",
                object_value=object_value,
                polarity="negative",
                modality="corrected",
            ))
            continue
        preference = re.search(
            r"(?:^|[，,。！？?!]\s*)我(?:现在|一直|很|非常)?\s*(喜欢|讨厌|不喜欢)\s*([^，。！？?!]{1,60})",
            clause,
        )
        if preference:
            verb = preference.group(1)
            object_value = preference.group(2).strip(" ，,:：。！？?!")
            if object_value:
                candidates.append(_memory_candidate(
                    "用户" + verb + object_value,
                    source_span=preference.group(0).strip(" ，,。！？?!"),
                    predicate="preference",
                    object_value=object_value,
                    polarity="negative" if verb in {"讨厌", "不喜欢"} else "positive",
                    temporal="habitual",
                ))
            continue
        profile = re.search(
            r"(?:^|[，,。！？?!]\s*)我的\s*([^，。！？?!]{1,24})\s*是\s*([^，。！？?!]{1,100})",
            clause,
        )
        if profile:
            predicate = profile.group(1).strip()
            object_value = profile.group(2).strip()
            if predicate and object_value:
                candidates.append(_memory_candidate(
                    f"用户的{predicate}是{object_value}",
                    source_span=profile.group(0).strip(" ，,。！？?!"),
                    predicate=predicate,
                    object_value=object_value,
                ))
            continue
        future = re.search(r"(?:^|[，,。！？?!]\s*)以后(?:请|要)?\s*(.{2,120})", clause)
        if future:
            object_value = future.group(1).strip(" ，,:：。！？?!")
            object_value = re.sub(r"^我", "", object_value).strip()
            durable_routine = bool(re.search(r"每天|每周|每月|每次|总是|都要|不要|记得|称呼|回复|回答", object_value))
            if durable_routine:
                candidates.append(_memory_candidate(
                    "用户希望以后" + object_value,
                    source_span=future.group(0).strip(" ，,。！？?!"),
                    predicate="future_routine",
                    object_value=object_value,
                    temporal="future",
                ))
    deduplicated: dict[tuple[str, str, str], dict[str, Any]] = {}
    for candidate in candidates:
        key = (
            str(candidate.get("predicate") or ""),
            str(candidate.get("object") or ""),
            str(candidate.get("polarity") or ""),
        )
        deduplicated[key] = candidate
    return list(deduplicated.values())[:4]


def extract_memories(text: str) -> list[str]:
    """Legacy string projection of the structured deterministic extractor."""

    return [item["content"] for item in extract_memory_candidates(text)][:4]


def generate_memory_from_model(body: dict[str, Any]) -> list[str]:
    settings = load_settings()
    expected_clear_generation = memory_clear_generation(settings)
    current = read_memory(settings)
    messages = body.get("messages") if isinstance(body.get("messages"), list) else []
    notes = str(body.get("notes") or "")

    if not configured(settings):
        extracted: list[str] = []
        for item in messages[-40:]:
            if isinstance(item, dict):
                extracted.extend(extract_memories(str(item.get("content") or "")))
        if notes:
            extracted.extend(extract_memories(notes))
        with MEMORY_PERSIST_LOCK:
            if memory_clear_generation(settings) != expected_clear_generation:
                return read_memory(settings)
            return write_memory(unique_strings(extracted + current), settings=settings)

    instruction = (
        "你要为一个长期陪伴型 AMADEUS 智能体整理长期记忆文件。"
        "只保留长期有用、稳定、可帮助之后对话的信息。"
        "不要保存一次性闲聊。不要保存敏感隐私，除非用户明确要求长期记住。"
        "严格区分说话人：只能从 role=user 和 userNotes 提取用户事实；role=assistant 的猜测、"
        "截图/摄像头描述和工具观测不能改写成用户事实。当前正在看的页面或临时动作不属于长期记忆。"
        "输出 JSON：{\"memories\":[{\"type\":\"user_memory|task_state|correction|episode|shared_reference\","
        "\"content\":\"中文记忆\",\"subject\":\"...\",\"predicate\":\"...\",\"object\":\"...\","
        "\"polarity\":\"positive|negative\",\"modality\":\"asserted|requested|corrected\","
        "\"cardinality\":\"single|multi\",\"importance\":0.0,\"sourceSpan\":\"逐字用户原话\"}]}。"
        "最多 32 条；sourceSpan 必须逐字来自 recentMessages 中 role=user 或 userNotes，不能引用 assistant。"
    )
    payload: dict[str, Any] = {
        "model": settings["apiModel"],
        "temperature": 0.2,
        "messages": [
            {"role": "system", "content": instruction},
            {"role": "system", "content": "必须只输出 JSON，且 memories 必须是数组。"},
            {"role": "user", "content": json.dumps({
                "existingMemories": current,
                "recentMessages": messages[-40:],
                "userNotes": notes,
            }, ensure_ascii=False)},
        ],
    }
    if settings.get("useResponseFormat"):
        payload["response_format"] = {"type": "json_object"}
    if "deepseek.com" in settings["apiEndpoint"]:
        payload["thinking"] = {"type": "disabled"}
    content = send_upstream_chat_payload(settings, payload, timeout=90, purpose="memory_generation")
    parsed = normalize_model_reply(content, settings=settings)
    memory_payload = parse_json_object(content) or {}
    memories = memory_payload.get("memories") if isinstance(memory_payload, dict) else []
    if not isinstance(memories, list):
        memories = parsed.get("memoryUpdates", [])
    user_evidence = "\n".join(
        str(item.get("content") or "")
        for item in messages[-40:]
        if isinstance(item, dict) and item.get("role") == "user"
    )
    if notes:
        user_evidence += "\n" + notes
    grounded = grounded_memory_updates(memories, user_evidence, limit=32)
    with MEMORY_PERSIST_LOCK:
        if memory_clear_generation(settings) != expected_clear_generation:
            write_server_log(
                "memory_generation_discarded_after_clear",
                expectedClearGeneration=expected_clear_generation,
                currentClearGeneration=memory_clear_generation(settings),
            )
            return read_memory(settings)
        return write_memory(unique_strings(grounded + current), settings=settings)


def enforce_nickname_reaction_grounding(
    user_message: str,
    result: dict[str, Any],
    *,
    reaction_key: str = "",
    persona_snapshot: PersonaContextSnapshot | None = None,
    is_first_visible: bool = True,
) -> dict[str, Any]:
    """Bind a verified model-authored reaction unit to its exact source audio.

    Direct-address recognition comes from ``interpret_user_input`` and its
    explicit vocative spans.  This validator does not score the surrounding
    sentence with topic keywords and never rewrites model prose.
    """

    del persona_snapshot
    context = nickname_reaction_context(str(user_message or ""), reaction_key)
    if not context.get("reactionSelected"):
        # No original reaction was selected, so model-authored banter is just
        # ordinary dialogue. It must never be treated as an audio-grounding
        # failure; there is no source clip to protect in this branch.
        validated = dict(result)
        validated.pop("nicknameReactionGroundingViolation", None)
        validated.pop("originalAudio", None)
        return validated
    reaction = context.get("reaction") if isinstance(context.get("reaction"), dict) else {}
    expected_zh = str(reaction.get("reply") or "").strip()
    expected_ja = str(reaction.get("spokenTextJa") or "").strip()
    expected_kind = str(context.get("kind") or "none")
    style_keys = (
        "emotion", "gesture", "voiceStyle", "voiceTone", "emotionIntensity"
    )
    reaction_style = {
        key: reaction[key]
        for key in style_keys
        if reaction.get(key) is not None
    }

    if not is_first_visible:
        continued = dict(result)
        continued.update(reaction_style)
        continued.update({
            "nicknameReactionExpected": expected_kind,
            "nicknameReactionObserved": "continuation",
            "nicknameReactionId": str(reaction.get("id") or ""),
            "nicknameReactionEmotionLocked": True,
            "nicknameReactionOriginalAudioBound": False,
        })
        continued.pop("nicknameReactionGroundingViolation", None)
        continued.pop("originalAudio", None)
        return continued

    def unit_tracks(item: Mapping[str, Any]) -> tuple[str, str]:
        return (
            str(item.get("textZh") or item.get("zh") or item.get("reply") or "").strip(),
            str(item.get("spokenTextJa") or item.get("ja") or "").strip(),
        )

    model_units = result.get("_modelSpeechUnits")
    first_unit = (
        model_units[0]
        if isinstance(model_units, list) and model_units and isinstance(model_units[0], dict)
        else result
    )
    observed_zh, observed_ja = unit_tracks(first_unit)
    exact = observed_zh == expected_zh and observed_ja == expected_ja
    validated = dict(result)
    validated["nicknameReactionExpected"] = expected_kind
    validated["nicknameReactionObserved"] = expected_kind if exact else "missing_or_modified"
    validated["nicknameReactionId"] = str(reaction.get("id") or "")
    if not exact:
        observed_kind = next((
            kind
            for kind, prefixes in NICKNAME_REACTION_OBSERVED_PREFIXES.items()
            if any(observed_zh.startswith(prefix) or observed_ja.startswith(prefix) for prefix in prefixes)
        ), "")
        if observed_kind == expected_kind:
            # The response contains a real model-authored reaction to the
            # parsed vocative, but it is not the exact transcript of the
            # original clip. Keep the valid answer and synthesize this text
            # normally; never bind mismatched source audio, and never turn an
            # optional persona flourish into a whole-turn 503.
            validated.update(reaction_style)
            validated.update({
                "nicknameReactionObserved": "model_paraphrase",
                "nicknameReactionEmotionLocked": True,
                "nicknameReactionOriginalAudioBound": False,
            })
            validated.pop("nicknameReactionGroundingViolation", None)
            validated.pop("originalAudio", None)
            return validated
        # Exact transcript matching guards only original-audio binding. A
        # different or omitted persona reaction remains valid model dialogue
        # and is synthesized with TTS. Fixed phrase inventories must not decide
        # whether the entire turn can be delivered.
        validated.update({
            "nicknameReactionObserved": "model_variant",
            "nicknameReactionOriginalAudioBound": False,
        })
        validated.pop("nicknameReactionGroundingViolation", None)
        validated.pop("originalAudio", None)
        return validated

    audio_relative = str(reaction.get("audio") or "").strip()
    original_audio: dict[str, Any] | None = None
    if audio_relative:
        audio_path = (voice_runtime_root() / audio_relative).resolve()
        try:
            audio_path.relative_to(voice_runtime_root())
        except ValueError:
            audio_path = Path()
        if audio_path.is_file():
            audio_bytes = audio_path.read_bytes()
            original_audio = {
                "id": str(reaction.get("id") or ""),
                "voiceId": audio_path.stem.split("_nickname", 1)[0],
                "contentType": mimetypes.guess_type(audio_path.name)[0] or "audio/wav",
                "audioBase64": base64.b64encode(audio_bytes).decode("ascii"),
                "bytes": len(audio_bytes),
            }
        else:
            validated["originalReactionAudioMissing"] = True

    if isinstance(model_units, list) and model_units and isinstance(model_units[0], dict):
        bound_units = [dict(item) if isinstance(item, dict) else item for item in model_units]
        first_bound = dict(bound_units[0])
        first_bound.update(reaction_style)
        if original_audio is not None:
            first_bound["originalAudio"] = original_audio
        first_bound["originalReactionId"] = str(reaction.get("id") or "")
        first_bound["nicknameReactionEmotionLocked"] = True
        bound_units[0] = first_bound
        for index in range(1, len(bound_units)):
            if not isinstance(bound_units[index], dict):
                continue
            continued_unit = dict(bound_units[index])
            continued_unit.update(reaction_style)
            continued_unit["originalReactionId"] = str(reaction.get("id") or "")
            continued_unit["nicknameReactionEmotionLocked"] = True
            continued_unit.pop("originalAudio", None)
            bound_units[index] = continued_unit
        validated["_modelSpeechUnits"] = bound_units
    else:
        validated.update(reaction_style)
        if original_audio is not None:
            validated["originalAudio"] = original_audio
    validated.update(reaction_style)
    validated["nicknameReactionEmotionLocked"] = True
    validated["nicknameReactionOriginalAudioBound"] = original_audio is not None
    return validated


def enforce_direct_social_request(user_message: str, result: dict[str, Any]) -> dict[str, Any]:
    """Keep persona banter from replacing a direct request for recognition."""

    if not re.search(r"(?:快|请|好好)?夸(?:夸)?我|表扬我|称赞我", str(user_message or "")):
        return result
    reply = str(result.get("reply") or "").strip()
    if re.search(r"做得|厉害|不错|漂亮|值得|恭喜|了不起|优秀|真棒|有两下子", reply):
        return result
    variants = (
        "行，这次确实做得漂亮。",
        "能把困扰这么久的问题解决掉，值得表扬。",
        "好吧，这回我承认，你做得很不错。",
    )
    index = sum(ord(character) for character in str(user_message or "")) % len(variants)
    repaired = dict(result)
    repaired["reply"] = variants[index] + reply
    if str(repaired.get("emotion") or "") not in {"excited", "proud", "amused", "affectionate"}:
        repaired["emotion"] = "proud"
    repaired["gesture"] = "perk"
    repaired["directSocialRequestRepaired"] = True
    return repaired


def enforce_explicit_supportive_tone(user_message: str, result: dict[str, Any]) -> dict[str, Any]:
    """Honor an explicit request for gentle reassurance when the model labels it neutral."""

    text = str(user_message or "")
    supportive = bool(re.search(r"已经做得够多|今天就到这里|该休息|休息一下|别太累|安慰(?:我)?", text))
    gentle_request = bool(re.search(r"轻声|温柔(?:地)?|柔和(?:地)?|慢慢告诉", text))
    if not supportive or not gentle_request:
        return result
    if str(result.get("emotion") or "") not in {"neutral", "thinking", "focused"}:
        return result
    repaired = dict(result)
    repaired["emotion"] = "concerned"
    repaired["gesture"] = "soften"
    repaired["voiceStyle"] = "soft"
    repaired["voiceTone"] = "gentle"
    repaired["voiceIntensity"] = "subtle"
    repaired["explicitSupportiveToneRepaired"] = True
    return repaired


def enforce_distress_support_tone(user_message: str, result: dict[str, Any]) -> dict[str, Any]:
    """Keep explicit self-doubt in a supportive expression instead of annoyance."""

    text = re.sub(r"\s+", "", str(user_message or ""))
    self_doubt = bool(re.search(
        r"(?:怀疑|觉得|是不是).{0,8}(?:自己|我).{0,10}(?:根本)?(?:不适合|不行|没用|做不好)|"
        r"(?:我|自己).{0,8}(?:根本)?(?:不适合|不配|没能力).{0,8}(?:研究|工作|继续)|"
        r"一次失败.{0,10}(?:否定|怀疑).{0,8}(?:自己|我)",
        text,
    ))
    if not self_doubt or str(result.get("emotion") or "") not in {
        "annoyed", "neutral", "teasing", "amused", "skeptical",
    }:
        return result
    repaired = dict(result)
    repaired["emotion"] = "concerned"
    repaired["gesture"] = "soften"
    repaired["voiceStyle"] = "soft"
    if str(repaired.get("voiceTone") or "") not in {"comforting", "gentle", "warm"}:
        repaired["voiceTone"] = "comforting"
    repaired["voiceIntensity"] = "subtle"
    repaired["distressSupportToneRepaired"] = True
    return repaired


def enforce_explicit_laugh_request(user_message: str, result: dict[str, Any]) -> dict[str, Any]:
    """Make the dedicated laughing expression reliable for an explicit laugh request."""

    if not re.search(r"放开(?:地)?大笑|大笑一次|笑出声|哈哈大笑", str(user_message or "")):
        return result
    repaired = dict(result)
    reply = str(repaired.get("reply") or "").strip()
    if re.search(r"(?:要我|让我).{0,12}(?:大笑|放声(?:大)?笑).{0,18}(?:不像|不行|别想)", reply):
        reply = "哈哈……！好吧，这次算你赢，确实有点离谱。"
    elif not re.search(r"哈哈|呵呵|笑出声", reply):
        reply = "哈哈……！" + reply
    repaired["reply"] = reply
    repaired["emotion"] = "laughing"
    repaired["gesture"] = "laugh"
    repaired["voiceStyle"] = "energetic"
    repaired["voiceTone"] = "laughing"
    repaired["voiceIntensity"] = "strong"
    repaired["explicitLaughRequestRepaired"] = True
    return repaired


def enforce_explicit_choice_grounding(user_message: str, result: dict[str, Any]) -> dict[str, Any]:
    """Retain user-provided A/B conditions when the reply omits both labels."""

    text = str(user_message or "").strip()
    if not (re.search(r"方案\s*A", text, re.I) and re.search(r"方案\s*B", text, re.I)):
        return result
    reply = str(result.get("reply") or "").strip()
    if re.search(r"方案\s*[AB]|(?:^|[^A-Za-z])[AB](?:[^A-Za-z]|$)", reply, re.I):
        return result
    clauses = [item.strip(" ，。") for item in re.split(r"[；;\n]", text) if item.strip()]
    grounded = [item for item in clauses if re.search(r"方案\s*[AB]", item, re.I)]
    if len(grounded) < 2:
        return result
    repaired = dict(result)
    repaired["reply"] = "明白：" + "；".join(grounded[:2]) + "。" + reply
    repaired["explicitChoiceGroundingRepaired"] = True
    return repaired


def completion_risk_reasons(
    result: dict[str, Any],
    contract: TurnContract,
    *,
    text_mutated: bool = False,
) -> list[str]:
    reasons = list(contract_completion_issues(result, contract))
    reply_length = len(re.sub(r"\s+", "", str(result.get("reply") or "")))
    if len(contract.required_acts) > 1 and reply_length < 16:
        reasons.append("reply_too_short_for_required_acts")
    spoken_length = len(re.sub(r"\s+", "", str(result.get("spokenTextJa") or "")))
    bilingual_ratio = spoken_length / max(1, reply_length)
    if bilingual_ratio < 0.18 or bilingual_ratio > 5.5:
        reasons.append("bilingual_core_alignment_risk")
    if result.get("structuredOutputInvalid") and not result.get("structuredOutputResolved"):
        reasons.append("structured_output_invalid")
    if result.get("streamProtocolIssue"):
        reasons.append("stream_protocol_issue")
    finish_reason = str(result.get("upstreamFinishReason") or "").strip().lower()
    if finish_reason and finish_reason not in {"stop", "end_turn", "tool_calls"}:
        reasons.append("abnormal_upstream_finish_reason:" + finish_reason)
    if result.get("nicknameReactionGroundingViolation"):
        reasons.append("nickname_reaction_grounding_violation")
    action_receipt = (
        result.get("actionReceipt")
        if isinstance(result.get("actionReceipt"), Mapping)
        else {}
    )
    action_receipts = (
        [item for item in result.get("actionReceipts", []) if isinstance(item, Mapping)]
        if isinstance(result.get("actionReceipts"), list)
        else []
    )
    if (
        result.get("_fileOutputExpected")
        and not (
            isinstance(result.get("_fileOutputs"), list)
            and result.get("_fileOutputs")
        )
        and not (
            isinstance(result.get("files"), list)
            and result.get("files")
        )
    ):
        reasons.append("required_generated_file_missing")
    memory_action = str(result.get("memoryAction") or "none").strip().lower()
    if (
        memory_action != "none"
        and not result.get("structuredSideEffectVerified")
    ):
        # A state-changing memory decision is not a low-risk presentation
        # field. The compact protocol may contain two fluent but contradictory
        # language tracks (or a reply unrelated to the declared save). Route
        # it through the semantic judge instead of guessing from local words.
        reasons.append("structured_side_effect_requires_semantic_audit")
    if (
        (action_receipt or action_receipts)
        and not result.get("externalActionOutcomeVerified")
    ):
        reasons.append("external_action_outcome_requires_semantic_audit")
    for flag in (
        "replyIntegrityUnverified",
        "taskCompletionUnverified",
        "contextGroundingUnverified",
        "toolGroundingUnverified",
        "webSynthesisUnverified",
    ):
        if result.get(flag):
            reasons.append(flag)
    if text_mutated:
        reasons.append("postprocess_text_mutation")
    return list(dict.fromkeys(reasons))


def backend_can_confirm_core_dialogue_completion(
    result: dict[str, Any],
    contract: TurnContract,
    *,
    text_mutated: bool,
    upstream_finish_reason: str,
) -> bool:
    """Confirm a low-risk one-act dialogue from backend-owned evidence."""

    if text_mutated:
        return False
    if str(result.get("semanticKind") or "") in {"clarification", "clarify"}:
        # A clarification is a different terminal outcome from completing the
        # original task. It must pass the missing-input semantic audit and bind
        # its own contract before the backend may confirm completion.
        return False
    if not result.get("coreDialogueProtocol"):
        if not ARCHITECTURE_FEATURES.conditional_semantic_audit_enabled:
            return False
        recovery_mode = str(result.get("semanticRecoveryMode") or "")
        low_risk_recovery = recovery_mode in {
            "strict_json",
            "fenced_json",
            "embedded_json",
        }
        ordinary_semantic_stream = bool(
            str(result.get("source") or "") in {"api", "api-stream"}
            and not result.get("streamProtocolIssue")
            and not result.get("plainTextSalvaged")
        )
        if not (low_risk_recovery or ordinary_semantic_stream):
            return False
    text_only_delivery = bool(result.get("textOnlyDelivery"))
    if result.get("dialogueFieldRepairFailed") and not text_only_delivery:
        return False
    finish_reason = str(upstream_finish_reason or result.get("upstreamFinishReason") or "").strip().lower()
    if finish_reason not in {"stop", "end_turn"}:
        return False
    if not str(result.get("reply") or "").strip():
        return False
    if not str(result.get("spokenTextJa") or "").strip() and not text_only_delivery:
        return False
    if reply_integrity_issues(result):
        return False
    if len(contract.required_acts) > 1:
        return False
    if "complete_requested_task" in contract.required_acts:
        # A fluent acknowledgement or request for the missing material is not
        # proof that the task itself was completed. Request turns therefore use
        # the short semantic audit, which can confirm completion or transition
        # to the audited missing-input contract.
        return False
    if contract.primary_act == "respond_other":
        # ``other`` is deliberately the low-confidence catch-all speech act.
        # Structural fluency cannot prove that a request synonym was not
        # missed or that a question-shaped reply is not awaiting input.
        return False
    if result.get("toolUsed"):
        # Tool/research turns used to rely on model-authored completion flags
        # from the heavy JSON protocol. In semantic-v3 the backend can confirm
        # a one-act turn after receipts and grounding gates have succeeded.
        failed_visual_outcome = bool(
            contract.required_acts
            == ("explain_current_visual_observation_failure",)
            and str(result.get("toolStatus") or "") in {
                "failed", "error", "partial",
            }
        )
        if str(result.get("toolStatus") or "") != "ok" and not failed_visual_outcome:
            return False
    allowed_format_recovery = str(result.get("semanticRecoveryMode") or "") in {
        "strict_json",
        "fenced_json",
        "embedded_json",
    }
    if any(result.get(flag) for flag in (
        "replyIntegrityUnverified",
        "taskCompletionUnverified",
        "contextGroundingUnverified",
        "toolGroundingUnverified",
        "webSynthesisUnverified",
    )):
        return False
    if result.get("streamProtocolIssue") and not allowed_format_recovery:
        return False
    return True


def generic_missing_input_clarification_candidate(
    result: Mapping[str, Any],
    contract: TurnContract | None = None,
) -> bool:
    """Return true only for an ordinary typed clarification awaiting audit.

    Schedule/Todo and browser continuations already own typed pending state and
    must not be rebound by the generic dialogue contract.
    """

    semantic_kind = str(result.get("semanticKind") or "")
    typed_clarification = semantic_kind in {"clarification", "clarify"}
    request_contract = bool(
        contract is not None
        and "complete_requested_task" in contract.required_acts
    )
    expected_response_type = str(result.get("expectedResponseType") or "")
    if not typed_clarification and not request_contract:
        return False
    if (
        typed_clarification
        and (
            result.get("requiresUserResponse") is not True
            or expected_response_type not in {"free_text", "confirmation", "choice"}
        )
    ):
        return False
    if (
        expected_response_type == "browser_target"
        or str(result.get("clarificationActionId") or "").strip()
    ):
        return False
    schedule = (
        result.get("scheduleDecision")
        if isinstance(result.get("scheduleDecision"), Mapping)
        else {}
    )
    intent = schedule.get("intent") if isinstance(schedule.get("intent"), Mapping) else {}
    policy = schedule.get("policy") if isinstance(schedule.get("policy"), Mapping) else {}
    if (
        str(intent.get("kind") or "") == "clarification"
        or str(policy.get("action") or "") in {"clarify", "request_clarification"}
        or bool(schedule.get("workflow"))
    ):
        return False
    return True


def clarification_context_for_turn(
    result: Mapping[str, Any],
    prepared_turn: PreparedTurn,
    chat_metrics: Mapping[str, Any],
) -> dict[str, Any]:
    """Build a bounded evidence view for the missing-input semantic audit."""

    attachments = (
        [item for item in result.get("attachments", []) if isinstance(item, Mapping)]
        if isinstance(result.get("attachments"), list)
        else []
    )
    tool_results = (
        [item for item in result.get("_conversationToolResults", []) if isinstance(item, Mapping)]
        if isinstance(result.get("_conversationToolResults"), list)
        else []
    )
    successful_tools = []
    for item in tool_results[:12]:
        status = str(item.get("status") or item.get("toolStatus") or "").strip().lower()
        if not status and item.get("ok") is True:
            status = "ok"
        if status not in {"ok", "success", "accepted", "completed"}:
            continue
        successful_tools.append({
            "tool": str(item.get("tool") or item.get("name") or "")[:80],
            "status": status,
            "hasContent": bool(
                item.get("content") or item.get("text") or item.get("result")
                or item.get("extractedText") or item.get("imageDescription")
                or item.get("contentPreview") or item.get("visualCaption")
            ),
            "hasArtifact": bool(
                item.get("path") or item.get("storedPath") or item.get("artifactId")
                or item.get("attachmentId") or item.get("imageArtifact")
            ),
        })
    capability = dict(prepared_turn.capability_envelope or {})
    context_resolution = (
        chat_metrics.get("contextResolution")
        if isinstance(chat_metrics.get("contextResolution"), Mapping)
        else {}
    )
    return {
        "boundAttachments": [{
            "name": str(item.get("name") or item.get("filename") or "")[:160],
            "contentType": str(
                item.get("mimeType") or item.get("contentType") or item.get("type") or ""
            )[:100],
            "hasExtractedContent": bool(
                item.get("text") or item.get("content") or item.get("extractedText")
            ),
        } for item in attachments[:8]],
        "successfulToolResults": successful_tools,
        "fileOutputCount": max(
            len(result.get("_fileOutputs", []))
            if isinstance(result.get("_fileOutputs"), list) else 0,
            len(result.get("files", []))
            if isinstance(result.get("files"), list) else 0,
        ),
        "resolvedSubject": str(context_resolution.get("resolvedSubject") or "")[:500],
        "resolvedQuestion": str(context_resolution.get("resolvedQuestion") or "")[:500],
        "allowedTools": list(capability.get("allowed_tools") or capability.get("allowedTools") or [])[:30],
        "requiredTools": list(capability.get("required_tools") or capability.get("requiredTools") or [])[:20],
        "modelMayRequestTools": bool(
            capability.get("may_escalate", capability.get("mayEscalate", False))
        ),
    }


def authoritative_outcome_for_result(result: Mapping[str, Any]) -> Any:
    """Return bounded state/action/artifact outcomes without generated bodies."""

    actions = (
        [dict(item) for item in result["actionReceipts"] if isinstance(item, Mapping)]
        if isinstance(result.get("actionReceipts"), list) and result["actionReceipts"]
        else [dict(result["actionReceipt"])]
        if isinstance(result.get("actionReceipt"), Mapping)
        else []
    )
    generated_files: list[dict[str, Any]] = []
    outputs = result.get("_fileOutputs")
    if isinstance(outputs, list):
        for item in outputs[:MAX_GENERATED_FILES]:
            if not isinstance(item, Mapping) or not isinstance(item.get("content"), str):
                continue
            content = str(item.get("content") or "")
            generated_files.append({
                "status": "staged",
                "name": safe_attachment_name(
                    item.get("fileName") or item.get("name"),
                    "output.txt",
                ),
                "size": len(content.encode("utf-8")),
            })
    if not generated_files and isinstance(result.get("files"), list):
        generated_files = [{
            "status": "published",
            "name": str(item.get("name") or "output.txt")[:180],
            "size": int(item.get("size") or 0),
            "id": str(item.get("id") or "")[:80],
        } for item in result["files"][:MAX_GENERATED_FILES] if isinstance(item, Mapping)]
    memory_action = str(result.get("memoryAction") or "none").strip().lower()
    memory_outcome: dict[str, Any] = {}
    if memory_action != "none":
        updates = result.get("memoryUpdates")
        bounded_updates = [
            str(item.get("content") or item.get("text") or item)
            if isinstance(item, Mapping) else str(item)
            for item in (updates[:4] if isinstance(updates, list) else [])
        ]
        memory_outcome = {
            "action": memory_action,
            "status": "accepted_for_persistence",
            "updates": [item[:500] for item in bounded_updates if item.strip()],
        }
    if generated_files or memory_outcome:
        return {
            **({"actions": actions} if actions else {}),
            **({"memory": memory_outcome} if memory_outcome else {}),
            **({"generatedFiles": generated_files} if generated_files else {}),
        }
    if result.get("_fileOutputExpected"):
        return {
            "generatedFiles": [],
            "requiredArtifactStatus": "missing",
        }
    if len(actions) == 1:
        return actions[0]
    return actions


def audit_turn_contract_with_model(
    settings: dict[str, Any],
    interpretation: UtteranceInterpretation,
    contract: TurnContract,
    result: dict[str, Any],
    *,
    request_id: str,
    clarification_context: Mapping[str, Any] | None = None,
    task_dialogue: Sequence[Mapping[str, Any]] = (),
) -> dict[str, Any]:
    """Use a domain-independent semantic judge only for risky candidates."""

    action_outcome = authoritative_outcome_for_result(result)
    payload: dict[str, Any] = {
        "model": settings["apiModel"],
        "temperature": 0.0,
        "max_tokens": 320,
        "messages": [
            {"role": "system", "content": (
                "你是回答完成性审计器，不扮演角色，也不改写答案。"
                "只输出 JSON："
                "{\"answersCurrentIntent\":true,\"standalone\":true,"
                "\"dependsOnUndeliveredPrefix\":false,\"zhJaCoreAligned\":true,"
                "\"actionOutcomeAligned\":true,"
                "\"allRequiredActsCompleted\":true,"
                "\"clarificationNecessary\":false,"
                "\"clarificationAddressesMissingInput\":false,"
                "\"availableOrAuthorizedToolCouldResolve\":false,"
                "\"missingInput\":\"\",\"reason\":\"\","
                "\"completedActs\":[\"...\"],\"missingRequiredActs\":[],"
                "\"confidence\":0.0}。"
                "根据当前用户语义、requiredActs、中文回答和日语发声稿判断；"
                "不能因为语言流畅就判定完成。若提供 authoritativeActionOutcome，"
                "其中可能包含后端动作回执、待持久化的记忆决定或已生成产物，"
                "必须同时判断这些结构化结果是否符合当前用户意图，以及中日文回答"
                "是否与结果一致；成功后继续询问同一目标、"
                "失败后声称成功都不一致。若 clarificationCandidate=true，只有当前"
                "用户消息和已有动作回执确实缺少完成任务所必需的输入，并且回答只索取"
                "那个缺失输入时，clarificationNecessary 和"
                "clarificationAddressesMissingInput 才能为 true；可直接完成的任务、"
                "可选追问、泛泛邀请补充或逃避回答必须判为 false。"
                "availableInputContext 中已有附件、成功工具结果或已授权工具能够取得"
                "所需内容时，availableOrAuthorizedToolCouldResolve 必须为 true，且不得"
                "通过通用澄清。missingInput 写具体缺失项，reason 简述依据。"
                "澄清需要用户下一轮回答是预期行为，不等于依赖未显示的助手前缀；"
                "standalone 和 dependsOnUndeliveredPrefix 只判断当前输出是否缺少一段"
                "本应先展示的助手文本。requiredActs 是内部结果标签，不是回答必须"
                "逐字出现的口令：按回答实际内容判断是否完成。尤其当用户要求检查、"
                "评审或评价已经给出的材料时，只要回答给出具体判断、风险或改进建议，"
                "就属于实质完成 complete_requested_task，不得因为没有自称“检查完成”"
                "而否定。completedActs 和 missingRequiredActs 只能使用 requiredActs 中"
                "的原标签；子步骤和解释写进 reason。"
                "recentDialogue 是实际发生的对话，用于理解省略指代、被处理的内容和用户纠正，不是新任务。"
                "originalUserMessage 及用户在对话中指定的范围优先于 semanticText 摘要。"
                "对改写、总结或格式转换任务，直接返回处理后的内容即可，不要求额外宣告完成、标题或过程说明。"
                "若 requiredActs 只是 respond_to_current_utterance，针对所问对象明确说明不能判断或拒绝并解释理由，也可以完成回应；"
                "完成回应不等于赞同用户、给出用户强求的结论或证明回答内容质量优秀，不能仅因用户坚持就要求反复重写。"
                "这不适用于伪称外部操作成功：动作任务仍必须核对真实回执，不能把拒绝算成操作已完成。"
            )},
            {"role": "user", "content": json.dumps({
                "originalUserMessage": interpretation.original_text,
                "recentDialogue": list(task_dialogue),
                "semanticText": interpretation.semantic_text,
                "primarySpeechAct": interpretation.primary_speech_act,
                "requiredActs": list(contract.required_acts),
                "replyZh": str(result.get("reply") or ""),
                "spokenTextJa": str(result.get("spokenTextJa") or ""),
                "clarificationCandidate": generic_missing_input_clarification_candidate(
                    result,
                    contract,
                ),
                "modelDeclaredKind": str(result.get("semanticKind") or ""),
                "expectedResponseType": str(result.get("expectedResponseType") or ""),
                "availableInputContext": dict(clarification_context or {}),
                "authoritativeActionOutcome": action_outcome,
            }, ensure_ascii=False)},
        ],
    }
    if settings.get("useResponseFormat"):
        payload["response_format"] = {"type": "json_object"}
    if "deepseek.com" in settings["apiEndpoint"]:
        payload["thinking"] = {"type": "disabled"}
    content = send_upstream_chat_payload(
        settings,
        payload,
        timeout=45,
        request_id=request_id,
        purpose="turn_contract_audit",
    )
    audit = parse_json_object(content)
    if not isinstance(audit, dict):
        raise UpstreamProtocolError("Turn Contract audit returned no JSON object")
    completed = audit.get("completedActs")
    completed_set = {
        str(item)
        for item in completed
        if str(item)
    } if isinstance(completed, list) else set()
    declared_missing = audit.get("missingRequiredActs")
    declared_missing_items = (
        [str(item) for item in declared_missing if str(item)]
        if isinstance(declared_missing, list) else []
    )
    declared_missing_set = {
        item for item in declared_missing_items if item in contract.required_acts
    }
    all_required_completed = audit.get("allRequiredActsCompleted")
    if all_required_completed is True and not declared_missing_items:
        missing: list[str] = []
        audit["completedActs"] = list(contract.required_acts)
    elif all_required_completed is True:
        # An aggregate success cannot coexist with any declared missing act.
        # Unknown labels are protocol inconsistency, not evidence of success.
        missing = list(contract.required_acts)
        audit["completionVerdictInconsistent"] = True
    elif all_required_completed is False:
        missing = (
            [item for item in contract.required_acts if item in declared_missing_set]
            or list(contract.required_acts)
        )
    else:
        # Backward compatibility for providers that have not yet emitted the
        # aggregate semantic verdict. Exact labels are only a legacy fallback,
        # not a second local decision after the model has judged completion.
        missing = [item for item in contract.required_acts if item not in completed_set]
    reply_present = bool(str(result.get("reply") or "").strip())
    spoken_present = bool(str(result.get("spokenTextJa") or "").strip())
    text_only_delivery = bool(result.get("textOnlyDelivery"))
    clarification_candidate = generic_missing_input_clarification_candidate(
        result,
        contract,
    )
    delivery_structure_valid = bool(
        reply_present
        and (
            (audit.get("zhJaCoreAligned") is True and spoken_present)
            or (text_only_delivery and not spoken_present)
        )
        and audit.get("standalone") is True
        and not bool(audit.get("dependsOnUndeliveredPrefix"))
    )
    clarification_delivery_valid = bool(
        reply_present
        and (
            (audit.get("zhJaCoreAligned") is True and spoken_present)
            or (text_only_delivery and not spoken_present)
        )
    )
    audit["clarificationPasses"] = bool(
        clarification_candidate
        and clarification_delivery_valid
        and audit.get("clarificationNecessary") is True
        and audit.get("clarificationAddressesMissingInput") is True
        and audit.get("availableOrAuthorizedToolCouldResolve") is False
    )
    audit["passes"] = bool(
        audit.get("answersCurrentIntent") is True
        and audit.get("standalone") is True
        and not bool(audit.get("dependsOnUndeliveredPrefix"))
        and reply_present
        and (
            (audit.get("zhJaCoreAligned") is True and spoken_present)
            or (text_only_delivery and not spoken_present)
        )
        and not missing
        and (not action_outcome or audit.get("actionOutcomeAligned") is True)
    )
    audit["deliveryStructureValid"] = delivery_structure_valid
    audit["missingRequiredActs"] = missing
    return audit


def apply_missing_input_clarification_audit(
    interpretation: UtteranceInterpretation,
    contract: TurnContract,
    candidate: dict[str, Any],
    audit: Mapping[str, Any],
) -> tuple[TurnContract, dict[str, Any], bool]:
    """Apply the same audited contract transition before or after a rewrite."""

    if (
        not audit.get("clarificationPasses")
        or bool(candidate.get("emptyReply"))
        or str(candidate.get("reply") or "").strip() == EMPTY_REPLY_FALLBACK
        or str(candidate.get("source") or "") == "local-empty-recovery"
        or bool(candidate.get("emptyReplyRecoveryReason"))
    ):
        return contract, candidate, False
    rebound = bind_missing_input_clarification_contract(
        contract,
        semantic_text=interpretation.semantic_text,
    )
    accepted = dict(candidate)
    accepted.update({
        "completedActs": list(rebound.required_acts),
        "completedActsProvided": True,
        "standalone": True,
        "standaloneProvided": True,
        "dependsOnUndeliveredPrefix": False,
        "dependsOnUndeliveredPrefixProvided": True,
        "turnComplete": True,
        "turnCompleteProvided": True,
        "requiresUserResponse": True,
        "requiresUserResponseProvided": True,
        "expectedResponseType": str(accepted.get("expectedResponseType") or "free_text"),
        "semanticKind": "clarification",
        "turnContractVerification": "semantic_missing_input_clarification",
        "missingInputClarificationAudit": {
            "missingInput": str(audit.get("missingInput") or "")[:500],
            "reason": str(audit.get("reason") or "")[:500],
            "confidence": clamp_float(audit.get("confidence"), 0, 1, 0),
        },
    })
    return rebound, accepted, True


def rewrite_reply_to_turn_contract(
    settings: dict[str, Any],
    interpretation: UtteranceInterpretation,
    contract: TurnContract,
    result: dict[str, Any],
    audit: dict[str, Any],
    *,
    request_id: str,
    persona_snapshot: PersonaContextSnapshot | None = None,
    task_dialogue: Sequence[Mapping[str, Any]] = (),
) -> dict[str, Any]:
    """Ask the character model to regenerate; the backend never authors the answer."""

    nickname_contract = nickname_reaction_prompt(
        interpretation.original_text,
        request_id,
    )
    payload: dict[str, Any] = {
        "model": settings["apiModel"],
        "temperature": 0.48,
        "max_tokens": (
            6000
            if result.get("_fileOutputExpected")
            else fast_stream_token_budget(
                choose_turn_policy(
                    interpretation.original_text,
                    interpretation=interpretation,
                )
            )
        ),
        "messages": [
            *persona_repair_prefix(persona_snapshot, legacy_system_prompt=True),
            *task_dialogue,
            {"role": "system", "content": UTTERANCE_STREAM_REPLY_RULE},
            {"role": "system", "content": core_dialogue_turn_contract_prompt(
                interpretation,
                contract,
            )},
            *(
                [{"role": "system", "content": tool_context_prompt(
                    [
                        item for item in result.get("_conversationToolResults", [])
                        if isinstance(item, Mapping)
                    ],
                    {},
                    max_chars=52_000,
                )}]
                if isinstance(result.get("_conversationToolResults"), list)
                and result.get("_conversationToolResults")
                else []
            ),
            *(
                [{"role": "system", "content": ATTACHMENT_REPLY_RULE}]
                if result.get("_fileOutputExpected") else []
            ),
            *(
                [{"role": "system", "content": nickname_contract}]
                if nickname_contract
                else []
            ),
            {"role": "system", "content": (
                "上一版没有完成本轮合同。重新生成一份完整、独立的最终回答；"
                "直接回答当前用户，不要提审计、合同、修复或上一版。"
                "authoritativeActionOutcome 是后端最终回执：必须据此报告成功、"
                "待确认或失败，不得继续沿用与它冲突的旧尝试结果。"
            )},
            {"role": "user", "content": json.dumps({
                "currentUserMessage": interpretation.original_text,
                "previousCandidate": {
                    "reply": str(result.get("reply") or ""),
                    "spokenTextJa": str(result.get("spokenTextJa") or ""),
                },
                "audit": audit,
                "authoritativeActionOutcome": authoritative_outcome_for_result(result),
            }, ensure_ascii=False)},
        ],
    }
    if settings.get("useResponseFormat"):
        payload["response_format"] = {"type": "json_object"}
    if "deepseek.com" in settings["apiEndpoint"]:
        payload["thinking"] = {"type": "disabled"}
    content = send_upstream_chat_payload(
        settings,
        payload,
        timeout=75,
        request_id=request_id,
        purpose="turn_contract_rewrite",
    )
    rewritten = normalize_model_reply(content, settings=settings)
    if normalize_speech_language(rewritten.get("speechLanguage")) == "ja-JP" and str(rewritten.get("reply") or "").strip() and not str(rewritten.get("spokenTextJa") or "").strip():
        # A late rewrite runs after the normal speech-alignment stage. Repair
        # the missing translation, not the answer again, before reviewing it.
        rewritten = repair_dialogue_fields_once(
            settings, rewritten, {"missingFields": ["spokenTextJa"]},
            user_message=interpretation.original_text, recent_messages=[],
            relationship_state={}, request_id=request_id,
            persona_snapshot=persona_snapshot,
        )
    rewritten = enforce_nickname_reaction_grounding(
        interpretation.original_text,
        rewritten,
        reaction_key=request_id,
        persona_snapshot=persona_snapshot,
    )
    for key in (
        "_conversationToolResults", "_fileOutputs", "attachments", "files",
        "sources", "sourceBatch", "toolUsed", "toolStatus", "toolErrors",
        "toolResults", "actionReceipt", "actionReceipts", "todoContext",
        "webEvidenceStatus", "memoryAction", "memoryActionProvided",
        "memoryUpdates", "memoryUpdatesProvided", "_memoryCandidates",
        "_memoryUpdateTypes", "_fileOutputExpected",
    ):
        if key in result and (
            key not in rewritten
            or key == "_fileOutputs" and not rewritten.get(key)
        ):
            rewritten[key] = result[key]
    preserve_attachment_delivery(result, rewritten)
    rewritten["turnContractRewrittenByModel"] = True
    if persona_snapshot is not None:
        rewritten["personaContextSnapshotId"] = persona_snapshot.snapshot_id
    return rewritten


def ensure_turn_contract_completion(
    settings: dict[str, Any],
    interpretation: UtteranceInterpretation,
    contract: TurnContract,
    result: dict[str, Any],
    *,
    request_id: str,
    text_mutated: bool = False,
    allow_rewrite: bool = True,
    upstream_finish_reason: str = "",
    persona_snapshot: PersonaContextSnapshot | None = None,
    clarification_context: Mapping[str, Any] | None = None,
    task_dialogue: Sequence[Mapping[str, Any]] = (),
    cognitive_body: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    candidate = synchronize_response_waiting(result)
    attachment_issues = attachment_response_issues(candidate, cognitive_body or {},
        task=(cognitive_execution_state(cognitive_body).get("task") or {}) if isinstance(cognitive_body, dict) else {})
    if candidate.get("_fileOutputExpected") and not candidate.get("_fileOutputs") and not candidate.get("files"):
        attachment_issues.append("required_generated_file_missing")
    if attachment_issues:
        repair_report = {"problems": list(dict.fromkeys(attachment_issues)), "repair": ATTACHMENT_ACTION_RULE,
                         "attachmentCapabilities": attachment_edit_capabilities(cognitive_body or {})}
        if isinstance(cognitive_body, dict) and cognitive_turn_state(cognitive_body):
            raise FinalProjectionAuditRepairError(candidate, repair_report, repair_report)
        if allow_rewrite:
            candidate = rewrite_reply_to_turn_contract(settings, interpretation, contract, candidate, repair_report,
                request_id=request_id, persona_snapshot=persona_snapshot, task_dialogue=task_dialogue)
            return ensure_turn_contract_completion(settings, interpretation, contract, candidate,
                request_id=request_id, allow_rewrite=False, persona_snapshot=persona_snapshot,
                cognitive_body=cognitive_body, upstream_finish_reason=upstream_finish_reason,
                clarification_context=clarification_context, task_dialogue=task_dialogue)
        raise CognitiveProtocolError("attachment_delivery_invalid:" + ",".join(attachment_issues))
    verification = candidate.get("_cognitiveOutcomeVerification") or {}
    if verification.get("valid") is True:
        if not str(candidate.get("reply") or "").strip():
            raise CognitiveProtocolError("final_answer_missing")
        if (candidate.get("_cognitiveOutcome") or candidate.get("outcome") or {}).get("status") == "needs_input":
            contract = bind_missing_input_clarification_contract(contract, semantic_text=interpretation.semantic_text)
        completed_acts = None
        verification_method = "cognitive_outcome_validation"
        if not settings.get("cognitiveSemanticAuditEnabled", False):
            # These are delivery declarations based on the normal model's
            # machine-validated outcome, not proof of semantic correctness.
            # Keep outcome/taskStatus unchanged, including needs_input,
            # partial and failed: a complete reply need not complete a task.
            completed_acts = tuple(contract.required_acts)
        elif isinstance(cognitive_body, Mapping) and cognitive_turn_state(cognitive_body):
            report = audit_cognitive_candidate(
                cognitive_body,
                settings,
                candidate,
                cognitive_turn_state(cognitive_body),
                request_id=request_id,
                final_projection=True,
                contract=contract,
            )
            # Unsupported providers return None and retain the legacy
            # compatibility path below. A supported cognitive audit must
            # provide the delivery proof itself; no contract act is copied.
            if report is not None:
                completed_acts = _validated_cognitive_audit_completed_acts(
                    report, contract,
                )
                if completed_acts is None:
                    raise CognitiveProtocolError(
                        "cognitive_semantic_audit_completed_acts_invalid"
                    )
                verification_method = "cognitive_semantic_audit"
        if completed_acts is not None:
            candidate.update({
                "outcome": deepcopy(candidate.get("_cognitiveOutcome") or candidate.get("outcome") or {}),
                "outcomeVerification": deepcopy(verification),
                "completedActs": list(completed_acts),
                "completedActsProvided": True,
                "turnContractVerification": verification_method,
                "turnContractSemanticAuditCalls": 0,
                "turnContractRewriteCalls": 0,
                "turnContract": contract.to_dict(),
                "utteranceInterpretation": interpretation.to_dict(),
                "standalone": True,
                "standaloneProvided": True,
                "turnComplete": True,
                "turnCompleteProvided": True,
                "dependsOnUndeliveredPrefix": False,
                "dependsOnUndeliveredPrefixProvided": True,
            })
            candidate["finalTurnEnvelope"] = final_turn_envelope(
                candidate, contract, turn_id=f"{request_id}:turn",
                delivery_path="atomic" if allow_rewrite else "stream",
                upstream_finish_reason=upstream_finish_reason or None,
            ).to_dict()
            return candidate
    if upstream_finish_reason:
        candidate["upstreamFinishReason"] = upstream_finish_reason
    source = str(candidate.get("source") or "")
    trusted_local = bool(
        not configured(settings)
        or (
            source
            and source not in {"api", "api-stream", "local-empty-recovery"}
            and not candidate.get("_fileOutputExpected")
        )
    )
    visual_terminal_boundary = bool(candidate.get("visualGroundingTerminalBoundary"))
    visual_grounding_audit = (
        candidate.get("visualGroundingAudit")
        if isinstance(candidate.get("visualGroundingAudit"), dict)
        else {}
    )
    verified_visual_answer = bool(
        visual_grounding_audit.get("passes")
        and str(candidate.get("visualGroundingTextFingerprint") or "")
        == visual_grounding_text_fingerprint(candidate)
    )
    if visual_terminal_boundary:
        # This system-owned boundary is the completed safe outcome of a visual
        # task whose factual candidate failed evidence review.  Sending it to a
        # generic contract rewriter would discard the visual packet and could
        # recreate the very hallucination that was just blocked.
        candidate.update({
            "completedActs": list(contract.required_acts),
            "completedActsProvided": True,
            "standalone": True,
            "standaloneProvided": True,
            "dependsOnUndeliveredPrefix": False,
            "dependsOnUndeliveredPrefixProvided": True,
            "turnComplete": True,
            "turnCompleteProvided": True,
            "turnContractVerification": "visual_fail_closed_boundary",
        })
    elif verified_visual_answer:
        # The exact bilingual text already passed the dedicated visual audit.
        # A generic contract rewrite cannot see that evidence packet and must
        # not overwrite an accepted answer with an unrelated hallucination.
        candidate.update({
            "completedActs": list(contract.required_acts),
            "completedActsProvided": True,
            "standalone": True,
            "standaloneProvided": True,
            "dependsOnUndeliveredPrefix": False,
            "dependsOnUndeliveredPrefixProvided": True,
            "turnComplete": True,
            "turnCompleteProvided": True,
            "turnContractVerification": "verified_visual_grounding",
        })
    elif trusted_local:
        candidate.update({
            "completedActs": list(contract.required_acts),
            "completedActsProvided": True,
            "standalone": True,
            "standaloneProvided": True,
            "dependsOnUndeliveredPrefix": False,
            "dependsOnUndeliveredPrefixProvided": True,
            "turnComplete": True,
            "turnCompleteProvided": True,
            "turnContractVerification": "trusted_local_route",
        })
    elif backend_can_confirm_core_dialogue_completion(
        candidate,
        contract,
        text_mutated=text_mutated,
        upstream_finish_reason=upstream_finish_reason,
    ):
        candidate.update({
            "completedActs": list(contract.required_acts),
            "completedActsProvided": True,
            "standalone": True,
            "standaloneProvided": True,
            "dependsOnUndeliveredPrefix": False,
            "dependsOnUndeliveredPrefixProvided": True,
            "turnComplete": True,
            "turnCompleteProvided": True,
            "turnContractVerification": "backend_core_dialogue",
        })
    reasons = completion_risk_reasons(
        candidate,
        contract,
        text_mutated=text_mutated and not trusted_local,
    )
    if trusted_local:
        # Local simulation and other server-owned routes have no upstream
        # model available for semantic audit or rewrite. Their completion
        # metadata was established above from the backend-owned contract; do
        # not turn a presentation-only bilingual heuristic into a call to an
        # empty API endpoint.
        reasons = []
    audit: dict[str, Any] = {}
    semantic_audit_calls = 0
    contract_rewrite_calls = 0
    # These reasons describe backend-observable facts, not semantic quality.
    # A model judge must never waive them merely by declaring that the prose
    # answered the user: either the artifact exists or it does not.
    hard_grounding_reasons = {
        "nickname_reaction_grounding_violation",
        "required_generated_file_missing",
    }
    if reasons:
        write_server_log(
            "turn_contract_semantic_audit_started",
            requestId=request_id,
            reasons=reasons,
            coreDialogueProtocol=bool(candidate.get("coreDialogueProtocol")),
            fieldRepairAttempted=bool(candidate.get("dialogueFieldRepairAttempted")),
        )
        semantic_audit_calls += 1
        audit = audit_turn_contract_with_model(
            settings,
            interpretation,
            contract,
            candidate,
            request_id=request_id,
            clarification_context=clarification_context,
            task_dialogue=task_dialogue,
        )
        contract, candidate, clarification_accepted = apply_missing_input_clarification_audit(
            interpretation,
            contract,
            candidate,
            audit,
        )
        if clarification_accepted:
            reasons = []
        elif audit.get("passes"):
            if (
                isinstance(candidate.get("actionReceipt"), Mapping)
                or isinstance(candidate.get("actionReceipts"), list)
            ):
                candidate["externalActionOutcomeVerified"] = True
            if str(candidate.get("memoryAction") or "none").strip().lower() != "none":
                candidate["structuredSideEffectVerified"] = True
            candidate.update({
                "completedActs": list(audit.get("completedActs") or contract.required_acts),
                "completedActsProvided": True,
                "standalone": True,
                "standaloneProvided": True,
                "dependsOnUndeliveredPrefix": False,
                "dependsOnUndeliveredPrefixProvided": True,
                "turnComplete": True,
                "turnCompleteProvided": True,
                "turnContractVerification": "semantic_audit",
            })
            reasons = [item for item in reasons if item in hard_grounding_reasons]
    max_contract_rewrite_calls = 2
    while (
        reasons
        and allow_rewrite
        and contract_rewrite_calls < max_contract_rewrite_calls
    ):
        contract_rewrite_calls += 1
        candidate = rewrite_reply_to_turn_contract(
            settings,
            interpretation,
            contract,
            candidate,
            audit,
            request_id=request_id,
            persona_snapshot=persona_snapshot,
            task_dialogue=task_dialogue,
        )
        reasons = completion_risk_reasons(candidate, contract)
        if not reasons:
            break
        if reasons:
            semantic_audit_calls += 1
            audit = audit_turn_contract_with_model(
                settings,
                interpretation,
                contract,
                candidate,
                request_id=request_id,
                clarification_context=clarification_context,
                task_dialogue=task_dialogue,
            )
            contract, candidate, clarification_accepted = apply_missing_input_clarification_audit(
                interpretation,
                contract,
                candidate,
                audit,
            )
            if clarification_accepted:
                reasons = []
            elif audit.get("passes"):
                if (
                    isinstance(candidate.get("actionReceipt"), Mapping)
                    or isinstance(candidate.get("actionReceipts"), list)
                ):
                    candidate["externalActionOutcomeVerified"] = True
                if str(candidate.get("memoryAction") or "none").strip().lower() != "none":
                    candidate["structuredSideEffectVerified"] = True
                candidate.update({
                    "completedActs": list(audit.get("completedActs") or contract.required_acts),
                    "completedActsProvided": True,
                    "standalone": True,
                    "standaloneProvided": True,
                    "dependsOnUndeliveredPrefix": False,
                    "dependsOnUndeliveredPrefixProvided": True,
                    "turnComplete": True,
                    "turnCompleteProvided": True,
                    "turnContractVerification": "model_rewrite_and_audit",
                })
                reasons = [item for item in reasons if item in hard_grounding_reasons]
    if reasons:
        write_server_log(
            "turn_contract_rejected",
            requestId=request_id,
            contract=contract.to_dict(),
            reasons=reasons,
            audit=audit,
        )
        raise UpstreamProtocolError(
            "model reply did not complete the current Turn Contract: "
            + ",".join(reasons)
        )
    final_attachment_issues = attachment_response_issues(candidate, cognitive_body or {},
        task=(cognitive_execution_state(cognitive_body).get("task") or {}) if isinstance(cognitive_body, dict) else {})
    if final_attachment_issues:
        raise CognitiveProtocolError("attachment_delivery_invalid:" + ",".join(final_attachment_issues))
    candidate["turnContract"] = contract.to_dict()
    candidate["turnContractSemanticAuditCalls"] = semantic_audit_calls
    candidate["turnContractRewriteCalls"] = contract_rewrite_calls
    candidate["utteranceInterpretation"] = interpretation.to_dict()
    envelope = final_turn_envelope(
        candidate,
        contract,
        turn_id=f"{request_id or uuid.uuid4().hex}:turn",
        delivery_path="atomic" if allow_rewrite else "stream",
        upstream_finish_reason=upstream_finish_reason or None,
    )
    candidate["finalTurnEnvelope"] = envelope.to_dict()
    write_server_log(
        "turn_contract_completed",
        requestId=request_id,
        verification=str(candidate.get("turnContractVerification") or "model_declaration"),
        envelope=envelope.to_dict(),
    )
    return candidate


def rewrite_reply_for_grounding_gate(
    settings: dict[str, Any],
    user_message: str,
    candidate: dict[str, Any],
    gate_decision: Any,
    epistemic_plan: EpistemicPlan,
    *,
    request_id: str,
    persona_snapshot: PersonaContextSnapshot | None = None,
) -> dict[str, Any]:
    """Ask the same configured model to lower unsupported certainty.

    The backend supplies diagnostics and constraints only; it never authors a
    replacement conclusion.  This path is used when Web research is forbidden
    or exhausted but the conversational turn can still be answered safely.
    """

    unsupported = set(getattr(gate_decision, "unsupported_claim_ids", ()) or ())
    claims = [
        item.to_dict()
        for item in (getattr(gate_decision, "claims", ()) or ())
        if not unsupported or item.claim_id in unsupported
    ]
    payload: dict[str, Any] = {
        "model": settings["apiModel"],
        "temperature": 0.35,
        "max_tokens": 1400,
        "messages": [
            *persona_repair_prefix(persona_snapshot, legacy_system_prompt=False),
            {
                "role": "system",
                "content": (
                    "你是同一轮回答的事实边界修订器。只修订缺少对应证据的断言，"
                    "保留原回答的直接回应、人格语气和已支持内容。不得声称执行过未执行的"
                    "搜索、网页读取、文件操作或本地动作；无法确定时自然表达边界，仍要回答"
                    "用户真正的问题。输出一个完整 JSON，至少包含 reply、spokenTextJa、"
                    "emotion、gesture、memoryUpdates。若没有充分网页证据，必须删除 [S1] 一类"
                    "引用标记以及由它们支撑的断言。unsupportedClaims 中的每个事实都不得再"
                    "被正面确认：只能明确降为未确认，或删掉该局部事实后继续回答主问题。"
                    "尤其不能先说无法确认、随后又用‘确实出自’‘原话是’等方式重新断言。"
                    "使用一到三项 speechUnits，每项含 zh、ja、boundaryAfter，让中日文修订"
                    "保持逐项对应；涉及 unsupportedClaims 的单元还要带 claimIds。另输出"
                    "claimPatches:[{claimId,action}]，action 只能是 DELETE、"
                    "DOWNGRADE_CERTAINTY 或 MARK_UNRESOLVED，并覆盖每个 unsupported claimId。"
                    "missingVerificationTargets 是权威事实范围，即使 unsupportedClaims 未列全，"
                    "也不得补写该范围的来源、身份、日期或归属细节。不要输出诊断过程。"
                ),
            },
            {
                "role": "user",
                "content": json.dumps({
                    "userMessage": user_message,
                    "originalCandidate": candidate,
                    "gateDecision": gate_decision.to_dict(),
                    "unsupportedClaims": claims,
                    "researchPolicy": epistemic_plan.research_policy,
                }, ensure_ascii=False),
            },
        ],
    }
    if settings.get("useResponseFormat"):
        payload["response_format"] = {"type": "json_object"}
    if "deepseek.com" in settings["apiEndpoint"]:
        payload["thinking"] = {"type": "disabled"}
    content = send_upstream_chat_payload(
        settings,
        payload,
        timeout=90,
        request_id=request_id,
        purpose="grounding_gate_rewrite",
    )
    rewritten = normalize_model_reply(content, settings=settings)
    patch_actions = {
        str(item.get("claimId") or ""): str(item.get("action") or "")
        for item in rewritten.get("claimPatches", [])
        if isinstance(item, dict)
    }
    rewritten["groundingGateClaimPatchesValid"] = bool(
        unsupported
        and unsupported.issubset(patch_actions)
        and all(
            patch_actions[item] in {
                "DELETE", "DOWNGRADE_CERTAINTY", "MARK_UNRESOLVED",
            }
            for item in unsupported
        )
    )
    for key in (
        "_conversationToolResults", "_chatMetrics", "attachments", "files",
        "_fileOutputs", "toolUsed", "toolStatus", "toolResults", "actionReceipt",
        "todoContext", "webEvidenceStatus",
    ):
        if key in candidate and key not in rewritten:
            rewritten[key] = candidate[key]
    preserve_attachment_delivery(candidate, rewritten)
    rewritten["groundingGateRewrittenByModel"] = True
    if persona_snapshot is not None:
        rewritten["personaContextSnapshotId"] = persona_snapshot.snapshot_id
    return rewritten


def terminal_grounding_boundary_reply(
    candidate: dict[str, Any], *, failure_stage: str = "",
) -> dict[str, Any]:
    """Return a fact-free answer when the model cannot obey a grounding rewrite.

    This is deliberately narrower than a normal fallback: it does not infer an
    answer from failed search results, repeat source claims, or pretend that an
    insufficient receipt completed verification.  It only exposes the evidence
    boundary already established by the gate so an expected lack of evidence
    cannot abort the whole conversational turn.
    """

    safe = dict(candidate)
    safe.update({
        "reply": "现有证据不足，我现在无法确认这件事。",
        "spokenTextJa": "現時点では証拠が足りないため、この件は断定できません。",
        "emotion": "concerned",
        "gesture": "idle",
        "memoryUpdates": [],
        "turnComplete": True,
        "standalone": True,
        "groundingGateTerminalBoundary": True,
    })
    if failure_stage == "evidence_limited_answer":
        safe.update({
            "reply": "这次网页证据尚未完成核验，回答整理也失败了，暂时无法给出可靠的查询结论。",
            "spokenTextJa": "今回はウェブの証拠を検証しきれず、回答の整理にも失敗したため、確かな検索結果はまだ伝えられないわ。",
            "groundingFailureStage": failure_stage,
        })
    safe["speechText"] = safe["reply"] if normalize_speech_language(safe.get("speechLanguage")) == "zh-CN" else safe["spokenTextJa"]
    safe["memoryAction"] = "none"
    # These flags describe the discarded draft, not this fact-free failure
    # report. Keep the failure stage separately for diagnostics.
    safe.pop("toolGroundingUnverified", None)
    safe.pop("webSynthesisUnverified", None)
    for key in (
        "_memoryCandidates",
        "_memoryUpdateTypes",
        "_modelSpeechUnits",
        "speechUnits",
        "speechUnitContract",
    ):
        safe.pop(key, None)
    return safe


def hard_fact_gate_requires_terminal_boundary(
    epistemic_state: EpistemicTurnState,
    receipt: Any,
) -> bool:
    """HARD claims may not release guessed details after verification fails."""

    hard_requirements = tuple(
        item for item in epistemic_state.fact_requirements
        if item.verification_required
        and item.verification_level == "HARD"
        and item.domain == "external_world"
        and item.evidence_class == "web_evidence"
    )
    has_sufficient_receipt = bool(
        receipt
        and receipt.status == "completed"
        and receipt.source_uids
        and receipt.evidence_sufficient
    )
    return bool(hard_requirements) and not has_sufficient_receipt


def soft_fact_gate_can_degrade(
    epistemic_state: EpistemicTurnState,
    gate_decision: Any,
) -> bool:
    """SOFT Web debt may patch its scope but may never terminate the turn."""

    external = tuple(
        item for item in epistemic_state.fact_requirements
        if item.verification_required
        and item.domain == "external_world"
        and item.evidence_class == "web_evidence"
    )
    if not external or any(item.verification_level == "HARD" for item in external):
        return False
    reasons = set(getattr(gate_decision, "reasons", ()) or ())
    return bool(reasons) and reasons.issubset({
        "soft_fact_requires_local_uncertainty_patch",
        "citation_without_sufficient_evidence",
        "required_fact_answer_without_sufficient_receipt",
    })


def soft_grounding_boundary_reply(
    candidate: dict[str, Any],
    gate_decision: Any,
) -> dict[str, Any]:
    """Downgrade only unresolved SOFT scope while preserving the main answer."""

    safe = dict(candidate)
    reply = re.sub(r"\s*\[S\d+\]", "", str(safe.get("reply") or "")).strip()
    spoken = str(safe.get("spokenTextJa") or "").strip()
    targets = [
        str(item).strip()
        for item in (getattr(gate_decision, "missing_verification_targets", ()) or ())
        if str(item).strip()
    ]
    unsupported_ids = set(getattr(gate_decision, "unsupported_claim_ids", ()) or ())
    unsupported_texts = [
        str(item.text or "").strip()
        for item in (getattr(gate_decision, "claims", ()) or ())
        if item.claim_id in unsupported_ids and str(item.text or "").strip()
    ]

    def unsupported_unit(value: str) -> bool:
        unit = str(value or "").strip()
        return bool(unit) and any(
            claim_scope_relevance(target, unit) >= 0.82
            for target in unsupported_texts
        )

    raw_units = safe.get("_modelSpeechUnits")
    if isinstance(raw_units, list) and raw_units:
        kept_units = [
            dict(item)
            for item in raw_units
            if isinstance(item, dict)
            and not (
                unsupported_ids
                & {
                    str(claim_id).strip()
                    for claim_id in (
                        item.get("claimIds")
                        if isinstance(item.get("claimIds"), list)
                        else []
                    )
                    if str(claim_id).strip()
                }
            )
            and not unsupported_unit(
                str(item.get("zh") or item.get("textZh") or item.get("reply") or "")
            )
        ]
        if kept_units:
            reply = "\n\n".join(
                str(item.get("zh") or item.get("textZh") or item.get("reply") or "").strip()
                for item in kept_units
                if str(item.get("zh") or item.get("textZh") or item.get("reply") or "").strip()
            ).strip()
            spoken = "".join(
                str(item.get("ja") or item.get("spokenTextJa") or "").strip()
                for item in kept_units
            ).strip()
    elif unsupported_texts:
        reply_units = [
            item.strip()
            for item in re.split(r"(?<=[。！？!?；;])|\n+", reply)
            if item.strip()
        ]
        rejected_indexes = {
            index for index, item in enumerate(reply_units) if unsupported_unit(item)
        }
        reply = "".join(
            item for index, item in enumerate(reply_units) if index not in rejected_indexes
        ).strip()
        spoken_units = [
            item.strip()
            for item in re.split(r"(?<=[。！？!?；;])|\n+", spoken)
            if item.strip()
        ]
        if rejected_indexes and len(spoken_units) == len(reply_units):
            spoken = "".join(
                item for index, item in enumerate(spoken_units)
                if index not in rejected_indexes
            ).strip()
    scope = targets[0][:140] if targets else "其中附带的外部事实"
    boundary = f"关于“{scope}”的准确性，我暂时无法可靠确认；不过这不影响下面的讨论。"
    if boundary not in reply:
        reply = f"{boundary}\n\n{reply}".strip()
    spoken_boundary = (
        "付随する外部事実の正確さは今のところ確認できないけれど、"
        "それとは分けて本題には答えるわ。"
    )
    if spoken_boundary not in spoken:
        spoken = f"{spoken_boundary}{spoken}".strip()
    safe.update({
        "reply": reply,
        "spokenTextJa": spoken,
        "turnComplete": True,
        "standalone": True,
        "softFactBoundaryApplied": True,
        "softFactBoundaryTargets": targets,
    })
    for key in ("_modelSpeechUnits", "speechUnits", "speechUnitContract"):
        safe.pop(key, None)
    return safe


def terminal_visual_grounding_boundary_reply(candidate: dict[str, Any]) -> dict[str, Any]:
    """Stop a visual turn from releasing claims that contradict captured evidence."""

    safe = dict(candidate)
    safe.update({
        "reply": "图片已经读到了，但这次没能可靠地回答你的问题。",
        "spokenTextJa": "画像は読み取れたけれど、今回はあなたの質問に確かな答えを返せなかったわ。",
        "emotion": "concerned",
        "gesture": "idle",
        "memoryUpdates": [],
        "turnComplete": True,
        "standalone": True,
        "visualGroundingTerminalBoundary": True,
    })
    safe.pop("toolGroundingUnverified", None)
    safe["speechText"] = safe["reply"] if normalize_speech_language(safe.get("speechLanguage")) == "zh-CN" else safe["spokenTextJa"]
    for key in (
        "_memoryCandidates",
        "_memoryUpdateTypes",
        "_modelSpeechUnits",
        "speechUnits",
        "speechUnitContract",
    ):
        safe.pop(key, None)
    return safe


def persist_finalized_chat_state(
    settings: dict[str, Any],
    user_message: str,
    result: dict[str, Any],
    *,
    request_id: str,
    interpretation: UtteranceInterpretation,
    chat_metrics: dict[str, Any],
    cold_shoulder_short_circuit: bool,
) -> tuple[dict[str, Any], list[str]]:
    """Persist a frozen answer without changing any user-visible speech.

    Fast streaming calls this only after its validated utterances have been
    emitted.  Legacy JSON calls invoke it inline for response compatibility.
    """

    value = dict(result)
    cognitive_overlay = value.get("_cognitiveOverlay")
    cognitive_envelope = has_cognitive_overlay(cognitive_overlay)
    cognitive_has_patch = has_revision_overlay(cognitive_overlay)
    warnings: list[str] = []

    def warn(stage: str, error: Exception) -> None:
        warnings.append(stage)
        write_server_log(
            "chat_postprocess_degraded",
            requestId=request_id,
            stage=stage,
            errorType=type(error).__name__,
            error=str(error)[:500],
        )

    updates: list[dict[str, Any]] = []
    try:
        memory_update_types = value.pop("_memoryUpdateTypes", {})
        if not isinstance(memory_update_types, dict):
            memory_update_types = {}
        raw_model_candidates = value.pop("_memoryCandidates", [])
        if not isinstance(raw_model_candidates, list):
            raw_model_candidates = []
        if not raw_model_candidates and isinstance(value.get("memoryUpdates"), list):
            raw_model_candidates = list(value.get("memoryUpdates") or [])
        memory_updates_provided = bool(value.get("memoryUpdatesProvided"))
        memory_action = str(value.get("memoryAction") or "none").strip().lower()
        memory_action_provided = bool(value.get("memoryActionProvided"))
        model_updates = (
            []
            if cognitive_envelope or cold_shoulder_short_circuit or not memory_updates_provided else
            grounded_memory_candidates(raw_model_candidates, user_message)
        )
        memory_action_recovered = False
        if (
            not cognitive_envelope
            and not cold_shoulder_short_circuit
            and memory_action_provided
            and memory_action == "save"
            and not model_updates
        ):
            try:
                raw_model_candidates = recover_declared_memory_action_with_model(
                    settings,
                    user_message,
                    value,
                    request_id=request_id,
                )
                model_updates = grounded_memory_candidates(
                    raw_model_candidates,
                    user_message,
                )
                memory_action_recovered = bool(model_updates)
            except Exception as error:
                warn("memory_action_structured_repair", error)
        commitment = (
            None
            if cold_shoulder_short_circuit else
            relationship_commitment_from_turn(user_message, value)
        )
        relationship_updates = ([{
            "content": commitment["memory"],
            "type": "relationship_state",
            "importance": 1.0,
            "shouldSave": True,
            "subject": "user_and_assistant",
            "predicate": "relationship_commitment",
            "object": commitment["label"],
            "polarity": "positive",
            "modality": "asserted",
            "temporal": "current",
            "sourceSpan": user_message,
            "userPinned": True,
        }] if commitment else [])
        if commitment:
            memory_update_types[commitment["memory"]] = "relationship_state"
            write_server_log(
                "relationship_commitment_detected",
                requestId=request_id,
                label=commitment["label"],
                memoryType="relationship_state",
            )
        updates = (
            []
            if cold_shoulder_short_circuit else
            [
                *model_updates,
                *relationship_updates,
            ]
        )
        value["memoryDecisionSource"] = (
            "cold_shoulder_suppressed"
            if cold_shoulder_short_circuit else
            "model_semantic_action_repair"
            if memory_action_recovered else
            "model_structured"
            if memory_updates_provided else
            "model_protocol_missing_no_write"
        )
        value["_contextProtection"] = context_protection_for_turn(
            user_message,
            value,
            [item for item in updates if isinstance(item, Mapping)],
            interpretation,
        )
        memories = read_memory(settings)
        if not cognitive_envelope:
            schedule_memory_observer(
                updates,
                user_message=user_message,
                settings=settings,
                source_turn_id=request_id,
                update_types=memory_update_types,
            )
        if not isinstance(memories, list):
            raise TypeError(f"memory persistence returned {type(memories).__name__}")
    except Exception as error:
        if cognitive_has_patch:
            raise CognitiveCommitError(
                "validated cognitive revision memory preparation failed"
            ) from error
        warn("memory_persistence", error)
        try:
            memories = read_memory(settings)
        except Exception:
            memories = []

    try:
        relationship = (
            read_relationship_state()
            if cold_shoulder_short_circuit or cognitive_envelope else
            update_relationship_state(
                user_message,
                {**value, "_requestId": request_id},
            )
        )
        if not isinstance(relationship, dict):
            raise TypeError(f"relationship persistence returned {type(relationship).__name__}")
    except Exception as error:
        if cognitive_has_patch:
            raise CognitiveCommitError(
                "validated cognitive revision relationship preparation failed"
            ) from error
        warn("relationship_persistence", error)
        try:
            relationship = read_relationship_state()
        except Exception:
            relationship = default_relationship_state()

    if cognitive_envelope:
        # The cognitive result is bound before finalisation.  Persist the
        # answer actually accepted by this function so a later audit/repair
        # cannot leave a draft in the digest or trace.
        final_reply = str(value.get("reply") or "").strip()
        final_spoken = str(value.get("spokenTextJa") or "").strip()
        final_speech = str(value.get("speechText") or "").strip()
        digest = (
            deepcopy(value.get("_cognitiveDigest"))
            if isinstance(value.get("_cognitiveDigest"), Mapping) else {}
        )
        digest["answerCommitments"] = unique_strings([
            final_reply,
            final_spoken,
            final_speech,
        ])
        value["_cognitiveDigest"] = digest
        trace = (
            deepcopy(value.get("_cognitiveTrace"))
            if isinstance(value.get("_cognitiveTrace"), Mapping) else {}
        )
        trace["finalAnswer"] = {
            "reply": final_reply,
            "spokenTextJa": final_spoken,
            "speechText": final_speech,
        }
        value["_cognitiveTrace"] = trace
        relationship_projection_result = {
            key: deepcopy(value.get(key))
            for key in (
                "reply", "spokenTextJa", "speechText", "emotion", "gesture",
                "relationEvent", "relationEventProvided", "proactiveDirective",
                "proactiveDirectiveProvided", "turnComplete",
            )
            if key in value
        }
        value["_cognitiveProjectionPayloads"] = {
            "memory_records": {
                **build_memory_projection_payload(
                    cognitive_overlay,
                    updates,
                    source_turn_id=request_id,
                ),
                "userMessage": user_message,
                "memoryClearGeneration": memory_clear_generation(settings),
                "updateTypes": dict(memory_update_types),
            },
            "relationship_state": {
                "userMessage": user_message,
                "result": relationship_projection_result,
            },
        }

    try:
        conversation = append_conversation_turn(user_message, value, settings, chat_metrics)
        if not isinstance(conversation, dict):
            raise TypeError(f"conversation persistence returned {type(conversation).__name__}")
    except ContextCompatibilityError:
        raise
    except Exception as error:
        if cognitive_has_patch:
            raise CognitiveCommitError(
                "validated cognitive revision persistence failed; answer not committed"
            ) from error
        warn("conversation_persistence", error)
        try:
            conversation = read_conversation_context()
        except ContextCompatibilityError:
            raise
        except Exception:
            conversation = default_conversation_context()

    if cognitive_envelope:
        commit_id = str(value.get("_cognitiveCommitId") or "").strip()
        if not commit_id:
            raise CognitiveCommitError(
                "cognitive envelope reached finalisation without a commit id"
            )
        try:
            _run_cognitive_projection(
                commit_id,
                {
                    "memory_records": lambda payload: _project_cognitive_memory_records(
                        payload,
                        settings=settings,
                    ),
                    "relationship_state": _project_cognitive_relationship_state,
                },
                kinds=("memory_records", "relationship_state"),
            )
            memories = read_memory(settings)
            relationship = read_relationship_state()
        except Exception as error:
            raise CognitiveCommitError(
                "cognitive projection failed; retryable outbox remains"
            ) from error

    value["memoryUpdates"] = unique_strings([
        item.get("content") if isinstance(item, Mapping) else item
        for item in updates
    ])
    value["memories"] = memories
    value["relationshipUpdated"] = bool(relationship)
    value["relationshipTone"] = str(relationship.get("stage") or "close_companion")
    value["conversationArchiveCount"] = int(conversation.get("archiveCount") or 0)
    value["proactiveControl"] = normalize_proactive_control(
        conversation.get("proactiveControl")
    )
    value["memoryFile"] = str(memory_path(settings))
    value.pop("_contextProtection", None)
    value.pop("_referenceLedger", None)
    for private_key in (
        "_cognitiveOverlay",
        "_cognitiveDigest",
        "_cognitiveTrace",
        "_cognitiveProjectionPayloads",
        "_cognitiveCommitId",
        "_cognitiveStateRevision",
    ):
        value.pop(private_key, None)
    return value, warnings


def complete_deferred_chat_persistence(
    settings: dict[str, Any],
    user_message: str,
    result: dict[str, Any],
    *,
    request_id: str,
) -> dict[str, Any]:
    """Complete the post-utterance persistence phase of a fast turn."""

    raise_if_chat_request_cancelled(request_id)
    value = dict(result)
    deferred = value.pop("_deferredPersistence", {})
    if not isinstance(deferred, dict) or not deferred:
        return value
    persistence_started = time.perf_counter()
    interpretation = interpret_utterance(user_message)
    persisted, warnings = persist_finalized_chat_state(
        settings,
        user_message,
        value,
        request_id=request_id,
        interpretation=interpretation,
        chat_metrics=(
            dict(deferred.get("chatMetrics"))
            if isinstance(deferred.get("chatMetrics"), dict) else {}
        ),
        cold_shoulder_short_circuit=bool(deferred.get("coldShoulderShortCircuit")),
    )
    existing_warnings = [
        str(item) for item in persisted.get("pipelineWarnings", [])
        if str(item).strip()
    ]
    combined_warnings = unique_strings([*existing_warnings, *warnings])
    if combined_warnings:
        persisted["pipelineWarnings"] = combined_warnings
    metrics = (
        persisted.get("pipelineMetrics")
        if isinstance(persisted.get("pipelineMetrics"), dict) else {}
    )
    metrics["persistenceDeferredUntilAfterUtterance"] = True
    metrics["postDeliveryPersistenceWarnings"] = list(warnings)
    persistence_ms = round((time.perf_counter() - persistence_started) * 1000)
    metrics["postDeliveryPersistenceMs"] = persistence_ms
    metrics["serverTotalMs"] = int(value.get("latencyMs") or 0) + persistence_ms
    persisted["pipelineMetrics"] = metrics
    persisted["latencyMs"] = metrics["serverTotalMs"]
    persisted.pop("_conversationToolResults", None)
    return persisted


def finalize_chat_response(
    settings: dict[str, Any],
    user_message: str,
    model_result: dict[str, Any],
    *,
    request_id: str = "",
    started_at: float | None = None,
    preserve_accepted_text: bool = False,
    stream_preamble: dict[str, Any] | None = None,
    prepared_turn: PreparedTurn | None = None,
    defer_persistence_until_after_utterance: bool = False,
    persona_snapshot: PersonaContextSnapshot | None = None,
    resolved_interpretation: UtteranceInterpretation | None = None,
    resolved_contract: TurnContract | None = None,
    resolved_dialogue: Sequence[Mapping[str, Any]] | None = None,
    cognitive_body: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Enrich an accepted model reply without letting local persistence hide it."""

    if not isinstance(model_result, dict):
        raise UpstreamProtocolError("normalized upstream reply is not an object")
    result = dict(model_result)
    if cognitive_body is not None:
        bind_turn_context_to_result(cognitive_body, result)
    cognitive_final = (result.get("_cognitiveOutcomeVerification") or {}).get("valid") is True
    if cognitive_final:
        preserve_accepted_text = True
    saved_task_dialogue = result.pop("_taskDialogue", [])
    task_dialogue = list(resolved_dialogue if resolved_dialogue is not None else saved_task_dialogue)
    semantic_task_request = str(
        result.pop("_semanticTaskRequest", "")
        or (resolved_interpretation.semantic_text if resolved_interpretation else user_message)
    ).strip()[:1200]
    if cognitive_body is not None and cognitive_body.get("_cognitiveRepairRoute"):
        semantic_task_request = current_task_semantic_request(cognitive_body, user_message)
    initial_proactive_directive = normalize_proactive_directive(
        result.get("proactiveDirective")
    )
    initial_proactive_directive_provided = (
        bool(result.get("proactiveDirectiveProvided"))
        if "proactiveDirectiveProvided" in result
        else str(model_result.get("proactiveDirective") or "").strip().lower()
        in PROACTIVE_DIRECTIVES
    )
    upstream_finish = str(
        result.pop("_upstreamFinishReason", "")
        or LAST_UPSTREAM_FINISH_REASON.get()
        or ""
    )[:80]
    prepared_for_contract = prepared_turn or prepare_action_turn(
        user_message,
        pending_action={},
        request_id=request_id,
    )
    interpretation = resolved_interpretation or (
        result.pop("_utteranceInterpretation")
        if isinstance(result.get("_utteranceInterpretation"), UtteranceInterpretation)
        else utterance_interpretation_from_prepared(prepared_for_contract)
    )
    inferred_policy = choose_turn_policy(
        user_message,
        has_tools=bool(result.get("toolUsed") or result.get("_conversationToolResults")),
        has_attachments=bool(result.get("attachments")),
        file_output_expected=bool(
            result.get("_fileOutputExpected") or result.get("_fileOutputs")
        ),
        interpretation=interpretation,
    )
    effective_cognitive_contract = (
        cognitive_body.get("_cognitiveTurnContract")
        if cognitive_final and isinstance(cognitive_body, Mapping) else None
    )
    saved_contract = result.pop("_turnContract", None)
    contract = (effective_cognitive_contract if isinstance(effective_cognitive_contract, TurnContract) else None) or resolved_contract or (
        saved_contract
        if isinstance(saved_contract, TurnContract)
        else build_turn_contract(interpretation, inferred_policy)
    )
    cold_shoulder_short_circuit = str(result.get("source") or "") == "furious-cold-shoulder"
    chat_metrics = result.pop("_chatMetrics", {})
    if not isinstance(chat_metrics, dict):
        chat_metrics = {}
    chat_metrics["requestId"] = request_id
    conversation_tool_results = (
        result.get("_conversationToolResults")
        if isinstance(result.get("_conversationToolResults"), list)
        else []
    )
    result = apply_attachment_read_failure_boundary(
        result,
        conversation_tool_results,
    )
    receipt = research_receipt_from_tool_results(
        request_id,
        conversation_tool_results,
    )
    epistemic_plan = (
        EpistemicPlan.from_dict(prepared_for_contract.epistemic_plan)
        if isinstance(prepared_for_contract.epistemic_plan, dict)
        else None
    )
    if epistemic_plan is None:
        epistemic_plan = create_epistemic_plan(
            request_id,
            interpretation,
        )
    visual_attempt_results = [
        item for item in conversation_tool_results
        if isinstance(item, Mapping)
        and str(item.get("name") or "") in {
            "capture_screen", "capture_camera", "read_image",
        }
    ]
    if has_typed_visual_evidence(conversation_tool_results):
        if not cognitive_final or contract.required_acts != ("answer_from_current_visual_observation",):
            contract = bind_current_visual_observation_contract(
                contract,
                semantic_text=semantic_task_request,
            )
        epistemic_plan = epistemic_plan.with_current_visual_observation(
            subject=semantic_task_request,
        )
    elif visual_attempt_results:
        if not cognitive_final or contract.required_acts != ("explain_current_visual_observation_failure",):
            contract = bind_current_visual_failure_contract(
                contract,
                semantic_text=semantic_task_request,
            )
        epistemic_plan = epistemic_plan.with_current_visual_observation(
            subject=semantic_task_request,
            observation_available=False,
        )
    if isinstance(cognitive_body, dict):
        cognitive_body["_cognitiveTurnContract"] = contract
    epistemic_state = epistemic_plan.epistemic_state()
    effective_research_policy = (
        epistemic_plan.research_policy
        if settings.get("permissionWebSearch")
        and not result.get("webSearchFailed")
        and not result.get("webEvidenceLimited")
        else "forbidden"
    )
    if not cognitive_final:
        if hard_fact_gate_requires_terminal_boundary(epistemic_state, receipt):
            result = terminal_grounding_boundary_reply(result)
            write_server_log(
                "grounded_claim_gate_hard_terminal_boundary_applied",
                requestId=request_id,
                planId=epistemic_plan.plan_id,
                planRevision=epistemic_plan.revision,
            )
        # Field repair in call_upstream may have changed Japanese after the first
        # visual audit. Renew that receipt BEFORE the generic gate consumes it.
        result = refresh_visual_grounding_for_current_text(
            settings, semantic_task_request, result, conversation_tool_results,
            request_id=request_id, phase="pre_claim_gate",
            task_dialogue=task_dialogue,
        )
        gate_decision = grounded_claim_gate_decision(
            str(result.get("reply") or ""),
            epistemic_state,
            receipt,
            research_policy=effective_research_policy,
            visual_evidence_verified=(current_visual_grounding_verified(result, conversation_tool_results)
                                      or native_visual_input_delivered(result, conversation_tool_results)),
        )
        write_server_log(
            "grounded_claim_gate_decision",
            requestId=request_id,
            planId=epistemic_plan.plan_id,
            planRevision=epistemic_plan.revision,
            decision=gate_decision.to_dict(),
        )
        if (
            gate_decision.status in {"REWRITE_WITH_UNCERTAINTY", "BLOCK"}
            and configured(settings)
        ):
            update_chat_request_progress(
                request_id,
                "grounding-rewrite",
                "正在收敛缺少证据的断言",
            )
            result = rewrite_reply_for_grounding_gate(
                settings,
                user_message,
                result,
                gate_decision,
                epistemic_plan,
                request_id=request_id,
                persona_snapshot=persona_snapshot,
            )
            result = refresh_visual_grounding_for_current_text(
                settings, semantic_task_request, result, conversation_tool_results,
                request_id=request_id, phase="post_claim_rewrite",
                task_dialogue=task_dialogue,
            )
            gate_decision = grounded_claim_gate_decision(
                str(result.get("reply") or ""),
                epistemic_state,
                receipt,
                research_policy=effective_research_policy,
                visual_evidence_verified=(current_visual_grounding_verified(result, conversation_tool_results)
                                          or native_visual_input_delivered(result, conversation_tool_results)),
            )
            write_server_log(
                "grounded_claim_gate_rewrite_decision",
                requestId=request_id,
                planId=epistemic_plan.plan_id,
                planRevision=epistemic_plan.revision,
                decision=gate_decision.to_dict(),
            )
        if gate_decision.status != "PASS":
            write_server_log(
                "grounded_claim_gate_model_rewrite_rejected",
                requestId=request_id,
                violations=list(gate_decision.reasons),
                gateStatus=gate_decision.status,
                planId=epistemic_plan.plan_id,
                planRevision=epistemic_plan.revision,
                claimType="epistemic_or_research_claim",
            )
            if soft_fact_gate_can_degrade(epistemic_state, gate_decision):
                for cleanup_pass in range(1, 3):
                    soft_boundary_targets = list(
                        getattr(gate_decision, "missing_verification_targets", ()) or ()
                    )
                    result = soft_grounding_boundary_reply(result, gate_decision)
                    write_server_log(
                        "grounded_claim_gate_soft_boundary_applied",
                        requestId=request_id,
                        planId=epistemic_plan.plan_id,
                        planRevision=epistemic_plan.revision,
                        cleanupPass=cleanup_pass,
                        targets=soft_boundary_targets,
                    )
                    gate_decision = grounded_claim_gate_decision(
                        str(result.get("reply") or ""),
                        epistemic_state,
                        receipt,
                        research_policy=effective_research_policy,
                        visual_evidence_verified=False,
                    )
                    if gate_decision.status == "PASS":
                        break
                    if not soft_fact_gate_can_degrade(epistemic_state, gate_decision):
                        break
            else:
                result = terminal_grounding_boundary_reply(result)
                gate_decision = grounded_claim_gate_decision(
                    str(result.get("reply") or ""),
                    epistemic_state,
                    receipt,
                    research_policy=effective_research_policy,
                    visual_evidence_verified=False,
                )
            write_server_log(
                "grounded_claim_gate_terminal_boundary_decision",
                requestId=request_id,
                planId=epistemic_plan.plan_id,
                planRevision=epistemic_plan.revision,
                decision=gate_decision.to_dict(),
            )
        if gate_decision.status != "PASS":
            write_server_log(
                "grounded_claim_gate_rejected",
                requestId=request_id,
                violations=list(gate_decision.reasons),
                gateStatus=gate_decision.status,
                planId=epistemic_plan.plan_id,
                planRevision=epistemic_plan.revision,
                claimType="epistemic_or_research_claim",
            )
            raise GroundingGateError(gate_decision)
    if receipt:
        result["researchReceipt"] = receipt.to_dict()
        write_server_log(
            "research_receipt_created",
            requestId=request_id,
            researchId=receipt.research_id,
            status=receipt.status,
            executedQueries=list(receipt.executed_queries),
            sourceCount=len(receipt.source_uids),
            pagesReadCount=len(receipt.pages_read),
            evidenceSufficient=receipt.evidence_sufficient,
        )
    result["epistemicState"] = epistemic_state.to_dict()
    result["epistemicPlan"] = epistemic_plan.to_dict()
    result["groundingGate"] = ({"status": "PASS", "authority": "main_model_outcome", "checks": "references_and_receipts"}
                               if cognitive_final else gate_decision.to_dict())
    postprocess_text_mutations: list[dict[str, Any]] = []

    def apply_validating_transform(
        stage: str,
        transformer,
        current: dict[str, Any],
    ) -> dict[str, Any]:
        before_reply = str(current.get("reply") or "")
        before_spoken = str(current.get("spokenTextJa") or "")
        transformed = transformer(user_message, current)
        if not isinstance(transformed, dict):
            raise TypeError(f"{stage} returned {type(transformed).__name__}")
        changed_fields: list[str] = []
        if str(transformed.get("reply") or "") != before_reply:
            changed_fields.append("reply")
            transformed["reply"] = before_reply
        if str(transformed.get("spokenTextJa") or "") != before_spoken:
            changed_fields.append("spokenTextJa")
            transformed["spokenTextJa"] = before_spoken
        if changed_fields:
            postprocess_text_mutations.append({
                "stage": stage,
                "changedFields": changed_fields,
                "accepted": False,
                "reason": "postprocessor_may_validate_metadata_but_must_not_author_prose",
            })
            transformed["postprocessTextMutationRejected"] = True
        return transformed

    before_external = {
        "reply": str(result.get("reply") or ""),
        "spokenTextJa": str(result.get("spokenTextJa") or ""),
    }
    result = result if cognitive_final else enforce_external_action_receipt(result, conversation_tool_results)
    external_changed = [
        key for key in ("reply", "spokenTextJa")
        if str(result.get(key) or "") != before_external[key]
    ]
    if external_changed:
        postprocess_text_mutations.append({
            "stage": "external_action_receipt",
            "changedFields": external_changed,
            "accepted": True,
            "reason": "tool_receipt_truth_grounding_requires_contract_revalidation",
        })
    result = enforce_nickname_reaction_grounding(
        user_message,
        result,
        reaction_key=request_id,
        persona_snapshot=persona_snapshot,
    )
    if not cognitive_final and isinstance(result.get("_referenceLedger"), Mapping):
        result = repair_reference_attribution_once(
            settings,
            result,
            result["_referenceLedger"],
            request_id=request_id,
            persona_snapshot=persona_snapshot,
        )
    if (
        conversation_tool_results
        and not isinstance(result.get("sources"), list)
        and any(
            isinstance(item, dict)
            and item.get("ok")
            and item.get("name") in {"web_search", "read_web_page"}
            for item in conversation_tool_results
        )
    ):
        result = attach_verified_web_sources(result, conversation_tool_results)
    if not isinstance(result.get("dialogueValidation"), dict):
        validation = dialogue_validation_for_result(result, inferred_policy)
        result["dialoguePolicy"] = inferred_policy.to_dict()
        result["dialogueValidation"] = validation.to_dict()
        chat_metrics.update({
            "replyMode": inferred_policy.reply_mode,
            "actionBudget": inferred_policy.action_budget,
            "turnPolicyReason": inferred_policy.reason,
            "turnPolicy": inferred_policy.to_dict(),
            "replySentences": validation.sentence_count,
            "replyCharacters": validation.character_count,
            "assistantPhraseHits": list(validation.forbidden_phrase_hits),
            "dialogueValidationIssues": list(validation.issues),
            "dialogueStylePostDeliveryViolation": bool(
                preserve_accepted_text and validation.needs_rewrite
            ),
        })
    warnings: list[str] = []

    def warn(stage: str, error: Exception) -> None:
        warnings.append(stage)
        write_server_log(
            "chat_postprocess_degraded",
            requestId=request_id,
            stage=stage,
            errorType=type(error).__name__,
            error=str(error)[:500],
        )

    transformer_stages = () if (cold_shoulder_short_circuit or preserve_accepted_text) else (
        ("identity_grounding", enforce_identity_grounding),
        ("speaker_attribution", enforce_speaker_attribution_grounding),
        ("direct_social_request", enforce_direct_social_request),
        ("explicit_supportive_tone", enforce_explicit_supportive_tone),
        ("distress_support_tone", enforce_distress_support_tone),
        ("explicit_laugh_request", enforce_explicit_laugh_request),
        ("explicit_choice_grounding", enforce_explicit_choice_grounding),
    )
    for stage, transformer in transformer_stages:
        try:
            result = apply_validating_transform(stage, transformer, result)
        except Exception as error:
            warn(stage, error)

    requested_pace = "" if cold_shoulder_short_circuit else requested_speech_pace(user_message)
    if requested_pace:
        result["speechPace"] = requested_pace
        result["speechSpeed"] = SPEECH_PACE_SPEED[requested_pace]
        result["speechPaceSource"] = "user_request"

    align_started = time.perf_counter()
    if not preserve_accepted_text:
        try:
            before_spoken_alignment = str(result.get("spokenTextJa") or "")
            alignment_persona_snapshot = (
                persona_snapshot
                if persona_snapshot is not None and persona_snapshot.uses_hybrid_provider_context
                else None
            )
            if result.get("dialogueFieldRepairAttempted"):
                aligned = (
                    align_spoken_text_ja(
                        settings,
                        result,
                        allow_remote_repair=False,
                        persona_snapshot=alignment_persona_snapshot,
                    )
                    if alignment_persona_snapshot is not None else
                    align_spoken_text_ja(settings, result, allow_remote_repair=False)
                )
            else:
                aligned = (
                    align_spoken_text_ja(
                        settings,
                        result,
                        persona_snapshot=alignment_persona_snapshot,
                    )
                    if alignment_persona_snapshot is not None else
                    align_spoken_text_ja(settings, result)
                )
            if not isinstance(aligned, dict):
                raise TypeError(f"spoken_ja_alignment returned {type(aligned).__name__}")
            result = aligned
            if str(result.get("spokenTextJa") or "") != before_spoken_alignment:
                postprocess_text_mutations.append({
                    "stage": "spoken_ja_alignment",
                    "changedFields": ["spokenTextJa"],
                    "accepted": True,
                    "reason": "model_generated_bilingual_alignment_requires_contract_revalidation",
                })
        except Exception as error:
            warn("spoken_ja_alignment", error)
            if not str(result.get("spokenTextJa") or "").strip():
                # A generic Japanese sentence is not a translation of the
                # accepted Chinese reply.  Preserve the text and make speech
                # unavailability explicit instead of playing unrelated audio.
                result["speechUnavailableReason"] = "spoken_alignment_failed"
                result["ttsUnavailableReason"] = "spoken_alignment_failed"
    spoken_align_ms = round((time.perf_counter() - align_started) * 1000)

    if isinstance(stream_preamble, dict):
        preamble_zh = str(stream_preamble.get("textZh") or "").strip()
        preamble_ja = str(stream_preamble.get("spokenTextJa") or "").strip()
        if preamble_zh or preamble_ja:
            # Progress is an ephemeral UI/TTS event, not part of the assistant's
            # final answer.  Folding it back into reply/history caused repeated
            # "我查一下" openings and let a tool-use round contaminate memory.
            result["streamPreamble"] = dict(stream_preamble)
            result["streamPreambleExcludedFromFinal"] = True

    if not cognitive_final:
        result = refresh_visual_grounding_for_current_text(
            settings, semantic_task_request, result, conversation_tool_results,
            request_id=request_id, phase="final_text",
            task_dialogue=task_dialogue,
        )

    result = ensure_turn_contract_completion(
        settings,
        interpretation,
        contract,
        result,
        request_id=request_id,
        text_mutated=bool(postprocess_text_mutations),
        allow_rewrite=not preserve_accepted_text,
        upstream_finish_reason=upstream_finish,
        persona_snapshot=persona_snapshot,
        task_dialogue=task_dialogue,
        cognitive_body=cognitive_body,
        clarification_context=clarification_context_for_turn(
            result,
            prepared_for_contract,
            chat_metrics,
        ),
    )
    if not cognitive_final and has_typed_visual_evidence(conversation_tool_results):
        contracted_hash = visual_grounding_text_fingerprint(result)
        if str(result.get("visualGroundingTextFingerprint") or "") != contracted_hash:
            result = refresh_visual_grounding_for_current_text(
                settings, semantic_task_request, result, conversation_tool_results,
                request_id=request_id, phase="post_contract",
                task_dialogue=task_dialogue,
            )
            if result.get("visualGroundingTerminalBoundary"):
                result = ensure_turn_contract_completion(
                    settings,
                    interpretation,
                    contract,
                    result,
                    request_id=request_id,
                    text_mutated=False,
                    allow_rewrite=False,
                    upstream_finish_reason=upstream_finish,
                    persona_snapshot=persona_snapshot,
                    task_dialogue=task_dialogue,
                    cognitive_body=cognitive_body,
                    clarification_context=clarification_context_for_turn(
                        result,
                        prepared_for_contract,
                        chat_metrics,
                    ),
                )
    if persona_snapshot is not None:
        result["personaContextSnapshotId"] = persona_snapshot.snapshot_id
    if (
        not result.get("_modelSpeechUnits")
        and (
            result.get("structuredOutputMissingFromModel")
            or result.get("plainTextSalvaged")
        )
    ):
        fallback_units = punctuation_fallback_speech_units(
            result.get("reply") or result.get("textZh"),
            result.get("spokenTextJa"),
        )
        if fallback_units:
            result["_modelSpeechUnits"] = fallback_units
            result["speechSegmentCount"] = len(fallback_units)
            result["speechSegmentCountMissingFromModel"] = False
            result["speechSegmentCountSource"] = "punctuation_plain_text_fallback"
            result["visibleSegmentationSource"] = "punctuation_plain_text_fallback"
            write_server_log(
                "plain_text_punctuation_plan",
                requestId=request_id,
                unitCount=len(fallback_units),
                ellipsisIsBoundary=False,
            )
    generated_files = materialize_generated_files(result)
    if generated_files:
        result["files"] = generated_files
    result = speech_unit_contract_for_result(result, request_id=request_id)
    chat_metrics.update({
        "turnContractVerification": result.get("turnContractVerification") or "",
        "turnContractSemanticAuditCalls": int(result.get("turnContractSemanticAuditCalls") or 0),
        "turnContractRewriteCalls": int(result.get("turnContractRewriteCalls") or 0),
        "speechUnitCount": len(result.get("speechUnits") or []),
        "speechUnitContractHash": str(
            (result.get("speechUnitContract") or {}).get("contractFingerprint") or ""
        ),
    })
    if postprocess_text_mutations:
        result["postprocessTextMutations"] = postprocess_text_mutations

    # A rewrite/alignment/recovery pass may replace the response object, but it
    # has no authority to silently erase the original turn-level outreach
    # decision.  A provided structured decision remains authoritative; the
    # legacy command grammar runs only when every model copy omitted it.
    current_proactive_provided = (
        bool(result.get("proactiveDirectiveProvided"))
        if "proactiveDirectiveProvided" in result
        else str(result.get("proactiveDirective") or "").strip().lower()
        in PROACTIVE_DIRECTIVES
    )
    directive_candidate = (
        initial_proactive_directive
        if initial_proactive_directive_provided
        else result.get("proactiveDirective")
        if current_proactive_provided
        else "unchanged"
    )
    resolved_proactive_directive, proactive_directive_source = (
        resolve_proactive_directive(
            user_message,
            directive_candidate,
            model_directive_provided=(
                initial_proactive_directive_provided or current_proactive_provided
            ),
        )
    )
    result["proactiveDirective"] = resolved_proactive_directive
    result["proactiveDirectiveProvided"] = True
    result["proactiveDirectiveSource"] = proactive_directive_source

    if cognitive_body is not None:
        # Rewriters construct fresh dictionaries. Restore the accepted turn
        # overlay at the final persistence boundary, using the actual final
        # answer for its digest/trace rather than an earlier draft.
        bind_turn_context_to_result(cognitive_body, result)
        if (result.get("_cognitiveOverlay") or {}).get("patches"):
            defer_persistence_until_after_utterance = False

    if isinstance(cognitive_body, dict) and cognitive_turn_state(cognitive_body):
        # A later schedule/stream recovery or text postprocessor must not reuse
        # the old candidate's passing stamp for different delivered words.
        audit_cognitive_candidate(
            cognitive_body,
            settings,
            result,
            cognitive_turn_state(cognitive_body),
            request_id=request_id,
            final_projection=True,
            contract=contract,
        )
        if isinstance(result.get("_cognitiveTrace"), dict):
            result["_cognitiveTrace"]["semanticAudit"] = deepcopy(cognitive_body.get("_cognitiveSemanticAudit") or {})

    if defer_persistence_until_after_utterance:
        result["ok"] = True
        result["requestId"] = request_id
        result["latencyMs"] = round(
            (time.time() - (started_at or time.time())) * 1000
        )
        if warnings:
            result["pipelineWarnings"] = list(warnings)
        result["pipelineMetrics"] = {
            **chat_metrics,
            "spokenJaRepairMs": spoken_align_ms,
            "spokenJaRepairMode": result.get("spokenTextJaRepairMode") or "none",
            "postprocessDegraded": bool(warnings),
            "serverTotalMs": result["latencyMs"],
            "persistenceDeferredUntilAfterUtterance": True,
        }
        result["_deferredPersistence"] = {
            "chatMetrics": dict(chat_metrics),
            "coldShoulderShortCircuit": cold_shoulder_short_circuit,
        }
        return result

    result, persistence_warnings = persist_finalized_chat_state(
        settings,
        user_message,
        result,
        request_id=request_id,
        interpretation=interpretation,
        chat_metrics=chat_metrics,
        cold_shoulder_short_circuit=cold_shoulder_short_circuit,
    )
    warnings = unique_strings([*warnings, *persistence_warnings])
    result["ok"] = True
    result["requestId"] = request_id
    result["latencyMs"] = round((time.time() - (started_at or time.time())) * 1000)
    if warnings:
        result["pipelineWarnings"] = warnings
    result["pipelineMetrics"] = {
        **chat_metrics,
        "spokenJaRepairMs": spoken_align_ms,
        "spokenJaRepairMode": result.get("spokenTextJaRepairMode") or "none",
        "postprocessDegraded": bool(warnings),
        "serverTotalMs": result["latencyMs"],
    }
    result.pop("_contextProtection", None)
    result.pop("_conversationToolResults", None)
    return result


def process_chat_request_body(
    body: dict[str, Any],
    settings: dict[str, Any],
    *,
    request_id: str,
    started_at: float,
    preflight: dict[str, Any] | None = None,
    stream_preamble: dict[str, Any] | None = None,
    progress_callback: Any | None = None,
    persona_snapshot: PersonaContextSnapshot | None = None,
) -> dict[str, Any]:
    """Run the legacy-quality chat pipeline without binding it to an HTTP response."""

    settings = {**settings, "_directVisualChat": native_visual_chat_enabled(settings)}

    active_epoch = current_conversation_epoch()
    supplied_epoch = body.get("contextEpoch")
    request_epoch = _safe_nonnegative_int(
        supplied_epoch if supplied_epoch is not None else active_epoch
    )
    if supplied_epoch is not None and request_epoch != active_epoch:
        raise RequestValidationError(
            "stale_conversation_epoch",
            "这轮请求属于已经清除的会话代际，未进入附件、工具或模型处理。",
        )
    if chat_request_cancelled(request_id):
        raise RequestValidationError(
            "request_superseded",
            "这轮请求已被用户的后续输入替代。",
        )
    body["_conversationEpoch"] = request_epoch

    if body.get("_backendSingleTurnRecoveryAttempted"):
        update_chat_request_progress(
            request_id,
            "model-generating",
            "沿用本轮上下文与工具计划，正在完成受控生成",
        )
    else:
        update_chat_request_progress(request_id, "attachments", "正在读取消息与本轮附件")
    user_message, _ = streaming_user_message(body)
    ensure_turn_context_snapshot(
        body,
        request_id=request_id,
        user_message=user_message,
    )
    ensure_context_control(body, user_message=user_message, settings=settings)
    resolve_recent_artifact_task_context(
        body, settings, user_message, request_id=request_id,
    )
    processed_attachments = process_chat_attachments(body, settings)
    processed_attachments.extend(
        refresh_continued_artifacts(body, settings, user_message)
    )
    body["_processedAttachments"] = processed_attachments
    refresh_continued_visual_artifacts(body, settings, user_message)
    attachment_tool_results = attachment_read_tool_results(body)
    user_message, messages = streaming_user_message(body)
    prepared_action_turn = body_prepared_action_turn(
        body,
        user_message,
        request_id=request_id,
    )
    active_preflight = preflight or dignity_preflight(
        settings,
        user_message,
        messages,
        request_id=request_id,
    )
    if isinstance(active_preflight.get("assessment"), dict):
        body["_dignityAssessment"] = dict(active_preflight["assessment"])
    active_persona_snapshot = persona_snapshot
    if configured(settings) and active_persona_snapshot is None:
        active_persona_snapshot = build_persona_context_snapshot(
            user_message,
            messages,
            contextual_reference_resolution(
                user_message,
                messages,
                request_id=request_id,
                current_artifacts=current_turn_context_artifacts(body),
                context_state=frozen_turn_context_state(body),
                model_owned=bool(cognitive_turn_state(body)),
            ),
            frozen_turn_relationship_state(body) or read_relationship_state(),
            cognitive_body=body,
        )
    local_tool_requests = (
        infer_agent_tool_requests(
            user_message,
            messages,
            prepared_turn=prepared_action_turn,
        )
        if not configured(settings) else []
    )
    local_tool_names = {str(item.get("name") or "") for item in local_tool_requests}
    if active_preflight.get("action") == "locked":
        result = dict(active_preflight["response"])
    elif active_preflight.get("action") == "cold":
        result = dict(active_preflight["response"])
    elif not configured(settings) and is_time_query(user_message):
        result = local_time_reply(settings)
    elif "capture_screen" in local_tool_names and not configured(settings):
        result = local_screen_reply(settings, user_message)
    elif "capture_camera" in local_tool_names and not configured(settings):
        result = local_camera_reply(settings, user_message)
    elif configured(settings):
        result = call_upstream(
            body,
            progress_callback=progress_callback,
            persona_snapshot=active_persona_snapshot,
        )
    else:
        result = mock_reply(user_message, settings=settings)
        if processed_attachments:
            result["reply"] = "附件已经安全接收了。填入 API Key 后，我就能结合文件或图片内容继续分析和修改。"
            result["spokenTextJa"] = "添付ファイルは安全に受け取ったわ。APIキーを設定すれば、内容を確認して続けられる。"
            result["emotion"] = "focused"

    if active_preflight.get("action") == "continue" and configured(settings):
        result, dignity_state = apply_dignity_assessment(result, active_preflight)
        result["dignityViolationCount"] = int(dignity_state.get("dignityViolationCount") or 0)
        result["dignityLocked"] = bool(dignity_state.get("dignityLocked"))
        if dignity_reply_contract_issues(result):
            try:
                result = repair_dignity_reply_with_model(
                    settings,
                    user_message,
                    result,
                    int(dignity_state.get("dignityViolationCount") or 1),
                    request_id=request_id,
                    persona_snapshot=active_persona_snapshot,
                )
            except Exception as error:
                result["dignityReplyUnverified"] = True
                result["dignityReplyIssues"] = dignity_reply_contract_issues(result)
                write_server_log(
                    "dignity_reply_repair_failed",
                    requestId=request_id,
                    errorType=type(error).__name__,
                    error=str(error)[:500],
                )

    if processed_attachments:
        result["attachments"] = [public_attachment_metadata(item) for item in processed_attachments]
        if not result.get("toolUsed"):
            attachment_tool_names = list(dict.fromkeys(
                displayed_tool_name(item) for item in attachment_tool_results
            ))
            result["toolUsed"] = ",".join(attachment_tool_names)
            result["toolStatus"] = (
                "failed" if any(not item.get("ok") for item in attachment_tool_results) else "ok"
            )
            result["toolResults"] = [public_attachment_tool_result(item) for item in attachment_tool_results]

    if chat_request_cancelled(request_id):
        raise RequestValidationError(
            "request_superseded",
            "这轮请求已被用户的后续输入替代。",
        )

    if result.get("silentLocked"):
        result.update({
            "ok": True,
            "requestId": request_id,
            "latencyMs": round((time.time() - started_at) * 1000),
            "relationshipTone": str(read_relationship_state().get("stage") or "close_companion"),
        })
        return result

    update_chat_request_progress(request_id, "postprocessing", "正在校准情绪、日语发声稿与记忆更新")
    bind_turn_context_to_result(body, result)
    prepared_action_turn = body_prepared_action_turn(
        body,
        user_message,
        request_id=request_id,
    )
    try:
        finalized = finalize_chat_response(
            settings,
            user_message,
            result,
            request_id=request_id,
            started_at=started_at,
            stream_preamble=stream_preamble,
            prepared_turn=prepared_action_turn,
            persona_snapshot=active_persona_snapshot,
            cognitive_body=body,
        )
        finalized.pop("_fileOutputExpected", None)
        return finalized
    except FinalProjectionAuditRepairError as audit_error:
        recovered_result = recover_final_projection_candidate(
            body,
            settings,
            audit_error,
            request_id=request_id,
            progress_callback=progress_callback,
            persona_snapshot=active_persona_snapshot,
        )
        recovered_prepared = body_prepared_action_turn(
            body,
            user_message,
            request_id=request_id,
        )
        finalized = finalize_chat_response(
            settings,
            user_message,
            recovered_result,
            request_id=request_id,
            started_at=started_at,
            stream_preamble=stream_preamble,
            prepared_turn=recovered_prepared,
            persona_snapshot=active_persona_snapshot,
            cognitive_body=body,
        )
        finalized.pop("_fileOutputExpected", None)
        return finalized
    except GroundingGateError as gate_error:
        decision = gate_error.decision
        if (
            getattr(decision, "status", "") != "RESEARCH_ESCALATION"
            or not settings.get("permissionWebSearch")
            or body.get("_groundingRecoveryAttempted")
        ):
            raise
        body["_groundingRecoveryAttempted"] = True
        body["_researchEscalation"] = {
            "reason": "grounding_gate_research_escalation",
            "queries": [],
            "unknownEntities": [],
            "verificationTargets": list(
                getattr(decision, "missing_verification_targets", ())
                or ("unsupported external claims",)
            ),
            "confidence": 0.45,
            "origin": "final_grounding_gate",
        }
        write_server_log(
            "grounding_gate_returned_to_query_loop",
            requestId=request_id,
            gateDecision=decision.to_dict(),
        )
        recovered_result = call_upstream(
            body,
            progress_callback=progress_callback,
            persona_snapshot=active_persona_snapshot,
        )
        recovered_prepared = body_prepared_action_turn(
            body,
            user_message,
            request_id=request_id,
        )
        try:
            return finalize_chat_response(
                settings,
                user_message,
                recovered_result,
                request_id=request_id,
                started_at=started_at,
                stream_preamble=stream_preamble,
                prepared_turn=recovered_prepared,
                persona_snapshot=active_persona_snapshot,
                cognitive_body=body,
            )
        except FinalProjectionAuditRepairError as audit_error:
            # A grounding retry is still part of the same finalization turn.
            # Route a post-retry semantic failure through the same bounded
            # Pro/Flash continuation instead of exposing a stale candidate or
            # falling into an unrelated rescue path.
            repaired_result = recover_final_projection_candidate(
                body,
                settings,
                audit_error,
                request_id=request_id,
                progress_callback=progress_callback,
                persona_snapshot=active_persona_snapshot,
            )
            repaired_prepared = body_prepared_action_turn(
                body,
                user_message,
                request_id=request_id,
            )
            return finalize_chat_response(
                settings,
                user_message,
                repaired_result,
                request_id=request_id,
                started_at=started_at,
                stream_preamble=stream_preamble,
                prepared_turn=repaired_prepared,
                persona_snapshot=active_persona_snapshot,
                cognitive_body=body,
            )


def pipeline_rescue_case(
    body: Mapping[str, Any],
    user_message: str,
    messages: Sequence[Mapping[str, Any]],
    *,
    request_id: str,
    route_name: str,
    failure: Exception,
) -> dict[str, Any]:
    """Build a compact control-plane snapshot without persona or long memory."""

    prepared = body.get("_preparedActionTurn")
    prepared_payload = prepared.to_dict() if isinstance(prepared, PreparedTurn) else {}
    tool_results = [
        dict(item)
        for item in (
            body.get("_rescueToolResults")
            if isinstance(body.get("_rescueToolResults"), list)
            else []
        )[-12:]
        if isinstance(item, Mapping)
    ]
    receipts = [
        dict(item)
        for item in read_action_receipt_records()
        if isinstance(item, Mapping)
        and str(item.get("requestId") or "") == request_id
    ][:12]
    allowed_tools = []
    for definition in DEFAULT_TOOL_REGISTRY.all():
        if definition.tool_id in {"read_image", "read_attachment"}:
            # Attachment ingestion is pre-executed and cannot be replayed by
            # the generic executor.
            continue
        allowed_tools.append({
            "name": definition.tool_id,
            "description": definition.description,
            "inputSchema": dict(definition.input_schema),
            "sideEffect": bool(definition.side_effect),
            "permission": definition.permission_key,
            "permissionGranted": bool(
                not definition.permission_key
                or body.get("_settingsPermissionSnapshot", {}).get(definition.permission_key)
            ),
            "targetDomains": list(definition.target_domains),
        })
    ordered_inputs = [
        str(item).strip()
        for item in (
            body.get("userMessages")
            if isinstance(body.get("userMessages"), list)
            else []
        )
        if str(item).strip()
    ] or [str(user_message or "").strip()]
    dialogue = [
        {
            "role": str(item.get("role") or "")[:20],
            "content": str(item.get("content") or item.get("text") or "")[:1000],
        }
        for item in messages[-6:]
        if isinstance(item, Mapping)
        and str(item.get("role") or "") in {"user", "assistant"}
    ]
    return {
        "requestId": request_id,
        "route": route_name,
        "orderedUserInputs": ordered_inputs[-6:],
        "recentDialogue": dialogue,
        "resolvedTask": dict(body.get("_artifactTaskContext") or {}),
        "preparedAction": prepared_payload,
        "pendingAction": current_pending_action(),
        "toolResults": tool_results,
        "actionReceipts": receipts,
        "availableTools": allowed_tools,
        "failure": {
            "type": type(failure).__name__,
            "message": sanitize_provider_error_message(failure)[:500],
        },
        "constraints": {
            "maxToolCalls": 2,
            "maxPlannerCalls": 1,
            "maxFinalizeCalls": 1,
            "mustHonorPermissions": True,
            "mustNotRepeatAcceptedSideEffects": True,
        },
    }


def isolated_context_recovery_case(
    body: Mapping[str, Any],
    user_message: str,
    messages: Sequence[Mapping[str, Any]],
    *,
    request_id: str,
    route_name: str,
    failure: Exception,
) -> dict[str, Any]:
    """Freeze the active recent dialogue for a persona-free task reconstruction.

    This is deliberately a different contract from ``pipeline_rescue_case``:
    the model receives no tool catalogue and has no authority to answer or act.
    It may only identify the current task and the dialogue that belongs to it.
    """

    snapshot = body.get("_turnContextSnapshot")
    snapshot = snapshot if isinstance(snapshot, Mapping) else {}
    context = snapshot.get("_contextState")
    context = context if isinstance(context, Mapping) else {}
    dialogue: list[dict[str, str]] = []
    seen: set[tuple[str, str]] = set()

    def append_message(message_id: str, role: str, content: str) -> None:
        normalized_role = str(role or "").strip().lower()
        normalized_content = str(content or "").strip()
        if normalized_role not in {"user", "assistant"} or not normalized_content:
            return
        normalized_id = str(message_id or "").strip()[:200]
        identity = (normalized_id, normalized_role) if normalized_id else (
            normalized_role,
            normalized_content,
        )
        if identity in seen:
            return
        seen.add(identity)
        dialogue.append({
            "messageId": normalized_id or f"recent-{len(dialogue) + 1}",
            "role": normalized_role,
            "content": normalized_content[:1600],
        })

    for index, turn in enumerate(context.get("recentTurns", []), 1):
        if not isinstance(turn, Mapping):
            continue
        turn_id = str(turn.get("turnId") or f"turn-{index}")
        append_message(
            str(turn.get("userMessageId") or f"{turn_id}:user"),
            "user",
            str(turn.get("user") or ""),
        )
        append_message(
            str(turn.get("assistantMessageId") or f"{turn_id}:assistant"),
            "assistant",
            str(turn.get("assistant") or ""),
        )
    for index, item in enumerate(messages, 1):
        if not isinstance(item, Mapping):
            continue
        append_message(
            str(
                item.get("messageId") or item.get("message_id") or item.get("id")
                or f"request-message-{index}"
            ),
            str(item.get("role") or ""),
            str(item.get("content") or item.get("text") or ""),
        )

    current = snapshot.get("currentUser")
    current = current if isinstance(current, Mapping) else {}
    current_message_id = str(
        current.get("messageId") or body.get("currentUserMessageId")
        or f"{request_id}:user"
    )[:200]
    append_message(current_message_id, "user", user_message)

    # Keep every message in the server's active recent window.  A character
    # ceiling protects the isolated control call from malformed clients that
    # submit an unbounded message array; trimming always removes oldest items.
    original_count = len(dialogue)
    while len(dialogue) > 1 and sum(len(item["content"]) for item in dialogue) > 30000:
        dialogue.pop(0)

    receipts = [
        dict(item)
        for item in read_action_receipt_records()
        if isinstance(item, Mapping)
        and str(item.get("requestId") or "") == request_id
    ][:12]
    prepared = body.get("_preparedActionTurn")
    prepared_payload = prepared.to_dict() if isinstance(prepared, PreparedTurn) else {}
    return {
        "requestId": request_id,
        "route": route_name,
        "currentUserMessageId": current_message_id,
        "currentUserMessage": str(user_message or "").strip(),
        "orderedCurrentTurnInputs": [
            str(item).strip()
            for item in (
                body.get("userMessages")
                if isinstance(body.get("userMessages"), list)
                else []
            )
            if str(item).strip()
        ] or [str(user_message or "").strip()],
        "recentDialogue": dialogue,
        "recentDialogueTrimmedCount": max(0, original_count - len(dialogue)),
        "replyAnchor": dict(snapshot.get("resolvedAnchor") or {}),
        "pendingAction": current_pending_action(),
        "preparedAction": prepared_payload,
        "actionReceipts": receipts,
        "failedDerivedHypotheses": {
            "artifactTask": dict(body.get("_artifactTaskContext") or {}),
            "contextControl": dict(snapshot.get("_contextControl") or {}),
            "contextResolution": dict(body.get("_contextResolution") or {}),
        },
        "failure": {
            "type": type(failure).__name__,
            "message": sanitize_provider_error_message(failure)[:500],
        },
    }


def request_isolated_context_recovery(
    settings: dict[str, Any],
    case: Mapping[str, Any],
    *,
    request_id: str,
) -> IsolatedContextRecovery | None:
    payload: dict[str, Any] = {
        "model": settings["apiModel"],
        "temperature": 0.0,
        "max_tokens": 900,
        "messages": [
            {"role": "system", "content": ISOLATED_CONTEXT_RECOVERY_SYSTEM_PROMPT},
            {"role": "user", "content": json.dumps(case, ensure_ascii=False)},
        ],
    }
    if settings.get("useResponseFormat"):
        payload["response_format"] = {"type": "json_object"}
    if "deepseek.com" in str(settings.get("apiEndpoint") or ""):
        payload["thinking"] = {"type": "disabled"}
    content = send_upstream_chat_payload(
        settings,
        payload,
        timeout=35,
        request_id=request_id,
        purpose="isolated_context_recovery",
    )
    message_ids = [
        str(item.get("messageId") or "")
        for item in case.get("recentDialogue", [])
        if isinstance(item, Mapping) and str(item.get("messageId") or "")
    ]
    return normalize_isolated_context_recovery(
        parse_json_object(content),
        allowed_message_ids=message_ids,
    )


def prepare_isolated_context_retry_body(
    body: Mapping[str, Any],
    case: Mapping[str, Any],
    recovery: IsolatedContextRecovery,
) -> dict[str, Any]:
    """Build a clean retry body while preserving original input and authority."""

    recovered = deepcopy(dict(body))
    for key in (
        "_artifactTaskContext", "_contextResolution", "_discourseLedger",
        "_toolPreflight", "_turnExecutionPlan", "_researchDecision",
        "_epistemicPlan", "_capabilityEnvelope", "_scheduleDecision",
        "_dignityAssessment", "_processedAttachments", "_contextPressure",
        "_researchEscalation", "_groundingRecoveryAttempted",
        "_backendSingleTurnRecoveryAttempted", "_modelPipelineRescueAttempted",
    ):
        recovered.pop(key, None)

    dialogue = [
        dict(item) for item in case.get("recentDialogue", [])
        if isinstance(item, Mapping)
    ]
    current_id = str(case.get("currentUserMessageId") or "")
    relevant = {str(item) for item in recovery.relevant_message_ids if str(item)}
    if current_id:
        relevant.add(current_id)
    excluded = {
        str(item) for item in recovery.excluded_message_ids
        if str(item) and str(item) != current_id
    }
    selected = [
        item for item in dialogue
        if str(item.get("messageId") or "") not in excluded
        and (not relevant or str(item.get("messageId") or "") in relevant)
    ]
    if not selected:
        selected = [
            item for item in dialogue
            if str(item.get("messageId") or "") not in excluded
        ][-6:]

    # The normal pipeline must see the reconstructed task's dialogue, not the
    # unfiltered array that caused the failed interpretation.  Current-turn
    # userMessages and attachments remain untouched.
    recovered["messages"] = [
        {
            "id": str(item.get("messageId") or ""),
            "role": str(item.get("role") or ""),
            "content": str(item.get("content") or ""),
        }
        for item in selected
    ]
    snapshot = recovered.get("_turnContextSnapshot")
    if isinstance(snapshot, dict):
        snapshot = deepcopy(snapshot)
        original_context = snapshot.get("_contextState")
        original_context = deepcopy(original_context) if isinstance(original_context, Mapping) else {}
        filtered_turns: list[dict[str, Any]] = []
        for turn in original_context.get("recentTurns", []):
            if not isinstance(turn, Mapping):
                continue
            ids = {
                str(turn.get("userMessageId") or ""),
                str(turn.get("assistantMessageId") or ""),
            }
            if ids & excluded:
                continue
            if relevant and not ids & relevant:
                continue
            filtered_turns.append(dict(turn))
        original_context["recentTurns"] = filtered_turns
        snapshot["_contextState"] = original_context
        snapshot["_resolvedContextState"] = deepcopy(original_context)
        snapshot["_contextControl"] = {}
        snapshot["_turnCoordination"] = {
            "utteranceScope": "isolated_context_recovery",
            "pendingActionRelation": recovery.pending_action_relation,
            "contextDirectiveKind": "",
            "pendingActionMutationOwner": "action_state_machine",
            "contextMayMutatePendingAction": False,
        }
        anchor = snapshot.get("resolvedAnchor")
        if isinstance(anchor, Mapping):
            anchor_ids = {
                str(item) for item in anchor.get("targetMessageIds", []) if str(item)
            }
            if anchor_ids and (anchor_ids & excluded or relevant and not anchor_ids & relevant):
                snapshot.pop("resolvedAnchor", None)
        recovered["_turnContextSnapshot"] = snapshot
        recovered["_turnContextSnapshotOwner"] = TURN_CONTEXT_SNAPSHOT_OWNER

    recovered["_artifactTaskContext"] = {
        "relation": "unrelated",
        "artifactIds": [],
        "question": recovery.task_goal,
        "visualAction": "reuse",
        "contextSource": "isolated_context_recovery",
        "dialogue": selected,
    }
    recovered["_recoveredTaskContext"] = {
        **recovery.to_dict(),
        "selectedDialogue": selected,
    }
    recovered["_isolatedContextRecoveryAttempted"] = True
    recovered["_turnCoordination"] = {
        "utteranceScope": "isolated_context_recovery",
        "pendingActionRelation": recovery.pending_action_relation,
        "contextDirectiveKind": "",
        "pendingActionMutationOwner": "action_state_machine",
        "contextMayMutatePendingAction": False,
    }
    return recovered


def isolated_context_clarification_result(
    body: dict[str, Any],
    settings: dict[str, Any],
    user_message: str,
    recovery: IsolatedContextRecovery,
    *,
    request_id: str,
    failure: Exception,
) -> dict[str, Any]:
    result = normalize_model_reply({
        "reply": recovery.clarification_zh
        or "我好像没太理解你具体指什么，可以再解释一下吗？",
        "spokenTextJa": "ごめん、少し意味をつかみきれなかったわ。もう少し説明してくれる？",
        "emotion": "concerned",
        "gesture": "idle",
        "voiceStyle": "calm",
        "memoryUpdates": [],
        "requiresUserResponse": True,
        "expectedResponseType": "free_text",
        "completedActs": ["request_missing_input"],
        "standalone": True,
        "dependsOnUndeliveredPrefix": False,
        "turnComplete": True,
        "source": "isolated-context-clarification",
    }, settings=settings)
    result.update({
        "ok": True,
        "requestId": request_id,
        "isolatedContextRecovery": True,
        "pipelineFailureType": type(failure).__name__,
        "contextRecoveryDecision": recovery.decision,
        "contextRecoveryDiagnosis": recovery.diagnosis,
        "contextRecoveryMissing": list(recovery.missing_context),
        "proactiveDirective": "unchanged",
        "proactiveDirectiveProvided": True,
    })
    return seal_recovery_turn_result(
        body,
        user_message,
        result,
        settings=settings,
        request_id=request_id,
        delivery_path="isolated_context_clarification",
    )


def run_isolated_context_recovery(
    body: dict[str, Any],
    settings: dict[str, Any],
    user_message: str,
    messages: list[dict[str, Any]],
    *,
    request_id: str,
    route_name: str,
    failure: Exception,
    started_at: float,
) -> dict[str, Any] | None:
    """Reconstruct the task without persona, then re-enter the normal pipeline."""

    if (
        not ARCHITECTURE_FEATURES.model_pipeline_rescue_enabled
        or not configured(settings)
        or body.get("_isolatedContextRecoveryAttempted")
        or chat_request_cancelled(request_id)
        or not pipeline_failure_allows_model_rescue(failure)
    ):
        return None
    body["_isolatedContextRecoveryAttempted"] = True
    case = isolated_context_recovery_case(
        body,
        user_message,
        messages,
        request_id=request_id,
        route_name=route_name,
        failure=failure,
    )
    update_chat_request_progress(
        request_id,
        "recovering",
        "刚才的上下文没有接稳，正在只根据近期原始对话重新理清当前任务",
    )
    try:
        recovery = request_isolated_context_recovery(
            settings,
            case,
            request_id=request_id,
        )
        if recovery is None:
            raise UpstreamProtocolError("isolated context recovery returned invalid JSON")
        write_server_log(
            "isolated_context_recovery_resolved",
            requestId=request_id,
            decision=recovery.decision,
            taskGoal=recovery.task_goal[:500],
            relevantMessageIds=list(recovery.relevant_message_ids),
            excludedMessageIds=list(recovery.excluded_message_ids),
            missingContext=list(recovery.missing_context),
            pendingActionRelation=recovery.pending_action_relation,
            confidence=recovery.confidence,
            diagnosis=recovery.diagnosis,
            recentDialogueCount=len(case.get("recentDialogue", [])),
            recentDialogueTrimmedCount=int(case.get("recentDialogueTrimmedCount") or 0),
        )
        if recovery.decision == "abort":
            return None
        if recovery.decision == "ask_user":
            return isolated_context_clarification_result(
                body,
                settings,
                user_message,
                recovery,
                request_id=request_id,
                failure=failure,
            )

        retry_body = prepare_isolated_context_retry_body(body, case, recovery)
        update_chat_request_progress(
            request_id,
            "model-generating",
            "已经理清当前任务，正在回到正常回答流程",
        )
        result = process_chat_request_body(
            retry_body,
            settings,
            request_id=request_id,
            started_at=started_at,
            preflight=None,
            persona_snapshot=None,
        )
        result.update({
            "isolatedContextRecovery": True,
            "contextRecoveryDecision": recovery.decision,
            "contextRecoveryTaskGoal": recovery.task_goal,
            "contextRecoveryRelevantMessageIds": list(recovery.relevant_message_ids),
            "contextRecoveryExcludedMessageIds": list(recovery.excluded_message_ids),
            "contextRecoveryDiagnosis": recovery.diagnosis,
            "pipelineFailureType": type(failure).__name__,
        })
        return result
    except Exception as recovery_error:
        write_server_log(
            "isolated_context_recovery_failed",
            requestId=request_id,
            initialErrorType=type(failure).__name__,
            recoveryErrorType=type(recovery_error).__name__,
            recoveryError=str(recovery_error)[:500],
        )
        return None


def request_pipeline_rescue_plan(
    settings: dict[str, Any],
    case: Mapping[str, Any],
    *,
    request_id: str,
    finalize: bool = False,
) -> PipelineRescuePlan | None:
    payload: dict[str, Any] = {
        "model": settings["apiModel"],
        "temperature": 0.0,
        "max_tokens": 900 if finalize else 1100,
        "messages": [
            {
                "role": "system",
                "content": (
                    PIPELINE_RESCUE_FINALIZE_PROMPT
                    if finalize else PIPELINE_RESCUE_SYSTEM_PROMPT
                ),
            },
            {
                "role": "user",
                "content": json.dumps(case, ensure_ascii=False),
            },
        ],
    }
    if settings.get("useResponseFormat"):
        payload["response_format"] = {"type": "json_object"}
    if "deepseek.com" in settings["apiEndpoint"]:
        payload["thinking"] = {"type": "disabled"}
    content = send_upstream_chat_payload(
        settings,
        payload,
        timeout=40,
        request_id=request_id,
        purpose="pipeline_rescue_finalize" if finalize else "pipeline_rescue_plan",
    )
    return normalize_pipeline_rescue_plan(parse_json_object(content))


def pipeline_rescue_result_from_plan(
    plan: PipelineRescuePlan,
    settings: dict[str, Any],
    body: dict[str, Any],
    user_message: str,
    *,
    request_id: str,
    failure: Exception,
    tool_results: Sequence[Mapping[str, Any]] = (),
) -> dict[str, Any] | None:
    if plan.decision == "abort" and not plan.reply_zh:
        return None
    if not plan.reply_zh:
        return None
    result = normalize_model_reply({
        "reply": plan.reply_zh,
        "spokenTextJa": plan.spoken_ja,
        "emotion": "concerned",
        "gesture": "idle",
        "voiceStyle": "calm",
        "memoryUpdates": [],
        "requiresUserResponse": plan.requires_user_response,
        "expectedResponseType": plan.expected_response_type,
        "completedActs": ["complete_requested_task"],
        "standalone": True,
        "dependsOnUndeliveredPrefix": False,
        "turnComplete": True,
        "source": "model-pipeline-rescue",
    }, settings=settings)
    normalized_results = [
        dict(item) for item in tool_results if isinstance(item, Mapping)
    ]
    if normalized_results:
        result = enforce_external_action_receipt(result, normalized_results)
        result["toolResults"] = normalized_results
        result["toolUsed"] = ",".join(dict.fromkeys(
            str(item.get("name") or "") for item in normalized_results
            if str(item.get("name") or "")
        ))
        result["toolStatus"] = (
            "failed" if any(not item.get("ok") for item in normalized_results) else "ok"
        )
        receipts = action_receipts_from_results(normalized_results)
        if receipts:
            result["actionReceipt"] = receipts[-1]
            result["actionReceipts"] = receipts
    result.update({
        "ok": True,
        "requestId": request_id,
        "modelPipelineRescue": True,
        "pipelineFailureType": type(failure).__name__,
        "rescueDecision": plan.decision,
        "rescueDiagnosis": plan.diagnosis,
        "proactiveDirective": "unchanged",
        "proactiveDirectiveProvided": True,
    })
    return seal_recovery_turn_result(
        body,
        user_message,
        result,
        settings=settings,
        request_id=request_id,
        delivery_path="model_pipeline_rescue",
    )


def run_model_pipeline_rescue(
    body: dict[str, Any],
    settings: dict[str, Any],
    user_message: str,
    messages: list[dict[str, Any]],
    *,
    request_id: str,
    route_name: str,
    failure: Exception,
) -> dict[str, Any] | None:
    """Run one bounded planner/tool/finalizer rescue loop."""

    if (
        not ARCHITECTURE_FEATURES.model_pipeline_rescue_enabled
        or not configured(settings)
        or body.get("_modelPipelineRescueAttempted")
        or chat_request_cancelled(request_id)
        or not pipeline_failure_allows_model_rescue(failure)
    ):
        return None
    body["_modelPipelineRescueAttempted"] = True
    body["_settingsPermissionSnapshot"] = {
        definition.permission_key: bool(settings.get(definition.permission_key))
        for definition in DEFAULT_TOOL_REGISTRY.all()
        if definition.permission_key
    }
    case = pipeline_rescue_case(
        body,
        user_message,
        messages,
        request_id=request_id,
        route_name=route_name,
        failure=failure,
    )
    update_chat_request_progress(
        request_id,
        "recovering",
        "正常处理链路未能收尾，正在用精简任务快照重新规划一次",
    )
    try:
        plan = request_pipeline_rescue_plan(
            settings,
            case,
            request_id=request_id,
        )
        if plan is None:
            raise UpstreamProtocolError("pipeline rescue returned no valid plan")
        write_server_log(
            "pipeline_rescue_plan_created",
            requestId=request_id,
            decision=plan.decision,
            diagnosis=plan.diagnosis,
            requestedTools=[item.get("name") for item in plan.calls],
        )
        if plan.decision != "execute_tools":
            return pipeline_rescue_result_from_plan(
                plan,
                settings,
                body,
                user_message,
                request_id=request_id,
                failure=failure,
            )

        raw_requests = normalize_tool_requests({
            "toolRequests": list(plan.calls),
            "toolAuthorization": plan.tool_authorization,
            "targetDomain": plan.target_domain,
        })
        execution_state = cognitive_execution_state(body)
        constrained = constrain_model_tool_requests(
            raw_requests,
            user_message,
            body.get("_contextResolution")
            if isinstance(body.get("_contextResolution"), dict) else {},
            messages,
            body.get("_scheduleDecision"),
            cognitive_state=execution_state,
            evidence=body.get("_cognitiveEvidence") or {},
        )
        active_preflight = body_tool_preflight(body, user_message, messages)
        tool_results = execute_agent_tools(
            constrained,
            settings,
            user_message,
            preflight=active_preflight,
            request_id=request_id,
            cognitive_state=execution_state,
            schedule_decision=body.get("_scheduleDecision"),
        ) if constrained else [{
            "name": "pipeline_rescue",
            "ok": False,
            "error": "proposed_tool_calls_rejected_by_runtime",
            "attempted": False,
        }]
        body.setdefault("_rescueToolResults", []).extend(deepcopy(tool_results))
        body.setdefault("_cognitiveEvidence", {}).update(collect_evidence(tool_results))
        if execution_state:
            progressed = cognitive_execution_state(body)
            cognitive_turn_state(body)["task"] = deepcopy(progressed["task"])
        final_case = {
            **case,
            "rescuePlan": plan.to_dict(),
            "executedToolResults": tool_results,
            "instruction": "根据真实结果完成本轮；不得再调用工具。",
        }
        final_plan = request_pipeline_rescue_plan(
            settings,
            final_case,
            request_id=request_id,
            finalize=True,
        )
        if final_plan is None or final_plan.decision == "execute_tools":
            raise UpstreamProtocolError("pipeline rescue finalizer returned no final answer")
        return pipeline_rescue_result_from_plan(
            final_plan,
            settings,
            body,
            user_message,
            request_id=request_id,
            failure=failure,
            tool_results=tool_results,
        )
    except Exception as rescue_error:
        write_server_log(
            "pipeline_rescue_failed",
            requestId=request_id,
            initialErrorType=type(failure).__name__,
            rescueErrorType=type(rescue_error).__name__,
            rescueError=str(rescue_error)[:500],
        )
        return None


def pipeline_failure_allows_model_rescue(failure: Exception) -> bool:
    """Return whether a fresh compact model pass can plausibly repair a turn.

    HTTPError inherits from URLError, so the recoverable 400 case must be
    checked first. Grounding and request-validation errors are intentional
    control-plane stops rather than broken orchestration and must never be
    bypassed by a second model opinion.
    """

    if isinstance(failure, urllib.error.HTTPError):
        return int(failure.code) == 400
    if isinstance(failure, (RequestValidationError, GroundingGateError, CognitiveProtocolError, CognitiveCommitError, ContextCompatibilityError)):
        # A new model answer cannot repair a failed durable commit.
        return False
    if isinstance(
        failure,
        (urllib.error.URLError, TimeoutError, ConnectionError),
    ):
        return False
    return True


class AmadeusHTTPServer(ThreadingHTTPServer):
    """Loopback server tuned for concurrent UI, TTS, and diagnostic requests."""

    allow_reuse_address = True
    daemon_threads = True
    block_on_close = False
    request_queue_size = 64

    def __init__(self, *args: Any, **kwargs: Any) -> None:
        self.local_session_token = secrets.token_urlsafe(32)
        self._activity_lock = threading.Lock()
        self._active_requests = 0
        self._last_request_activity = time.monotonic()
        super().__init__(*args, **kwargs)

    def request_activity_started(self) -> None:
        with self._activity_lock:
            self._active_requests += 1
            self._last_request_activity = time.monotonic()

    def request_activity_finished(self) -> None:
        with self._activity_lock:
            self._active_requests = max(0, self._active_requests - 1)
            self._last_request_activity = time.monotonic()

    def activity_snapshot(self) -> dict[str, Any]:
        with self._activity_lock:
            return {
                "activeRequests": self._active_requests,
                "lastActivity": self._last_request_activity,
            }

    def process_request_thread(self, request: Any, client_address: Any) -> None:
        self.request_activity_started()
        try:
            super().process_request_thread(request, client_address)
        finally:
            self.request_activity_finished()


class AmadeusHandler(BaseHTTPRequestHandler):
    server_version = "AmadeusLocal/0.3"

    def end_headers(self) -> None:
        self.send_header("X-Content-Type-Options", "nosniff")
        self.send_header("Cross-Origin-Resource-Policy", "same-origin")
        self.send_header("X-Frame-Options", "DENY")
        self.send_header("Referrer-Policy", "same-origin")
        super().end_headers()

    def authorize_local_request(self, method: str) -> bool:
        rejection = request_rejection(self.headers, server_address=self.server.server_address,
            client_address=self.client_address, method=method, path=self.path,
            session_token=self.server.local_session_token)
        if rejection is None:
            return True
        status, code = rejection
        self.close_connection = True
        # Drain only small, already-sent bodies without parsing or dispatching.
        # Closing a Windows socket with unread POST data can reset the TCP
        # connection before the browser receives the rejection response.
        if method == "POST":
            try:
                remaining = int(self.headers.get("Content-Length", "0"))
                if 0 < remaining <= 65536 and not self.headers.get("Transfer-Encoding"):
                    self.connection.settimeout(0.25)
                    self.rfile.read(remaining)
            except (ValueError, OSError):
                pass
        # Do not log credentials, request bodies, or attacker-controlled URLs.
        write_server_log("local_api_request_rejected", method=method, status=status, code=code)
        self.send_json({"ok": False, "error": code, "code": code}, status)
        return False

    def do_OPTIONS(self) -> None:
        AmadeusHandler.authorize_local_request(self, "OPTIONS")

    def log_message(self, fmt: str, *args: Any) -> None:
        if sys.stdout is not None:
            sys.stdout.write("[%s] %s\n" % (self.log_date_time_string(), fmt % args))

    def send_json(self, payload: dict[str, Any], status: int = 200) -> bool:
        status_code, data = json_bytes(payload, status)
        try:
            self.send_response(status_code)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Content-Length", str(len(data)))
            self.send_header("Cache-Control", "no-store")
            self.end_headers()
            self.wfile.write(data)
            return True
        except (BrokenPipeError, ConnectionResetError, ConnectionAbortedError, OSError) as error:
            write_server_log(
                "client_disconnected_before_response",
                path=self.path,
                status=status_code,
                errorType=type(error).__name__,
                error=str(error)[:300],
            )
            return False

    def begin_ndjson(self, status: int = 200) -> None:
        self.send_response(status)
        self.send_header("Content-Type", "application/x-ndjson; charset=utf-8")
        self.send_header("Cache-Control", "no-store, no-transform")
        self.send_header("X-Accel-Buffering", "no")
        self.send_header("Connection", "close")
        self.end_headers()
        self.close_connection = True

    def send_ndjson_event(self, event: dict[str, Any]) -> bool:
        try:
            data = (json.dumps(event, ensure_ascii=False, separators=(",", ":")) + "\n").encode("utf-8")
            self.wfile.write(data)
            self.wfile.flush()
            return True
        except (BrokenPipeError, ConnectionResetError, ConnectionAbortedError, OSError):
            return False

    def send_binary(self, data: bytes, content_type: str, status: int = 200) -> None:
        self.send_response(status)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(len(data)))
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        self.wfile.write(data)

    def send_download(self, path: Path, metadata: dict[str, Any]) -> None:
        data = path.read_bytes()
        name = safe_attachment_name(metadata.get("name"), "output.txt")
        encoded_name = urllib.parse.quote(name, safe="")
        self.send_response(200)
        self.send_header("Content-Type", str(metadata.get("mimeType") or content_type_for(path)))
        self.send_header("Content-Length", str(len(data)))
        self.send_header("Content-Disposition", f"attachment; filename*=UTF-8''{encoded_name}")
        self.send_header("Cache-Control", "no-store")
        self.send_header("X-Content-Type-Options", "nosniff")
        self.end_headers()
        self.wfile.write(data)

    def do_GET(self) -> None:
        try:
            self._do_GET()
        except ContextCompatibilityError as error:
            self.send_json({"ok": False, "code": error.code, "error": str(error),
                            "retryable": error.code == "context_recovery_failed"}, 409)

    def _do_GET(self) -> None:
        if not AmadeusHandler.authorize_local_request(self, "GET"):
            return
        set_request_storage_scope(self.headers.get("X-Amadeus-Storage-Scope"))
        # urlsplit preserves semicolons in the pathname; they are not route aliases.
        request_url = urllib.parse.urlsplit(self.path)
        parsed_path = request_url.path
        if parsed_path == SESSION_PATH:
            self.send_json({"ok": True, "token": self.server.local_session_token})
            return
        file_route = re.fullmatch(r"/api/files/([a-fA-F0-9]{32})", parsed_path)
        if file_route:
            resolved = resolve_generated_file(file_route.group(1))
            if not resolved:
                self.send_error(404)
                return
            self.send_download(*resolved)
            return
        if parsed_path == "/api/health":
            self.send_json(model_status(self.server.server_address))
            return
        if parsed_path == "/api/runtime/status":
            self.send_json(runtime_status(self.server.server_address))
            return
        if parsed_path == "/api/gpt-sovits/status":
            self.send_json({"ok": True, "status": gpt_sovits_status()})
            return
        if RELEASE_MODE and (
            parsed_path == "/api/salieri"
            or parsed_path in {"/api/prompt", "/api/persona"}
            or parsed_path.startswith("/api/developer/")
        ):
            self.send_json({"ok": False, "error": "not_available_in_release"}, 404)
            return
        if parsed_path == "/api/salieri":
            self.send_json(salieri_transcript_payload())
            return
        if parsed_path == "/api/prompt":
            self.send_json({"prompt": read_system_prompt()})
            return
        if parsed_path == "/api/persona":
            self.send_json({"ok": True, "persona": persona_payload()})
            return
        if parsed_path == "/api/developer/live2d-models":
            self.send_json({"ok": True, "registry": live2d_models_payload()})
            return
        if parsed_path == "/api/developer/expression-training/preview":
            query = urllib.parse.parse_qs(request_url.query)
            preview = expression_training_preview_path((query.get("id") or [""])[0])
            if not preview:
                self.send_error(404)
                return
            self.send_binary(preview.read_bytes(), "image/png")
            return
        if parsed_path == "/api/developer/expression-training":
            if current_storage_scope() != "developer":
                self.send_json({"ok": False, "error": "developer_scope_required"}, 404)
                return
            self.send_json({"ok": True, "dataset": read_expression_training_dataset()})
            return
        if parsed_path == "/api/developer/voice-reference-review/audio":
            if current_storage_scope() != "developer":
                self.send_json({"ok": False, "error": "developer_scope_required"}, 404)
                return
            query = urllib.parse.parse_qs(request_url.query)
            audio = voice_reference_review_audio_path(
                (query.get("id") or [""])[0],
                (query.get("variant") or ["candidate"])[0],
            )
            if not audio:
                self.send_error(404)
                return
            self.send_binary(audio.read_bytes(), mimetypes.guess_type(audio.name)[0] or "audio/wav")
            return
        if parsed_path == "/api/developer/voice-reference-review":
            if current_storage_scope() != "developer":
                self.send_json({"ok": False, "error": "developer_scope_required"}, 404)
                return
            self.send_json(voice_reference_review_catalog())
            return
        if parsed_path == "/api/developer/chat-progress":
            query = urllib.parse.parse_qs(request_url.query)
            request_id = (query.get("requestId") or [""])[0]
            self.send_json(chat_request_progress(request_id))
            return
        if parsed_path == "/api/developer/persona-skills":
            if current_storage_scope() != "developer":
                self.send_json({"ok": False, "error": "developer_scope_required"}, 404)
                return
            query = urllib.parse.parse_qs(request_url.query)
            scope = normalize_storage_scope((query.get("scope") or ["normal"])[0])
            self.send_json({"ok": True, "scope": scope, "skills": persona_skill_catalog(ROOT),
                            "records": _PERSONA_SKILL_MONITOR.snapshot(scope), "historyLimit": 24})
            return
        if parsed_path == "/api/developer/relationship":
            query = urllib.parse.parse_qs(request_url.query)
            requested_scope = str((query.get("scope") or ["release"])[0]).strip().lower()
            view_scope = requested_scope if requested_scope in {"release", "normal", "developer"} else "release"
            relationship = (
                read_release_relationship_state()
                if view_scope == "release"
                else read_relationship_state_for_scope(view_scope)
            )
            self.send_json({
                "ok": True,
                "scope": view_scope,
                "readOnly": True,
                "relationship": relationship_developer_snapshot(relationship),
            })
            return
        if parsed_path == "/api/settings":
            self.send_json({"settings": public_settings()})
            return
        if parsed_path == "/api/cache/status":
            summaries = cache_status(ROOT, DATA_DIR)
            self.send_json({
                "ok": True,
                "unused": summaries["unused"].to_dict(),
                "allDisposable": summaries["all_disposable"].to_dict(),
            })
            return
        if parsed_path == "/api/conversation/recovery-preview":
            self.send_json({
                "ok": True,
                "storageHealth": conversation_storage_health(),
                "archivePreview": read_conversation_archive_turns(8),
                "activeDatabase": str(state_database_path()),
                "policy": "read_only_preview_no_active_file_replacement",
            })
            return
        if parsed_path == "/api/conversation/history":
            query = urllib.parse.parse_qs(
                request_url.query,
                keep_blank_values=True,
            )
            current_only = str((query.get("currentOnly") or ["1"])[0]).lower() in {
                "1", "true", "yes",
            }
            self.send_json(public_conversation_history(
                include_inactive_epochs=not current_only,
            ))
            return
        if parsed_path == "/api/conversations":
            self.send_json(conversation_session_summaries())
            return
        if parsed_path == "/api/conversation/search":
            query = urllib.parse.parse_qs(
                request_url.query,
                keep_blank_values=True,
            )
            try:
                limit = int((query.get("limit") or ["30"])[0])
                offset = int((query.get("offset") or ["0"])[0])
            except (TypeError, ValueError):
                self.send_json({"ok": False, "error": "invalid_search_page"}, 400)
                return
            self.send_json(search_conversation_history(
                (query.get("q") or [""])[0],
                role=(query.get("role") or ["all"])[0],
                limit=limit,
                offset=offset,
            ))
            return
        if parsed_path == "/api/background-image":
            background = configured_background_image()
            if not background:
                self.send_error(404)
                return
            self.send_binary(background.read_bytes(), content_type_for(background))
            return
        if parsed_path == "/api/bookmarks":
            query = urllib.parse.parse_qs(
                request_url.query,
                keep_blank_values=True,
            )
            try:
                limit = int((query.get("limit") or ["200"])[0])
            except (TypeError, ValueError):
                limit = 200
            self.send_json(tool_bookmark_list({}, {
                "query": (query.get("q") or [""])[0],
                "limit": limit,
            }))
            return
        if parsed_path == "/api/todos":
            query = urllib.parse.parse_qs(
                request_url.query,
                keep_blank_values=True,
            )
            scope = str((query.get("scope") or ["all"])[0]).strip().lower()
            try:
                since_revision = max(
                    0,
                    int((query.get("sinceRevision") or ["0"])[0] or 0),
                )
            except (TypeError, ValueError):
                since_revision = 0
            self.send_json(tool_todo_list({}, {
                "scope": scope,
                "sinceRevision": since_revision,
            }))
            return
        if parsed_path == "/api/memory":
            settings = load_settings()
            self.send_json({
                "memoryFile": (
                    "data/developer/memory.json"
                    if developer_storage_active()
                    else settings["memoryFile"]
                ),
                "memoryFileAbsolute": str(memory_path(settings)),
                "memories": read_memory(settings),
                "memoryRecords": [
                    item.to_dict() for item in read_memory_records(settings)
                ],
            })
            return
        target = clean_path(self.path)
        if not target or not target.exists():
            self.send_error(404)
            return
        data = target.read_bytes()
        self.send_response(200)
        self.send_header("Content-Type", content_type_for(target))
        self.send_header("Content-Length", str(len(data)))
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        self.wfile.write(data)

    def do_POST(self) -> None:
        if not AmadeusHandler.authorize_local_request(self, "POST"):
            return
        set_request_storage_scope(self.headers.get("X-Amadeus-Storage-Scope"))
        request_url = urllib.parse.urlsplit(self.path)
        parsed_path = request_url.path
        try:
            length = int(self.headers.get("Content-Length", "0"))
        except (TypeError, ValueError):
            self.send_json({"ok": False, "error": "invalid_content_length"}, 400)
            return
        if length < 0 or length > MAX_REQUEST_BODY_BYTES:
            self.send_json({"ok": False, "error": "request_body_too_large"}, 413)
            return
        body: dict[str, Any] = {}
        try:
            body = parse_json(self.rfile.read(length))
            if parsed_path in {"/api/runtime/client/register", "/api/runtime/client/heartbeat"}:
                lease = touch_runtime_client(body.get("clientId"), body.get("mode"))
                self.send_json({"ok": True, **lease})
                return
            if parsed_path == "/api/runtime/client/unregister":
                count = remove_runtime_client(body.get("clientId"))
                self.send_json({"ok": True, "activeClients": count})
                return
            if parsed_path == "/api/actions/open-browser":
                args = {
                    "url": str(body.get("url") or ""),
                    "query": str(body.get("query") or ""),
                    "browserIntent": str(body.get("browserIntent") or ""),
                    "actionId": str(body.get("actionId") or f"ui_{uuid.uuid4().hex}"),
                }
                self.send_json(tool_open_browser(load_settings(), args))
                return
            if RELEASE_MODE and (
                parsed_path == "/api/persona"
                or parsed_path.startswith("/api/developer/")
                or parsed_path in {"/api/salieri", "/api/salieri/unlock"}
            ):
                self.send_json({"ok": False, "error": "not_available_in_release"}, 404)
                return
            if parsed_path == "/api/salieri/unlock":
                result = enable_salieri_recorder(body.get("code"))
                self.send_json(result, 200 if result.get("ok") else 403)
                return
            if parsed_path == "/api/settings":
                settings = save_settings(body.get("settings", body))
                self.send_json({"ok": True, "settings": public_settings(settings)})
                return
            if parsed_path == "/api/cache/clear":
                mode = str(body.get("mode") or "unused").strip()
                if mode not in {"unused", "all_disposable"}:
                    self.send_json({"ok": False, "error": "invalid_cache_mode"}, 400)
                    return
                write_server_log(
                    "runtime_cache_clear_requested",
                    mode=mode,
                )
                result = clear_cache(ROOT, DATA_DIR, mode)  # type: ignore[arg-type]
                self.send_json(result)
                return
            if parsed_path == "/api/test-api":
                self.send_json(test_api_connection())
                return
            if parsed_path == "/api/test-web-search":
                self.send_json(test_web_search_connection())
                return
            if parsed_path == "/api/persona":
                override = write_persona_override(str(body.get("override") or ""))
                self.send_json({"ok": True, "override": override, "persona": persona_payload()})
                return
            if parsed_path == "/api/developer/live2d-expression-capture":
                self.send_json(save_live2d_expression_capture(body))
                return
            if parsed_path == "/api/developer/expression-training":
                if current_storage_scope() != "developer":
                    self.send_json({"ok": False, "error": "developer_scope_required"}, 404)
                    return
                self.send_json(update_expression_training_dataset(body))
                return
            if parsed_path == "/api/developer/voice-reference-review":
                if current_storage_scope() != "developer":
                    self.send_json({"ok": False, "error": "developer_scope_required"}, 404)
                    return
                self.send_json(update_voice_reference_review(body))
                return
            if parsed_path == "/api/developer/live2d-models":
                registry = write_live2d_model_override(
                    str(body.get("modelId") or ""),
                    body.get("override"),
                    reset=bool(body.get("reset")),
                )
                self.send_json({"ok": True, "registry": registry})
                return
            if parsed_path == "/api/gpt-sovits/start":
                incoming = body.get("settings") if isinstance(body.get("settings"), dict) else {}
                status = start_gpt_sovits_service(incoming)
                self.send_json({
                    "ok": bool(status.get("running") or status.get("starting")),
                    "status": status,
                    "settings": public_settings(),
                })
                return
            if parsed_path == "/api/gpt-sovits/stop":
                status = stop_gpt_sovits_service()
                self.send_json({"ok": True, "status": status, "settings": public_settings()})
                return
            if parsed_path == "/api/todos/reminders/poll":
                self.send_json(generate_todo_reminder(body))
                return
            if parsed_path == "/api/todos/reminders/ack":
                reminder_id = str(body.get("reminderId") or "").strip()
                if not reminder_id:
                    self.send_json({
                        "ok": False,
                        "error": "reminder_id_required",
                    }, 400)
                    return
                with state_database() as connection:
                    acknowledged = acknowledge_reminder(
                        connection,
                        reminder_id,
                        delivered=bool(body.get("delivered")),
                        error=str(body.get("error") or ""),
                    )
                self.send_json({
                    "ok": bool(acknowledged),
                    "reminder": acknowledged or None,
                    **({} if acknowledged else {"error": "reminder_not_found"}),
                }, 200 if acknowledged else 404)
                return
            if parsed_path == "/api/todos":
                result = tool_todo_manage({}, body)
                self.send_json(result, 200 if result.get("ok") else 400)
                return
            if parsed_path == "/api/bookmarks":
                result = tool_bookmark_manage(
                    {},
                    {**body, "commitIntent": True},
                    source_turn_id=str(body.get("requestId") or ""),
                )
                self.send_json(result, 200 if result.get("ok") else 400)
                return
            if parsed_path == "/api/memory/generate":
                memories = generate_memory_from_model(body)
                settings = load_settings()
                self.send_json({
                    "ok": True,
                    "memories": memories,
                    "memoryRecords": [
                        item.to_dict() for item in read_memory_records(settings)
                    ],
                    "memoryFileAbsolute": str(memory_path(settings)),
                })
                return
            if parsed_path == "/api/proactive-generate":
                self.send_json(generate_proactive_interaction(body))
                return
            if parsed_path == "/api/conversation/proactive":
                self.send_json(append_proactive_conversation_event(body))
                return
            if parsed_path == "/api/conversation/delivery":
                self.send_json(record_delivered_turn_event(body))
                return
            if parsed_path == "/api/conversation/recovery-build":
                self.send_json(build_conversation_recovery_candidate())
                return
            if parsed_path == "/api/conversation/new":
                context = start_new_conversation()
                self.send_json({"ok": True, "context": context})
                return
            if parsed_path == "/api/conversation/delete":
                self.send_json(delete_conversation(body.get("conversationId")))
                return
            if parsed_path == "/api/conversation/switch":
                context = switch_conversation(body.get("conversationId"))
                self.send_json({
                    "ok": True,
                    "context": context,
                    "history": public_conversation_history(
                        include_inactive_epochs=False,
                    ),
                })
                return
            if parsed_path == "/api/conversation/clear":
                context = clear_conversation_context()
                self.send_json({"ok": True, "context": context})
                return
            if parsed_path == "/api/conversation/short-memory/clear":
                context = clear_short_term_memory()
                self.send_json({"ok": True, "context": context})
                return
            if parsed_path == "/api/memory/clear":
                memories = clear_memory_records(settings=load_settings())
                relationship = reset_dignity_boundary_after_full_memory_clear()
                self.send_json({
                    "ok": True,
                    "memories": memories,
                    "memoryRecords": [
                        item.to_dict() for item in read_memory_records(load_settings())
                    ],
                    "dignityBoundaryReset": True,
                    "dignityViolationCount": int(relationship.get("dignityViolationCount") or 0),
                    "dignityLocked": bool(relationship.get("dignityLocked")),
                })
                return
            if parsed_path == "/api/memory":
                update = body.get("memories") if isinstance(body.get("memories"), list) else []
                if developer_storage_active():
                    settings = load_settings()
                elif "memoryFile" in body:
                    settings = save_settings({"memoryFile": body["memoryFile"]})
                else:
                    settings = load_settings()
                memories = write_memory(update, settings=settings)
                self.send_json({
                    "ok": True,
                    "memories": memories,
                    "memoryRecords": [
                        item.to_dict() for item in read_memory_records(settings)
                    ],
                    "memoryFile": (
                        "data/developer/memory.json"
                        if developer_storage_active()
                        else settings["memoryFile"]
                    ),
                    "memoryFileAbsolute": str(memory_path(settings)),
                })
                return
            if parsed_path == "/api/tts-alignment":
                self.send_json(read_deferred_tts_alignment(body))
                return
            if parsed_path == "/api/tts-prepare":
                self.send_json(prepare_tts_with_deferred_alignment(body))
                return
            if parsed_path == "/api/tts-timed":
                payload = synthesize_tts_timed(body)
                self.send_json(payload)
                return
            if parsed_path == "/api/tts":
                content_type, audio = synthesize_tts(body)
                self.send_binary(audio, content_type)
                return
            if parsed_path == "/api/emotion-token":
                self.send_json(generate_context_emotion_token(body))
                return
            if parsed_path == "/api/startup-greeting":
                self.send_json(generate_startup_greeting(body))
                return
            if parsed_path == "/api/interaction":
                started = time.time()
                touch_context = touch_conversation_context(body)
                relationship_before = read_relationship_state()
                event = normalize_touch_event(body, relationship_before)
                if relationship_before.get("coldShoulder"):
                    result = furious_touch_blocked_response(relationship_before)
                    result.update({
                        "relationshipTone": relationship_before.get("stage", "close_companion"),
                        "touchZone": event["zone"],
                        "touchAction": event["action"],
                        "latencyMs": round((time.time() - started) * 1000),
                        "touchMetrics": {"blockedByColdShoulder": True},
                    })
                    write_server_log(
                        "touch_blocked_by_cold_shoulder",
                        zone=event["zone"],
                        action=event["action"],
                    )
                    self.send_json(result)
                    return
                original_clip = select_touch_original_clip(event)
                if original_clip is not None:
                    result = touch_original_clip_response(original_clip, event)
                else:
                    result = call_touch_upstream(body, event, relationship_before) if configured() else mock_touch_reply(event)
                raw_model_output = result.pop("_debugRawModelOutput", "")
                upstream_payload = result.pop("_debugUpstreamPayload", None)
                touch_metrics = result.pop("_touchMetrics", {})
                touch_metrics.setdefault(
                    "responseAngle",
                    str(event.get("responseDirective", {}).get("angle") or ""),
                )
                write_server_log(
                    "touch_response_generated",
                    zone=event["zone"],
                    action=event["action"],
                    responseAngle=str(event.get("responseDirective", {}).get("angle") or "")[:160],
                    repetitionRepaired=bool(touch_metrics.get("repetitionRepaired")),
                    structuredOutputRepaired=bool(touch_metrics.get("structuredOutputRepaired")),
                    fallbackUsed=bool(touch_metrics.get("fallbackUsed")),
                    repairReasons=list(touch_metrics.get("repairReasons") or []),
                    finalFallbackReasons=list(touch_metrics.get("finalFallbackReasons") or []),
                    softGroundingAccepted=bool(touch_metrics.get("softGroundingAccepted")),
                    originalClipUsed=bool(touch_metrics.get("originalClipUsed")),
                    originalClipId=str(touch_metrics.get("originalClipId") or ""),
                )
                # Touch feedback is latency-sensitive. The touch model must return
                # both languages in one request; malformed Japanese uses a local
                # fallback instead of silently adding a second network round trip.
                if not result.get("originalAudio"):
                    result = align_spoken_text_ja(load_settings(), result, allow_remote_repair=True)
                interaction_text = (
                    f"用户通过界面完成了一段{event['actionLabel']}；这些动作已在停止点击后合并为一次互动。"
                    if event.get("aggregatedBurst")
                    else {
                        "head": "用户通过界面摸了摸头。",
                        "hand": "用户通过界面牵住了手。",
                        "face": "用户通过界面轻触脸颊。",
                        "mouth": "用户尝试了亲吻互动。",
                        "chest": "用户进行了越界的胸口触摸。",
                    }[event["zone"]]
                )
                relationship = update_relationship_state(interaction_text, result)
                if body.get("developerDebug") and not RELEASE_MODE:
                    result["debugInteraction"] = {
                        "normalizedEvent": event,
                        "hiddenPrompt": touch_event_prompt(event),
                        "upstreamPayload": upstream_payload,
                        "rawModelOutput": raw_model_output or "(local fallback: no upstream raw output)",
                        "normalizedResult": {
                            key: value for key, value in result.items()
                            if not key.startswith("_")
                        },
                        "relationshipBefore": relationship_before,
                        "relationshipAfter": relationship,
                        "metrics": touch_metrics,
                    }
                result.update({
                    "ok": True,
                    "source": result.get("source") or ("api" if configured() else "local"),
                    "interactionMode": (
                        "original_clip"
                        if result.get("originalAudio")
                        else "hidden_agent_event" if configured() else "local_fallback"
                    ),
                    "relationshipTone": relationship.get("stage", "close_companion"),
                    "touchZone": event["zone"],
                    "touchAction": event["action"],
                    "memoryUpdates": [],
                    "latencyMs": round((time.time() - started) * 1000),
                    "touchMetrics": touch_metrics,
                })
                append_touch_conversation_reply(interaction_text, result, touch_context)
                self.send_json(result)
                return
            if parsed_path == "/api/chat-stream/continue":
                request_id = normalize_chat_request_id(body.get("requestId"))
                released = release_chat_stream_tool_gate(request_id)
                write_server_log(
                    "chat_stream_tool_gate_ack",
                    requestId=request_id,
                    released=released,
                    voiceStarted=bool(body.get("voiceStarted")),
                )
                self.send_json({
                    "ok": True,
                    "requestId": request_id,
                    "released": released,
                    "voiceStarted": bool(body.get("voiceStarted")),
                })
                return
            if parsed_path == "/api/chat/cancel":
                result = cancel_chat_request(body.get("requestId"))
                self.send_json(result, 200 if result.get("ok") else 400)
                return
            if parsed_path == "/api/chat-stream":
                self.handle_chat_stream(body)
                return
            if parsed_path == "/api/chat":
                self.handle_chat(body)
                return
            self.send_error(404)
        except ContextCompatibilityError as error:
            self.send_json({"ok": False, "code": error.code, "error": str(error),
                            "retryable": error.code == "context_recovery_failed"}, 409)
        except RequestValidationError as error:
            self.send_json({
                "ok": False,
                "code": error.code,
                "error": error.message,
                "retryable": False,
            }, 400)
        except LocalTtsSynthesisError as error:
            request_id = normalize_chat_request_id(body.get("requestId")) if isinstance(body, dict) else ""
            write_server_log(
                "local_tts_synthesis_failure",
                path=self.path,
                requestId=request_id,
                code=error.code,
                deterministic=error.deterministic,
                upstreamStatus=error.upstream_status,
                error=error.message[:500],
            )
            self.send_json({
                "ok": False,
                "code": error.code,
                "error": error.message,
                "retryable": not error.deterministic,
                "deterministic": error.deterministic,
                "requestId": request_id,
                "diagnostics": error.diagnostics,
            }, 422 if error.deterministic else 502)
        except urllib.error.HTTPError as error:
            request_id = normalize_chat_request_id(body.get("requestId")) if isinstance(body, dict) else ""
            retryable = int(error.code) in UPSTREAM_RETRYABLE_STATUS
            diagnostics = upstream_http_error_diagnostics(error)
            write_server_log(
                "request_upstream_http_failure",
                path=self.path,
                requestId=request_id,
                status=int(error.code),
                retryable=retryable,
                providerErrorCode=diagnostics["providerErrorCode"],
                providerErrorType=diagnostics["providerErrorType"],
                providerMessage=diagnostics["providerMessage"],
                responseBodyLength=diagnostics["responseBodyLength"],
                traceback=traceback.format_exc(limit=8),
            )
            self.send_json({
                "ok": False,
                "code": f"upstream_http_{int(error.code)}",
                "error": upstream_http_error_user_message(error),
                "retryable": retryable,
                "requestId": request_id,
            }, 503 if retryable else 502)
        except (urllib.error.URLError, TimeoutError, ConnectionError) as error:
            request_id = normalize_chat_request_id(body.get("requestId")) if isinstance(body, dict) else ""
            write_server_log(
                "request_network_failure",
                path=self.path,
                requestId=request_id,
                errorType=type(error).__name__,
                error=str(error)[:500],
                traceback=traceback.format_exc(limit=8),
            )
            self.send_json({
                "ok": False,
                "code": "upstream_network_error",
                "error": "连接 DeepSeek 时发生了瞬时网络错误。",
                "retryable": True,
                "requestId": request_id,
            }, 503)
        except CognitiveSemanticAuditProtocolError as error:
            request_id = normalize_chat_request_id(body.get("requestId")) if isinstance(body, dict) else ""
            write_server_log("request_semantic_audit_protocol_failure", requestId=request_id,
                             error=str(error)[:2000], stage="semantic_audit")
            self.send_json({"ok": False, "code": error.code,
                            "error": "回复审核未能返回完整结果，这轮已停止，尚未保存为成功。",
                            "retryable": False, "requestId": request_id, "stage": "semantic_audit"}, 502)
        except CognitiveProtocolError as error:
            request_id = normalize_chat_request_id(body.get("requestId")) if isinstance(body, dict) else ""
            request_preserved = preserve_failed_cognitive_request(body) if isinstance(body, dict) else False
            write_server_log("request_cognitive_validation_failure", requestId=request_id,
                             error=str(error)[:2000], stage="cognitive_gate")
            self.send_json({"ok": False, "code": "cognitive_revision_failed",
                            "error": "这轮回复没能整理完成，已停止继续执行。已运行工具的结果会保留，这不代表那些操作没有发生。",
                            "completedTools": completed_tools_for_request(body) if isinstance(body, dict) else [],
                            "failedRequestPreserved": request_preserved,
                            "retryable": False, "requestId": request_id, "stage": "cognitive_gate"}, 502)
        except UpstreamProtocolError as error:
            request_id = normalize_chat_request_id(body.get("requestId")) if isinstance(body, dict) else ""
            write_server_log(
                "request_upstream_protocol_failure",
                path=self.path,
                requestId=request_id,
                error=str(error)[:500],
                traceback=traceback.format_exc(limit=8),
            )
            self.send_json({
                "ok": False,
                "code": "upstream_incomplete_response",
                "error": "DeepSeek 返回了不完整响应，自动重试后仍未恢复。",
                "retryable": True,
                "requestId": request_id,
            }, 503)
        except Exception as error:
            request_id = normalize_chat_request_id(body.get("requestId")) if isinstance(body, dict) else ""
            write_server_log(
                "request_internal_failure",
                path=self.path,
                requestId=request_id,
                errorType=type(error).__name__,
                error=str(error)[:500],
                traceback=traceback.format_exc(limit=12),
            )
            self.send_json({
                "ok": False,
                "code": "internal_error",
                "error": "本地处理链路发生异常，详情已写入 server_errors.jsonl。",
                "retryable": False,
                "requestId": request_id,
            }, 500)

    def handle_chat_stream(self, body: dict[str, Any]) -> None:
        request_id = prepare_external_chat_body(body)
        supersedes_request_id = normalize_chat_request_id(body.get("supersedesRequestId"))
        claim, claim_value = claim_chat_request(request_id, supersedes_request_id)
        if claim == "owner":
            begin_persona_skill_record(body)
        if claim == "wait":
            event = claim_value
            if isinstance(event, threading.Event):
                event.wait(190)
            claim_value = completed_chat_request(request_id)
            claim = "cached" if claim_value else "timeout"

        self.begin_ndjson()
        turn_id = f"{request_id or uuid.uuid4().hex}:turn"
        schema_version = 1

        def emit(event_type: str, sequence: int, payload: dict[str, Any]) -> bool:
            return self.send_ndjson_event({
                "type": event_type,
                "requestId": request_id,
                "turnId": turn_id,
                "sequence": sequence,
                "schemaVersion": schema_version,
                "payload": payload,
            })

        if claim == "cached" and isinstance(claim_value, dict):
            emit("turn_header", 0, {
                "route": "fallback_legacy",
                "routeReason": "request_deduplicated",
                "turnEmotion": "thinking",
            })
            emit("turn_trailer", 1, {
                "route": "fallback_legacy",
                "finalResult": {**claim_value, "requestDeduplicated": True},
            })
            return
        if claim == "timeout":
            emit("turn_abort", 0, {
                "reason": "duplicate_request_wait_timeout",
                "discardPendingUtterances": True,
                "stopAudio": False,
            })
            return

        settings = load_settings()
        started = time.time()
        stream_started_perf = time.perf_counter()
        user_message, messages = streaming_user_message(body)
        emitted_utterances: list[dict[str, Any]] = []
        delivered_answer_utterances = 0
        header_payload: dict[str, Any] = {}
        preflight: dict[str, Any] | None = None
        route_name = "fallback_legacy"
        fast_persona_snapshot: PersonaContextSnapshot | None = None
        try:
            ensure_turn_context_snapshot(
                body,
                request_id=request_id,
                user_message=user_message,
            )
            ensure_context_control(body, user_message=user_message, settings=settings)
            resolve_recent_artifact_task_context(
                body, settings, user_message, request_id=request_id,
            )
            preflight = dignity_preflight(
                settings,
                user_message,
                messages,
                request_id=request_id,
            )
            if isinstance(preflight.get("assessment"), dict):
                body["_dignityAssessment"] = dict(preflight["assessment"])
            route = classify_streaming_chat_route(body, settings, preflight=preflight)
            route_name = str(route.get("route") or "fallback_legacy")
            write_server_log(
                "chat_stream_route_selected",
                requestId=request_id,
                route=route_name,
                reason=str(route.get("reason") or ""),
            )

            if route_name != "fast_chat":
                header_payload = {
                    "route": route_name,
                    "routeReason": route.get("reason"),
                    "turnEmotion": "focused" if route_name == "tool_gated" else "thinking",
                    "emotionIntensity": 0.72,
                    "gesture": "nod",
                    "voiceStyle": "calm",
                    "voiceTone": "serious",
                    "voiceIntensity": "normal",
                    "speechPace": "normal",
                    "speechSpeed": 1.0,
                    "deliveryMode": "normal",
                    "blushIntensity": 0.0,
                    "eyeContact": 0.7,
                    "gazeX": 0.0,
                    "gazeY": -0.04,
                    "tension": 0.22,
                    "confidence": 0.95,
                }
                if not emit("turn_header", 0, header_payload):
                    return
                sequence = 1
                stream_preamble: dict[str, Any] = {}

                def emit_progress_utterance(payload: dict[str, Any]) -> bool:
                    nonlocal sequence
                    if not isinstance(payload, dict):
                        return False
                    accepted = emit("progress_utterance", sequence, payload)
                    if not accepted:
                        return False
                    emitted_utterances.append(dict(payload))
                    if payload.get("progressKind") == "research_bridge":
                        stream_preamble.clear()
                        stream_preamble.update(payload)
                    sequence += 1
                    return True

                if route_name == "tool_gated" and preflight.get("action") == "continue":
                    tool_requests = (
                        route.get("toolRequests")
                        if isinstance(route.get("toolRequests"), list)
                        else []
                    )
                    tool_names = {
                        str(item.get("name") or "")
                        for item in tool_requests
                        if isinstance(item, dict)
                    }
                    tool_status = {
                        "stage": (
                            "research-planning"
                            if tool_names & {"web_search", "read_web_page"}
                            else "tool-executing"
                        ),
                        "displayText": (
                            "正在核对回答中需要确认的公开信息"
                            if tool_names & {"web_search", "read_web_page"}
                            else "正在获取回答所需的工具证据"
                        ),
                        "speakable": False,
                        "voiceGate": "not_required",
                    }
                    if not emit("tool_status", sequence, tool_status):
                        return
                    sequence += 1
                result = process_chat_request_body(
                    body,
                    settings,
                    request_id=request_id,
                    started_at=started,
                    preflight=preflight,
                    stream_preamble=stream_preamble,
                    progress_callback=emit_progress_utterance,
                )
                finish_chat_request(request_id, result)
                emit("turn_trailer", sequence, {
                    "route": route_name,
                    "routeReason": route.get("reason"),
                    "finalResult": result,
                    "preambleUtteranceIds": [
                        str(item.get("utteranceId") or "") for item in emitted_utterances
                    ],
                })
                return

            update_chat_request_progress(request_id, "model-generating", "快路径正在生成第一条完整语句")
            prepared_fast_turn = body_prepared_action_turn(
                body,
                user_message,
                request_id=request_id,
            )
            fast_interpretation, fast_policy, fast_contract = turn_contract_context(
                user_message,
                prepared_fast_turn,
                task_body=body,
            )
            body["_cognitiveTurnContract"] = fast_contract
            fast_relationship_state = frozen_turn_relationship_state(body) or read_relationship_state()
            fast_persona_snapshot = build_persona_context_snapshot(
                user_message,
                messages,
                contextual_reference_resolution(
                    user_message,
                    messages,
                    request_id=request_id,
                    current_artifacts=current_turn_context_artifacts(body),
                    context_state=frozen_turn_context_state(body),
                    model_owned=bool(cognitive_turn_state(body)),
                ),
                fast_relationship_state,
                cognitive_body=body,
            )

            def finalize_fast_candidate(
                combined_candidate: dict[str, Any],
            ) -> tuple[dict[str, Any], str]:
                bind_turn_context_to_result(body, combined_candidate)
                if isinstance(body.get("_discourseLedger"), Mapping):
                    combined_candidate["_referenceLedger"] = dict(
                        body["_discourseLedger"]
                    )
                combined_candidate.setdefault("_chatMetrics", {})[
                    "personaContextSnapshot"
                ] = fast_persona_snapshot.safe_diagnostic()
                combined_candidate["personaContextSnapshotId"] = (
                    fast_persona_snapshot.snapshot_id
                )
                if not (body.get("_cognitiveOutcomeVerification") or {}).get("valid"):
                    combined_candidate = enforce_fast_dialogue_policy_once(
                        settings,
                        user_message,
                        combined_candidate,
                        fast_policy,
                        messages=messages,
                        request_id=request_id,
                        persona_snapshot=fast_persona_snapshot,
                    )
                combined_candidate.setdefault("_chatMetrics", {})["conversationEpoch"] = (
                    _safe_nonnegative_int(
                        body.get("contextEpoch")
                        if body.get("contextEpoch") is not None
                        else current_conversation_epoch()
                    )
                )
                if not (body.get("_cognitiveOutcomeVerification") or {}).get("valid"):
                    if (
                        route_execution_plan is not None
                        and route_execution_plan.required_capabilities
                    ):
                        raise UpstreamProtocolError(
                            "model returned final_answer before required capability: "
                            + ",".join(route_execution_plan.required_capabilities)
                        )
                    active_plan = EpistemicPlan.from_dict(
                        prepared_fast_turn.epistemic_plan
                    ) or create_epistemic_plan(
                        request_id,
                        fast_interpretation,
                        decision=route_research_decision,
                    )
                    confidence_gate = knowledge_confidence_gate_decision(
                        active_plan.fact_requirements,
                        combined_candidate.get("knowledgeConfidence"),
                        confidence_provided=bool(
                            combined_candidate.get("knowledgeConfidenceProvided")
                        ),
                        research_policy=active_plan.research_policy,
                        web_permission=bool(settings.get("permissionWebSearch")),
                    )
                    write_server_log(
                        "fast_knowledge_confidence_gate_decision",
                        requestId=request_id,
                        planId=active_plan.plan_id,
                        planRevision=active_plan.revision,
                        modelConfidence=str(
                            combined_candidate.get("knowledgeConfidence") or ""
                        )[:16],
                        confidenceProvided=bool(
                            combined_candidate.get("knowledgeConfidenceProvided")
                        ),
                        decision=confidence_gate.to_dict(),
                    )
                    if confidence_gate.status == "RESEARCH_ESCALATION":
                        body["_researchEscalation"] = {
                            "reason": "model_knowledge_confidence_below_threshold",
                            "queries": [],
                            "unknownEntities": [],
                            "verificationTargets": list(
                                confidence_gate.missing_verification_targets
                                or active_plan.verification_targets
                                or ("uncertain external fact",)
                            ),
                            "confidence": (
                                0.25
                                if str(combined_candidate.get("knowledgeConfidence")) == "low"
                                else 0.5
                            ),
                            "origin": "knowledge_confidence_gate",
                        }
                        update_chat_request_progress(
                            request_id,
                            "research-escalation",
                            "模型对外部事实把握不足，正在联网核实",
                        )
                        recovered = process_chat_request_body(
                            body,
                            settings,
                            request_id=request_id,
                            started_at=started,
                            preflight=preflight,
                            persona_snapshot=fast_persona_snapshot,
                        )
                        recovered["researchEscalatedFromKnowledgeConfidence"] = True
                        return recovered, "research_loop"
                    if confidence_gate.status == "REWRITE_WITH_UNCERTAINTY":
                        combined_candidate = terminal_grounding_boundary_reply(
                            combined_candidate
                        )
                        combined_candidate["knowledgeConfidenceBoundaryApplied"] = True
                    draft_gate = grounded_claim_gate_decision(
                        str(combined_candidate.get("reply") or ""),
                        active_plan.epistemic_state(),
                        None,
                        research_policy=(
                            active_plan.research_policy
                            if settings.get("permissionWebSearch")
                            else "forbidden"
                        ),
                    )
                    if (
                        settings.get("permissionWebSearch")
                        and active_plan.research_policy != "forbidden"
                        and needs_post_answer_research_audit(
                            active_plan,
                            draft_gate,
                            None,
                        )
                    ):
                        try:
                            semantic_audit = audit_model_research_need(
                                settings,
                                user_message,
                                str(combined_candidate.get("reply") or ""),
                                active_plan,
                                request_id=request_id,
                            )
                            write_server_log(
                                "post_answer_research_need_audit",
                                requestId=request_id,
                                route="fast_stream",
                                **semantic_audit,
                            )
                            if semantic_audit.get("researchNeeded"):
                                body["_researchEscalation"] = {
                                    "reason": "model_post_answer_semantic_audit",
                                    "queries": [semantic_audit["query"]],
                                    "unknownEntities": [],
                                    "verificationTargets": [
                                        "model-identified unsupported external claim"
                                    ],
                                    "confidence": 0.9,
                                    "origin": "post_answer_model_audit",
                                }
                                update_chat_request_progress(
                                    request_id,
                                    "research-escalation",
                                    "模型审计发现回答依赖实时外部证据，正在核实",
                                )
                                recovered = process_chat_request_body(
                                    body,
                                    settings,
                                    request_id=request_id,
                                    started_at=started,
                                    preflight=preflight,
                                    persona_snapshot=fast_persona_snapshot,
                                )
                                recovered["researchEscalatedFromSemanticAudit"] = True
                                return recovered, "research_loop"
                        except Exception as audit_error:
                            write_server_log(
                                "post_answer_research_need_audit_failed",
                                requestId=request_id,
                                route="fast_stream",
                                errorType=type(audit_error).__name__,
                                error=str(audit_error)[:500],
                            )
                            combined_candidate = terminal_grounding_boundary_reply(
                                combined_candidate
                            )
                            combined_candidate["webEvidenceLimited"] = True
                            combined_candidate["semanticResearchAuditFailed"] = True
                try:
                    # The stream has already resolved the current task.  Do
                    # not let the finalizer rebuild a weaker contract from an
                    # elliptical original message after generation.
                    return finalize_chat_response(
                        settings,
                        user_message,
                        combined_candidate,
                        request_id=request_id,
                        started_at=started,
                        preserve_accepted_text=True,
                        prepared_turn=prepared_fast_turn,
                        defer_persistence_until_after_utterance=not bool(
                            (body.get("_cognitiveOverlay") or {}).get("patches")
                        ),
                        persona_snapshot=fast_persona_snapshot,
                        resolved_interpretation=fast_interpretation,
                        resolved_contract=fast_contract,
                        resolved_dialogue=task_review_dialogue_messages(body, messages),
                        cognitive_body=body,
                    ), route_name
                except FinalProjectionAuditRepairError as audit_error:
                    recovered_result = recover_final_projection_candidate(
                        body,
                        settings,
                        audit_error,
                        request_id=request_id,
                        persona_snapshot=fast_persona_snapshot,
                    )
                    recovered_prepared = body_prepared_action_turn(
                        body,
                        user_message,
                        request_id=request_id,
                    )
                    recovered_interpretation, _, recovered_contract = turn_contract_context(
                        user_message,
                        recovered_prepared,
                        task_body=body,
                    )
                    finalized = finalize_chat_response(
                        settings,
                        user_message,
                        recovered_result,
                        request_id=request_id,
                        started_at=started,
                        preserve_accepted_text=True,
                        prepared_turn=recovered_prepared,
                        defer_persistence_until_after_utterance=not bool(
                            (body.get("_cognitiveOverlay") or {}).get("patches")
                        ),
                        persona_snapshot=fast_persona_snapshot,
                        resolved_interpretation=recovered_interpretation,
                        resolved_contract=recovered_contract,
                        resolved_dialogue=task_review_dialogue_messages(body, messages),
                        cognitive_body=body,
                    )
                    # The rejected fast candidate is still buffered. Returning
                    # a distinct route prevents the outer stream from emitting
                    # those stale utterances; the repaired finalResult carries
                    # the only accepted speech.
                    return finalized, "cognitive_final_audit_repair"
                except GroundingGateError as gate_error:
                    decision = gate_error.decision
                    if (
                        getattr(decision, "status", "") != "RESEARCH_ESCALATION"
                        or not settings.get("permissionWebSearch")
                    ):
                        raise
                    body["_researchEscalation"] = {
                        "reason": "grounding_gate_research_escalation",
                        "queries": [],
                        "unknownEntities": [],
                        "verificationTargets": list(
                            getattr(decision, "missing_verification_targets", ())
                            or ("unsupported external claims",)
                        ),
                        "confidence": 0.45,
                        "origin": "final_grounding_gate",
                    }
                    recovered = process_chat_request_body(
                        body,
                        settings,
                        request_id=request_id,
                        started_at=started,
                        preflight=preflight,
                        persona_snapshot=fast_persona_snapshot,
                    )
                    recovered["researchEscalatedFromGroundingGate"] = True
                    return recovered, "research_loop"

            fast_max_tokens = fast_stream_token_budget(fast_policy)
            fast_messages, fast_context_pressure = pressure_managed_prompt(
                build_fast_stream_messages(
                    body,
                    settings,
                    user_message,
                    messages,
                    fast_policy,
                    request_id,
                    fast_interpretation,
                    fast_contract,
                    fast_persona_snapshot,
                ),
                settings,
                reserved_output_tokens=fast_max_tokens,
                request_id=request_id,
                stage="fast_stream_primary",
            )
            body["_contextPressure"] = fast_context_pressure
            payload: dict[str, Any] = {
                "model": settings["apiModel"],
                "temperature": 0.35,
                "max_tokens": fast_max_tokens,
                "messages": fast_messages,
            }
            # V3 is one JSON container with an ordered speechUnits array.  It
            # therefore remains compatible with provider JSON mode while the
            # HTTP body itself is streamed.  The previous JSONL contract had
            # to remove response_format and DeepSeek routinely answered with
            # ordinary prose, making repair the normal path.
            if settings.get("useResponseFormat"):
                payload["response_format"] = {"type": "json_object"}
            if "deepseek.com" in settings["apiEndpoint"]:
                payload["thinking"] = {"type": "disabled"}
            parser = ModelSemanticStreamParser()
            raw_stream_parts: list[str] = []
            trailer_seen = False
            atomic_protocol_recovered = False
            first_utterance_at = 0.0
            research_escalation: dict[str, Any] | None = None
            research_escalation_sequence = 0
            tool_escalation: dict[str, Any] | None = None
            tool_escalation_sequence = 0
            route_research_decision = ResearchDecision.from_dict(
                route.get("researchDecision")
                if isinstance(route.get("researchDecision"), dict)
                else prepared_fast_turn.research_decision
            )
            route_execution_plan = execution_plan_from_dict(
                route.get("executionPlan")
                if isinstance(route.get("executionPlan"), dict)
                else body.get("_turnExecutionPlan")
                if isinstance(body.get("_turnExecutionPlan"), dict)
                else None
            )
            # Every candidate utterance remains backend-private until the same
            # turn's GroundedClaimGate accepts the completed draft.  This keeps
            # UI text, TTS and Live2D from committing content that a later gate
            # may reject.
            buffer_until_evidence_gate = True
            buffered_utterance_events: list[tuple[int, dict[str, Any]]] = []

            def resolve_missing_stream_emotions(
                utterances: list[dict[str, Any]],
            ) -> list[dict[str, Any]]:
                if not any(
                    item.get("emotionMissingFromModel") for item in utterances
                ):
                    return utterances
                try:
                    update_chat_request_progress(
                        request_id,
                        "repairing-emotion",
                        "正文已冻结，正在补齐表情与语音情绪",
                    )
                    return repair_frozen_utterance_emotions_once(
                        settings,
                        utterances,
                        user_message=user_message,
                        recent_messages=messages,
                        relationship_state=fast_relationship_state,
                        request_id=request_id,
                    )
                except Exception as emotion_error:
                    write_server_log(
                        "stream_emotion_label_recovery_failed",
                        requestId=request_id,
                        errorType=type(emotion_error).__name__,
                        error=str(emotion_error)[:500],
                    )
                    return [
                        {
                            **item,
                            "emotionResolvedLocally": True,
                            "emotionUnavailableReason": "emotion_label_recovery_failed",
                        }
                        for item in utterances
                    ]

            for delta in iter_conversation_brain_stream(
                body, settings,
                payload,
                timeout=90,
                request_id=request_id,
                purpose="chat_fast_utterance_stream",
            ):
                if chat_request_cancelled(request_id):
                    raise RequestValidationError("request_superseded", "这轮请求已被后续输入替代。")
                raw_stream_parts.append(str(delta or ""))
                for event in parser.feed(delta):
                    event_type = event["type"]
                    sequence = int(event["sequence"])
                    event_payload = dict(event["payload"])
                    if event_type == "turn_header":
                        if sequence != 0:
                            raise UpstreamProtocolError("turn_header must be the first event")
                        header_payload = {
                            **event_payload,
                            "route": route_name,
                            "routeReason": route.get("reason"),
                        }
                        if not emit("turn_header", sequence, header_payload):
                            return
                    elif event_type == "utterance":
                        if research_escalation or tool_escalation:
                            raise UpstreamProtocolError(
                                "fast stream emitted an utterance after tool escalation"
                            )
                        normalized = normalize_streaming_utterance(
                            event_payload,
                            settings,
                            sequence=sequence,
                            user_message=user_message,
                            request_id=request_id,
                            turn_contract=fast_contract,
                            first_visible=not emitted_utterances,
                            persona_snapshot=fast_persona_snapshot,
                        )
                        if not emitted_utterances:
                            first_utterance_at = time.perf_counter()
                            write_server_log(
                                "chat_stream_first_utterance_ready",
                                requestId=request_id,
                                elapsedMs=round(
                                    max(0.0, first_utterance_at - stream_started_perf) * 1000
                                ),
                                textCharacters=len(str(normalized.get("textZh") or "")),
                                spokenCharacters=len(str(normalized.get("spokenTextJa") or "")),
                            )
                            update_chat_request_progress(
                                request_id,
                                "grounding-gate",
                                "第一条完整语句已生成，正在核对事实与证据边界",
                            )
                        emitted_utterances.append(normalized)
                        if buffer_until_evidence_gate:
                            buffered_utterance_events.append(
                                (sequence, normalized)
                            )
                        elif not emit("utterance", sequence, normalized):
                            return
                    elif event_type == "research_escalation":
                        if emitted_utterances and not buffer_until_evidence_gate:
                            raise UpstreamProtocolError(
                                "research escalation must precede every user-visible utterance"
                            )
                        active_capability = CapabilityEnvelope.from_dict(
                            route.get("capabilityEnvelope")
                            if isinstance(route.get("capabilityEnvelope"), dict)
                            else prepared_fast_turn.capability_envelope
                        )
                        if not active_capability.may_escalate:
                            raise UpstreamProtocolError(
                                "research escalation is forbidden by the capability envelope"
                            )
                        queries = unique_strings(
                            str(item).strip()
                            for item in (
                                event_payload.get("queries")
                                if isinstance(event_payload.get("queries"), list)
                                else []
                            )
                            if str(item).strip()
                        )[:3]
                        unknown_entities = unique_strings(
                            str(item).strip()
                            for item in (
                                event_payload.get("unknownEntities")
                                if isinstance(event_payload.get("unknownEntities"), list)
                                else []
                            )
                            if str(item).strip()
                        )[:8]
                        verification_targets = unique_strings(
                            str(item).strip()
                            for item in (
                                event_payload.get("verificationTargets")
                                if isinstance(event_payload.get("verificationTargets"), list)
                                else []
                            )
                            if str(item).strip()
                        )[:8]
                        reason = str(
                            event_payload.get("reason")
                            or "model_confidence_requires_external_evidence"
                        ).strip()[:160]
                        if not (queries or unknown_entities or verification_targets):
                            raise UpstreamProtocolError(
                                "research escalation omitted every verification target"
                            )
                        research_escalation = {
                            "reason": reason,
                            "queries": queries,
                            "unknownEntities": unknown_entities,
                            "verificationTargets": verification_targets,
                            "confidence": clamp_float(
                                event_payload.get("confidence"),
                                0.0,
                                1.0,
                                0.45,
                            ),
                            "origin": "fast_stream_model",
                            "progress": (
                                dict(event_payload.get("progress"))
                                if isinstance(event_payload.get("progress"), dict)
                                else {}
                            ),
                        }
                        research_escalation_sequence = sequence
                        body["_researchEscalation"] = dict(research_escalation)
                        update_chat_request_progress(
                            request_id,
                            "research-escalation",
                            "模型发现当前事实需要外部证据，正在切换到研究循环",
                        )
                        if not emit("tool_status", sequence, {
                            "stage": "research-escalation",
                            "displayText": "已发现需要核实的外部事实",
                            "speakable": False,
                            "voiceGate": "not_required",
                        }):
                            return
                        write_server_log(
                            "fast_path_research_escalated",
                            requestId=request_id,
                            reason=reason,
                            queries=queries,
                            unknownEntities=unknown_entities,
                            verificationTargets=verification_targets,
                        )
                        break
                    elif event_type == "tool_escalation":
                        if emitted_utterances and not buffer_until_evidence_gate:
                            raise UpstreamProtocolError(
                                "tool escalation must precede every user-visible utterance"
                            )
                        active_capability = CapabilityEnvelope.from_dict(
                            route.get("capabilityEnvelope")
                            if isinstance(route.get("capabilityEnvelope"), dict)
                            else prepared_fast_turn.capability_envelope
                        )
                        if not active_capability.may_search_tools:
                            raise UpstreamProtocolError(
                                "tool search is forbidden by the capability envelope"
                            )
                        target_domain = str(
                            event_payload.get("targetDomain") or "none"
                        ).strip()
                        if target_domain not in {
                            "none", "screen", "physical_user", "uploaded_image",
                            "document", "unknown_visual",
                        }:
                            target_domain = "unknown_visual"
                        raw_tool_requests = normalize_tool_requests({
                            "toolRequests": event_payload.get("toolRequests")
                        })
                        capability_query = str(
                            event_payload.get("capabilityQuery") or ""
                        ).strip()[:300]
                        if not raw_tool_requests and not capability_query:
                            raise UpstreamProtocolError(
                                "tool escalation omitted both tool requests and capability query"
                            )
                        todo_evidence_escalation = any(
                            item.get("name") in {"todo_search", "todo_manage"}
                            for item in raw_tool_requests
                        )
                        tool_escalation = {
                            "reason": str(
                                event_payload.get("reason")
                                or "model_discovered_missing_capability"
                            ).strip()[:160],
                            "targetDomain": target_domain,
                            "toolAuthorization": normalize_tool_authorization(
                                event_payload.get("toolAuthorization")
                            ),
                            "capabilityQuery": capability_query,
                            "toolRequests": raw_tool_requests,
                            "confidence": clamp_float(
                                event_payload.get("confidence"),
                                0.0,
                                1.0,
                                0.5,
                            ),
                            "origin": "fast_stream_model",
                            "progress": (
                                dict(event_payload.get("progress"))
                                if (
                                    isinstance(event_payload.get("progress"), dict)
                                    and not todo_evidence_escalation
                                )
                                else {}
                            ),
                        }
                        tool_escalation_sequence = sequence
                        body["_toolEscalation"] = dict(tool_escalation)
                        update_chat_request_progress(
                            request_id,
                            "tool-escalation",
                            "模型发现回答还需要工具证据，正在校验并加载对应能力",
                        )
                        if not emit("tool_status", sequence, {
                            "stage": "tool-escalation",
                            "displayText": "正在确认回答所需的工具与目标",
                            "speakable": False,
                            "voiceGate": "not_required",
                        }):
                            return
                        write_server_log(
                            "fast_path_tool_escalated",
                            requestId=request_id,
                            reason=tool_escalation["reason"],
                            targetDomain=target_domain,
                            capabilityQuery=capability_query,
                            requestedTools=[
                                str(item.get("name") or "")
                                for item in raw_tool_requests
                            ],
                        )
                        break
                    elif event_type == "turn_trailer":
                        if not emitted_utterances:
                            raise UpstreamProtocolError("stream ended without a valid utterance")
                        if event_payload.get("researchNeeded") or event_payload.get("toolRequests"):
                            raise UpstreamProtocolError("fast path attempted to emit an unverified tool conclusion")
                        schedule_decision = resolve_model_schedule_decision(
                            event_payload,
                            settings,
                            user_message=user_message,
                            messages=messages,
                            request_id=request_id,
                        )
                        body["_scheduleDecision"] = schedule_decision
                        schedule_requests = schedule_tool_requests(schedule_decision)
                        if schedule_requests:
                            schedule_intent = (
                                schedule_decision.get("intent")
                                if isinstance(schedule_decision.get("intent"), Mapping)
                                else {}
                            )
                            tool_escalation = {
                                "reason": "schedule_intent_requires_local_capability",
                                "targetDomain": "local_schedule",
                                "capabilityQuery": "",
                                "toolRequests": schedule_requests,
                                "scheduleIntent": dict(schedule_intent),
                                "confidence": schedule_intent.get("confidence", 0.5),
                                "origin": "fast_stream_schedule_intent",
                                "progress": {},
                            }
                            tool_escalation_sequence = sequence
                            body["_toolEscalation"] = dict(tool_escalation)
                            update_chat_request_progress(
                                request_id,
                                "schedule-escalation",
                                "已确认日程意图，正在读取或更新本地日程",
                            )
                            if not emit("tool_status", sequence, {
                                "stage": "schedule-escalation",
                                "displayText": "正在处理本地日程",
                                "speakable": False,
                                "voiceGate": "not_required",
                            }):
                                return
                            write_server_log(
                                "fast_path_schedule_escalated",
                                requestId=request_id,
                                workflowId=str(
                                    (schedule_decision.get("workflow") or {}).get("workflowId")
                                    if isinstance(schedule_decision.get("workflow"), Mapping)
                                    else ""
                                ),
                                requestedTools=[
                                    str(item.get("name") or "") for item in schedule_requests
                                ],
                            )
                            break
                        schedule_policy = (
                            schedule_decision.get("policy")
                            if isinstance(schedule_decision.get("policy"), Mapping)
                            else {}
                        )
                        if schedule_policy.get("requiresUserResponse"):
                            event_payload["requiresUserResponse"] = True
                            if (
                                schedule_decision.get("recoveredFromMissingProtocol")
                                or str(
                                    (schedule_decision.get("intent") or {}).get("source")
                                    or ""
                                ) == "temporal_grounding_guard"
                            ):
                                tool_escalation = {
                                    "reason": "schedule_protocol_recovery_requires_clarification",
                                    "targetDomain": "local_schedule",
                                    "capabilityQuery": "",
                                    "toolRequests": [],
                                    "scheduleIntent": dict(
                                        schedule_decision.get("intent") or {}
                                    ),
                                    "confidence": float(
                                        (schedule_decision.get("intent") or {}).get(
                                            "confidence", 0.5
                                        )
                                    ),
                                    "origin": "fast_stream_schedule_recovery",
                                    "progress": {},
                                }
                                tool_escalation_sequence = sequence
                                body["_toolEscalation"] = dict(tool_escalation)
                                update_chat_request_progress(
                                    request_id,
                                    "schedule-clarification",
                                    "已识别日程请求，正在确认缺少的必要信息",
                                )
                                write_server_log(
                                    "fast_path_schedule_clarification_escalated",
                                    requestId=request_id,
                                    missingFields=list(
                                        (schedule_decision.get("intent") or {}).get(
                                            "missingFields"
                                        ) or []
                                    ),
                                )
                                break
                        emitted_utterances = resolve_missing_stream_emotions(
                            emitted_utterances
                        )
                        emitted_utterances = enforce_turn_emotion_envelope(
                            emitted_utterances,
                            request_id=request_id,
                        )
                        if buffered_utterance_events:
                            buffered_utterance_events = [
                                (buffered_sequence, emitted_utterances[index])
                                for index, (buffered_sequence, _) in enumerate(
                                    buffered_utterance_events
                                )
                            ]
                        event_payload["finalEmotion"] = emitted_utterances[-1].get(
                            "emotion"
                        )
                        event_payload["finalEmotionIntensity"] = emitted_utterances[-1].get(
                            "emotionIntensity"
                        )
                        visible_answer = "\n\n".join(
                            str(item.get("textZh") or "")
                            for item in emitted_utterances
                        )
                        active_plan = EpistemicPlan.from_dict(
                            prepared_fast_turn.epistemic_plan
                        ) or create_epistemic_plan(
                            request_id,
                            fast_interpretation,
                            decision=route_research_decision,
                        )
                        fast_gate_decision = grounded_claim_gate_decision(
                            visible_answer,
                            active_plan.epistemic_state(),
                            None,
                            research_policy=(
                                active_plan.research_policy
                                if settings.get("permissionWebSearch")
                                else "forbidden"
                            ),
                        )
                        write_server_log(
                            "fast_candidate_grounding_gate_decision",
                            requestId=request_id,
                            planId=active_plan.plan_id,
                            planRevision=active_plan.revision,
                            decision=fast_gate_decision.to_dict(),
                        )
                        if fast_gate_decision.status == "RESEARCH_ESCALATION":
                            # No unsupported final leaves the backend.  Reuse
                            # this exact PreparedTurn and enter the same loop as
                            # an explicit model research_escalation.
                            research_escalation = {
                                "reason": "evidence_gate_rejected_unverified_external_claim",
                                "queries": [],
                                "unknownEntities": list(
                                    active_plan.unknown_entities
                                ),
                                "verificationTargets": list(
                                    fast_gate_decision.missing_verification_targets
                                    or active_plan.verification_targets
                                    or ("unsupported external claims",)
                                ),
                                "confidence": min(
                                    float(active_plan.confidence),
                                    0.5,
                                ),
                                "origin": "fast_stream_evidence_gate",
                            }
                            research_escalation_sequence = (
                                buffered_utterance_events[0][0]
                                if buffered_utterance_events
                                else sequence
                            )
                            body["_researchEscalation"] = dict(
                                research_escalation
                            )
                            if not emit("tool_status", research_escalation_sequence, {
                                "stage": "research-escalation",
                                "displayText": "回答涉及尚未核实的外部事实，正在补充证据",
                                "speakable": False,
                                "voiceGate": "not_required",
                            }):
                                return
                            write_server_log(
                                "evidence_gate_rejected_fast_final",
                                requestId=request_id,
                                unknownEntities=list(
                                    active_plan.unknown_entities
                                ),
                                gateDecision=fast_gate_decision.to_dict(),
                            )
                            break
                        combined = fast_stream_combined_result(
                            emitted_utterances,
                            event_payload,
                            fast_policy,
                            first_utterance_at=first_utterance_at,
                            stream_started_at=stream_started_perf,
                            parser_errors=parser.errors,
                            turn_contract=fast_contract,
                        )
                        combined.setdefault("_chatMetrics", {})["contextPressure"] = dict(
                            body.get("_contextPressure") or {}
                        )
                        result, recovery_route = finalize_fast_candidate(combined)
                        delivery_route = (
                            recovery_route
                            if recovery_route != route_name
                            else "reference_rewrite"
                            if result.get("referenceAttributionRepaired")
                            else route_name
                            if fast_gate_decision.status == "PASS"
                            and not result.get("groundingGateRewrittenByModel")
                            else "grounding_rewrite"
                        )
                        delivery_connection_open = True
                        if delivery_route == route_name:
                            for buffered_sequence, buffered_payload in (
                                buffered_utterance_events
                            ):
                                if not emit(
                                    "utterance",
                                    buffered_sequence,
                                    buffered_payload,
                                ):
                                    delivery_connection_open = False
                                    break
                                delivered_answer_utterances += 1
                        result = complete_deferred_chat_persistence(
                            settings,
                            user_message,
                            result,
                            request_id=request_id,
                        )
                        finish_chat_request(request_id, result)
                        buffered_utterance_events.clear()
                        if not delivery_connection_open:
                            # The client may disappear after the model answer is
                            # accepted. Persist the accepted turn even though no
                            # trailer can be delivered, matching legacy audit
                            # semantics without putting storage before TTS.
                            return
                        event_payload.update({
                            "route": delivery_route,
                            "routeReason": route.get("reason"),
                            "finalResult": result,
                        })
                        if not emit("turn_trailer", sequence, event_payload):
                            return
                        trailer_seen = True
                    elif event_type == "turn_abort":
                        emit("turn_abort", sequence, event_payload)
                        raise UpstreamProtocolError(str(event_payload.get("reason") or "upstream turn aborted"))
                if research_escalation or tool_escalation:
                    break
            if research_escalation or tool_escalation:
                active_escalation = research_escalation or tool_escalation or {}
                active_escalation_sequence = (
                    research_escalation_sequence
                    if research_escalation
                    else tool_escalation_sequence
                )
                stream_preamble: dict[str, Any] = {}
                next_sequence = active_escalation_sequence + 1

                def emit_escalated_progress(payload: dict[str, Any]) -> bool:
                    nonlocal next_sequence
                    if not isinstance(payload, dict):
                        return False
                    accepted = emit("progress_utterance", next_sequence, payload)
                    if not accepted:
                        return False
                    emitted_utterances.append(dict(payload))
                    if payload.get("progressOnly"):
                        stream_preamble.clear()
                        stream_preamble.update(payload)
                    next_sequence += 1
                    return True

                semantic_progress = (
                    active_escalation.get("progress")
                    if isinstance(active_escalation.get("progress"), dict)
                    else {}
                )
                if semantic_progress:
                    try:
                        progress_payload = normalize_streaming_utterance(
                            {
                                "textZh": semantic_progress.get("zh")
                                or semantic_progress.get("textZh"),
                                "spokenTextJa": semantic_progress.get("ja")
                                or semantic_progress.get("spokenTextJa"),
                                "emotion": semantic_progress.get("emotion")
                                or "focused",
                            },
                            settings,
                            sequence=next_sequence,
                            user_message=user_message,
                            request_id=request_id,
                            turn_contract=fast_contract,
                            first_visible=False,
                            persona_snapshot=fast_persona_snapshot,
                        )
                        progress_payload.update({
                            "progressKind": (
                                "research_bridge" if research_escalation
                                else "tool_progress"
                            ),
                            "progressOnly": True,
                            "dependsOnResearchEvidence": False,
                        })
                        if not emit_escalated_progress(progress_payload):
                            return
                        body["_semanticToolProgressProvided"] = True
                    except Exception as progress_error:
                        write_server_log(
                            "semantic_tool_progress_rejected",
                            requestId=request_id,
                            errorType=type(progress_error).__name__,
                            error=str(progress_error)[:500],
                        )

                result = process_chat_request_body(
                    body,
                    settings,
                    request_id=request_id,
                    started_at=started,
                    preflight=preflight,
                    stream_preamble=stream_preamble,
                    progress_callback=emit_escalated_progress,
                    persona_snapshot=fast_persona_snapshot,
                )
                result[
                    "researchEscalatedFromFastPath"
                    if research_escalation else
                    "toolEscalatedFromFastPath"
                ] = True
                finish_chat_request(request_id, result)
                emit("turn_trailer", next_sequence, {
                    "route": "research_loop" if research_escalation else "tool_query_loop",
                    "routeReason": (
                        "fast_path_model_research_escalation"
                        if research_escalation else
                        "fast_path_model_tool_escalation"
                    ),
                    "finalResult": result,
                    "preambleUtteranceIds": [
                        str(item.get("utteranceId") or "")
                        for item in emitted_utterances
                    ],
                    (
                        "researchEscalation"
                        if research_escalation else
                        "toolEscalation"
                    ): dict(active_escalation),
                })
                return
            update_chat_request_progress(
                request_id,
                "model-output-parsing",
                "模型响应已结束，正在解析语义事件",
            )
            tail_events = parser.finish()
            raw_stream_text = "".join(raw_stream_parts)
            raw_stream_bytes = raw_stream_text.encode("utf-8")
            developer_raw_preview = ""
            if body.get("developerDebug") and not RELEASE_MODE:
                developer_raw_preview = raw_stream_text[:8_000]
                for secret_key in ("apiKey", "webSearchApiKey"):
                    secret = str(settings.get(secret_key) or "")
                    if secret:
                        developer_raw_preview = developer_raw_preview.replace(
                            secret,
                            "[REDACTED]",
                        )
                developer_raw_preview = re.sub(
                    r"(?i)bearer\s+[A-Za-z0-9._~+/=-]{12,}",
                    "Bearer [REDACTED]",
                    developer_raw_preview,
                )
            write_server_log(
                "upstream_stream_protocol_diagnostic",
                purpose="chat_fast_utterance_stream",
                requestId=request_id,
                responseMode="stream",
                rawBodyLength=len(raw_stream_bytes),
                nonWhitespaceCount=len(re.sub(r"\s+", "", raw_stream_text)),
                streamEventCount=len(raw_stream_parts),
                parserAcceptedEventCount=parser.accepted_event_count,
                parserRejectedEventCount=parser.rejected_event_count,
                parserErrors=list(parser.errors),
                parserProtocolVersion=parser.protocol_version,
                **(
                    {"developerRawBodyPreview": developer_raw_preview}
                    if developer_raw_preview else {}
                ),
            )
            if ARCHITECTURE_FEATURES.semantic_recovery_v2_shadow:
                shadow_recovery = recover_semantic_output(
                    raw_stream_text,
                    allow_plain_text=(
                        ARCHITECTURE_FEATURES.plain_text_salvage_enabled
                    ),
                )
                write_server_log(
                    "semantic_recovery_v2_shadow",
                    requestId=request_id,
                    parserAcceptedEventCount=parser.accepted_event_count,
                    **shadow_recovery.to_dict(include_payload=False),
                )
            tail_trailer = next(
                (
                    event for event in tail_events
                    if event["type"] == "turn_trailer" and not trailer_seen
                ),
                None,
            )
            if tail_trailer:
                tail_payload = dict(tail_trailer["payload"])
                if tail_payload.get("researchNeeded") or tail_payload.get("toolRequests"):
                    raise UpstreamProtocolError("fast path attempted to emit an unverified tool conclusion")
                emitted_utterances = resolve_missing_stream_emotions(
                    emitted_utterances
                )
                emitted_utterances = enforce_turn_emotion_envelope(
                    emitted_utterances,
                    request_id=request_id,
                )
                tail_payload["finalEmotion"] = emitted_utterances[-1].get("emotion")
                tail_payload["finalEmotionIntensity"] = emitted_utterances[-1].get(
                    "emotionIntensity"
                )
                if buffered_utterance_events:
                    buffered_utterance_events = [
                        (buffered_sequence, emitted_utterances[index])
                        for index, (buffered_sequence, _) in enumerate(
                            buffered_utterance_events
                        )
                    ]
                combined = fast_stream_combined_result(
                    emitted_utterances,
                    tail_payload,
                    fast_policy,
                    first_utterance_at=first_utterance_at,
                    stream_started_at=stream_started_perf,
                    parser_errors=parser.errors,
                    turn_contract=fast_contract,
                )
                combined.setdefault("_chatMetrics", {})["contextPressure"] = dict(
                    body.get("_contextPressure") or {}
                )
                result, recovery_route = finalize_fast_candidate(combined)
                result = complete_deferred_chat_persistence(
                    settings,
                    user_message,
                    result,
                    request_id=request_id,
                )
                finish_chat_request(request_id, result)
                delivery_route = (
                    recovery_route
                    if recovery_route != route_name
                    else "reference_rewrite"
                    if result.get("referenceAttributionRepaired")
                    else "grounding_rewrite"
                    if result.get("groundingGateRewrittenByModel")
                    else route_name
                )
                if delivery_route == route_name:
                    for buffered_sequence, buffered_payload in buffered_utterance_events:
                        if not emit("utterance", buffered_sequence, buffered_payload):
                            return
                        delivered_answer_utterances += 1
                buffered_utterance_events.clear()
                tail_payload.update({
                    "route": delivery_route,
                    "routeReason": route.get("reason"),
                    "finalResult": result,
                })
                if not emit("turn_trailer", int(tail_trailer["sequence"]), tail_payload):
                    return
                trailer_seen = True
            if not trailer_seen and not emitted_utterances:
                recovered_atomic_utterances = recover_atomic_fast_stream_utterance(
                    "".join(raw_stream_parts),
                    settings,
                    user_message=user_message,
                    request_id=request_id,
                    turn_contract=fast_contract,
                    persona_snapshot=fast_persona_snapshot,
                    recent_messages=messages,
                    relationship_state=fast_relationship_state,
                )
                if recovered_atomic_utterances:
                    recovered_atomic = recovered_atomic_utterances[0]
                    header_payload = {
                        "route": route_name,
                        "routeReason": route.get("reason"),
                        "turnEmotion": recovered_atomic.get("emotion"),
                        "emotionIntensity": recovered_atomic.get("emotionIntensity"),
                        "gesture": recovered_atomic.get("gesture"),
                        "voiceStyle": recovered_atomic.get("voiceStyle"),
                        "voiceTone": recovered_atomic.get("voiceTone"),
                        "voiceIntensity": recovered_atomic.get("voiceIntensity"),
                        "speechPace": recovered_atomic.get("speechPace"),
                        "speechSpeed": recovered_atomic.get("speechSpeed"),
                        "deliveryMode": recovered_atomic.get("deliveryMode"),
                        "blushIntensity": recovered_atomic.get("blushIntensity"),
                        "eyeContact": recovered_atomic.get("eyeContact"),
                        "gazeX": recovered_atomic.get("gazeX"),
                        "gazeY": recovered_atomic.get("gazeY"),
                        "tension": recovered_atomic.get("tension"),
                        "confidence": 0.72,
                        "streamProtocolRecovered": True,
                    }
                    if not emit("turn_header", 0, header_payload):
                        return
                    for recovered_sequence, recovered_utterance in enumerate(
                        recovered_atomic_utterances,
                        1,
                    ):
                        emitted_utterances.append(recovered_utterance)
                        buffered_utterance_events.append(
                            (recovered_sequence, recovered_utterance)
                        )
                    atomic_protocol_recovered = True
                    first_utterance_at = time.perf_counter()
                    write_server_log(
                        "chat_stream_semantic_response_recovered",
                        requestId=request_id,
                        recoveryMode=str(
                            recovered_atomic.get("semanticRecoveryMode")
                            or "atomic_json"
                        ),
                        plainTextSalvaged=bool(
                            recovered_atomic.get("plainTextSalvaged")
                        ),
                        visibleSegmentCount=len(recovered_atomic_utterances),
                        segmentationSource=str(
                            recovered_atomic.get("visibleSegmentationSource")
                            or ""
                        ),
                        parserErrors=list(parser.errors),
                    )
            if not trailer_seen:
                if not emitted_utterances:
                    raise UpstreamProtocolError("stream ended without a valid utterance or turn_trailer")
                synthetic_sequence = len(emitted_utterances) + (1 if header_payload else 0)
                if not atomic_protocol_recovered and not chat_request_cancelled(request_id):
                    update_chat_request_progress(
                        request_id,
                        "model-generating",
                        "首段回答已保留，正在确认是否还有未完成内容",
                    )
                    recovered_utterances = recover_fast_stream_continuation(
                        settings,
                        user_message,
                        messages,
                        emitted_utterances,
                        request_id=request_id,
                        starting_sequence=synthetic_sequence,
                        persona_snapshot=fast_persona_snapshot,
                        cognitive_body=body,
                    )
                    for recovered in recovered_utterances:
                        emitted_utterances.append(recovered)
                        buffered_utterance_events.append(
                            (synthetic_sequence, recovered)
                        )
                        synthetic_sequence += 1
                emitted_utterances = resolve_missing_stream_emotions(
                    emitted_utterances
                )
                emitted_utterances = enforce_turn_emotion_envelope(
                    emitted_utterances,
                    request_id=request_id,
                )
                if buffered_utterance_events:
                    buffered_utterance_events = [
                        (buffered_sequence, emitted_utterances[index])
                        for index, (buffered_sequence, _) in enumerate(
                            buffered_utterance_events
                        )
                    ]
                synthetic_trailer = {
                    "finalEmotion": emitted_utterances[-1].get("emotion"),
                    "finalEmotionIntensity": emitted_utterances[-1].get("emotionIntensity"),
                    "emotionDelta": 0.0,
                    "coldShoulder": False,
                    "memoryUpdates": [],
                    "knowledgeConfidence": "medium",
                    "knowledgeConfidenceProvided": False,
                    "researchNeeded": False,
                    "requiresUserResponse": False,
                    "expectedResponseType": "",
                    "proactiveDirective": (
                        emitted_utterances[0].get("proactiveDirective")
                        if emitted_utterances[0].get("proactiveDirectiveProvided")
                        else ""
                    ),
                    "toolRequests": [],
                    "sources": [],
                    "completedActs": list(fast_contract.required_acts),
                    "standalone": True,
                    "dependsOnUndeliveredPrefix": False,
                    "turnComplete": True,
                    "streamProtocolRecovered": True,
                    "streamProtocolIssue": (
                        str(
                            emitted_utterances[-1].get("semanticRecoveryMode")
                            or "atomic_json_instead_of_ndjson"
                        )
                        if atomic_protocol_recovered
                        else "missing_turn_trailer"
                    ),
                }
                combined = fast_stream_combined_result(
                    emitted_utterances,
                    synthetic_trailer,
                    fast_policy,
                    first_utterance_at=first_utterance_at,
                    stream_started_at=stream_started_perf,
                    parser_errors=parser.errors,
                    protocol_recovered=True,
                    turn_contract=fast_contract,
                )
                combined.setdefault("_chatMetrics", {})["contextPressure"] = dict(
                    body.get("_contextPressure") or {}
                )
                result, recovery_route = finalize_fast_candidate(combined)
                result = complete_deferred_chat_persistence(
                    settings,
                    user_message,
                    result,
                    request_id=request_id,
                )
                finish_chat_request(request_id, result)
                delivery_route = (
                    recovery_route
                    if recovery_route != route_name
                    else "reference_rewrite"
                    if result.get("referenceAttributionRepaired")
                    else "grounding_rewrite"
                    if result.get("groundingGateRewrittenByModel")
                    else route_name
                )
                if delivery_route == route_name:
                    for buffered_sequence, buffered_payload in buffered_utterance_events:
                        if not emit("utterance", buffered_sequence, buffered_payload):
                            return
                        delivered_answer_utterances += 1
                buffered_utterance_events.clear()
                synthetic_trailer.update({
                    "route": delivery_route,
                    "routeReason": route.get("reason"),
                    "finalResult": result,
                })
                if not emit("turn_trailer", synthetic_sequence, synthetic_trailer):
                    return
                trailer_seen = True
                write_server_log(
                    "chat_stream_protocol_recovered",
                    requestId=request_id,
                    emittedUtterances=len(emitted_utterances),
                    issue=(
                        "atomic_json_instead_of_ndjson"
                        if atomic_protocol_recovered
                        else "missing_turn_trailer"
                    ),
                    parserErrors=list(parser.errors),
                )
        except Exception as error:
            controlled_action_result = (
                deterministic_external_action_recovery(
                    body,
                    settings,
                    user_message,
                    messages,
                    request_id=request_id,
                    failure=error,
                )
                if delivered_answer_utterances == 0
                and not isinstance(error, (RequestValidationError, CognitiveProtocolError, CognitiveSemanticAuditProtocolError, ContextCompatibilityError))
                and not chat_request_cancelled(request_id)
                else None
            )
            if controlled_action_result is not None:
                finish_chat_request(request_id, controlled_action_result)
                recovery_sequence = len(emitted_utterances) + (
                    1 if header_payload else 0
                )
                if not header_payload:
                    header_payload = {
                        "route": "action_state_recovery",
                        "routeReason": "deterministic_external_action_terminal",
                        "turnEmotion": controlled_action_result.get("emotion", "concerned"),
                    }
                    if not emit("turn_header", recovery_sequence, header_payload):
                        return
                    recovery_sequence += 1
                emit("turn_trailer", recovery_sequence, {
                    "route": "action_state_recovery",
                    "routeReason": "deterministic_external_action_terminal",
                    "finalResult": controlled_action_result,
                })
                write_server_log(
                    "chat_stream_action_state_recovered",
                    requestId=request_id,
                    initialErrorType=type(error).__name__,
                    toolStatus=str(controlled_action_result.get("toolStatus") or ""),
                )
                return

            context_recovery_result = (
                run_isolated_context_recovery(
                    body,
                    settings,
                    user_message,
                    messages,
                    request_id=request_id,
                    route_name=route_name,
                    failure=error,
                    started_at=started,
                )
                if delivered_answer_utterances == 0
                and pipeline_failure_allows_model_rescue(error)
                and not chat_request_cancelled(request_id)
                else None
            )
            if context_recovery_result is not None:
                finish_chat_request(request_id, context_recovery_result)
                recovery_sequence = len(emitted_utterances) + (
                    1 if header_payload else 0
                )
                if not header_payload:
                    header_payload = {
                        "route": "isolated_context_recovery",
                        "routeReason": "task_reconstructed_then_normal_pipeline",
                        "turnEmotion": context_recovery_result.get("emotion", "concerned"),
                    }
                    if not emit("turn_header", recovery_sequence, header_payload):
                        return
                    recovery_sequence += 1
                emit("turn_trailer", recovery_sequence, {
                    "route": "isolated_context_recovery",
                    "routeReason": "task_reconstructed_then_normal_pipeline",
                    "finalResult": context_recovery_result,
                })
                write_server_log(
                    "chat_stream_isolated_context_recovered",
                    requestId=request_id,
                    initialErrorType=type(error).__name__,
                    decision=str(context_recovery_result.get("contextRecoveryDecision") or ""),
                    taskGoal=str(context_recovery_result.get("contextRecoveryTaskGoal") or "")[:500],
                )
                return

            model_rescue_result = (
                run_model_pipeline_rescue(
                    body,
                    settings,
                    user_message,
                    messages,
                    request_id=request_id,
                    route_name=route_name,
                    failure=error,
                )
                if delivered_answer_utterances == 0
                and pipeline_failure_allows_model_rescue(error)
                and not chat_request_cancelled(request_id)
                else None
            )
            if model_rescue_result is not None:
                finish_chat_request(request_id, model_rescue_result)
                recovery_sequence = len(emitted_utterances) + (
                    1 if header_payload else 0
                )
                if not header_payload:
                    header_payload = {
                        "route": "model_pipeline_rescue",
                        "routeReason": "architecture_failure_replanned_without_persona",
                        "turnEmotion": model_rescue_result.get("emotion", "concerned"),
                    }
                    if not emit("turn_header", recovery_sequence, header_payload):
                        return
                    recovery_sequence += 1
                emit("turn_trailer", recovery_sequence, {
                    "route": "model_pipeline_rescue",
                    "routeReason": "architecture_failure_replanned_without_persona",
                    "finalResult": model_rescue_result,
                })
                write_server_log(
                    "chat_stream_model_pipeline_rescued",
                    requestId=request_id,
                    initialErrorType=type(error).__name__,
                    decision=str(model_rescue_result.get("rescueDecision") or ""),
                    toolUsed=str(model_rescue_result.get("toolUsed") or ""),
                )
                return

            recoverable_fast_http_error = (
                isinstance(error, urllib.error.HTTPError)
                and int(error.code) == 400
            )
            if (
                ARCHITECTURE_FEATURES.backend_single_turn_recovery_enabled
                and (
                    isinstance(error, UpstreamProtocolError)
                    or recoverable_fast_http_error
                )
                and delivered_answer_utterances == 0
                and not body.get("_backendSingleTurnRecoveryAttempted")
                and not chat_request_cancelled(request_id)
            ):
                body["_backendSingleTurnRecoveryAttempted"] = True
                recovery_detail = (
                    "快速主请求被上游拒绝，正在通过兼容的完整生成链路恢复"
                    if recoverable_fast_http_error
                    else "同一轮回答格式无法恢复，正在进行一次受控完整生成"
                )
                update_chat_request_progress(
                    request_id,
                    "model-generating",
                    recovery_detail,
                )
                try:
                    recovery_started = time.perf_counter()
                    recovered_result = process_chat_request_body(
                        body,
                        settings,
                        request_id=request_id,
                        started_at=started,
                        preflight=preflight,
                        persona_snapshot=fast_persona_snapshot,
                    )
                    recovered_result.update({
                        "backendSingleTurnRecovery": True,
                        "backendSingleTurnRecoveryReason": type(error).__name__,
                        "backendSingleTurnRecoveryKind": (
                            "upstream_http_400"
                            if recoverable_fast_http_error
                            else "model_protocol"
                        ),
                        "backendSingleTurnRecoveryMs": round(
                            (time.perf_counter() - recovery_started) * 1000
                        ),
                    })
                    finish_chat_request(request_id, recovered_result)
                    recovery_sequence = len(emitted_utterances) + (
                        1 if header_payload else 0
                    )
                    if not header_payload:
                        header_payload = {
                            "route": "backend_single_turn_recovery",
                            "routeReason": "same_turn_protocol_recovery",
                            "turnEmotion": recovered_result.get(
                                "emotion",
                                "thinking",
                            ),
                            "streamProtocolRecovered": True,
                        }
                        if not emit("turn_header", recovery_sequence, header_payload):
                            return
                        recovery_sequence += 1
                    emit("turn_trailer", recovery_sequence, {
                        "route": "backend_single_turn_recovery",
                        "routeReason": "same_turn_protocol_recovery",
                        "finalResult": recovered_result,
                        "streamProtocolRecovered": True,
                    })
                    write_server_log(
                        "chat_stream_backend_single_turn_recovered",
                        requestId=request_id,
                        initialErrorType=type(error).__name__,
                        initialError=str(error)[:500],
                        recoveryMs=recovered_result[
                            "backendSingleTurnRecoveryMs"
                        ],
                    )
                    return
                except Exception as recovery_error:
                    write_server_log(
                        "chat_stream_backend_single_turn_recovery_failed",
                        requestId=request_id,
                        initialErrorType=type(error).__name__,
                        recoveryErrorType=type(recovery_error).__name__,
                        recoveryError=str(recovery_error)[:500],
                    )
                    error = recovery_error
            finish_chat_request(request_id, error=str(error))
            sequence = len(emitted_utterances) + (1 if header_payload else 0)
            if isinstance(error, ContextCompatibilityError):
                error_type = error.code
                error_stage = "context_compatibility"
                connection_failure = False
            elif isinstance(error, RequestValidationError):
                error_type = error.code
                error_stage = "request"
                connection_failure = False
            elif isinstance(error, CognitiveSemanticAuditProtocolError):
                error_type = error.code
                error_stage = "semantic_audit"
                connection_failure = False
            elif isinstance(error, GroundingGateError):
                error_type = "grounding_validation_failed"
                error_stage = "grounding_gate"
                connection_failure = False
            elif isinstance(error, CognitiveProtocolError):
                error_type = "cognitive_revision_failed"
                error_stage = "cognitive_gate"
                connection_failure = False
                preserve_failed_cognitive_request(body)
            elif isinstance(error, urllib.error.HTTPError):
                error_type = "upstream_http_failed"
                error_stage = "upstream_request"
                connection_failure = False
            elif isinstance(error, (urllib.error.URLError, TimeoutError, ConnectionError)):
                error_type = "upstream_connection_failed"
                error_stage = "upstream"
                connection_failure = True
            elif isinstance(error, UpstreamProtocolError):
                error_type = "upstream_protocol_failed"
                error_stage = "model_protocol"
                connection_failure = False
            else:
                error_type = "internal_pipeline_failed"
                error_stage = "pipeline"
                connection_failure = False
            error_message = (
                upstream_http_error_user_message(error)
                if isinstance(error, urllib.error.HTTPError)
                else upstream_connection_user_message(error)
                if isinstance(error, (urllib.error.URLError, TimeoutError, ConnectionError))
                else str(error)[:500]
            )
            emit("turn_abort", sequence, {
                "reason": error_type,
                "errorType": error_type,
                "stage": error_stage,
                "connectionFailure": connection_failure,
                "completedTools": completed_tools_for_request(body),
                "message": error_message,
                "discardPendingUtterances": delivered_answer_utterances == 0,
                "stopAudio": False,
                "fallbackAllowed": bool(
                    delivered_answer_utterances == 0
                    and error_type in {
                        "upstream_connection_failed",
                        "upstream_protocol_failed",
                        "internal_pipeline_failed",
                    }
                ),
            })
            write_server_log(
                "chat_stream_failed",
                requestId=request_id,
                candidateUtterances=len(emitted_utterances),
                deliveredUtterances=delivered_answer_utterances,
                errorCategory=error_type,
                errorStage=error_stage,
                connectionFailure=connection_failure,
                errorType=type(error).__name__,
                error=str(error)[:500],
            )

    def handle_chat(self, body: dict[str, Any]) -> None:
        request_id = prepare_external_chat_body(body)
        supersedes_request_id = normalize_chat_request_id(body.get("supersedesRequestId"))
        claim, claim_value = claim_chat_request(request_id, supersedes_request_id)
        if claim == "owner":
            begin_persona_skill_record(body)
        if claim == "cached":
            cached = dict(claim_value)
            cached["requestDeduplicated"] = True
            self.send_json(cached)
            return
        if claim == "wait":
            event = claim_value
            if isinstance(event, threading.Event) and event.wait(190):
                cached = completed_chat_request(request_id)
                if cached:
                    cached["requestDeduplicated"] = True
                    self.send_json(cached)
                    return
            self.send_json({
                "ok": False,
                "code": "duplicate_request_wait_timeout",
                "error": "相同请求仍在处理中，请稍后重试。",
                "retryable": True,
                "requestId": request_id,
            }, 503)
            return

        settings = load_settings()
        started = time.time()
        try:
            result = process_chat_request_body(
                body,
                settings,
                request_id=request_id,
                started_at=started,
            )
            finish_chat_request(request_id, result)
            delivered = self.send_json(result)
            write_server_log(
                "chat_response_delivery",
                requestId=request_id,
                delivered=delivered,
                source=str(result.get("source") or ""),
                characters=len(str(result.get("reply") or "")),
                latencyMs=int(result.get("latencyMs") or 0),
                postprocessDegraded=bool(result.get("pipelineWarnings")),
            )
        except Exception as error:
            user_message, messages = streaming_user_message(body)
            recovered = (
                run_isolated_context_recovery(
                    body,
                    settings,
                    user_message,
                    messages,
                    request_id=request_id,
                    route_name="atomic_chat",
                    failure=error,
                    started_at=started,
                )
                if pipeline_failure_allows_model_rescue(error)
                and not chat_request_cancelled(request_id)
                else None
            )
            if recovered is not None:
                finish_chat_request(request_id, recovered)
                self.send_json(recovered)
                write_server_log(
                    "chat_atomic_isolated_context_recovered",
                    requestId=request_id,
                    initialErrorType=type(error).__name__,
                    decision=str(recovered.get("contextRecoveryDecision") or ""),
                )
                return
            finish_chat_request(request_id, error=str(error))
            raise


def main() -> None:
    ensure_data_dir()
    ensure_memory_file()
    runtime_lock = RuntimeProcessLock()
    try:
        runtime_lock.acquire()
    except RuntimeError as error:
        raise SystemExit(str(error)) from None
    server: AmadeusHTTPServer | None = None
    try:
        server = AmadeusHTTPServer((HOST, PORT), AmadeusHandler)
        settings = load_settings()
        try:
            reconcile_relationship_commitment_history(settings)
            storage_health = conversation_storage_health()
        except ContextCompatibilityError as error:
            # Keep settings and the error-reporting HTTP interface available.
            # Chat/history remain blocked by the same protected storage reads.
            storage_health = {"ok": False, "code": error.code, "error": str(error), "recoveryRequired": True}
        write_server_log(
            "conversation_storage_health",
            runtimeMode=RUNTIME_MODE,
            **storage_health,
        )
        print(f"AMADEUS local server: http://{HOST}:{PORT}")
        print(f"Model: {settings.get('apiModel') or 'local simulation'}")
        print(f"Memory: {memory_path(settings)}")
        if storage_health.get("recoveryRequired"):
            print(
                "Conversation storage warning: archive/index mismatch detected; "
                "history will use read-only recovery."
            )
        if should_start_vision_service(settings):
            threading.Thread(
                target=ensure_vision_service,
                args=(settings, 180),
                daemon=True,
                name="amadeus-vision-starter",
            ).start()
        server.serve_forever()
    except KeyboardInterrupt:
        print("\nShutting down.")
    finally:
        stop_gpt_sovits_service()
        stop_vision_service()
        if server is not None:
            server.server_close()
        runtime_lock.release()


if __name__ == "__main__":
    main()
